// ---------- Ask: a question answered from the app's own records (app/assistant.py) ----------
// The server finds the products (and BOQs, for someone who may see them) a question is about -
// that part is free - and the AI model answers from those records only, naming the ones it used.
// Each question is one of the day's AI requests, from a share that leaves the rest for reading
// files. The questions and answers live in this tab for the session; nothing is saved.
const askView = { history: [], busy: false, status: null };
const ASK_EXAMPLES = DISCIPLINE === "decorative"
  ? ["Which pendants do we have in brass?", "What is the price of the cheapest table lamp?"]
  : ["A Duragreen downlight of nearly 1400 lm with a cut-out under 100 mm",
     "Warm white trimless downlight for a bathroom, DALI dimmable",
     "What is the NPD price of NYX -Midi?", "Which BOQs used 75 ZOOM, and at what price?"];

async function renderAsk(generation) {
  app.innerHTML = '<div class="muted">Loading…</div>';
  let status;
  try {
    status = await api("/api/ask/status");
  } catch (e) {
    if (renderSuperseded(generation)) return;
    app.innerHTML = '<div class="error-box">Could not load Ask: ' + escapeHtml(e.message) + "</div>";
    return;
  }
  if (renderSuperseded(generation)) return;
  askView.status = status;
  askDraw();
}

function askBudgetText(s) {
  if (!s || !s.available) return "The AI model is not switched on on this server.";
  return `${s.questions_left} question${s.questions_left === 1 ? "" : "s"} left today (of ${s.questions_per_day}; ` +
    `the rest of the day's ${s.per_day} AI requests are kept for reading files)` + (s.plan ? ` · ${s.plan}` : "");
}

function askCardHtml(entry) {
  if (entry.error) {
    return `<article class="ask-card"><div class="ask-q">${escapeHtml(entry.question)}</div>` +
      `<div class="error-box">${escapeHtml(entry.error)}</div></article>`;
  }
  const r = entry.result;
  const notes = (r.notes || []).map((n) => `<div class="ask-note">${escapeHtml(n)}</div>`).join("");
  const sources = (r.sources || []).map((s) =>
    `<button type="button" class="btn small secondary ask-source" data-kind="${attr(s.kind)}" data-ref="${attr(String(s.ref))}"` +
    ` title="${attr(s.kind === "boq" ? "Open this BOQ" : "Open this product")}">${s.kind === "boq" ? "BOQ" : "Product"}: ${escapeHtml(s.title)}</button>`).join("");
  const reading = (r.reading || []).length
    ? `<div class="ask-reading"><span class="muted">Read as:</span> ${r.reading.map((w) => `<span class="ask-read">${escapeHtml(w)}</span>`).join("")}</div>` : "";
  const how = r.from_catalogue
    ? (r.asked_model ? `${escapeHtml(r.model || "The AI model")} was asked to read the wording (one request). The products and their values are the catalogue's own.`
      : "Every value is the catalogue's own. Worked out here, so no AI request was used.")
    : r.asked_model
    ? `Answered by ${escapeHtml(r.model || "the AI model")} from ${Number(r.records_given) || 0} record${r.records_given === 1 ? "" : "s"} - check it against them.`
    : "Answered without the AI model: nothing matched, so no request was used.";
  return `<article class="ask-card">
      <div class="ask-q">${escapeHtml(entry.question)}</div>
      ${reading}
      <div class="ask-a">${escapeHtml(r.answer)}</div>
      ${notes}
      ${sources ? `<div class="ask-sources"><span class="muted">From:</span> ${sources}</div>` : ""}
      <div class="muted ask-meta">${how}</div>
    </article>`;
}

function askDraw() {
  const s = askView.status || {};
  // Searches by specification need no model, so an exhausted allowance never closes the box.
  app.innerHTML = `
    <div class="toolbar"><h2 style="margin-right:auto">Ask</h2></div>
    <section class="ask">
      <p class="muted">Ask in your own words about the ${s.boqs ? "products and BOQs" : "products"} in this app. Searches by
        specification are checked against the catalogue's own values, and the answer shows how your words were read. Other
        questions go to the free AI model, which answers from the app's records and names the ones it used. Check anything
        before you rely on it. Ask cannot change anything.</p>
      <form id="ask-form" class="ask-form">
        <textarea id="ask-q" rows="2" maxlength="500" placeholder="${attr("For example: " + ASK_EXAMPLES[0])}"
          aria-label="Your question" ${askView.busy ? "disabled" : ""}></textarea>
        <button class="btn" id="ask-go" type="submit" ${askView.busy ? "disabled" : ""}>${askView.busy ? "Asking…" : "Ask"}</button>
      </form>
      <div class="ask-budget muted" id="ask-budget">${escapeHtml(askBudgetText(s))}</div>
      <div class="ask-examples">${ASK_EXAMPLES.map((q) =>
        `<button type="button" class="btn small secondary ask-example" data-q="${attr(q)}" ${askView.busy ? "disabled" : ""}>${escapeHtml(q)}</button>`).join("")}</div>
      <div id="ask-answers">${askView.history.map(askCardHtml).join("")}</div>
    </section>`;
  const box = document.getElementById("ask-q");
  document.getElementById("ask-form").addEventListener("submit", (e) => { e.preventDefault(); askSubmit(box.value); });
  // Enter asks; Shift+Enter starts a new line.
  box.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); askSubmit(box.value); }
  });
  app.querySelectorAll(".ask-example").forEach((b) => b.addEventListener("click", () => askSubmit(b.dataset.q)));
  app.querySelectorAll(".ask-source").forEach((b) => b.addEventListener("click", () => {
    const ref = Number(b.dataset.ref);
    if (b.dataset.kind === "boq") openBoq(ref);
    else showSpecsheetDetail(ref);
  }));
  if (!askView.busy) box.focus();
}

async function askSubmit(question) {
  question = String(question || "").trim();
  if (!question || askView.busy) return;
  askView.busy = true;
  askDraw();
  let entry;
  try {
    const result = await api("/api/ask", { method: "POST", body: JSON.stringify({ question }),
                                           headers: { "Content-Type": "application/json" } });
    entry = { question, result };
    if (result.budget) askView.status = { ...askView.status, ...result.budget };
  } catch (e) {
    entry = { question, error: e.message };
  }
  askView.history.unshift(entry);
  askView.busy = false;
  if (state.view === "ask") askDraw();
}

function renderHelp(generation) {
  // Sections marked admin: true are about running the app, so only an admin is shown them.
  const HELP_SECTIONS_SHOWN = HELP_SECTIONS.filter((s) => !s.admin || IS_ADMIN);
  app.innerHTML = `
    <div class="toolbar"><h2 style="margin-right:auto">Help - Using the Quotation Tool</h2></div>
    <p class="muted">A quick reference for building BOQs and Quotations. Click a topic to jump to it.</p>
    <div class="panel" style="padding:12px 14px;margin-bottom:16px">
      <div style="display:flex;flex-wrap:wrap;gap:6px">
        ${HELP_SECTIONS_SHOWN.map((s) => `<a href="#help-${s.id}" class="btn small secondary" style="text-decoration:none">${escapeHtml(s.title)}</a>`).join("")}
      </div>
    </div>
    ${HELP_SECTIONS_SHOWN.map((s) => `
      <div class="panel" id="help-${s.id}" style="padding:14px 18px;margin-bottom:14px">
        <h3 style="margin-top:0">${escapeHtml(s.title)}</h3>
        ${s.html}
      </div>`).join("")}
  `;
}

// ---------------- utils ----------------

function escapeHtml(str) {
  return String(str ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function attr(str) { return escapeHtml(str); }
// "beam_angle" -> "Beam Angle" - specsheet `fields` keys are raw snake_case, spanning every
// section a PDF happens to have (mechanical/optical/power/...), so a fixed per-typology label
// map would need one entry per key ever seen across every product type; a simple mechanical
// prettify covers all of them without needing to be kept in sync with the parser's vocabulary.
function prettifyFieldKey(key) {
  return key.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

// ---------------- nav wiring + boot ----------------

document.querySelectorAll(".nav-btn").forEach((btn) => {
  btn.addEventListener("click", () => { closeHeaderMenus(); setNavOpen(false); setView(btn.dataset.view); });
});

// The header's two menus (DESIGN.md, phase 4): "Manage" and the person menu. One is open at a time;
// a click outside, Escape, or choosing an item closes it. On a narrow screen both are laid out flat
// inside the fold-out menu instead, so these buttons are not shown there.
function closeHeaderMenus(except) {
  document.querySelectorAll(".nav-group-btn, .person-btn").forEach((b) => {
    if (b === except) return;
    b.setAttribute("aria-expanded", "false");
    b.parentElement.classList.remove("open");
  });
}
document.querySelectorAll(".nav-group-btn, .person-btn").forEach((b) => {
  b.addEventListener("click", (e) => {
    e.stopPropagation();
    const open = !b.parentElement.classList.contains("open");
    closeHeaderMenus(b);
    b.parentElement.classList.toggle("open", open);
    b.setAttribute("aria-expanded", open ? "true" : "false");
    if (open) b.parentElement.querySelector(".nav-btn, .person-item")?.focus();
  });
});
// A click outside an open menu only closes it: it must not also open the BOQ row it landed on.
document.addEventListener("click", (e) => {
  if (e.target.closest(".nav-group, .person")) return;
  if (!document.querySelector(".nav-group.open, .person.open")) return;
  closeHeaderMenus();
  e.preventDefault();
  e.stopPropagation();
}, true);
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  const open = document.querySelector(".nav-group.open > button, .person.open > button");
  if (open) { closeHeaderMenus(); open.focus(); }
});
(function () {
  const out = document.querySelector(".person-initials");
  if (!out) return;
  const local = String(window.ME_EMAIL || "").split("@")[0];
  const parts = local.split(/[._\-]+/).filter(Boolean);
  out.textContent = (parts.length > 1 ? parts[0][0] + parts[1][0] : local.slice(0, 2)).toUpperCase();
})();

// On a narrow screen the tabs, the email and Logout fold into a menu behind #nav-toggle. It is a
// class on <body>, not on the menu itself, so a stylesheet rule can also stop the page behind it
// from scrolling while it is open. Choosing a tab, tapping anywhere outside the bar or pressing
// Escape folds it away again - the ways out a person tries first.
function setNavOpen(open) {
  document.body.classList.toggle("nav-open", open);
  const toggle = document.getElementById("nav-toggle");
  if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
}
document.getElementById("nav-toggle")?.addEventListener("click", () => {
  setNavOpen(!document.body.classList.contains("nav-open"));
});
// Whether a click began inside `selector`, read from the path the click travelled rather than
// from its target's ancestors now. A control that redraws itself when clicked (the outline's
// "+ Add area" becomes a name field) has left the page by the time the click reaches the
// document, and a detached target has no ancestors - it looked like a tap outside, and closed
// the sheet the person was working in.
function clickWasInside(e, selector) {
  return e.composedPath().some((node) => node instanceof Element && node.matches(selector));
}
document.addEventListener("click", (e) => {
  if (document.body.classList.contains("nav-open") && !clickWasInside(e, ".topbar")) setNavOpen(false);
});
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape" || !document.body.classList.contains("nav-open")) return;
  setNavOpen(false);
  document.getElementById("nav-toggle")?.focus();
});

// The BOQ editor's outline as a sheet on a phone (see renderEditor). While it is open the page
// behind it is dimmed by a layer that takes the tap (body::after in style.css), so a tap meant to
// close the sheet can never also press a button underneath it - a Delete, say.
function setOutlineSheetOpen(open) {
  document.body.classList.toggle("outline-open", open);
  document.querySelector(".outline-fab")?.setAttribute("aria-expanded", open ? "true" : "false");
}
document.addEventListener("click", (e) => {
  if (document.body.classList.contains("outline-open") && !clickWasInside(e, ".editor-sidebar, .outline-fab")) {
    setOutlineSheetOpen(false);
  }
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && document.body.classList.contains("outline-open")) setOutlineSheetOpen(false);
});

// Back (see rememberInHistory). With a dialog, the tab menu or the outline sheet open, Back
// closes that and the screen stays - what a phone's own apps do - by putting back the entry
// Back just took. Otherwise it goes to the screen the entry names. Whatever box was being typed
// in is let go of first, so its "saved when you leave a field" save still happens.
window.addEventListener("popstate", async (e) => {
  const entry = e.state;
  if (!entry || !entry.view) return;
  const covering = modalRoot.innerHTML || document.body.classList.contains("nav-open") ||
    document.body.classList.contains("outline-open");
  if (covering) {
    closeModal();
    setNavOpen(false);
    setOutlineSheetOpen(false);
    history.pushState(historyEntry(), "");
    return;
  }
  document.activeElement?.blur();
  restoringFromHistory = true;
  try {
    if (entry.view === "editor" && entry.boqId) {
      if (state.currentBoq && state.currentBoq.id === entry.boqId) await setView("editor");
      else await openBoq(entry.boqId);
    } else {
      if (entry.view === "boqs") state.currentBoq = null;
      await setView(entry.view);
    }
  } catch (err) {
    // A BOQ deleted since (or one that will not load) - the list, rather than a dead end.
    state.currentBoq = null;
    await setView("boqs");
  } finally {
    restoringFromHistory = false;
  }
  // A screen that would not let go (an unsaved product-code structure the person chose to
  // keep) is still showing; its entry goes back, so history matches the screen.
  if (state.view !== entry.view) history.pushState(historyEntry(), "");
});

// Who is signed in, for the header and for the People tab's "you" marker. Written into the
// page by the server (see _render_app), as what this person may do already was (window.PERMS),
// which the server enforces per request regardless - see _required_permission in app/main.py.
// It used to come from /api/me after the page loaded: a round trip on every visit to print an
// email the server already had, and a People tab opened quickly could not yet tell which row
// was yours.
window.__meEmail = window.ME_EMAIL || "";
state.currentUser = { email: window.__meEmail };

// The first screen replaces this page's history entry rather than adding one, so Back from it
// leaves the app as before (and a reload starts afresh on the list, as it always has).
restoringFromHistory = true;
setView(HOME_VIEW);
restoringFromHistory = false;

// ---------------- NPD: New Product Development ----------------
//
// Everywhere else a product arrives by being read out of a manufacturer's PDF, and its price
// is joined on afterwards by hand. Here the product is authored: what it is and what it costs
// are entered once, together, and its specsheet is generated from that. So the form is laid
// out in the order the work actually happens - identify it, picture it, describe it, price it -
// rather than as one long wall of inputs.

const npdView = {
  products: [],
  typologies: [],
  editing: null,      // null = the list; an object = the form
  // The classification panel's state. It exists because this tab became the only place
  // products are priced: 273 products in one flat grid answers no question anybody has,
  // whereas "which Track Lights are still unpriced" is the question this screen is now for.
  brand: null,        // null = not chosen yet (opens on the biggest brand); "" = all brands
  typology: "",       // "" = every typology
  priced: "",         // "" = any, "priced", "unpriced"
  query: "",
  component: "",      // "" | "drivers" | "supplies" | "accessories" - which panel is open
  accessories: null,  // the accessory catalogue, fetched the first time it is opened
  accIssues: null,    // what is untidy in it, fetched alongside
  accIssuesOpen: false,
  accRename: "",      // the accessory whose rename box is open
  accRenameTo: null,  // what is typed in it (null = the accessory's current name)
  accQuery: "",
  accOpen: "",        // the accessory whose product list is expanded
  accSetup: "",       // the accessory whose parameters & picture panel is open
  // What is defined for each accessory, for a product's own Accessories section: {at, byKey:
  // {key: {params, image, image_url}}} - read from GET /api/accessories, kept for half a minute.
  accDefs: null,
  // That panel's working copy: {key, loading | error | data (the server's reply), params
  // (being edited, each with a `pending` option still being typed), busy, problem, saved}.
  accDraft: null,
  // The accessory library (app/accessory_parts.py): {list} or {error}, read when first needed and
  // again after anything changes it; its search, filter, and the accessory whose products are open.
  lib: null,
  libQuery: "",
  libFilter: "",
  libOpen: null,
  accOther: false,    // NPD -> Accessory library -> "Other brands" (the by-name catalogue)
};

const NPD_UNCLASSIFIED = "__unclassified__";

// Fetched once per visit, with each accessory's product list included - 31 KB over the wire, and
// the alternative is a request every time a row is expanded.
// Renaming writes into the specsheets themselves, which is the point: the catalogue is only a
// reading of them, so making it consistent means making them consistent. Everything is refetched
// afterwards rather than patched in the page - the counts, prices and codes all move.
async function npdAccDoRename(key, to) {
  const entry = (npdView.accessories.accessories || []).find(function (a) { return a.key === key; });
  if (!entry) return;
  const target = String(to || "").trim();
  if (!target || target === entry.name) return;
  if (!confirm("Rename \u201c" + entry.name + "\u201d to \u201c" + target + "\u201d in " +
      entry.count + " specsheet(s)?\n\nTheir accessory prices and order codes move with it. " +
      "This changes the specsheets themselves, not just this screen.")) return;
  try {
    const done = await api("/api/accessories/" + encodeURIComponent(key) + "/rename", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ to: target }),
    });
    npdView.accRename = "";
    npdView.accRenameTo = null;
    npdView.accOpen = "";
    npdView.accSetup = "";        // its parameters & picture moved with the name (accessories.rename)
    npdView.accDraft = null;
    npdView.accessories = null;
    npdView.accIssues = null;
    npdRenderList();
    await npdLoadAccCatalogue();
    alert("Renamed to \u201c" + done.to + "\u201d in " + done.products + " specsheet(s)" +
      (done.prices ? ", " + done.prices + " accessory price(s)" : "") +
      (done.codes ? ", " + done.codes + " order code(s)" : "") + ".");
  } catch (err) {
    alert("Could not rename it: " + err.message);
  }
}

async function npdLoadAccCatalogue() {
  if (npdView.accessories) return;
  try {
    npdView.accessories = await api("/api/accessories?full=1");
  } catch (err) {
    npdView.accessories = { count: 0, accessories: [], error: err.message };
  }
  if (state.view === "npd" && npdView.component === "accessories") npdRenderList();
  try {
    npdView.accIssues = await api("/api/accessories/issues");
  } catch (err) {
    npdView.accIssues = null;
  }
  if (state.view === "npd" && npdView.component === "accessories") npdRenderList();
}

// What is untidy in the accessory data. Shown rather than repaired: every one of these is a
// judgement about what a manufacturer meant - whether "louver" and "louvre" are one part, which
// product an unattached price was for - and the app has no business deciding that quietly.
function npdAccIssuesHtml() {
  const i = npdView.accIssues;
  if (!i) return "";
  const loose = (i.orphan_prices || []).filter(function (o) { return /not attached/.test(o.reason); });
  const bits = [];
  if ((i.spellings || []).length) {
    bits.push("<li><b>" + i.spellings.length + "</b> accessor" +
      (i.spellings.length === 1 ? "y is" : "ies are") + " spelled more than one way across " +
      "datasheets \u2014 counted as one here, and each product keeps its own spelling on its " +
      "own line. " + i.spellings.slice(0, 3).map(function (g) {
        return "<span class=\"pill\">" + escapeHtml(g.variants.map(function (v) { return v.name; }).join(" / ")) + "</span>";
      }).join(" ") + (i.spellings.length > 3 ? " and " + (i.spellings.length - 3) + " more" : "") + "</li>");
  }
  if ((i.debris || []).length) {
    bits.push("<li><b>" + i.debris.length + "</b> accessor" + (i.debris.length === 1 ? "y reads" : "ies read") +
      " like a sentence the parser picked up rather than a name, and " +
      (i.debris.length === 1 ? "is" : "are") + " left out of this catalogue: " +
      i.debris.slice(0, 2).map(function (d) {
        return "<span class=\"pill\">" + escapeHtml(d.text.slice(0, 70)) + "</span> on " + d.products;
      }).join(" ") + ". Correct the product\u2019s Accessories field to bring it in.</li>");
  }
  if (loose.length) {
    const names = {};
    loose.forEach(function (o) { names[o.accessory] = (names[o.accessory] || 0) + 1; });
    const top = Object.keys(names).sort(function (a, b) { return names[b] - names[a]; }).slice(0, 5);
    bits.push("<li><b>" + loose.length + "</b> accessory price" + (loose.length === 1 ? " is" : "s are") +
      " attached to no product, so nothing can ever find " + (loose.length === 1 ? "it" : "them") +
      ": an accessory is priced under a product, and these belong to none. " +
      top.map(function (n) { return "<span class=\"pill\">" + escapeHtml(n) + "</span>"; }).join(" ") +
      (Object.keys(names).length > top.length ? " and others" : "") +
      ". Open the product they belong to and price the accessory there \u2014 the figures are not " +
      "lost, they are simply unreachable where they sit.</li>");
  }
  const near = (i.near || []).filter(function (n) {
    return !npdView.accMergedAway || !npdView.accMergedAway[n.a.key + "|" + n.b.key];
  });
  const nearHtml = near.length
    ? '<div class="npd-cat-near"><b>Pairs that may be the same part, spelled differently</b>' +
      '<p class="muted">Not merged by any rule, and they should not be: "Beam Widening Lens (+10\u00b0)" ' +
      'and "(+20\u00b0)" look just as alike as "Lens" and "Lense" do, and only someone who knows the ' +
      "products can tell those apart. Use Rename on either one to merge them.</p>" +
      near.map(function (n) {
        return '<div class="npd-cat-near-row">' +
          "<span>" + escapeHtml(n.a.name) + ' <small class="muted">' + n.a.count + "</small></span>" +
          '<span class="muted">vs</span>' +
          "<span>" + escapeHtml(n.b.name) + ' <small class="muted">' + n.b.count + "</small></span>" +
          // The one click settles on the name more products already use; the Rename box beside
          // each accessory is there for when the commoner spelling is the wrong one.
          '<button type="button" class="mx-link" data-needs="specsheets.add" ' +
            'data-npd-cat-merge="' + attr(n.b.key) + '" data-npd-cat-merge-to="' + attr(n.a.name) + '">' +
            "Make both " + escapeHtml(n.a.name) + "</button>" +
          "</div>";
      }).join("") + "</div>"
    : "";
  if (!bits.length && !nearHtml) return '<p class="npd-ptables-lede">Nothing untidy found in the accessory data.</p>';
  return '<details class="npd-acc-issues"' + (npdView.accIssuesOpen ? " open" : "") + '><summary>' +
    (bits.length + (near.length ? 1 : 0)) +
    " thing(s) worth tidying in the accessory data</summary><ul>" + bits.join("") + "</ul>" +
    nearHtml + "</details>";
}

function npdBlankDraft() {
  return {
    id: null,              // set when revising a saved product
    approval_status: null,
    product_name: "", typology: "", series: "", family: "", variant: "",
    model_no: "", make: "InHouse", sub_typology: "",
    // The description line the sheet prints in its first bar. Held rather than derived: see
    // npdTitleBlockHtml for why the composed version is a suggestion and not the answer.
    description_line: "",
    existing: {},          // label -> url, for pictures already attached
    groups: [],            // the typology's parameter template, as returned by the server
    values: {},            // field_key -> printed value ("WHITE / BLACK")
    base_price: "",
    affects: {},           // field_key -> does this parameter change the price
    accessories: [],       // [{ name, price }] - orderable alongside the product
    optionRows: {},        // field_key -> [{ value, adder }] while a parameter is priced
    adders: {},            // field_key -> { option: amount }
    files: { product_image: null, line_diagram: null, more_diagrams: [] },
    moreDiagrams: [],       // [{label, url}] further dimension drawings already saved
    removeDiagrams: [],     // labels of saved ones to take off on save
    // Which identity fields this typology names its products by, and the short codes already
    // known for their values. Fetched when a typology is chosen - see npdLoadIdentity.
    identity: { fields: [], codes: [] },
    saving: false,
  };
}

// The options a printed value offers, by the same rule a specsheet is written and read by:
// "WHITE / BLACK" is two choices. Deriving them rather than asking for them separately keeps
// one field to fill in instead of two that can disagree.
//
// A strip light's wattage is per metre: "7.2W/M / 9.6W/M" is two options, and the slash between W
// and M is the unit, not a separator. A slash inside brackets qualifies one option -
// "SURFACE ( FIXED / ADJUSTABLE )" is one mounting. With no slash between options, commas list
// them ("2700K, 3000K, 4000K"), except a comma between digits ("50,000hrs"). Same rule as
// npd.split_options on the server.
function npdOptionsOf(value) {
  const splitAt = function (text, isSeparator) {
    const parts = [];
    let start = 0;
    let depth = 0;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === "(") { depth += 1; continue; }
      if (text[i] === ")") { depth = Math.max(0, depth - 1); continue; }
      if (depth > 0 || !isSeparator(text, i)) continue;
      parts.push(text.slice(start, i));
      start = i + 1;
    }
    parts.push(text.slice(start));
    return parts.map(function (s) { return s.trim(); }).filter(Boolean);
  };
  const slashes = splitAt(String(value || ""), function (text, i) {
    return text[i] === "/" &&
      !(/[Ww]$/.test(text.slice(0, i).trimEnd()) && /^\s*[Mm](?![A-Za-z])/.test(text.slice(i + 1)));
  });
  if (slashes.length !== 1) return slashes;
  return splitAt(slashes[0], function (text, i) {
    return text[i] === "," &&
      !(/\d$/.test(text.slice(0, i).trimEnd()) && /^\s*\d/.test(text.slice(i + 1)));
  });
}

function npdMoney(n) {
  return Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
}

// ---------------- Activity (admin only) ----------------
//
// Who did what. Opens on the question it was built to answer first - who created which BOQ -
// and below that the full record of every change, sign-in and download, newest first.
// Nothing here can edit or remove an entry; the server has no endpoint that would.

const activityView = { group: "", user: "", q: "", rows: [], nextBefore: null, summary: null };

const ACTIVITY_GROUPS = [
  ["", "Everything"], ["boq_created", "BOQs created"], ["deletions", "Deletions"],
  ["boq_edits", "BOQ edits"], ["catalogue", "Catalogue & prices"],
  ["exports", "Downloads"], ["signins", "Sign-ins"],
];

// Stored in UTC; shown in the reader's own time, which for this studio is IST.
function activityTime(iso) {
  if (!iso) return "";
  const d = new Date(/[zZ]|[+-]\d\d:?\d\d$/.test(iso) ? iso : iso + "Z");
  return d.toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric",
                                     hour: "2-digit", minute: "2-digit" });
}

function activityQuery(before) {
  const params = new URLSearchParams();
  if (activityView.group) params.set("group", activityView.group);
  if (activityView.user) params.set("user", activityView.user);
  if (activityView.q.trim()) params.set("q", activityView.q.trim());
  if (before) params.set("before", before);
  params.set("limit", "100");
  return "/api/activity?" + params.toString();
}

async function renderActivity(generation) {
  app.innerHTML = '<div class="muted">Loading…</div>';
  let summary, page;
  try {
    [summary, page] = await Promise.all([api("/api/activity/summary"), api(activityQuery())]);
  } catch (e) {
    if (renderSuperseded(generation)) return;
    app.innerHTML = '<div class="error-box">Could not load the activity log: ' +
      escapeHtml(e.message) + "</div>";
    return;
  }
  if (renderSuperseded(generation)) return;
  activityView.summary = summary;
  activityView.rows = page.rows;
  activityView.nextBefore = page.next_before;
  activityDraw();
}

function activityDraw() {
  const sum = activityView.summary || {};
  const since = sum.recording_since ? activityTime(sum.recording_since) : null;
  const creators = sum.boqs_created || [];
  const recent = sum.recent_boqs || [];

  app.innerHTML =
    '<div class="toolbar"><h2 style="margin-right:auto">Activity</h2>' +
      '<span class="muted">' + (sum.total || 0) + " entr" + (sum.total === 1 ? "y" : "ies") +
      " recorded</span></div>" +
    '<p class="muted act-lede">Every change anyone makes, every sign-in and every download, ' +
      "newest first. Only you can see this, and no entry can be edited or removed. " +
      (since
        ? "Recording began " + escapeHtml(since) + " — BOQs made before then have no recorded creator."
        : "Nothing has been recorded yet.") + "</p>" +

    '<div class="act-grid">' +
      '<section class="panel"><h3 class="act-h">Who has created BOQs</h3>' +
        (creators.length
          ? '<table class="data-table act-table"><thead><tr><th>Person</th>' +
            '<th class="num">BOQs</th><th>Most recent</th></tr></thead><tbody>' +
            creators.map(function (c) {
              return '<tr><td><button type="button" class="linkish" data-act-user="' +
                attr(c.user) + '">' + escapeHtml(c.user) + '</button></td><td class="num">' +
                c.count + '</td><td class="act-when">' + escapeHtml(activityTime(c.last)) +
                "</td></tr>";
            }).join("") + "</tbody></table>"
          : '<p class="muted">No BOQ has been created since recording began.</p>') +
      "</section>" +
      '<section class="panel"><h3 class="act-h">Latest BOQs created</h3>' +
        (recent.length
          ? '<ul class="act-recent">' + recent.map(function (r) {
              return "<li><b>" + escapeHtml(r.boq_name || "Untitled") + "</b>" +
                '<span class="muted">' + escapeHtml(r.user) + " · " +
                escapeHtml(activityTime(r.at)) + "</span></li>";
            }).join("") + "</ul>"
          : '<p class="muted">None yet.</p>') +
      "</section>" +
    "</div>" +

    '<section class="panel">' +
      '<h3 class="act-h">Everything that happened</h3>' +
      '<div class="act-filters">' +
        '<div class="act-chips">' + ACTIVITY_GROUPS.map(function (g) {
          return '<button type="button" class="config-tile small' +
            (activityView.group === g[0] ? " selected" : "") + '" data-act-group="' +
            attr(g[0]) + '">' + escapeHtml(g[1]) + "</button>";
        }).join("") + "</div>" +
        '<div class="act-controls">' +
          '<select id="act-user"><option value="">Everyone</option>' +
            (sum.people || []).map(function (u) {
              return '<option value="' + attr(u) + '"' +
                (activityView.user === u ? " selected" : "") + ">" + escapeHtml(u) + "</option>";
            }).join("") + "</select>" +
          '<input type="search" id="act-q" placeholder="Search a BOQ, product or person…" value="' +
            attr(activityView.q) + '">' +
        "</div>" +
      "</div>" +
      (activityView.rows.length
        ? '<div class="act-scroll"><table class="data-table act-table act-log"><thead><tr>' +
          "<th>When</th><th>Who</th><th>What</th><th>BOQ</th></tr></thead><tbody>" +
          activityView.rows.map(function (r) {
            const kind = r.action.indexOf("delete") >= 0 ? " act-del"
              : r.action === "auth.failed" ? " act-warn"
              : r.action === "boq.create" ? " act-new" : "";
            return '<tr class="' + kind.trim() + '"><td class="act-when">' +
              escapeHtml(activityTime(r.at)) + '</td><td class="act-who">' +
              escapeHtml(r.user || "") + "</td><td>" + escapeHtml(r.summary || r.action) +
              "</td><td>" + escapeHtml(r.boq_name || "") + "</td></tr>";
          }).join("") + "</tbody></table></div>" +
          (activityView.nextBefore
            ? '<div style="margin-top:12px"><button type="button" class="btn small secondary" ' +
              'id="act-more">Show older entries</button></div>'
            : "")
        : '<p class="muted" style="margin-top:12px">Nothing matches those filters.</p>') +
    "</section>";

  app.querySelectorAll("[data-act-group]").forEach(function (b) {
    b.addEventListener("click", function () {
      activityView.group = b.dataset.actGroup;
      activityReload();
    });
  });
  bindPreviewButtons(app);
  app.querySelectorAll("[data-act-user]").forEach(function (b) {
    b.addEventListener("click", function () {
      activityView.user = b.dataset.actUser;
      activityView.group = "boq_created";
      activityReload();
    });
  });
  const userSel = app.querySelector("#act-user");
  if (userSel) userSel.addEventListener("change", function () {
    activityView.user = userSel.value;
    activityReload();
  });
  const search = app.querySelector("#act-q");
  let timer = null;
  if (search) search.addEventListener("input", function () {
    activityView.q = search.value;
    clearTimeout(timer);
    // Waits for a pause in typing, so a search is one request rather than one per letter.
    timer = setTimeout(activityReload, 300);
  });
  const more = app.querySelector("#act-more");
  if (more) more.addEventListener("click", async function (e) {
    await withBusy(e.currentTarget, async function () {
      const page = await api(activityQuery(activityView.nextBefore));
      activityView.rows = activityView.rows.concat(page.rows);
      activityView.nextBefore = page.next_before;
      activityDraw();
    });
  });
}

async function activityReload() {
  const hadFocus = document.activeElement && document.activeElement.id === "act-q";
  try {
    const page = await api(activityQuery());
    activityView.rows = page.rows;
    activityView.nextBefore = page.next_before;
  } catch (e) {
    alert("Could not load the activity log: " + e.message);
    return;
  }
  activityDraw();
  if (hadFocus) {
    const box = app.querySelector("#act-q");
    if (box) { box.focus(); box.setSelectionRange(box.value.length, box.value.length); }
  }
}

// ---------------------------------------------------------------- NPD: brand, and DuraGreen
//
// NPD opens on one brand at a time, chosen from the dropdown at the top of the tab. InHouse is
// authored here - its specsheet is generated from what is typed, and it is coded by the studio's
// own product code. DuraGreen is DuraGreen's: read from its website and spec sheets, coded by the
// order codes DuraGreen prints (app/duragreen.py). The two are separate screens over separate
// data, so nothing done on one can change the other.
const NPD_BRANDS = ["InHouse", "Duragreen"];
const NPD_BRAND_LABEL = { InHouse: "InHouse", Duragreen: "DuraGreen" };

function npdChosenBrand() {
  if (npdView.npdBrand) return npdView.npdBrand;
  let saved = "";
  try { saved = localStorage.getItem("npd.brand") || ""; } catch (e) { saved = ""; }
  npdView.npdBrand = NPD_BRANDS.indexOf(saved) >= 0 ? saved : "InHouse";
  return npdView.npdBrand;
}

function npdBrandPickerHtml() {
  const current = npdChosenBrand();
  return '<label class="npd-brand-pick" title="Which brand’s products to work on - each brand has its own NPD">' +
    '<span>Brand</span><select id="npd-brand-select">' +
    NPD_BRANDS.map(function (b) {
      return '<option value="' + attr(b) + '"' + (b === current ? " selected" : "") + ">" +
        escapeHtml(NPD_BRAND_LABEL[b] || b) + "</option>";
    }).join("") + "</select></label>";
}

function npdBindBrandPicker() {
  const sel = app.querySelector("#npd-brand-select");
  if (!sel) return;
  sel.addEventListener("change", function () {
    npdView.npdBrand = sel.value;
    try { localStorage.setItem("npd.brand", sel.value); } catch (e) { /* remembered for this visit only */ }
    npdView.editing = null;
    dgView.open = null;
    renderNpd(currentRender());
  });
}

// The list draws its cards a page at a time: all 615 at once took a third of a second, on every
// filter click too (27 Oct). A filter, a series or a search starts again at the first page.
const DG_PAGE = 60;

const dgView = {
  products: [],
  configFields: [],
  shown: DG_PAGE,     // cards drawn so far
  open: null,         // the product open in the editor: the server's reply plus a working draft
  query: "",
  typology: "",
  status: "",         // "" | approved | pending | held
  coded: "",          // "" | "coded" | "uncoded"
  priced: "",         // "" | "priced" | "unpriced"
  keySeries: dgRemembered("dg.keySeries"),   // "" | ACME | MOOD | EVOLINE | FLOW - the shelf picked
  range: "",          // within a series: DuraGreen's own range name ("ACME CURVE", "MOOD SQUARE")
  size: "",           // within a series: the body size ("57mm")
};

// The four series the studio quotes most (owner, 22 Oct), in the order they are asked for. The
// server says which products belong to each (app/duragreen.py key_series_of); this is only the
// order and a line about what each is, so a newcomer knows which shelf to open.
const DG_KEY_SERIES = [
  ["ACME", "Recessed and surface downlights, wall lights and pendants - the core range"],
  ["MOOD", "Square and round recessed downlights with deep anti-glare"],
  ["EVOLINE", "Multi-spot line and square fittings, recessed, surface and on the 48V track"],
  ["FLOW", "Linear multi-spot fittings, recessed and surface"],
];

// A per-browser convenience (the shelf last opened), never state anyone relies on: storage may be
// blocked, and the page works the same without it.
function dgRemembered(key) {
  try { return localStorage.getItem(key) || ""; } catch (e) { return ""; }
}
function dgRemember(key, value) {
  try { localStorage.setItem(key, value || ""); } catch (e) { /* remembered for this visit only */ }
}

// A product's body size, for the size chips: its family ("57mm") where it has one.
function dgSizeOf(p) { return p.family || ""; }

// The shelf: one tile per key series, each saying how many products it holds and how many of
// them DuraGreen prints codes for - the thing that decides whether a product quotes in one click.
function dgSeriesShelfHtml(all, current) {
  return '<section class="dg-series-shelf" aria-label="Key series">' + DG_KEY_SERIES.map(function (pair) {
    const name = pair[0];
    const mine = all.filter(function (p) { return p.key_series === name; });
    const coded = mine.filter(function (p) { return p.order_codes > 0; }).length;
    const thumb = (mine.find(function (p) { return p.thumb_url && p.approval_status === "approved"; }) ||
                   mine.find(function (p) { return p.thumb_url; }) || {}).thumb_url;
    return '<button type="button" class="dg-series-tile' + (current === name ? " selected" : "") +
      '" data-dg-key-series="' + attr(name) + '" aria-pressed="' + (current === name) + '">' +
      (thumb ? '<img src="' + attr(thumb) + '" alt="" loading="lazy">' : '<span class="dg-series-noimg"></span>') +
      '<span class="dg-series-text"><span class="dg-series-name">' + escapeHtml(name) + "</span>" +
      '<span class="dg-series-blurb">' + escapeHtml(pair[1]) + "</span>" +
      '<span class="dg-series-count">' + mine.length + " products · " + coded + " with printed codes</span></span>" +
      "</button>";
  }).join("") + "</section>";
}

// Chips for a facet inside the open series, most products first; none when there is only one value.
function dgFacetEntries(rows, keyOf) {
  const m = new Map();
  rows.forEach(function (p) { const k = keyOf(p); if (k) m.set(k, (m.get(k) || 0) + 1); });
  return [...m.entries()].sort(function (a, b) {
    return (parseFloat(a[0]) || 0) - (parseFloat(b[0]) || 0) || b[1] - a[1] || a[0].localeCompare(b[0]);
  }).map(function (e) { return { value: e[0], label: e[0], count: e[1] }; });
}

const DG_STATUS_BADGE = {
  printed: "Printed by DuraGreen",
  composed: "Built from this product's printed parts",
  catalogue: "Built with its range's code table",
  pattern: "Built by its own codes' pattern",
  general: "Built with another part of its range",
  unconfirmed: "Unconfirmed",
};
// Only an unconfirmed code is shown as a warning; the others are DuraGreen's own rules, and the
// reason line under the code says which.
function dgStatusPill(status) {
  return '<span class="dg-pill ' + (status === "unconfirmed" ? "dg-pill-warn" : status === "general" ? "dg-pill-info" : "dg-pill-ok") +
    '">' + escapeHtml(DG_STATUS_BADGE[status] || status) + "</span>";
}

function dgLabel(key) {
  return (dgView.open && dgView.open.data.labels && dgView.open.data.labels[key]) ||
    prettifyFieldKey(key);
}

async function renderDuragreenNpd(generation) {
  app.innerHTML = '<div class="muted">Loading…</div>';
  let res;
  try {
    res = await api("/api/npd/duragreen/products");
  } catch (e) {
    if (renderSuperseded(generation)) return;
    app.innerHTML = '<div class="error-box">Could not load DuraGreen: ' + escapeHtml(e.message) + "</div>";
    return;
  }
  if (renderSuperseded(generation)) return;
  dgView.products = res.products;
  dgView.configFields = res.config_fields;
  if (dgView.open) return dgOpenProduct(dgView.open.data.id);
  dgRenderList();
}

function dgIsPriced(p) { return p.base_price != null || p.adder_count > 0; }

function dgVisible() {
  const q = dgView.query.trim().toLowerCase();
  return dgView.products.filter(function (p) {
    if (dgView.keySeries && p.key_series !== dgView.keySeries) return false;
    if (dgView.keySeries && dgView.range && p.series !== dgView.range) return false;
    if (dgView.keySeries && dgView.size && dgSizeOf(p) !== dgView.size) return false;
    if (dgView.typology === NPD_UNCLASSIFIED ? p.typology : (dgView.typology && p.typology !== dgView.typology)) return false;
    if (dgView.status && p.approval_status !== dgView.status) return false;
    if (dgView.coded === "coded" && !p.order_codes) return false;
    if (dgView.coded === "uncoded" && p.order_codes) return false;
    if (dgView.priced === "priced" && !dgIsPriced(p)) return false;
    if (dgView.priced === "unpriced" && dgIsPriced(p)) return false;
    if (q && [p.product_name, p.series, p.family, p.variant, p.typology].join(" ").toLowerCase().indexOf(q) < 0) return false;
    return true;
  });
}

// One facet row, drawn exactly as InHouse's classification panel draws its own.
function dgChips(label, entries, current, dataKey) {
  return '<div class="npd-facet"><span class="npd-facet-label">' + escapeHtml(label) + "</span>" +
    '<div class="npd-chips">' + entries.map(function (e) {
      return '<button type="button" class="config-tile small' + (e.value === current ? " selected" : "") +
        '" data-' + dataKey + '="' + attr(e.value) + '">' + escapeHtml(e.label) +
        (e.count != null ? ' <span class="muted">(' + e.count + ")</span>" : "") + "</button>";
    }).join("") + "</div></div>";
}

function dgRenderList() {
  // With a series open, every count and chip below is that series' own, so the panel answers
  // "what is in ACME" rather than "what is in DuraGreen".
  const everything = dgView.products;
  const all = dgView.keySeries ? everything.filter(function (p) { return p.key_series === dgView.keySeries; }) : everything;
  const rows = dgVisible();
  // a series is drawn range by range, sizes in order: the page is cut in that order, so "Show
  // more" carries on where the page ended instead of slipping cards into the ranges above
  if (dgView.keySeries && !dgView.range) rows.sort(dgShelfOrder);
  const ranges = dgView.keySeries ? dgFacetEntries(all, function (p) { return p.series; }) : [];
  const sizes = dgView.keySeries
    ? dgFacetEntries(all.filter(function (p) { return !dgView.range || p.series === dgView.range; }), dgSizeOf) : [];
  const typ = new Map();
  all.forEach(function (p) { const k = p.typology || NPD_UNCLASSIFIED; typ.set(k, (typ.get(k) || 0) + 1); });
  const count = function (fn) { return all.filter(fn).length; };
  const coded = count(function (p) { return p.order_codes > 0; });
  const pending = count(function (p) { return p.approval_status === "pending"; });

  app.innerHTML =
    '<div class="npd-head"><div>' + npdBrandPickerHtml() +
      "<h2>New Product Development — DuraGreen</h2>" +
      '<p class="muted npd-lede">DuraGreen’s catalogue, read from its website and every spec sheet as an ' +
      "engineer reads them. The source of truth is DuraGreen: each product links to its page and its sheet, " +
      "and a BOQ line gets the order code DuraGreen prints for that exact configuration — never a " +
      "InHouse-style code, never a guess. New products found on the website wait here until approved.</p></div>" +
      '<div class="dg-head-actions">' +
        '<button class="btn secondary" id="dg-naming-open" title="DuraGreen’s code tables, the structures made in NPD, and how every product is named">Naming</button>' +
        '<button class="btn secondary" id="dg-configurator" title="Choose what is asked when a DuraGreen product is added to a BOQ">Configurator questions</button>' +
        (can("npd.edit") ? '<button class="btn primary" id="dg-new">+ Add a DuraGreen product</button>' : "") +
      "</div>" +
    "</div>" +
    dgSeriesShelfHtml(everything, dgView.keySeries) +
    '<section class="npd-classify"><div class="npd-classify-head"><h3>' +
      (dgView.keySeries ? escapeHtml(dgView.keySeries) + ' <button type="button" class="btn small ghost" id="dg-all-series">Show all DuraGreen</button>'
        : "Classification") + "</h3>" +
      '<p class="npd-classify-summary">' + all.length + " products · <strong>" + coded +
      " with printed order codes</strong>, " + (all.length - coded) + " without · " + pending +
      " awaiting approval</p></div>" +
      (ranges.length > 1 ? dgChips("Range", [{ value: "", label: "All", count: all.length }].concat(ranges), dgView.range, "dg-range") : "") +
      (sizes.length > 1 ? dgChips("Size", [{ value: "", label: "Any" }].concat(sizes), dgView.size, "dg-size") : "") +
      dgChips("Typology", [{ value: "", label: "All", count: all.length }].concat(
        [...typ.entries()].sort(function (a, b) { return b[1] - a[1]; }).map(function (e) {
          return { value: e[0], label: e[0] === NPD_UNCLASSIFIED ? "Unclassified" : e[0], count: e[1] };
        })), dgView.typology, "dg-typology") +
      dgChips("Status", [{ value: "", label: "Any" }, { value: "approved", label: "In the library", count: count(function (p) { return p.approval_status === "approved"; }) },
        { value: "pending", label: "Awaiting approval", count: pending },
        { value: "held", label: "On hold", count: count(function (p) { return p.approval_status === "held"; }) }],
        dgView.status, "dg-status") +
      dgChips("Order codes", [{ value: "", label: "Any" }, { value: "coded", label: "Has printed codes", count: coded },
        { value: "uncoded", label: "None printed", count: all.length - coded }], dgView.coded, "dg-coded") +
      dgChips("Pricing", [{ value: "", label: "Any" }, { value: "priced", label: "Priced", count: count(dgIsPriced) },
        { value: "unpriced", label: "Not priced yet", count: all.length - count(dgIsPriced) }], dgView.priced, "dg-priced") +
      '<div class="npd-facet npd-facet-search"><input type="search" id="dg-q" placeholder="Search name, series, size…" value="' + attr(dgView.query) + '"></div>' +
    "</section>" +
    (rows.length === 0
      ? '<div class="npd-empty"><h3>Nothing matches those filters</h3></div>'
      : '<div class="npd-count muted">Showing ' + Math.min(rows.length, dgView.shown) + " of " + rows.length +
          (rows.length < all.length ? " (" + all.length + " in all)" : "") + "</div>" +
        dgGridHtml(rows.slice(0, dgView.shown)) +
        (rows.length > dgView.shown
          ? '<div class="dg-more-wrap"><button type="button" class="btn secondary" id="dg-more">Show ' +
              Math.min(DG_PAGE, rows.length - dgView.shown) + ' more <span class="muted">(' + (rows.length - dgView.shown) +
              " not shown)</span></button></div>" : ""));

  dgBindList();
}

// The cards; inside an open series with no range picked, under a heading per DuraGreen range
// (ACME CURVE, ACME SNOOT ...), sizes in order, so the shelf reads like the catalogue's pages.
function dgGridHtml(rows) {
  if (!dgView.keySeries || dgView.range) {
    return '<div class="card-grid npd-grid">' + rows.map(dgCardHtml).join("") + "</div>";
  }
  const groups = new Map();
  rows.forEach(function (p) {
    const k = p.series || "Other";
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(p);
  });
  return [...groups.keys()].sort(function (a, b) { return a.localeCompare(b); }).map(function (k) {
    const list = groups.get(k).slice().sort(dgShelfOrder);
    return '<h4 class="dg-range-head">' + escapeHtml(k) + ' <span class="muted">(' + list.length + ")</span></h4>" +
      '<div class="card-grid npd-grid">' + list.map(dgCardHtml).join("") + "</div>";
  }).join("");
}

// A series' shelf order: range (ACME CURVE, ACME SNOOT ...), then size, then name.
function dgShelfOrder(a, b) {
  return (a.series || "Other").localeCompare(b.series || "Other") ||
    (parseFloat(dgSizeOf(a)) || 0) - (parseFloat(dgSizeOf(b)) || 0) ||
    (a.product_name || "").localeCompare(b.product_name || "");
}

function dgCardHtml(p) {
  return '<div class="spec-card npd-card">' +
    '<div class="npd-card-img">' + (p.thumb_url ? '<img src="' + attr(p.thumb_url) + '" alt="" loading="lazy">'
      : '<div class="npd-noimg">no image</div>') + "</div>" +
    '<div class="npd-card-body">' +
      '<div class="npd-card-name">' + escapeHtml(p.product_name || "Untitled") + npdStatusTag(p.approval_status) + "</div>" +
      '<div class="npd-card-meta">' + escapeHtml([p.series, p.typology || "Unclassified"].filter(Boolean).join(" · ")) + "</div>" +
      '<div class="dg-card-codes">' + (p.order_codes
        ? '<span class="dg-pill dg-pill-ok">' + p.order_codes + " order code" + (p.order_codes === 1 ? "" : "s") + "</span>"
        : p.named_by ? "" : '<span class="dg-pill dg-pill-gap">No printed codes</span>') +
        (p.named_by ? '<span class="dg-pill dg-pill-info" title="Its codes are built from this naming structure">Named by ' +
          escapeHtml(p.named_by) + "</span>" : "") +
        (p.unconfirmed_parts ? '<span class="dg-pill dg-pill-warn" title="Code parts taken from the range matrix or matched by meaning - confirm with DuraGreen">' +
          p.unconfirmed_parts + " to confirm</span>" : "") + "</div>" +
      '<div class="npd-card-price">' + (dgIsPriced(p)
        ? '<span class="price-tag-locked">Base ₹' + npdMoney(p.base_price || 0) + "</span>" +
          (p.adder_count ? '<span class="npd-adders">' + p.adder_count + " adder" + (p.adder_count === 1 ? "" : "s") + "</span>" : "")
        : '<span class="price-tag-none">Not priced yet</span>') + "</div>" +
      '<div class="row-actions">' +
        '<button class="btn small secondary" data-dg-open="' + p.id + '">' + (can("npd.edit") || can("prices.edit") ? "Open" : "View") + "</button>" +
        (p.has_pdf ? '<a class="btn small ghost" href="/api/specsheets/' + p.id + '/pdf" target="_blank" rel="noopener">Spec sheet</a>' : "") +
        (p.source_url ? '<a class="btn small ghost" href="' + attr(p.source_url) + '" target="_blank" rel="noopener">Website ↗</a>' : "") +
        (can("npd.approve") ? dgStatusActions(p) : "") +
      "</div>" +
    "</div></div>";
}

function dgBindList() {
  npdBindBrandPicker();
  const rerender = function () { dgView.shown = DG_PAGE; dgRenderList(); };
  app.querySelector("#dg-more")?.addEventListener("click", function () {
    dgView.shown += DG_PAGE;
    dgRenderList();
  });
  [["dg-typology", "typology"], ["dg-status", "status"], ["dg-coded", "coded"], ["dg-priced", "priced"],
   ["dg-range", "range"], ["dg-size", "size"]].forEach(function (pair) {
    app.querySelectorAll("[data-" + pair[0] + "]").forEach(function (b) {
      b.addEventListener("click", function () {
        dgView[pair[1]] = b.getAttribute("data-" + pair[0]);
        if (pair[1] === "range") dgView.size = "";      // a size of another range would hide everything
        rerender();
      });
    });
  });
  // Opening a series starts it clean (its own ranges and sizes, any typology); the same tile again
  // closes it. Remembered for this browser, so the shelf a person works in is open next time.
  const pickSeries = function (name) {
    dgView.keySeries = name;
    dgView.range = "";
    dgView.size = "";
    dgView.typology = "";
    dgRemember("dg.keySeries", name);
    rerender();
  };
  app.querySelectorAll("[data-dg-key-series]").forEach(function (b) {
    b.addEventListener("click", function () {
      pickSeries(dgView.keySeries === b.dataset.dgKeySeries ? "" : b.dataset.dgKeySeries);
    });
  });
  app.querySelector("#dg-all-series")?.addEventListener("click", function () { pickSeries(""); });
  const q = app.querySelector("#dg-q");
  let timer = null;
  q.addEventListener("input", function () {
    dgView.query = q.value;
    clearTimeout(timer);
    timer = setTimeout(function () {
      dgView.shown = DG_PAGE;
      dgRenderList();
      const box = app.querySelector("#dg-q");
      box.focus();
      box.setSelectionRange(box.value.length, box.value.length);
    }, 250);
  });
  app.querySelectorAll("[data-dg-open]").forEach(function (b) {
    b.addEventListener("click", function () { withBusy(b, function () { return dgOpenProduct(b.dataset.dgOpen); }); });
  });
  app.querySelectorAll("[data-dg-set-status]").forEach(function (b) {
    b.addEventListener("click", function () { dgSetStatus(b.dataset.id, b.dataset.dgSetStatus, b); });
  });
  app.querySelector("#dg-new")?.addEventListener("click", dgNewProductModal);
  app.querySelector("#dg-naming-open").addEventListener("click", function () { npdOpenNomenclature(DG_MAKE); });
  app.querySelector("#dg-configurator").addEventListener("click", function () {
    cfgEditorOpen("Duragreen", cfgEdTypologiesOf(dgView.products, "Duragreen"),
                  dgView.typology && dgView.typology !== NPD_UNCLASSIFIED ? dgView.typology : "");
  });
}

// The buttons carry data-dg-set-status, never data-dg-status: that one is the Status filter chips'
// (dgChips), and until 26 Oct both shared it, so a filter chip also fired a status change for
// product "undefined" - HTTP 422 on every click of "Awaiting approval".
function dgStatusActions(p) {
  if (p.approval_status === "approved") {
    return '<button class="btn small secondary" data-dg-set-status="held" data-id="' + p.id + '" title="Take it out of the library">Put on hold</button>';
  }
  return '<button class="btn small primary" data-dg-set-status="approved" data-id="' + p.id + '" title="Release it to the Specsheet Library and the BOQ pickers">Approve</button>';
}

async function dgSetStatus(id, status, button) {
  await withBusy(button, async function () {
    try {
      await api("/api/npd/duragreen/products/" + id + "/status", {
        method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status: status }),
      });
      state.specsheets = [];        // the library's contents just changed
      if (dgView.open) dgView.open = null;
      await renderNpd(currentRender());
    } catch (e) { alert(e.message); }
  });
}

// Adding a DuraGreen product, three ways (21 Oct). From its page on DuraGreen's website - every
// variant card on that page, each read with its spec sheet - or from a spec sheet PDF, both read
// by the same rules as the 19 Oct catalogue run (app/duragreen_import.py), and both shown first:
// nothing is saved until the person ticks what to bring in. Or typed in by hand. Whatever comes
// in new waits for approval like every other DuraGreen product.
const DG_ADD_TABS = [["web", "From its web page"], ["pdf", "From a spec sheet PDF"], ["hand", "Type it in"]];

function dgTypologyOptions(selected) {
  const list = [...new Set(dgView.products.map(function (p) { return p.typology; }).filter(Boolean))];
  if (selected && list.indexOf(selected) < 0) list.push(selected);
  return '<option value="">Unclassified</option>' + list.sort().map(function (t) {
    return '<option value="' + attr(t) + '"' + (t === selected ? " selected" : "") + ">" + escapeHtml(t) + "</option>";
  }).join("");
}

function dgSeriesDatalist() {
  return '<datalist id="dg-series-list">' + [...new Set(dgView.products.map(function (p) { return p.series; }))].sort()
    .map(function (s) { return '<option value="' + attr(s) + '">'; }).join("") + "</datalist>";
}

function dgNewProductModal() {
  const modal = openModal('<span class="close-x" title="Close">✕</span><h3>Add a DuraGreen product</h3>' +
    '<div class="mode-toggle dg-add-tabs">' + DG_ADD_TABS.map(function (t, i) {
      return '<button type="button" class="btn small' + (i ? " secondary" : "") + '" data-dg-tab="' + t[0] + '">' + escapeHtml(t[1]) + "</button>";
    }).join("") + "</div>" + dgSeriesDatalist() +
    '<div id="dg-add-body"></div>', "modal-lg");
  modal.querySelector(".close-x").addEventListener("click", closeModal);
  const body = modal.querySelector("#dg-add-body");
  dgAdd = dgAddFresh();         // "Type it in" starts empty each time the window opens
  const show = function (tab) {
    modal.querySelectorAll("[data-dg-tab]").forEach(function (b) { b.classList.toggle("secondary", b.dataset.dgTab !== tab); });
    if (tab === "web") dgAddFromWeb(body);
    else if (tab === "pdf") dgAddFromPdf(body);
    else dgAddByHand(body);
  };
  modal.querySelectorAll("[data-dg-tab]").forEach(function (b) {
    b.addEventListener("click", function () { show(b.dataset.dgTab); });
  });
  show("web");
}

function dgAddFromWeb(body) {
  body.innerHTML =
    '<p class="muted">Paste the address of the product’s page on duragreenlighting.co.uk. Every version on that page ' +
    "is read with its spec sheet — order codes, options, finishes and specification — and shown here first. " +
    "Nothing is saved until you choose what to bring in.</p>" +
    '<div class="dg-add-row"><input type="url" id="dg-w-url" placeholder="https://duragreenlighting.co.uk/product/…">' +
    '<button class="btn primary" id="dg-w-read">Read the page</button></div>' +
    '<div class="error-box" id="dg-add-msg" hidden></div><div id="dg-add-result"></div>';
  const input = body.querySelector("#dg-w-url");
  input.focus();
  const read = function (button) {
    withBusy(button, async function () {
      dgAddMessage(body, "");
      body.querySelector("#dg-add-result").innerHTML =
        '<p class="muted">Reading the page and its spec sheets… this takes a few seconds per sheet.</p>';
      try {
        const res = await api("/api/npd/duragreen/import/preview", {
          method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ url: input.value.trim() }),
        });
        dgRenderImportPreview(body, res);
      } catch (err) {
        body.querySelector("#dg-add-result").innerHTML = "";
        dgAddMessage(body, err.message);
      }
    });
  };
  body.querySelector("#dg-w-read").addEventListener("click", function (e) { read(e.currentTarget); });
  input.addEventListener("keydown", function (e) { if (e.key === "Enter") read(body.querySelector("#dg-w-read")); });
}

function dgAddFromPdf(body) {
  body.innerHTML =
    '<p class="muted">For a product DuraGreen has sent a spec sheet for. The sheet’s order-code table, legend, finishes ' +
    "and specification are read exactly as the website’s sheets are. Leave the series and name blank to take them from the " +
    "sheet’s own heading; you can correct them before bringing the product in.</p>" +
    '<div class="npd-fields">' +
      '<label class="npd-f-wide">Spec sheet (PDF)<input type="file" id="dg-p-file" accept="application/pdf,.pdf"></label>' +
      '<label>Series (product family)<input id="dg-p-series" list="dg-series-list" placeholder="e.g. ACME FIXED"></label>' +
      '<label>Product name<input id="dg-p-name" placeholder="e.g. 57 Mini-Trim Fixed"></label>' +
      '<label>Size<input id="dg-p-family" placeholder="e.g. 57mm"></label>' +
      '<label>Typology<select id="dg-p-typology">' + dgTypologyOptions("") + "</select></label>" +
      '<label class="npd-f-wide">DuraGreen web page (if any)<input id="dg-p-url" placeholder="https://duragreenlighting.co.uk/product/…"></label>' +
    "</div>" +
    '<div class="modal-actions"><button class="btn primary" id="dg-p-read">Read the sheet</button></div>' +
    '<div class="error-box" id="dg-add-msg" hidden></div><div id="dg-add-result"></div>';
  body.querySelector("#dg-p-read").addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      dgAddMessage(body, "");
      const file = body.querySelector("#dg-p-file").files[0];
      if (!file) { dgAddMessage(body, "Choose the spec sheet PDF first."); return; }
      const form = new FormData();
      form.append("file", file);
      [["series", "#dg-p-series"], ["product_name", "#dg-p-name"], ["family", "#dg-p-family"],
       ["typology", "#dg-p-typology"], ["source_url", "#dg-p-url"]].forEach(function (pair) {
        form.append(pair[0], body.querySelector(pair[1]).value.trim());
      });
      try {
        dgRenderImportPreview(body, await api("/api/npd/duragreen/import/preview-pdf", { method: "POST", body: form }));
      } catch (err) { dgAddMessage(body, err.message); }
    });
  });
}

// "Type it in" (27 Oct): a product DuraGreen has sent details of, named the way DuraGreen names it -
// in one of its code tables if it belongs to that range, or in a structure made for its codes - with
// every segment decided: fixed for this product, or chosen when quoting and priced by what each choice
// adds. The codes shown are the server's (POST .../naming/preview), built exactly as a saved product's.
let dgAdd = null;

function dgAddFresh() {
  return { series: "", product_name: "", family: "", typology: "", source_url: "", structure: "", modes: {},
           values: {}, adders: {}, base: "", structures: null, identity: [], preview: null, error: "",
           // Its details (17 Nov): the list its typology is described by, and what is typed per detail
           details: null, detail: {}, extra: [] };
}

// What a typology's product is described by (GET /api/npd/duragreen/details): the typology's NPD
// template - InHouse's parameters, in InHouse's groups and order - then DuraGreen's own options it
// leaves out, or DuraGreen's own groups when the typology has no template. Asked once per typology.
const dgAddDetailsCache = new Map();
async function dgAddLoadDetails(a) {
  const t = a.typology || "";
  if (a.details && a.details.typology === t) return;
  try {
    if (!dgAddDetailsCache.has(t)) {
      dgAddDetailsCache.set(t, api("/api/npd/duragreen/details?typology=" + encodeURIComponent(t))
        .catch(function (e) { dgAddDetailsCache.delete(t); throw e; }));
    }
    const res = await dgAddDetailsCache.get(t);
    if ((a.typology || "") === t) a.details = res;
  } catch (e) {
    a.error = "Could not load the details for this typology: " + e.message;
  }
}

function dgAddDetailOf(a, k) {
  return a.detail[k] || (a.detail[k] = { value: "", choice: false, rows: [] });
}

// A detail the chosen naming structure decides (fixed, or chosen when quoting) is typed there,
// not here: one place for each value, as InHouse's ACCESSORIES row points to its own section.
function dgAddManaged(a, st, k) {
  if (!st || !st.segments.some(function (seg) { return seg.attribute === k; })) return false;
  const m = a.modes[k];
  return !!m && m.mode !== "out";
}

// Every detail the form shows: the typology's list, then any added with "+ Add a detail".
function dgAddVisibleKeys(a) {
  const out = [];
  ((a.details || {}).groups || []).forEach(function (g) {
    g.items.forEach(function (it) { if (out.indexOf(it.key) < 0) out.push(it.key); });
  });
  a.extra.forEach(function (k) { if (out.indexOf(k) < 0) out.push(k); });
  return out;
}

// Changing how it is named never loses what was typed: the old structure's values come back to
// the details, and the new structure starts from them - one value fixed, choices quoted with what
// each adds.
function dgAddSwitchStructure(a, name) {
  const old = dgAddStructure(a);
  if (old) {
    old.segments.forEach(function (seg) {
      const k = seg.attribute, m = a.modes[k];
      if (!m || m.mode === "out") return;
      const vals = a.values[k] || [];
      if (m.mode === "quoted" && vals.length) {
        a.detail[k] = { value: "", choice: true, rows: vals.map(function (v) {
          const add = (a.adders[k] || {})[v];
          return { value: v, adder: add == null ? "" : String(add) };
        }) };
      } else if (m.mode === "fixed" && m.value) {
        a.detail[k] = { value: m.value, choice: false, rows: [] };
      }
    });
  }
  a.structure = name;
  a.modes = {};
  a.values = {};
  a.adders = {};
  a.preview = null;
  const st = dgAddStructure(a);
  if (!st) return;
  st.segments.forEach(function (seg) {
    const k = seg.attribute, d = a.detail[k];
    if (!d) return;
    const vals = d.choice ? d.rows.map(function (r) { return String(r.value).trim(); }).filter(Boolean) : [];
    if (vals.length) {
      a.modes[k] = { mode: "quoted" };
      a.values[k] = vals.filter(function (v, i) { return vals.indexOf(v) === i; });
      d.rows.forEach(function (r) {
        const v = String(r.value).trim();
        if (v && r.adder !== "" && r.adder != null) (a.adders[k] = a.adders[k] || {})[v] = r.adder;
      });
    } else if (!d.choice && String(d.value).trim()) {
      a.modes[k] = { mode: "fixed", value: String(d.value).trim() };
    }
  });
  dgAddDefaults(a);
}

// The details as the create route takes them: a single value printed in `fields`; a choice as the
// list in `options`, printed joined ("8W / 10W / 12W") as every DuraGreen product prints one, with
// what each adds. Details the naming structure decides are sent with the structure instead.
function dgAddDetailsPayload(a, st, mayPrice) {
  const out = { fields: {}, options: {}, adders: {} };
  dgAddVisibleKeys(a).forEach(function (k) {
    const d = a.detail[k];
    if (!d || dgAddManaged(a, st, k)) return;
    if (!d.choice) {
      const v = String(d.value).trim();
      if (v) out.fields[k] = v;
      return;
    }
    const vals = [], add = {};
    d.rows.forEach(function (r) {
      const v = String(r.value).trim();
      if (!v || vals.indexOf(v) >= 0) return;
      vals.push(v);
      if (mayPrice && r.adder !== "" && r.adder != null) add[v] = r.adder;
    });
    if (!vals.length) return;
    out.options[k] = vals;
    out.fields[k] = vals.join(" / ");
    if (Object.keys(add).length) out.adders[k] = add;
  });
  return out;
}

function dgAddDetailRowHtml(a, st, it, mayPrice) {
  const k = it.key;
  const label = '<div class="npd-row-label">' + escapeHtml(it.label) + "</div>";
  if (dgAddManaged(a, st, k)) {
    const m = a.modes[k];
    const shown = m.mode === "fixed" ? (m.value || "") : (a.values[k] || []).join(" · ");
    return '<div class="npd-row is-managed">' + label +
      '<div class="npd-row-value"><div class="npd-managed">' + escapeHtml(shown || "Not decided yet") + "</div></div>" +
      '<div class="npd-row-price"><span class="npd-managed-note">set in How DuraGreen names it</span></div></div>';
  }
  const d = a.detail[k] || { value: "", choice: false, rows: [] };
  const toggle = '<div class="npd-row-price"><button type="button" class="npd-toggle' + (d.choice ? " on" : "") +
    '" data-d-choice="' + attr(k) + '" role="switch" aria-checked="' + (d.choice ? "true" : "false") + '" aria-label="' +
    attr(it.label + ": chosen when quoting") + '"><span class="npd-toggle-track"><span class="npd-toggle-knob"></span></span>' +
    '<span class="npd-toggle-text">Chosen when quoting</span></button></div>';
  if (!d.choice) {
    return '<div class="npd-row">' + label + '<div class="npd-row-value"><input data-d-val="' + attr(k) + '" value="' +
      attr(d.value) + '" aria-label="' + attr(it.label) + '"></div>' + toggle + "</div>";
  }
  const cls = mayPrice ? "npd-optrow" : "npd-optrow dg-optrow-noprice";
  return '<div class="npd-row is-priced">' + label + '<div class="npd-row-value"><div class="npd-optlist">' +
    '<div class="npd-optlist-head' + (mayPrice ? "" : " dg-optrow-noprice") + '"><span>Choice</span>' +
    (mayPrice ? "<span>Adds to base price</span>" : "") + "<span></span></div>" +
    d.rows.map(function (r, i) {
      return '<div class="' + cls + '"><input data-d-opt="' + attr(k) + '" data-i="' + i + '" value="' + attr(r.value) +
        '" aria-label="' + attr(it.label + " choice " + (i + 1)) + '">' +
        (mayPrice ? '<span class="npd-money-input small"><span class="npd-rupee">+₹</span><input type="number" min="0" step="0.01" data-d-add="' +
          attr(k) + '" data-i="' + i + '" value="' + attr(r.adder) + '" placeholder="0" aria-label="' +
          attr("Amount " + (r.value || "this choice") + " adds") + '"></span>' : "") +
        '<button type="button" class="npd-optdel" data-d-del="' + attr(k) + '" data-i="' + i + '" title="Remove this choice">×</button></div>';
    }).join("") +
    '<button type="button" class="npd-optadd" data-d-new="' + attr(k) + '">+ Add a choice</button></div></div>' + toggle + "</div>";
}

function dgAddDetailsHtml(a, st, mayPrice) {
  if (!a.typology) return '<p class="muted">Pick its typology above, and the details a product of that kind is described by appear here.</p>';
  if (!a.details) return '<p class="muted">Loading its details…</p>';
  const groups = a.details.groups.slice();
  const extra = a.extra.map(function (k) {
    const o = (a.details.others || []).find(function (x) { return x.key === k; });
    return { key: k, label: o ? o.label : k };
  });
  if (extra.length) groups.push({ group: "ADDED", items: extra });
  const shown = dgAddVisibleKeys(a);
  const more = (a.details.others || []).filter(function (o) { return shown.indexOf(o.key) < 0; });
  return '<p class="muted">' + (a.details.source === "template"
      ? "As a " + escapeHtml(a.details.template) + " is described in NPD, then DuraGreen’s own options. "
      : "DuraGreen’s own details (NPD has no template for this typology). ") +
    "Type what is known; leave the rest blank. Switch on <b>Chosen when quoting</b> for a detail the Configurator should " +
    "ask, and list its choices" + (mayPrice ? ", each with what it adds to the price." : ".") + "</p>" +
    '<div class="dg-add-details">' + groups.map(function (g) {
      return '<div class="npd-group"><div class="npd-group-head">' + escapeHtml(g.group) + '</div><div class="npd-rows">' +
        g.items.map(function (it) { return dgAddDetailRowHtml(a, st, it, mayPrice); }).join("") + "</div></div>";
    }).join("") + "</div>" +
    (more.length ? '<label class="dg-add-more">+ Add a detail<select id="dg-d-more"><option value="">Choose a detail…</option>' +
      more.map(function (o) { return '<option value="' + attr(o.key) + '">' + escapeHtml(o.label) + "</option>"; }).join("") +
      "</select></label>" : "");
}

function dgAddBindDetails(body, a, redraw) {
  body.querySelectorAll("[data-d-val]").forEach(function (inp) {
    inp.addEventListener("input", function () { dgAddDetailOf(a, inp.dataset.dVal).value = inp.value; });
  });
  body.querySelectorAll("[data-d-opt]").forEach(function (inp) {
    inp.addEventListener("input", function () { dgAddDetailOf(a, inp.dataset.dOpt).rows[+inp.dataset.i].value = inp.value; });
  });
  body.querySelectorAll("[data-d-add]").forEach(function (inp) {
    inp.addEventListener("input", function () { dgAddDetailOf(a, inp.dataset.dAdd).rows[+inp.dataset.i].adder = inp.value; });
  });
  body.querySelectorAll("[data-d-choice]").forEach(function (b) {
    b.addEventListener("click", function () {
      const k = b.dataset.dChoice, d = dgAddDetailOf(a, k);
      if (d.choice) {
        // back to one value: the choices printed as one ("8W / 10W"), nothing lost
        d.value = d.rows.map(function (r) { return String(r.value).trim(); }).filter(Boolean).join(" / ");
        d.choice = false;
      } else {
        const vals = dgOptionList(d.value);
        if (!d.rows.length || vals.length) d.rows = (vals.length ? vals : [""]).map(function (v) { return { value: v, adder: "" }; });
        d.choice = true;
      }
      redraw();
      body.querySelector('[data-d-opt="' + k + '"]')?.focus();
    });
  });
  body.querySelectorAll("[data-d-new]").forEach(function (b) {
    b.addEventListener("click", function () {
      const k = b.dataset.dNew, d = dgAddDetailOf(a, k);
      d.rows.push({ value: "", adder: "" });
      redraw();
      const boxes = body.querySelectorAll('[data-d-opt="' + k + '"]');
      if (boxes.length) boxes[boxes.length - 1].focus();
    });
  });
  body.querySelectorAll("[data-d-del]").forEach(function (b) {
    b.addEventListener("click", function () {
      const d = dgAddDetailOf(a, b.dataset.dDel);
      d.rows.splice(+b.dataset.i, 1);
      if (!d.rows.length) d.rows.push({ value: "", adder: "" });
      redraw();
    });
  });
  body.querySelector("#dg-d-more")?.addEventListener("change", function (e) {
    if (e.target.value && a.extra.indexOf(e.target.value) < 0) a.extra.push(e.target.value);
    redraw();
  });
}

async function dgAddByHand(body) {
  const a = dgAdd || (dgAdd = dgAddFresh());
  if (!a.structures) {
    body.innerHTML = '<p class="muted">Loading DuraGreen’s naming structures…</p>';
    try {
      const res = await api("/api/npd/duragreen/structures");
      a.structures = res.structures || [];
      a.identity = res.identity_keys || [];
    } catch (e) {
      a.structures = [];
      a.error = "Could not load the naming structures: " + e.message;
    }
    if (a.pendingStructure) {
      const name = a.pendingStructure;
      delete a.pendingStructure;
      dgAddSwitchStructure(a, name);
    } else if (a.structure) dgAddDefaults(a);
  }
  if (a.typology && !(a.details && a.details.typology === a.typology)) {
    dgAddByHandDraw(body);
    await dgAddLoadDetails(a);
    if (dgAdd !== a) return;
  }
  dgAddByHandDraw(body);
  if (a.structure) dgAddPreviewSoon(body, 0);
}

function dgAddStructure(a) {
  return a.structure ? (a.structures || []).find(function (s) { return s.name === a.structure; }) || null : null;
}

// A new product's first guess at each segment: what names the product itself (its type, size, style)
// is fixed; an accessory is left out; everything else - power, CCT, driver, beam, colours - is chosen
// when quoting. Every one can be changed.
function dgAddDefaults(a) {
  const st = dgAddStructure(a);
  if (!st) return;
  st.segments.forEach(function (seg) {
    const k = seg.attribute;
    if (a.modes[k]) return;
    if (a.identity.indexOf(k) >= 0 || k === "style" || k === "trim") a.modes[k] = { mode: "fixed", value: "" };
    else if (k === "accessories") a.modes[k] = { mode: "out" };
    else a.modes[k] = { mode: "quoted" };
  });
}

// The values a quoted segment offers: the structure's own meanings (power is a number, so none), and
// any typed in.
function dgAddListed(seg) {
  return seg.attribute === "wattage" ? [] : seg.entries.map(function (e) { return e.meaning; });
}

function dgAddCodeCell(a, seg, m) {
  const p = a.preview;
  if (!p || p.error) return "";
  if (m.mode === "fixed") {
    const piece = (p.pieces || []).find(function (x) { return x.field === seg.attribute; });
    return piece && piece.token && piece.token !== "?" ? '<code class="dg-optcode">' + escapeHtml(piece.token) + "</code>"
      : (m.value ? dgShortPill("none") : "");
  }
  if (m.mode === "quoted") {
    const opt = (p.options || []).find(function (x) { return x.field === seg.attribute; });
    if (opt) {
      return '<div class="dg-add-codes">' + opt.values.map(function (v) {
        return '<span title="' + attr(v.value + (v.note ? " - " + v.note : "")) + '">' +
          (v.code ? '<code class="dg-optcode">' + escapeHtml(v.code) + "</code>" : dgShortPill("none")) + "</span>";
      }).join("") + "</div>";
    }
    const one = (p.pieces || []).find(function (x) { return x.field === seg.attribute; });
    return one && one.token ? '<code class="dg-optcode">' + escapeHtml(one.token) + "</code>" : "";
  }
  return "";
}

function dgAddPreviewHtml(a) {
  const p = a.preview;
  if (!p) return '<span class="muted">The code appears here as you decide.</span>';
  if (p.error) return '<span class="muted">' + escapeHtml(p.error) + "</span>";
  const f = p.first || {};
  // a code built from the structure's letters is the structure's, not a range table's
  const pill = f.status === "catalogue" ? '<span class="dg-pill dg-pill-ok dg-pill-short">From ' + escapeHtml(a.structure) + "</span>" : dgShortPill(f.status);
  return (f.code ? "Reads as <span class=\"dg-code dg-code-big\">" + escapeHtml(f.code) + "</span>" + pill
      : '<span class="muted">No code yet: ' + escapeHtml(f.reason || "decide each segment") + "</span>") +
    (p.total ? '<div class="muted">' + p.coded + " of " + (p.worked < p.total ? "the first " + p.worked + " of " + p.total : p.total) +
      " combination" + (p.total === 1 ? "" : "s") + " get a code" + (Object.keys(f.chosen || {}).length
        ? " · shown: " + escapeHtml(Object.keys(f.chosen).map(function (k) { return f.chosen[k]; }).join(" · ")) : "") + "</div>" : "");
}

function dgAddPayloadOptions(a) {
  const st = dgAddStructure(a), out = {};
  if (!st) return out;
  st.segments.forEach(function (seg) {
    const m = a.modes[seg.attribute];
    if (m && m.mode === "quoted" && (a.values[seg.attribute] || []).length) out[seg.attribute] = a.values[seg.attribute].slice();
  });
  return out;
}

let dgAddPreviewTimer = null;
function dgAddPreviewSoon(body, wait) {
  clearTimeout(dgAddPreviewTimer);
  dgAddPreviewTimer = setTimeout(async function () {
    const a = dgAdd, st = dgAddStructure(a);
    if (!st) return;
    let res;
    try {
      res = await api("/api/npd/duragreen/naming/preview", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ structure: a.structure, modes: dgNamingPayload(a.structure, st.segments, a.modes).modes,
                               options: dgAddPayloadOptions(a), typology: a.typology }),
      });
    } catch (e) { res = { error: e.message }; }
    if (dgAdd !== a || a.structure !== (res.structure || a.structure)) return;
    a.preview = res;
    // filled in place: a person typing a value or a price is not interrupted by a redraw
    const box = body.querySelector("#dg-n-preview");
    if (box) box.innerHTML = dgAddPreviewHtml(a);
    body.querySelectorAll("[data-n-code]").forEach(function (cell) {
      const seg = st.segments.find(function (s) { return s.attribute === cell.dataset.nCode; });
      if (seg) cell.innerHTML = dgAddCodeCell(a, seg, a.modes[seg.attribute] || { mode: "out" });
    });
  }, wait == null ? 300 : wait);
}

function dgAddByHandDraw(body) {
  const a = dgAdd, mayPrice = can("prices.edit");
  const st = dgAddStructure(a);
  const opt = function (s) {
    return '<option value="' + attr(s.name) + '"' + (s.name === a.structure ? " selected" : "") + ">" + escapeHtml(s.name) + "</option>";
  };
  const printed = (a.structures || []).filter(function (s) { return !s.made; });
  const made = (a.structures || []).filter(function (s) { return s.made; });
  const field = function (id, key, label, placeholder, extra) {
    return "<label" + (extra || "") + ">" + escapeHtml(label) + '<input id="' + id + '" data-n-field="' + key + '" value="' + attr(a[key]) +
      '" placeholder="' + attr(placeholder) + '"' + (key === "series" ? ' list="dg-series-list"' : "") + "></label>";
  };
  const quotedHtml = function (seg) {
    const k = seg.attribute, chosen = a.values[k] || [];
    const listed = dgAddListed(seg);
    const all = listed.concat(chosen.filter(function (v) { return listed.indexOf(v) < 0; }));
    return '<div class="dg-add-vals">' + all.map(function (v) {
        const on = chosen.indexOf(v) >= 0;
        const add = (a.adders[k] || {})[v];
        return '<label class="dg-add-val' + (on ? " on" : "") + '"><input type="checkbox" data-n-val="' + attr(k) + '" value="' + attr(v) + '"' +
          (on ? " checked" : "") + "> " + escapeHtml(v) +
          (on && mayPrice ? ' <span class="npd-money-input small"><span class="npd-rupee">+₹</span><input type="number" min="0" step="0.01" data-n-add="' +
            attr(k) + '" data-v="' + attr(v) + '" value="' + attr(add == null ? "" : add) + '" placeholder="0" aria-label="' +
            attr("Amount " + v + " adds") + '"></span>' : "") + "</label>";
      }).join("") +
      (listed.length > 1 ? '<span class="dg-add-all"><button type="button" class="btn tiny ghost" data-n-all="' + attr(k) + '">All</button>' +
        '<button type="button" class="btn tiny ghost" data-n-none="' + attr(k) + '">None</button></span>' : "") +
      '<span class="dg-add-other"><input data-n-other="' + attr(k) + '" placeholder="' + attr(k === "wattage" ? "Add a power, e.g. 8W" : "Add another value") +
        '" aria-label="' + attr("Add a value for " + seg.segment) + '"><button type="button" class="btn tiny ghost" data-n-otheradd="' + attr(k) + '">Add</button></span></div>';
  };
  body.innerHTML =
    '<p class="muted">For a product DuraGreen has sent details of without a spec sheet. Give it enough to be configured and ' +
    "quoted: its typology, then its details — each one value, or choices made when quoting. If DuraGreen’s codes for it are " +
    "known, name it the way DuraGreen does below. It starts awaiting approval; everything can be changed in the product afterwards.</p>" +
    '<div class="npd-fields">' +
      field("dg-n-series", "series", "Series (product family)", "e.g. ACME FIXED") +
      field("dg-n-name", "product_name", "Product name", "e.g. 57 Mini-Trim Fixed") +
      field("dg-n-family", "family", "Size", "e.g. 57mm") +
      '<label>Typology<select id="dg-n-typology" data-n-field="typology">' + dgTypologyOptions(a.typology) + "</select></label>" +
      field("dg-n-url", "source_url", "DuraGreen web page (if any)", "https://duragreenlighting.co.uk/product/…", ' class="npd-f-wide"') +
    "</div>" +
    "<h4>Its details</h4>" + dgAddDetailsHtml(a, st, mayPrice) +
    "<h4>How DuraGreen names it</h4>" +
    (a.error ? '<div class="error-box">' + escapeHtml(a.error) + "</div>" : "") +
    '<div class="dg-nm-pickrow"><label>Named by<select id="dg-n-structure"><option value="">Not yet — I will add its codes in the product</option>' +
      (printed.length ? '<optgroup label="DuraGreen’s code tables">' + printed.map(opt).join("") + "</optgroup>" : "") +
      (made.length ? '<optgroup label="Made in NPD">' + made.map(opt).join("") + "</optgroup>" : "") + "</select></label>" +
      '<button type="button" class="btn small ghost" id="dg-n-make">+ Make a new structure</button></div>' +
    (st ? dgNamingRibbonHtml(st.segments) + dgNamingRowsHtml({
      segments: st.segments, modes: a.modes, identity: a.identity, mayEdit: true, quotedHtml: quotedHtml,
      codeOf: function (seg, m) { return '<span data-n-code="' + attr(seg.attribute) + '">' + dgAddCodeCell(a, seg, m) + "</span>"; },
    }) : "") +
    (mayPrice ? '<div class="npd-basebar dg-basebar"><label class="npd-base">Base price<span class="npd-money-input"><span class="npd-rupee">₹</span>' +
      '<input type="number" min="0" step="0.01" id="dg-n-base" value="' + attr(a.base) + '" placeholder="not priced"></span></label>' +
      '<p class="npd-basenote">Every configuration starts here; each ticked choice above can <strong>add</strong> to it. Blank: priced later.</p></div>' : "") +
    (st ? '<div class="dg-test-out dg-add-preview" id="dg-n-preview">' + dgAddPreviewHtml(a) + "</div>" : "") +
    '<div class="error-box" id="dg-add-msg" hidden></div>' +
    '<div class="modal-actions"><button class="btn secondary" id="dg-n-cancel">Cancel</button>' +
    '<button class="btn primary" id="dg-n-save">Add</button></div>';

  const redraw = function () { dgAddByHandDraw(body); dgAddPreviewSoon(body); };
  body.querySelectorAll("[data-n-field]").forEach(function (inp) {
    inp.addEventListener(inp.tagName === "SELECT" ? "change" : "input", function () { a[inp.dataset.nField] = inp.value; });
  });
  // A new typology brings its own list of details; what was typed stays, for every detail both share.
  body.querySelector("#dg-n-typology").addEventListener("change", function () {
    dgAddByHand(body);
  });
  dgAddBindDetails(body, a, redraw);
  body.querySelector("#dg-n-structure").addEventListener("change", function (e) {
    dgAddSwitchStructure(a, e.target.value);
    redraw();
  });
  body.querySelector("#dg-n-make").addEventListener("click", function () {
    // the editor takes this window's place, and gives it back with the new structure chosen
    dgStructureEditorInto(body, null, {
      onSaved: function (res) {
        dgAddSwitchStructure(a, "");          // what the old structure held goes back to the details first
        a.structures = null;
        a.pendingStructure = res.name;
        dgAddByHand(body);
      },
      onCancel: function () { dgAddByHandDraw(body); },
    });
  });
  if (st) {
    dgNamingRowsBind(body, a.modes, redraw, function () { dgAddPreviewSoon(body); });
    body.querySelectorAll("[data-n-val]").forEach(function (cb) {
      cb.addEventListener("change", function () {
        const k = cb.dataset.nVal, list = a.values[k] = (a.values[k] || []).filter(function (v) { return v !== cb.value; });
        if (cb.checked) list.push(cb.value);
        else if (a.adders[k]) delete a.adders[k][cb.value];
        redraw();
      });
    });
    body.querySelectorAll("[data-n-all],[data-n-none]").forEach(function (b) {
      b.addEventListener("click", function () {
        const k = b.dataset.nAll || b.dataset.nNone, seg = st.segments.find(function (s) { return s.attribute === k; });
        if (b.dataset.nAll) {
          const have = a.values[k] || [];
          a.values[k] = have.concat(dgAddListed(seg).filter(function (v) { return have.indexOf(v) < 0; }));
        } else {
          a.values[k] = [];
          delete a.adders[k];
        }
        redraw();
      });
    });
    body.querySelectorAll("[data-n-add]").forEach(function (inp) {
      inp.addEventListener("input", function () {
        const k = inp.dataset.nAdd;
        a.adders[k] = a.adders[k] || {};
        if (inp.value === "") delete a.adders[k][inp.dataset.v];
        else a.adders[k][inp.dataset.v] = inp.value;
      });
    });
    const addOther = function (k) {
      const box = body.querySelector('[data-n-other="' + k + '"]');
      const v = box ? box.value.trim() : "";
      if (!v) return;
      a.values[k] = (a.values[k] || []).filter(function (x) { return x !== v; }).concat([v]);
      redraw();
      body.querySelector('[data-n-other="' + k + '"]')?.focus();
    };
    body.querySelectorAll("[data-n-otheradd]").forEach(function (b) {
      b.addEventListener("click", function () { addOther(b.dataset.nOtheradd); });
    });
    body.querySelectorAll("[data-n-other]").forEach(function (inp) {
      inp.addEventListener("keydown", function (e) { if (e.key === "Enter") { e.preventDefault(); addOther(inp.dataset.nOther); } });
    });
  }
  // the base price is offered with or without a naming structure: details can add to it too
  body.querySelector("#dg-n-base")?.addEventListener("input", function (e) { a.base = e.target.value; });
  body.querySelector("#dg-n-cancel").addEventListener("click", closeModal);
  body.querySelector("#dg-n-save").addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      const payload = { series: a.series.trim(), product_name: a.product_name.trim(), family: a.family.trim(),
                        typology: a.typology, source_url: a.source_url.trim() };
      const det = dgAddDetailsPayload(a, st, mayPrice);
      payload.fields = det.fields;
      payload.options = det.options;
      const adders = det.adders;
      if (st) {
        payload.naming = dgNamingPayload(a.structure, st.segments, a.modes);
        const named = dgAddPayloadOptions(a);
        Object.keys(named).forEach(function (k) {
          payload.options[k] = named[k];
          delete adders[k];
          named[k].forEach(function (v) {
            const amt = (a.adders[k] || {})[v];
            if (amt !== undefined && amt !== "") (adders[k] = adders[k] || {})[v] = amt;
          });
        });
      }
      if (mayPrice) {
        payload.base_price = a.base === "" ? null : Number(a.base);
        payload.price_adders = adders;
      }
      try {
        const res = await api("/api/npd/duragreen/products", {
          method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload),
        });
        closeModal();
        dgNaming.data = null;
        await dgOpenProduct(res.id);
      } catch (err) { dgAddMessage(body, err.message); }
    });
  });
}

function dgAddMessage(body, text) {
  const msg = body.querySelector("#dg-add-msg");
  if (!msg) return;
  msg.hidden = !text;
  msg.textContent = text;
}

// Several values shown as several values - a chip each - never "A / B" (owner, 27 Oct): a bare
// slash is also part of some values ("On/off", "0/1-10V"), so a slash list cannot be read back.
function dgValueChips(values) {
  return (values || []).map(function (v) { return '<span class="dg-vchip">' + escapeHtml(v) + "</span>"; }).join("");
}

function dgOptionSummary(options) {
  const keys = Object.keys(options || {}).filter(function (k) { return (options[k] || []).length; });
  if (!keys.length) return '<span class="muted">No options read</span>';
  return keys.map(function (k) {
    return "<span><b>" + escapeHtml(prettifyFieldKey(k)) + "</b> " + dgValueChips(options[k]) + "</span>";
  }).join("");
}

// A preview row's prices: what the product costs now, and - for someone who may edit prices -
// boxes to set or change them as it comes in, pre-filled with the current figures. A box left
// blank keeps that price; an import never removes one (that is done in the product's own page).
function dgImportPriceBoxes(it) {
  const cur = it.prices || {};
  const adders = cur.price_adders || {};
  const count = Object.keys(adders).reduce(function (n, k) { return n + Object.keys(adders[k] || {}).length; }, 0);
  const now = cur.base_price != null
    ? "Base ₹" + npdMoney(cur.base_price) + (count ? " · " + count + " adder" + (count === 1 ? "" : "s") : "")
    : "Not priced yet";
  if (!can("prices.edit")) return '<div class="dg-imp-note">Price: ' + escapeHtml(now) + "</div>";
  const fields = Object.keys(it.price_options || {});
  const box = function (attrs, value) {
    return '<input type="number" min="0" step="0.01" inputmode="decimal" ' + attrs + ' value="' +
      attr(value != null ? String(value) : "") + '">';
  };
  return '<details class="dg-imp-prices"><summary>Prices <span class="muted">— ' + escapeHtml(now) + "</span></summary>" +
    '<p class="muted">A box left blank keeps the price it has. An adder is what that option adds to the base price.</p>' +
    '<label class="dg-imp-base">Base price (₹)' + box('data-imp-base placeholder="e.g. 1000"', cur.base_price) + "</label>" +
    fields.map(function (f) {
      return '<div class="dg-imp-adders"><span class="dg-imp-adder-label">' + escapeHtml(prettifyFieldKey(f)) + "</span>" +
        it.price_options[f].map(function (v) {
          return "<label>" + escapeHtml(v) + box('placeholder="+0" data-imp-adder-field="' + attr(f) +
            '" data-imp-adder-value="' + attr(v) + '"', (adders[f] || {})[v]) + "</label>";
        }).join("") + "</div>";
    }).join("") +
    "</details>";
}

function dgImportPricesOf(row) {
  const out = {};
  const base = row.querySelector("[data-imp-base]");
  if (base && base.value.trim() !== "") out.base_price = base.value.trim();
  const adders = {};
  row.querySelectorAll("[data-imp-adder-field]").forEach(function (input) {
    if (input.value.trim() === "") return;
    const f = input.dataset.impAdderField;
    if (!adders[f]) adders[f] = {};
    adders[f][input.dataset.impAdderValue] = input.value.trim();
  });
  if (Object.keys(adders).length) out.price_adders = adders;
  return out;
}

// What a reading found, one row per product, before anything is saved. A product whose sheet
// could not be read starts unticked: bringing it in would give a product with no codes.
function dgRenderImportPreview(body, res) {
  const out = body.querySelector("#dg-add-result");
  const isPdf = res.kind === "pdf";
  const items = res.items || [];
  const sheetMissing = function (it) { return !it.read_ok; };
  out.innerHTML =
    (isPdf ? "" : '<div class="dg-imp-head"><b>' + escapeHtml(res.page_title || "") + "</b>" +
      (res.category ? " · " + escapeHtml(res.category) : "") + " — " + items.length + " product" +
      (items.length === 1 ? "" : "s") + " on this page</div>") +
    '<div class="dg-imp-list">' + items.map(function (it) {
      const ex = it.existing;
      const ch = it.changes;
      const changeText = !ex ? "" : (!ch.fields.length && !ch.options.length
        ? "Already in the app and the same as the website says."
        : "Will change " + [ch.fields.length ? ch.fields.length + " detail" + (ch.fields.length === 1 ? "" : "s") : "",
                             ch.options.length ? ch.options.length + " option list" + (ch.options.length === 1 ? "" : "s") : ""]
            .filter(Boolean).join(" and ") + ".") +
        (it.codes ? " Its " + ch.codes_replaced + " code" + (ch.codes_replaced === 1 ? "" : "s") + " from " +
          escapeHtml(it.spec_sheet) + " are read again; " + ch.codes_kept + " other" + (ch.codes_kept === 1 ? "" : "s") +
          " (catalogue, typed in) stay." : "") + " Its approval stays as it is, and its prices change only if you change them below.";
      return '<div class="dg-imp-item' + (sheetMissing(it) ? " dg-imp-warn" : "") + '">' +
        '<label class="dg-imp-pick"><input type="checkbox" data-imp-key="' + attr(it.key) + '"' + (sheetMissing(it) ? "" : " checked") + ">" +
          '<span class="dg-imp-name">' + escapeHtml(it.product_name || "(no name)") + "</span>" +
          (ex ? '<span class="dg-pill dg-pill-info">Update #' + escapeHtml(String(ex.id)) + " · " +
                escapeHtml(ex.approval_status === "approved" ? "in the library" : ex.approval_status) + "</span>"
              : '<span class="dg-pill dg-pill-ok">New · will await approval</span>') +
        "</label>" +
        '<div class="muted dg-imp-meta">' + escapeHtml([it.series, it.family, it.spec_sheet].filter(Boolean).join(" · ")) + "</div>" +
        (isPdf ? '<div class="npd-fields dg-imp-identity">' +
            '<label>Series<input data-imp-series value="' + attr(it.series) + '" list="dg-series-list"></label>' +
            '<label>Product name<input data-imp-name value="' + attr(it.product_name) + '"></label>' +
            '<label>Size<input data-imp-family value="' + attr(it.family) + '"></label></div>' +
            (it.guessed ? '<div class="muted dg-imp-note">Series and name were read from the sheet’s heading — check them.</div>' : "")
          : "") +
        '<div class="dg-imp-facts">' +
          (it.codes ? '<span class="dg-pill dg-pill-ok">' + it.codes + " order code" + (it.codes === 1 ? "" : "s") + "</span> " +
            '<span class="dg-imp-codes">' + it.sample_codes.map(escapeHtml).join(", ") + (it.codes > it.sample_codes.length ? ", …" : "") + "</span>"
            : '<span class="dg-pill dg-pill-gap">No order codes read</span>') +
        "</div>" +
        '<div class="dg-imp-options">' + dgOptionSummary(it.options) + "</div>" +
        '<label class="dg-imp-typology">Typology <select data-imp-typology>' + dgTypologyOptions(ex ? ex.typology : it.typology) + "</select></label>" +
        dgImportPriceBoxes(it) +
        (changeText ? '<div class="dg-imp-note">' + changeText + "</div>" : "") +
        (ch && (ch.fields.length || ch.options.length) ? '<details class="dg-imp-diff"><summary>What changes</summary><table>' +
          ch.fields.map(function (f) {
            return "<tr><th>" + escapeHtml(f.label) + "</th><td>" + (dgValueChips(dgOptionList(f.before)) || "—") +
              "</td><td>→ " + (dgValueChips(dgOptionList(f.after)) || "—") + "</td></tr>";
          }).join("") +
          ch.options.map(function (o) {
            return "<tr><th>" + escapeHtml(prettifyFieldKey(o.key)) + " options</th><td>" + (dgValueChips(o.before) || "—") +
              "</td><td>→ " + (dgValueChips(o.after) || "—") + "</td></tr>";
          }).join("") + "</table></details>" : "") +
        (it.warnings.length ? '<ul class="dg-imp-warnings">' + it.warnings.map(function (w) { return "<li>" + escapeHtml(w) + "</li>"; }).join("") + "</ul>" : "") +
        "</div>";
    }).join("") + "</div>" +
    '<div class="dg-imp-actions"><span class="muted" id="dg-imp-count"></span>' +
    '<button class="btn primary" id="dg-imp-apply">Bring in</button></div>';

  const count = function () {
    const n = out.querySelectorAll("[data-imp-key]:checked").length;
    out.querySelector("#dg-imp-count").textContent = n + " of " + items.length + " ticked";
    const b = out.querySelector("#dg-imp-apply");
    b.disabled = !n;
    b.textContent = n === 1 ? "Bring in 1 product" : "Bring in " + n + " products";
  };
  out.querySelectorAll("[data-imp-key]").forEach(function (c) { c.addEventListener("change", count); });
  count();
  out.querySelector("#dg-imp-apply").addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      dgAddMessage(body, "");
      const chosen = [...out.querySelectorAll(".dg-imp-item")].filter(function (row) {
        return row.querySelector("[data-imp-key]").checked;
      }).map(function (row) {
        const pick = Object.assign({ key: row.querySelector("[data-imp-key]").dataset.impKey,
                                     typology: row.querySelector("[data-imp-typology]").value }, dgImportPricesOf(row));
        if (isPdf) {
          pick.series = row.querySelector("[data-imp-series]").value.trim();
          pick.product_name = row.querySelector("[data-imp-name]").value.trim();
          pick.family = row.querySelector("[data-imp-family]").value.trim();
        }
        return pick;
      });
      try {
        const res2 = await api("/api/npd/duragreen/import", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ token: res.token, items: chosen }),
        });
        state.specsheets = [];          // the library may have changed
        dgRenderImportDone(body, res2.results);
      } catch (err) { dgAddMessage(body, err.message); }
    });
  });
}

function dgRenderImportDone(body, results) {
  const added = results.filter(function (r) { return r.action === "added"; }).length;
  body.innerHTML =
    '<div class="dg-imp-done"><p><b>' + added + " added</b> (awaiting approval) and <b>" + (results.length - added) +
    " updated</b>. New products reach the BOQ pickers once they are approved here in NPD (DuraGreen).</p>" +
    '<ul class="dg-imp-results">' + results.map(function (r) {
      return "<li>" + escapeHtml(r.series + " — " + r.product_name) + " <span class=\"muted\">(" +
        escapeHtml(r.action === "added" ? "added" : "updated") + ", " + r.codes_written + " code" + (r.codes_written === 1 ? "" : "s") +
        ((r.price_changes || []).length ? ", " + r.price_changes.length + " price" + (r.price_changes.length === 1 ? "" : "s") + " set" : "") +
        ')</span> <button class="btn small ghost" data-imp-open="' + attr(String(r.id)) + '">Open</button></li>';
    }).join("") + "</ul></div>" +
    '<div class="modal-actions"><button class="btn primary" id="dg-imp-close">Done</button></div>';
  const finish = async function (openId) {
    closeModal();
    if (openId) { await dgOpenProduct(openId); return; }
    await renderNpd(currentRender());
  };
  body.querySelector("#dg-imp-close").addEventListener("click", function () { finish(null); });
  body.querySelectorAll("[data-imp-open]").forEach(function (b) {
    b.addEventListener("click", function () { finish(b.dataset.impOpen); });
  });
}

// ---------------------------------------------------------------- one DuraGreen product

async function dgOpenProduct(id) {
  let data;
  try {
    data = await api("/api/npd/duragreen/products/" + id);
  } catch (e) {
    alert("Could not open the product: " + e.message);
    return;
  }
  const draft = {
    fields: Object.assign({}, data.fields || {}),
    options: {},
    typology: data.typology || "",
    base_price: data.base_price == null ? "" : String(data.base_price),
    price_adders: JSON.parse(JSON.stringify(data.price_adders || {})),
    lists: {},                 // printed facts with several values, one box each
    addedOptionKeys: [],       // options an editor started quoting the product on, not yet saved
    // the naming structure a person put it in, and how it fills each segment (27 Oct)
    naming: data.naming ? { structure: data.naming.structure, modes: JSON.parse(JSON.stringify(data.naming.modes || {})) }
      : { structure: "", modes: {} },
  };
  (data.config_fields || []).forEach(function (k) {
    draft.options[k] = ((data.options || {})[k] || []).slice();
  });
  // A spec field that holds several values ("55 mm / 60 mm") is edited as a list; a quoted option
  // is not, since its option rows say the same - but a printed list the product is not quoted on
  // (optional accessories: "Honeycomb / Elliptical Lens / Solite lens") is.
  Object.keys(draft.fields).forEach(function (key) {
    if (draft.options[key] && draft.options[key].length) return;
    const vals = dgOptionList(draft.fields[key]);
    if (vals.length > 1) draft.lists[key] = vals;
  });
  dgView.open = { data: data, draft: draft, tester: {}, testResult: null, dirty: false,
                  combos: null, comboFilter: "", comboAll: false, addCode: null };
  dgRenderProduct();
}

// What a printed or tested configuration reads as: its values in the product's field order.
function dgVectorLabel(vector, fields) {
  return fields.filter(function (k) { return vector[k]; }).map(function (k) { return vector[k]; }).join(" · ");
}

// Sets the code tester to a whole configuration at once - a printed combination picked as one
// choice, or a row of the every-combination table - and asks the server for its code.
async function dgTry(vector) {
  const o = dgView.open;
  o.tester = Object.assign({}, vector || {});
  await dgRunTester();
}

async function dgRunTester() {
  const o = dgView.open;
  try {
    o.testResult = await api("/api/npd/duragreen/code", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sheet_id: o.data.id, chosen: o.tester }),
    });
  } catch (err) { o.testResult = { code: "", reason: err.message }; }
  dgRenderProduct();
}

// One row of the every-combination table, sorted into what a person needs to know first: the
// sheet prints it, the app builds it from DuraGreen's rules, it is built but unconfirmed, or
// there is no code (and why).
function dgComboKind(row) {
  if (row.printed && row.printed.length) return "printed";
  if (!row.code) return "none";
  return row.status === "unconfirmed" ? "unconfirmed" : "built";
}
const DG_COMBO_KINDS = [
  ["", "All"], ["printed", "Printed on the sheet"], ["built", "Built from DuraGreen's rules"],
  ["unconfirmed", "Unconfirmed"], ["none", "No code"],
];

function dgCombosHtml(o, fields) {
  const c = o.combos;
  const lede = '<p class="muted">Every combination of the options below, with the code each one gets: the ones DuraGreen ' +
    "prints on the spec sheet, the ones built from its rules (and how surely), and the ones with no code and why. " +
    "Worked out from the saved product" + (o.dirty ? " — save first to see your changes here" : "") + ".</p>";
  if (!c) {
    return lede + '<button class="btn small secondary" id="dg-combos-load">Show every combination</button>';
  }
  if (c.loading) return lede + '<p class="muted">Working out every combination…</p>';
  if (c.error) return lede + '<div class="error-box">' + escapeHtml(c.error) + "</div>";
  if (!c.fields.length) return lede + '<p class="muted">This product lists no options to combine.</p>';
  const counts = {};
  c.rows.forEach(function (r) { const k = dgComboKind(r); counts[k] = (counts[k] || 0) + 1; });
  const shownRows = c.rows.filter(function (r) { return !o.comboFilter || dgComboKind(r) === o.comboFilter; });
  const LIMIT = 150;
  const visible = o.comboAll ? shownRows : shownRows.slice(0, LIMIT);
  const chips = '<div class="npd-chips dg-combo-chips">' + DG_COMBO_KINDS.map(function (k) {
    const n = k[0] ? (counts[k[0]] || 0) : c.rows.length;
    return '<button type="button" class="config-tile small' + (o.comboFilter === k[0] ? " selected" : "") +
      '" data-dg-combo-filter="' + attr(k[0]) + '">' + escapeHtml(k[1]) + ' <span class="muted">(' + n + ")</span></button>";
  }).join("") + "</div>";
  const cap = c.total > c.rows.length
    ? '<p class="muted">The first ' + c.rows.length + " of " + c.total + " combinations are shown.</p>" : "";
  const table = '<div class="npd-ptable-scroll"><table class="dg-table dg-combos dg-lead-actions"><thead><tr><th></th>' +
    c.fields.map(function (k) { return "<th>" + escapeHtml(dgLabel(k)) + "</th>"; }).join("") +
    "<th>Code</th><th>How</th></tr></thead><tbody>" +
    visible.map(function (r) {
      const kind = dgComboKind(r);
      const idx = c.rows.indexOf(r);
      const codeCell = kind === "printed"
        ? '<span class="dg-code">' + escapeHtml(r.printed.join(", ")) + "</span>"
        : r.code
          ? '<span class="dg-code' + (r.status === "unconfirmed" ? " code-unconfirmed" : "") + '">' + escapeHtml(r.code) + "</span>" +
            (r.missing && r.missing.length ? ' <span class="muted">+ ' + escapeHtml(r.missing.map(dgLabel).join(", ")) + "</span>" : "")
          : '<span class="muted" title="' + attr(r.reason || "") + '">' + escapeHtml(r.reason || "No code") + "</span>";
      const how = kind === "printed" ? '<span class="dg-pill dg-pill-ok">On the spec sheet</span>'
        : r.code ? dgStatusPill(r.status) : '<span class="dg-pill dg-pill-gap">No code</span>';
      return '<tr class="dg-combo-' + kind + '"><td class="dg-row-actions"><button class="btn tiny ghost" data-dg-combo-try="' + idx +
        '" title="Load this combination into the code tester">Try</button></td>' +
        c.fields.map(function (k) { return "<td>" + escapeHtml(r.chosen[k] || "") + "</td>"; }).join("") +
        "<td>" + codeCell + "</td><td>" + how + "</td></tr>";
    }).join("") + "</tbody></table></div>";
  const more = !o.comboAll && shownRows.length > LIMIT
    ? '<button class="btn tiny ghost" id="dg-combos-all">Show all ' + shownRows.length + "</button>" : "";
  return lede + chips + cap + table + more;
}

// Options are written "6W / 8W / 10W" - a slash WITH spaces round it, NPD's own separator
// (npd.OPTION_SEPARATOR). A bare slash is part of a value: "On/off" and "0/1-10V" are one
// control each, and splitting on every slash would turn them into four.
function dgOptionList(text) {
  return String(text || "").split(/\s+\/\s+/).map(function (s) { return s.trim(); }).filter(Boolean);
}

// The NPD (DuraGreen) product page's two sides fill the window below the product's header, each
// scrolling on its own (style.css, .dg-layout). Measured, not assumed: the header's height depends
// on the product's name, buttons and picture, and the window's on the person's screen. Until 26 Oct
// each side was as tall as the window but started below the header, so its last 150-odd pixels
// hung below the screen and the wheel could never reach them. Only a window too short for any use
// (under ~500px) gets sides of DG_SPLIT_MIN that need the page scrolled a little to show them; a
// 1280x720 laptop at 125% zoom (576px) still fits them whole.
const DG_SPLIT_MIN = 240;

function dgFitLayout() {
  const layout = app.querySelector(".dg-layout");
  if (!layout) return;
  const top = layout.getBoundingClientRect().top + window.scrollY;   // from the top of the page
  layout.style.setProperty("--dg-h", Math.max(DG_SPLIT_MIN, Math.floor(window.innerHeight - top - 16)) + "px");
}

// Once per page load; a no-op on every other screen (no .dg-layout). One measurement per frame
// however many resize events a drag fires.
let dgFitQueued = false;
window.addEventListener("resize", function () {
  if (dgFitQueued) return;
  dgFitQueued = true;
  requestAnimationFrame(function () { dgFitQueued = false; dgFitLayout(); });
});

// The structure the product's draft is named by, or null.
function dgDraftStructure(o) {
  const name = o.draft.naming.structure;
  return name ? (o.data.naming_structures || []).find(function (s) { return s.name === name; }) || null : null;
}

// The options this product may be quoted on: DuraGreen's own, any it holds, and the details its
// naming structure (as the draft has it) chooses when quoting - a baffle style, a detail of its own.
function dgConfigFields(o) {
  const out = (o.data.config_fields || []).slice();
  const st = dgDraftStructure(o);
  if (st) {
    st.segments.forEach(function (seg) {
      const m = o.draft.naming.modes[seg.attribute];
      if (m && m.mode === "quoted" && out.indexOf(seg.attribute) < 0) out.push(seg.attribute);
    });
  }
  return out;
}

// "Naming" on the product page: which structure names it, and per segment whether it is fixed for
// this product, chosen when quoting (its options and prices are the rows under Specification and
// pricing), or not in its code. A product one of DuraGreen's catalogue pages names follows that page.
function dgNamingSectionHtml(o, mayEdit) {
  const d = o.data, nm = o.draft.naming;
  if (d.naming_locked && !nm.structure) {
    return '<p class="dg-scheme"><span class="dg-pill dg-pill-info">DuraGreen’s own naming</span> ' + escapeHtml(d.naming_locked) + "</p>";
  }
  const all = d.naming_structures || [];
  const opt = function (s) {
    return '<option value="' + attr(s.name) + '"' + (s.name === nm.structure ? " selected" : "") + ">" + escapeHtml(s.name) + "</option>";
  };
  const printed = all.filter(function (s) { return !s.made; }), made = all.filter(function (s) { return s.made; });
  const st = dgDraftStructure(o);
  const picker = '<div class="dg-nm-pickrow"><label>Named by<select id="dg-nm-structure"' + (mayEdit ? "" : " disabled") + ">" +
      '<option value="">Its own codes only — no structure</option>' +
      (printed.length ? '<optgroup label="DuraGreen’s code tables">' + printed.map(opt).join("") + "</optgroup>" : "") +
      (made.length ? '<optgroup label="Made in NPD">' + made.map(opt).join("") + "</optgroup>" : "") + "</select></label>" +
      (mayEdit ? '<button type="button" class="btn small ghost" id="dg-nm-make">+ Make a new structure</button>' : "") + "</div>";
  const lede = '<p class="muted">How DuraGreen names it. A product no catalogue page names can follow one of DuraGreen’s code tables — ' +
    "ACME’s, if it is an ACME fitting — or a structure made for its range. Each segment is then fixed for this product, chosen " +
    "when it is quoted (its options and what each adds to the price are under Specification and pricing), or not part of its code." +
    (d.naming_locked ? " Its catalogue page names it too: take it out of the structure to follow the page." : "") + "</p>";
  if (!st) return lede + picker;
  const optionsOf = function (k) { return (o.draft.options[k] || []).filter(Boolean); };
  const table = dgNamingRowsHtml({
    segments: st.segments, modes: nm.modes, identity: d.identity_keys || [], mayEdit: mayEdit,
    quotedHtml: function (seg) {
      const vals = optionsOf(seg.attribute);
      const unused = seg.entries.filter(function (e) { return vals.indexOf(e.meaning) < 0; });
      return (vals.length ? dgValueChips(vals) : '<span class="muted">No options yet</span>') +
        (mayEdit && seg.attribute !== "wattage" && unused.length
          ? ' <button type="button" class="btn tiny ghost" data-nm-fill="' + attr(seg.attribute) + '">+ ' +
              (vals.length ? "the other " + unused.length : "all " + unused.length) + " from the structure</button>" : "") +
        '<div class="muted dg-nm-hint">Options and prices: Specification and pricing</div>';
    },
    codeOf: function (seg, m) {
      if (m.mode === "fixed") return dgNamingFixedCode(seg, m.value);
      if (m.mode === "quoted") return '<span class="muted">per option</span>';
      return "";
    },
  });
  // a detail fixed here while it still lists options would still be asked by the Configurator
  const clash = st.segments.filter(function (seg) {
    const m = nm.modes[seg.attribute];
    return m && m.mode !== "quoted" && optionsOf(seg.attribute).length > 1;
  });
  return lede + picker + table +
    (clash.length ? '<p class="dg-piece-note">' + escapeHtml(clash.map(function (s) { return s.segment; }).join(", ")) +
      " still list" + (clash.length === 1 ? "s" : "") + " several options below — remove them, or the Configurator will still ask.</p>" : "") +
    '<p class="muted">Saved with the product. The tester and the table of every combination then build its codes from ' +
    escapeHtml(st.name) + "’s letters — a code DuraGreen printed or sent for a configuration still comes first.</p>";
}

function dgRenderProduct() {
  const o = dgView.open;
  const d = o.data, draft = o.draft;
  // Each side scrolls on its own (26 Oct); a redraw - every Try, every option typed - must leave
  // both where the person had them, not jump them back to the top.
  const kept = app.querySelector(".dg-layout[data-dg-id='" + d.id + "']")
    ? { main: app.querySelector(".dg-main").scrollTop, side: app.querySelector(".dg-side").scrollTop } : null;
  const mayEdit = can("npd.edit"), mayPrice = can("prices.edit");
  const ro = function (ok) { return ok ? "" : " disabled"; };
  const configFields = dgConfigFields(o);
  // the options as the person has them now - a row being typed may still be empty
  const optionsOf = function (k) { return (draft.options[k] || []).filter(Boolean); };
  // a quoted option is shown as InHouse NPD shows one: a row per option, its code and its adder
  const isOptionRow = function (k) {
    return configFields.indexOf(k) >= 0 && ((draft.options[k] || []).length || draft.addedOptionKeys.indexOf(k) >= 0);
  };

  // Every value its own row, never "A / B / C" in one box (owner, 27 Oct): a quoted option as a
  // table of option, code, how sure and the amount it adds - InHouse NPD's - and a printed fact
  // with several values (two cut-outs, two input voltages) as a list of values.
  const optionRowHtml = function (k, label) {
    const rows = draft.options[k] || [];
    return '<div class="dg-wide dg-prow"><div class="npd-cap">' + escapeHtml(label) + "</div>" +
      '<div class="npd-optlist dg-optlist"><div class="npd-optlist-head"><span>Option</span><span>Code</span>' +
        "<span>Adds to base price</span><span></span></div>" +
      rows.map(function (v, i) {
        const add = (draft.price_adders[k] || {})[v];
        return '<div class="npd-optrow"><input data-dg-opt="' + attr(k) + '" data-i="' + i + '" value="' + attr(v) + '"' +
            ro(mayEdit) + ' aria-label="' + attr(label + " option " + (i + 1)) + '">' +
          '<span class="npd-optcode" data-dg-codecell="' + attr(k) + '" data-i="' + i + '">' + dgOptionCodeCell(o.nomen, k, v) + "</span>" +
          '<span class="npd-money-input small"><span class="npd-rupee">+₹</span><input type="number" min="0" step="0.01"' +
            ' data-dg-optadd="' + attr(k) + '" data-i="' + i + '" value="' + attr(add == null ? "" : add) + '" placeholder="0"' +
            ro(mayPrice) + ' aria-label="' + attr("Amount " + (v || "this option") + " adds") + '"></span>' +
          (mayEdit ? '<button type="button" class="npd-optdel" data-dg-optdel="' + attr(k) + '" data-i="' + i +
            '" title="Remove this option">×</button>' : "<span></span>") +
          "</div>";
      }).join("") +
      (mayEdit ? '<button type="button" class="npd-optadd" data-dg-optnew="' + attr(k) + '">+ Add option</button>' : "") +
      "</div></div>";
  };
  const valueListHtml = function (key, label) {
    const vals = draft.lists[key] || [];
    return '<div class="dg-wide dg-prow"><div class="npd-cap">' + escapeHtml(label) + "</div>" +
      '<div class="npd-optlist dg-vallist">' + vals.map(function (v, i) {
        return '<div class="npd-optrow"><input data-dg-val="' + attr(key) + '" data-i="' + i + '" value="' + attr(v) + '"' +
          ro(mayEdit) + ' aria-label="' + attr(label + " value " + (i + 1)) + '">' +
          (mayEdit ? '<button type="button" class="npd-optdel" data-dg-valdel="' + attr(key) + '" data-i="' + i +
            '" title="Remove this value">×</button>' : "<span></span>") + "</div>";
      }).join("") +
      (mayEdit ? '<button type="button" class="npd-optadd" data-dg-valnew="' + attr(key) + '">+ Add value</button>' : "") +
      "</div></div>";
  };
  const inGroups = {};
  const groupsHtml = (d.groups || []).map(function (g) {
    return '<div class="npd-group"><div class="npd-group-head">' + escapeHtml(g.group) + "</div>" +
      '<div class="npd-fields">' + g.items.map(function (it) {
        inGroups[it.key] = true;
        if (isOptionRow(it.key)) return optionRowHtml(it.key, it.label);
        if (draft.lists[it.key]) return valueListHtml(it.key, it.label);
        return '<label>' + escapeHtml(it.label) + '<input data-dg-field="' + attr(it.key) + '" value="' +
          attr(draft.fields[it.key] || "") + '"' + ro(mayEdit) + "></label>";
      }).join("") + "</div></div>";
  }).join("");
  // Quoted options the spec groups do not hold - a version, a mounting, a bezel and a baffle
  // finish - and, for an editor, any option the product could be quoted on but is not yet.
  const quotedOnly = configFields.filter(function (k) { return !inGroups[k] && isOptionRow(k); });
  const notOffered = configFields.filter(function (k) { return !isOptionRow(k); });
  const quotedHtml = quotedOnly.length || (mayEdit && notOffered.length)
    ? '<div class="npd-group"><div class="npd-group-head">Quoted options</div><div class="npd-fields">' +
        quotedOnly.map(function (k) { return optionRowHtml(k, dgLabel(k)); }).join("") +
        (mayEdit && notOffered.length
          ? '<label class="dg-wide dg-add-option">Quote it on another option<select id="dg-add-option">' +
              '<option value="">Choose an option…</option>' + notOffered.map(function (k) {
                return '<option value="' + attr(k) + '">' + escapeHtml(dgLabel(k)) + "</option>"; }).join("") +
            "</select></label>" : "") +
      "</div></div>" : "";
  const baseHtml = '<div class="npd-basebar dg-basebar"><label class="npd-base">Base price' +
      '<span class="npd-money-input"><span class="npd-rupee">₹</span><input type="number" min="0" step="0.01" id="dg-base" value="' +
      attr(draft.base_price) + '"' + ro(mayPrice) + ' placeholder="not priced"></span></label>' +
      '<p class="npd-basenote">Every configuration starts here, and each option below can <strong>add</strong> to it. ' +
      "Blank means not priced yet: a BOQ line then starts at 0 and is priced by hand.</p></div>";

  // Wattage and optics are already in "Orders"; only what the row adds beyond the configuration
  // gets a column of its own, so the table fits the panel and its remove button stays in view.
  const printedCols = ["lumens", "lumens_92ra", "lumens_98ra", "efficacy", "length"];
  // Headed as the sheet's own table heads them ("lm system(92Ra)"), short enough to fit the panel.
  const DG_PRINTED_LABEL = { lumens: "lm", lumens_92ra: "lm Ra92", lumens_98ra: "lm Ra98", efficacy: "lm/W", length: "Length" };
  const shownCols = printedCols.filter(function (c) { return (d.order_codes || []).some(function (r) { return r.printed[c]; }); });
  // One column per option the codes are told apart by - wattage, CCT, beam, driver; a track's
  // length and colour - so a person sees at a glance which combinations the sheet prints.
  const vf = d.vector_fields || [];
  const printedRows = (d.order_codes || []).filter(function (c) { return !/\(code example\)/.test(c.source || ""); });
  const codesHtml = (d.order_codes || []).length
    ? '<div class="npd-ptable-scroll"><table class="dg-table dg-lead-actions"><thead><tr><th></th><th>Order code</th>' +
        vf.map(function (k) { return "<th>" + escapeHtml(dgLabel(k)) + "</th>"; }).join("") +
        shownCols.map(function (c) { return "<th>" + escapeHtml(DG_PRINTED_LABEL[c] || prettifyFieldKey(c)) + "</th>"; }).join("") +
        "<th></th></tr></thead><tbody>" +
      d.order_codes.map(function (c) {
        // Where the code came from rides on the code itself, as a hover note - the panel is
        // narrow, and a column of the same file name on every row pushed the remove button off it.
        // The catalogue's worked example is the code's template, not a code to order: said so.
        const isExample = /\(code example\)/.test(c.source || "");
        const entered = /^entered by/.test(c.source || "");
        const from = "From " + (c.source || "the spec sheet") + ((c.printed || {}).note ? " - " + c.printed.note : "");
        // A value the sheet's table does not state for the row ("?30": its code says 30, its
        // table not which CCT) is shown as the code's own piece, not as one of the options.
        const cells = isExample
          ? '<td class="dg-orders" colspan="' + Math.max(1, vf.length) + '">' + escapeHtml("Catalogue example (p." +
              ((c.printed || {}).page || "?") + ") - the code's template") + "</td>"
          : vf.map(function (k) {
              const v = (c.config || {})[k];
              const fromCode = k === "cct" && (c.printed || {}).cct_from_code;
              return "<td>" + (v == null ? '<span class="muted">—</span>'
                : /^\?/.test(v) ? '<span class="muted" title="The sheet does not say; the code has ' + attr(v.slice(1)) + '">' + escapeHtml(v.slice(1)) + " ?</span>"
                : escapeHtml(v) + (fromCode ? ' <span class="muted" title="The table prints these rows alike; the code ends in ' +
                    attr(fromCode) + ', DuraGreen\'s way of writing this CCT">(from the code)</span>' : "")) + "</td>";
            }).join("");
        // The row's buttons come first: the option columns make the table wide, and buttons at
        // its far end scrolled out of sight.
        return '<tr' + (isExample ? ' class="dg-example-row"' : "") + '><td class="dg-row-actions">' +
          (isExample ? "" : '<button class="btn tiny ghost" data-dg-try-code="' + c.id + '" title="Load this combination into the code tester">Try</button>') +
          (mayEdit ? '<button class="btn tiny ghost dg-del" data-dg-del-code="' + c.id + '" title="Remove this code">✕</button>' : "") +
          '</td><td class="dg-code" title="' + attr(from) + '">' +
          escapeHtml(c.code) + (entered ? ' <span class="dg-pill dg-pill-info" title="' + attr(from) + '">entered</span>' : "") + "</td>" +
          cells + shownCols.map(function (col) { return "<td>" + escapeHtml(c.printed[col] || "") + "</td>"; }).join("") +
          "</tr>";
      }).join("") + "</tbody></table></div>"
    : '<p class="muted">DuraGreen prints no order code table for this product. Add the codes DuraGreen sends below.</p>';

  const partsHtml = (d.code_parts || []).length
    ? '<div class="npd-ptable-scroll"><table class="dg-table"><thead><tr><th>Option</th><th>Value</th><th>Code part</th><th>How sure</th><th></th></tr></thead><tbody>' +
      d.code_parts.map(function (p) {
        return "<tr><td>" + escapeHtml(dgLabel(p.attribute)) + "</td><td>" + escapeHtml(p.value) + '</td><td class="dg-code">' +
          // Where the part came from, and why, ride on the badge as a hover note - a column of its
          // own pushed the remove button out of the panel.
          escapeHtml(p.code) + '</td><td><span class="dg-pill ' + (p.status === "stated" ? "dg-pill-ok" : "dg-pill-warn") + '" title="' +
          attr([p.source && "From " + p.source.replace(/_/g, " "), p.note].filter(Boolean).join(" - ")) + '">' +
          escapeHtml(p.status) + "</span></td><td>" +
          (mayEdit ? '<button class="btn tiny ghost dg-del" data-dg-del-part="' + p.id + '" title="Remove this code part">✕</button>' : "") +
          "</td></tr>";
      }).join("") + "</tbody></table></div>"
    : '<p class="muted">No code parts recorded.</p>';

  // Every field the product is quoted on - a luminaire's wattage and CCT, a track's length, a
  // track feed's polarity groove - so the tester asks what a BOQ line would be asked.
  const testerFields = configFields.filter(function (k) { return optionsOf(k).length; });
  const r = o.testResult;
  // How each piece of the tested code was found - the first row is the printed code (or the
  // catalogue example) the chosen pieces were put into.
  const piecesHtml = r && r.code && (r.pieces || []).length
    ? '<table class="dg-table dg-pieces dg-readonly"><thead><tr><th>Piece</th><th>For</th><th>Code</th><th>From</th></tr></thead><tbody>' +
      r.pieces.map(function (p) {
        return "<tr><td>" + escapeHtml(p.field === "pattern" ? "Pattern" : dgLabel(p.field)) + "</td><td>" + escapeHtml(p.value || "") +
          '</td><td class="dg-code">' + escapeHtml(p.code) + '</td><td title="' + attr([p.source, p.note].filter(Boolean).join(" - ")) + '">' +
          // the full source rides on the hover; the cell keeps it short enough for the side panel
          escapeHtml((p.source || "").replace(/_/g, " ").replace(/^2026 General Catalogue /, "cat. ")) +
          (p.status === "unconfirmed" ? " " + dgStatusPill("unconfirmed") +
            // why it is unconfirmed is the point of the row, so it is read, not hovered for
            (p.note ? '<div class="dg-piece-note">' + escapeHtml(p.note) + "</div>" : "") : "") + "</td></tr>";
      }).join("") + "</tbody></table>"
    : "";
  // A printed combination picked as one choice: every option it states set at once, so a person
  // starts from what DuraGreen actually prints rather than assembling it option by option.
  const usablePrinted = printedRows.filter(function (c) { return Object.keys(c.vector || {}).length; });
  const sameVector = function (c) {
    const keys = Object.keys(c.vector || {});
    return keys.length && keys.every(function (k) { return o.tester[k] === c.vector[k]; });
  };
  const pickedPrinted = usablePrinted.find(sameVector);
  const printedPick = usablePrinted.length
    ? '<label class="npd-f-wide">Printed combination <span class="muted">(' + usablePrinted.length + " on the spec sheet)</span>" +
        '<select id="dg-test-printed"><option value="">Choose a combination DuraGreen prints…</option>' +
        usablePrinted.map(function (c) {
          return '<option value="' + c.id + '"' + (pickedPrinted && pickedPrinted.id === c.id ? " selected" : "") + ">" +
            escapeHtml(dgVectorLabel(c.vector, configFields) + "  →  " + c.code) + "</option>";
        }).join("") + "</select></label>"
    : '<p class="muted">The spec sheet prints no code this product\'s options can pick out - every code below is built.</p>';
  // After a built code, a person who has DuraGreen's own answer for this combination can record it.
  const canRecord = mayEdit && r && r.status && r.status !== "printed" && !(r.missing || []).length;
  // A code a person typed in is used as DuraGreen's own, but the badge says where it came from.
  const enteredHit = r && r.status === "printed" && (r.pieces || []).length && /^entered by/.test(r.pieces[0].source || "");
  const resultPill = enteredHit
    ? '<span class="dg-pill dg-pill-ok" title="' + attr(r.pieces[0].source) + '">Entered in NPD from DuraGreen</span>'
    : r ? dgStatusPill(r.status) : "";
  const testerHtml = '<div class="npd-fields">' + printedPick + testerFields.map(function (k) {
      const opts = optionsOf(k);
      return "<label>" + escapeHtml(dgLabel(k)) + '<select data-dg-test="' + attr(k) + '">' +
        (opts.length > 1 ? '<option value="">Choose…</option>' : "") +
        opts.map(function (v) { return '<option value="' + attr(v) + '"' + (o.tester[k] === v ? " selected" : "") + ">" + escapeHtml(v) + "</option>"; }).join("") +
        "</select></label>";
    }).join("") + "</div>" +
    '<div class="dg-test-out' + (r && r.code ? "" : " empty") + '">' + (r
      ? (r.code ? '<span class="dg-code dg-code-big' + (r.status === "unconfirmed" ? " code-unconfirmed" : "") + '">' + escapeHtml(r.code) + "</span>" +
          resultPill : "") +
        (r.code && r.status !== "printed" ? '<div class="dg-not-printed">Not printed on the spec sheet for this combination — built as shown below.</div>' : "") +
        '<div class="muted">' + escapeHtml(r.reason || "") + "</div>" + piecesHtml +
        (canRecord ? '<button class="btn tiny secondary" id="dg-record">Record DuraGreen\'s code for this combination…</button>' : "")
      : '<div class="muted">Pick a printed combination, or choose options, to see the code a BOQ line would get.</div>') + "</div>";

  // How DuraGreen builds this product's code: the catalogue page's worked example with its
  // legend, then its range's code table - so a person can check a built code against the page.
  const cr = d.code_rules || {};
  const trackSystem = (d.params || {})["TRACK SYSTEM"] || null;
  // Whose rules write this product's code, in a sentence: ACME's and MOOD's tables are their own
  // ranges' rules, never a step light's or a pendant's (owner, 22 Oct 2026).
  const sc = d.scheme || {};
  const DG_SCHEME_BADGE = { ACME: "ACME range", MOOD: "MOOD range", EVOLINE: "EVOLINE range", PAGE: "Its own page and sheet",
                            SHEET: "Its own sheet only", NONE: "No printed code",
                            STRUCTURE: "Named by " + (sc.range || "a structure") };
  // the saved structure (the side panel shows what is saved; the Naming section shows the draft)
  const namedBy = d.naming ? (d.naming_structures || []).find(function (s) { return s.name === d.naming.structure; }) || null : null;
  const schemeHtml = sc.name
    ? '<div class="dg-scheme"><span class="dg-pill ' + (sc.name === "NONE" ? "dg-pill-gap" : "dg-pill-info") + '">' +
        escapeHtml(DG_SCHEME_BADGE[sc.name] || sc.name) + "</span> " + escapeHtml(sc.text || "") + "</div>"
    : "";
  const rulesHtml = schemeHtml + (cr.example
    ? '<p class="muted">From DuraGreen\'s 2026 General Catalogue, p.' + escapeHtml(String(cr.page || "?")) + ". Example: " +
        '<span class="dg-code">' + escapeHtml(cr.example) + "</span>" +
        (cr.adapted ? " — the page prints pattern " + escapeHtml(cr.adapted.style[0]) + " (" +
          escapeHtml(cr.adapted.page_example) + "); this product is pattern " + escapeHtml(cr.adapted.style[1]) +
          ", as its own codes show." : "") + "</p>" +
      (cr.left_out && cr.left_out.length
        ? '<p class="muted">' + dgStatusPill("unconfirmed") + " The page's example leaves out " + escapeHtml(cr.left_out.join(", ")) +
          " that its own legend lists, so it is not used to build codes on its own.</p>" : "") +
      '<div class="npd-ptable-scroll"><table class="dg-table dg-readonly"><thead><tr><th>Piece</th><th>Code</th><th>Means</th></tr></thead><tbody>' +
        (cr.legend || []).map(function (l) {
          return "<tr><td>" + escapeHtml(dgLabel(l[0])) + '</td><td class="dg-code">' + escapeHtml(l[1]) + "</td><td>" + escapeHtml(l[2]) + "</td></tr>";
        }).join("") + "</tbody></table></div>" +
      '<details class="dg-add"><summary>' + escapeHtml(cr.table) + " code table" +
        (cr.table_is_general ? " — for reference only: not this product's rule" : "") +
        "</summary>" + (cr.table_source ? '<p class="muted">' + escapeHtml(cr.table_source) +
          (cr.table_is_general ? ". This product is not an " + escapeHtml(cr.table) + " downlight, so a piece taken from this table is marked unconfirmed." : "") +
          "</p>" : "") +
        '<div class="npd-ptable-scroll"><table class="dg-table dg-readonly"><tbody>' +
        (cr.segments || []).map(function (s) {
          return "<tr><td>" + escapeHtml(s.segment) + (s.dash_after ? " –" : "") + "</td><td>" +
            s.entries.map(function (e) { return '<span class="dg-code">' + escapeHtml(e.code) + "</span> " + escapeHtml(e.meaning); }).join("<br>") +
            "</td></tr>";
        }).join("") + "</tbody></table></div></details>"
    : trackSystem
      // A track part is not built from a rule: its sheet prints every code in full - the part's
      // own code and its colour letter - and the app uses them exactly as printed.
      ? '<p class="muted">DuraGreen prints every code for this part in full' +
          (trackSystem["Colour letter"] ? " — the part's own code, then its colour letter (" + escapeHtml(trackSystem["Colour letter"]) + ")" : "") +
          ". They are used exactly as printed; nothing is built.</p>" +
        '<div class="npd-ptable-scroll"><table class="dg-table dg-readonly"><tbody>' +
        Object.keys(trackSystem).map(function (k) {
          return "<tr><td>" + escapeHtml(k) + "</td><td>" + escapeHtml(trackSystem[k]) + "</td></tr>";
        }).join("") + "</tbody></table></div>"
      : namedBy
        // a product a person put in a structure: that structure, as DuraGreen (or NPD) writes it
        ? '<p class="muted">' + escapeHtml(namedBy.name) + " — " + escapeHtml(namedBy.made ? "made in NPD" : namedBy.source) + "</p>" +
          dgNamingRibbonHtml(namedBy.segments)
        : "");        // the scheme line above already says it has no catalogue page

  // A code DuraGreen printed or sent, with the options it orders. The options are chosen from
  // the product's own words, so the code is found when a BOQ line chooses the same ones. From
  // then on it is used as DuraGreen's own code - so the code box is never filled in for the
  // person: a built code (shown greyed, for comparison) is not DuraGreen's answer.
  const ac = o.addCode || {};
  const addCodeHtml = mayEdit
    ? '<details class="dg-add" id="dg-ac"' + (o.addCode ? " open" : "") + '><summary>Add an order code DuraGreen printed or sent</summary>' +
        '<p class="muted">Every option it orders, then the code exactly as DuraGreen gives it. A BOQ line choosing the same ' +
        "options gets this code as DuraGreen's own.</p><div class=\"npd-fields\">" +
        testerFields.map(function (k) {
          const opts = optionsOf(k), cur = (ac.vector || {})[k] || "";
          return "<label>" + escapeHtml(dgLabel(k)) + '<select data-dg-ac="' + attr(k) + '"><option value="">' +
            (opts.length > 1 ? "Not stated" : "—") + "</option>" +
            opts.map(function (v) { return '<option value="' + attr(v) + '"' + (cur === v ? " selected" : "") + ">" + escapeHtml(v) + "</option>"; }).join("") +
            "</select></label>";
        }).join("") +
        '<label class="npd-f-wide">Code<input id="dg-ac-code" autocomplete="off" placeholder="' +
          attr(ac.built ? "built: " + ac.built + " — type DuraGreen's own" : "e.g. AFL5706W-27D24") + '"></label>' +
        '<label class="npd-f-wide">Where it came from<input id="dg-ac-note" placeholder="e.g. DuraGreen email, 22 Oct · spec sheet p.2"></label>' +
      '</div><button class="btn small secondary" id="dg-ac-save">Add code</button></details>' +
      '<details class="dg-add"><summary>Record what one option adds to the code</summary><div class="npd-fields">' +
        '<label>Option<select id="dg-ap-attr">' + ["cct", "control", "beam_angle", "wattage"].map(function (k) {
          return '<option value="' + attr(k) + '">' + escapeHtml(dgLabel(k)) + "</option>"; }).join("") + "</select></label>" +
        '<label>Value<input id="dg-ap-value" placeholder="e.g. 2700K"></label>' +
        '<label>Code part<input id="dg-ap-code" placeholder="e.g. 27"></label>' +
        '<label class="npd-f-wide">Note<input id="dg-ap-note" placeholder="e.g. DuraGreen email, 20 Oct"></label>' +
      '</div><button class="btn small secondary" id="dg-ap-save">Add code part</button></details>'
    : "";

  app.innerHTML =
    '<div class="npd-head"><div>' + npdBrandPickerHtml() +
      '<button class="btn tiny ghost" id="dg-back">← All DuraGreen products</button>' +
      "<h2>" + escapeHtml(d.product_name || "Untitled") + " " + npdStatusTag(d.approval_status) + "</h2>" +
      '<p class="muted npd-lede">' + escapeHtml([d.series, d.family, d.variant].filter(Boolean).join(" · ")) + "</p>" +
      '<div class="row-actions">' +
        (d.pdf_url ? '<a class="btn small secondary" href="' + attr(d.pdf_url) + '" target="_blank" rel="noopener">DuraGreen spec sheet</a>' : "") +
        (d.source_url ? '<a class="btn small secondary" href="' + attr(d.source_url) + '" target="_blank" rel="noopener">Website page ↗</a>' : "") +
        (can("npd.approve") ? dgStatusActions(d) : "") +
      "</div></div>" +
      '<div class="dg-head-img">' + (d.thumb_url ? '<img src="' + attr(d.thumb_url) + '" alt="">' : "") + "</div>" +
    "</div>" +
    '<div class="dg-layout" data-dg-id="' + attr(String(d.id)) + '">' +
    '<div class="dg-main dg-pane" tabindex="0" aria-label="Product details, codes and how the code is built">' +
      '<section class="npd-step"><h3>Classification</h3><div class="npd-fields"><label>Typology<input id="dg-typology" value="' +
        attr(draft.typology) + '"' + ro(mayEdit) + ' list="dg-typ-list"></label><datalist id="dg-typ-list">' +
        [...new Set(dgView.products.map(function (p) { return p.typology; }).filter(Boolean))].sort().map(function (t) {
          return '<option value="' + attr(t) + '">'; }).join("") + "</datalist></div></section>" +
      '<section class="npd-step dg-nm-step" id="dg-nm-step"><h3>Naming</h3>' + dgNamingSectionHtml(o, mayEdit) + "</section>" +
      '<section class="npd-step"><h3>Specification and pricing</h3>' +
        '<p class="muted">As an engineer reads the spec sheet. An option row is what the Configurator offers when this ' +
        "product is added to a BOQ, with the code DuraGreen writes for it and what it adds to the price.</p>" +
        baseHtml + groupsHtml + quotedHtml + "</section>" +
      '<div class="npd-save-bar"><span class="muted" id="dg-save-msg">' + (o.dirty ? "Unsaved changes" : "") + "</span>" +
        (mayEdit || mayPrice ? '<button class="btn primary" id="dg-save"' + (o.dirty ? "" : " disabled") + ">Save</button>" : "") + "</div>" +
      // The code tables are wide - a column per option - so they live here, beside the tester,
      // which stays in view in the side panel while a row is tried.
      '<section class="npd-step"><h3>Order codes printed in the spec sheet</h3>' +
        '<p class="muted">The combinations DuraGreen prints a code for. <b>Try</b> loads one into the code tester.</p>' +
        codesHtml + addCodeHtml + "</section>" +
      '<section class="npd-step" id="dg-combos"><h3>Codes for every combination</h3>' + dgCombosHtml(o, vf) + "</section>" +
      '<section class="npd-step dg-nomen" id="dg-nomen"><h3>How this product\'s code is built</h3>' +
        dgNomenHtml(o.nomen) + "</section>" +
    "</div>" +
    '<aside class="dg-side dg-pane" tabindex="0" aria-label="Order code tester and code rules">' +
      '<section class="npd-step"><h3>Order code tester</h3>' + testerHtml + "</section>" +
      '<section class="npd-step"><h3>How DuraGreen builds this code</h3>' + rulesHtml + "</section>" +
      '<section class="npd-step"><h3>What each option adds to the code</h3>' + partsHtml + "</section>" +
    "</aside></div>";

  // The two sides fill the window below the header before a kept position is put back - a side
  // shorter than its old position would cut it short. The header's picture changes its height
  // when it arrives, so it is measured again then.
  dgFitLayout();
  const headImg = app.querySelector(".dg-head-img img");
  if (headImg && !headImg.complete) headImg.addEventListener("load", dgFitLayout, { once: true });
  if (kept) {
    // put back at once: with smooth scrolling on, a restore would visibly glide from the top
    [[".dg-main", kept.main], [".dg-side", kept.side]].forEach(function (pair) {
      const pane = app.querySelector(pair[0]);
      pane.style.scrollBehavior = "auto";
      pane.scrollTop = pair[1];
      pane.style.scrollBehavior = "";
    });
  }
  if (!o.nomen && !o.nomenLoading) dgLoadNomenclature();

  npdBindBrandPicker();
  const markDirty = function () {
    o.dirty = true;
    const b = app.querySelector("#dg-save");
    if (b) b.disabled = false;
    app.querySelector("#dg-save-msg").textContent = "Unsaved changes";
  };
  app.querySelector("#dg-back").addEventListener("click", function () {
    if (o.dirty && !confirm("Leave without saving your changes?")) return;
    dgView.open = null;
    renderNpd(currentRender());
  });
  app.querySelectorAll("[data-dg-field]").forEach(function (inp) {
    inp.addEventListener("input", function () { draft.fields[inp.dataset.dgField] = inp.value; markDirty(); });
  });
  // A quoted option's rows. Its adder is kept by the option's value, so renaming an option carries
  // its adder with it; the code column and the tester follow once the box is left.
  app.querySelectorAll("[data-dg-opt]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      const k = inp.dataset.dgOpt, i = Number(inp.dataset.i), list = draft.options[k];
      const old = list[i], adders = draft.price_adders[k] || {};
      list[i] = inp.value;
      if (old && old in adders && !(inp.value in adders)) {
        adders[inp.value] = adders[old];
        delete adders[old];
      }
      markDirty();
    });
    inp.addEventListener("change", dgRenderProduct);
  });
  app.querySelectorAll("[data-dg-optadd]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      const k = inp.dataset.dgOptadd, opt = (draft.options[k] || [])[Number(inp.dataset.i)];
      if (!opt) return;
      draft.price_adders[k] = draft.price_adders[k] || {};
      if (inp.value === "") delete draft.price_adders[k][opt];
      else draft.price_adders[k][opt] = inp.value;
      markDirty();
    });
  });
  app.querySelectorAll("[data-dg-optdel]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      const k = btn.dataset.dgOptdel, gone = draft.options[k].splice(Number(btn.dataset.i), 1)[0];
      if (draft.price_adders[k]) delete draft.price_adders[k][gone];
      markDirty();
      dgRenderProduct();
    });
  });
  app.querySelectorAll("[data-dg-optnew]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      const k = btn.dataset.dgOptnew;
      draft.options[k] = (draft.options[k] || []).concat([""]);
      dgRenderProduct();
      app.querySelector('[data-dg-opt="' + k + '"][data-i="' + (draft.options[k].length - 1) + '"]')?.focus();
    });
  });
  app.querySelector("#dg-add-option")?.addEventListener("change", function (e) {
    const k = e.target.value;
    if (!k) return;
    draft.addedOptionKeys.push(k);
    draft.options[k] = (draft.options[k] || []).concat([""]);
    dgRenderProduct();
    app.querySelector('[data-dg-opt="' + k + '"]')?.focus();
  });
  // A printed fact with several values, one box each; stored as before ("A / B").
  app.querySelectorAll("[data-dg-val]").forEach(function (inp) {
    inp.addEventListener("input", function () { draft.lists[inp.dataset.dgVal][Number(inp.dataset.i)] = inp.value; markDirty(); });
  });
  app.querySelectorAll("[data-dg-valdel]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      draft.lists[btn.dataset.dgValdel].splice(Number(btn.dataset.i), 1);
      markDirty();
      dgRenderProduct();
    });
  });
  app.querySelectorAll("[data-dg-valnew]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      const key = btn.dataset.dgValnew;
      draft.lists[key].push("");
      dgRenderProduct();
      app.querySelector('[data-dg-val="' + key + '"][data-i="' + (draft.lists[key].length - 1) + '"]')?.focus();
    });
  });
  app.querySelector("#dg-typology")?.addEventListener("input", function (e) { draft.typology = e.target.value; markDirty(); });
  // Naming (27 Oct): the structure, then how each of its segments is filled.
  const identity = d.identity_keys || [];
  const namingDefaults = function () {
    const st = dgDraftStructure(o);
    if (st) {
      dgNamingDefaults(st.segments, draft.naming.modes, function (k) { return (draft.options[k] || []).filter(Boolean); },
                       function (k) { return draft.fields[k]; }, identity);
    }
  };
  app.querySelector("#dg-nm-structure")?.addEventListener("change", function (e) {
    draft.naming.structure = e.target.value;
    namingDefaults();
    markDirty();
    dgRenderProduct();
  });
  const nmStep = app.querySelector("#dg-nm-step");
  if (nmStep) {
    dgNamingRowsBind(nmStep, draft.naming.modes, dgRenderProduct, function (a, mode) {
      markDirty();
      // chosen when quoting: its options are rows under Specification and pricing - one to start
      if (mode === "quoted" && !(draft.options[a] || []).length) {
        draft.options[a] = [""];
        if (draft.addedOptionKeys.indexOf(a) < 0) draft.addedOptionKeys.push(a);
      }
    });
  }
  app.querySelectorAll("[data-nm-fill]").forEach(function (b) {
    b.addEventListener("click", function () {
      const a = b.dataset.nmFill, st = dgDraftStructure(o);
      const seg = st && st.segments.find(function (s) { return s.attribute === a; });
      if (!seg) return;
      const have = (draft.options[a] || []).filter(Boolean);
      draft.options[a] = have.concat(seg.entries.map(function (e) { return e.meaning; }).filter(function (v) { return have.indexOf(v) < 0; }));
      if (draft.addedOptionKeys.indexOf(a) < 0) draft.addedOptionKeys.push(a);
      markDirty();
      dgRenderProduct();
    });
  });
  // A structure made from here is chosen for this product at once; the unsaved form stays as it is.
  app.querySelector("#dg-nm-make")?.addEventListener("click", function () {
    dgStructureEditorModal(null, async function (res) {
      try {
        o.data = await api("/api/npd/duragreen/products/" + d.id);
      } catch (err) { alert(err.message); return; }
      draft.naming.structure = res.name;
      namingDefaults();
      o.dirty = true;
      dgRenderProduct();
    });
  });
  app.querySelector("#dg-base")?.addEventListener("input", function (e) { draft.base_price = e.target.value; markDirty(); });
  app.querySelector("#dg-save")?.addEventListener("click", function (e) { withBusy(e.currentTarget, dgSave); });
  app.querySelectorAll("[data-dg-test]").forEach(function (sel) {
    sel.addEventListener("change", function () {
      o.tester[sel.dataset.dgTest] = sel.value;
      dgRunTester();
    });
  });
  // A printed combination, picked as one choice - from the tester's list or a printed row.
  const codeById = function (id) { return (d.order_codes || []).find(function (c) { return String(c.id) === String(id); }); };
  app.querySelector("#dg-test-printed")?.addEventListener("change", function (e) {
    const c = codeById(e.target.value);
    if (c) dgTry(c.vector);
  });
  app.querySelectorAll("[data-dg-try-code]").forEach(function (b) {
    b.addEventListener("click", function () {
      const c = codeById(b.dataset.dgTryCode);
      if (c) dgTry(c.vector);
    });
  });
  app.querySelector("#dg-record")?.addEventListener("click", function () {
    o.addCode = { vector: Object.assign({}, o.tester), built: (o.testResult || {}).code || "" };
    dgRenderProduct();
    const box = app.querySelector("#dg-ac-code");
    if (box) { box.scrollIntoView({ block: "center" }); box.focus(); }
  });
  app.querySelector("#dg-combos-load")?.addEventListener("click", async function (e) {
    o.combos = { loading: true };
    dgRenderProduct();
    try {
      o.combos = await api("/api/npd/duragreen/products/" + d.id + "/combinations");
    } catch (err) { o.combos = { error: "Could not work out the combinations: " + err.message }; }
    dgRenderProduct();
  });
  app.querySelectorAll("[data-dg-combo-filter]").forEach(function (b) {
    b.addEventListener("click", function () {
      o.comboFilter = b.dataset.dgComboFilter;
      o.comboAll = false;
      dgRenderProduct();
    });
  });
  app.querySelector("#dg-combos-all")?.addEventListener("click", function () { o.comboAll = true; dgRenderProduct(); });
  app.querySelectorAll("[data-dg-combo-try]").forEach(function (b) {
    b.addEventListener("click", function () {
      const row = (o.combos.rows || [])[Number(b.dataset.dgComboTry)];
      if (row) dgTry(row.chosen);
    });
  });
  app.querySelectorAll("[data-dg-del-code]").forEach(function (b) {
    b.addEventListener("click", function () {
      if (!confirm("Remove this order code? It is recorded in the activity log.")) return;
      withBusy(b, async function () {
        try { await api("/api/npd/duragreen/codes/" + b.dataset.dgDelCode, { method: "DELETE" }); await dgReopen(); }
        catch (err) { alert(err.message); }
      });
    });
  });
  app.querySelectorAll("[data-dg-del-part]").forEach(function (b) {
    b.addEventListener("click", function () {
      if (!confirm("Remove this code part? It is recorded in the activity log.")) return;
      withBusy(b, async function () {
        try { await api("/api/npd/duragreen/parts/" + b.dataset.dgDelPart, { method: "DELETE" }); await dgReopen(); }
        catch (err) { alert(err.message); }
      });
    });
  });
  app.querySelector("#dg-ac-save")?.addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      const config = {};
      app.querySelectorAll("[data-dg-ac]").forEach(function (inp) { if (inp.value.trim()) config[inp.dataset.dgAc] = inp.value.trim(); });
      try {
        await api("/api/npd/duragreen/products/" + d.id + "/codes", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ code: app.querySelector("#dg-ac-code").value, config: config,
                                 note: app.querySelector("#dg-ac-note").value }),
        });
        await dgReopen();
      } catch (err) { alert(err.message); }
    });
  });
  app.querySelector("#dg-ap-save")?.addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      try {
        await api("/api/npd/duragreen/products/" + d.id + "/parts", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ attribute: app.querySelector("#dg-ap-attr").value, value: app.querySelector("#dg-ap-value").value,
                                 code: app.querySelector("#dg-ap-code").value, note: app.querySelector("#dg-ap-note").value }),
        });
        await dgReopen();
      } catch (err) { alert(err.message); }
    });
  });
  app.querySelectorAll("[data-dg-set-status]").forEach(function (b) {
    b.addEventListener("click", function () { dgSetStatus(b.dataset.id, b.dataset.dgSetStatus, b); });
  });
}

// After a code or part changes: the codes come from the server, the unsaved form stays.
async function dgReopen() {
  const o = dgView.open;
  o.data = await api("/api/npd/duragreen/products/" + o.data.id);
  o.testResult = null;
  o.addCode = null;
  o.combos = null;      // worked out from the codes, which just changed
  o.nomen = null;       // so is how the code is built
  dgRenderProduct();
}

// "How this product's code is built" (26 Oct): fetched once the page is drawn, and put into its
// own section so the panes keep their place.
async function dgLoadNomenclature() {
  const o = dgView.open;
  if (!o) return;
  const id = o.data.id;
  o.nomenLoading = true;
  try {
    const n = await api("/api/npd/duragreen/products/" + id + "/nomenclature");
    if (!dgView.open || dgView.open.data.id !== id) return;
    o.nomen = n;
  } catch (e) {
    o.nomen = { error: e.message };
  } finally {
    o.nomenLoading = false;
  }
  const box = app.querySelector("#dg-nomen");
  if (box) box.innerHTML = "<h3>How this product's code is built</h3>" + dgNomenHtml(o.nomen);
  // the Code column of the option rows reads the same answer; filled in place, so a person typing
  // in a box above it is not interrupted by a redraw
  app.querySelectorAll("[data-dg-codecell]").forEach(function (cell) {
    const k = cell.dataset.dgCodecell;
    cell.innerHTML = dgOptionCodeCell(o.nomen, k, (o.draft.options[k] || [])[Number(cell.dataset.i)]);
  });
}

const DG_NOMEN_SOURCE = { code_legend: "its spec sheet's legend" };
// Short names for the option table, where the full badge on every row wrapped into large bubbles;
// the full sentence is on hover.
const DG_STATUS_SHORT = { printed: "Printed", composed: "Its own codes", catalogue: "Range table",
                          general: "Own range", pattern: "Own pattern", unconfirmed: "Unconfirmed", none: "No code" };

// The Code cell of a quoted option's row: what DuraGreen writes for it and how sure that is, from
// the product's nomenclature (dgLoadNomenclature) - the same answer as the tester and the table at
// the foot. An option typed since the last save has no answer until it is saved.
function dgOptionCodeCell(nomen, field, value) {
  if (!value) return "";
  if (!nomen) return '<span class="muted">…</span>';
  if (nomen.error) return '<span class="muted" title="' + attr(nomen.error) + '">?</span>';
  const opt = (nomen.options || []).find(function (x) { return x.field === field; });
  if (!opt) return '<span class="muted" title="Not a piece of this product\'s order code">—</span>';
  if (opt.how) return '<span class="muted" title="' + attr(opt.how) + '">picks the version</span>';
  const hit = (opt.values || []).find(function (x) { return x.value === value; });
  if (!hit) return '<span class="muted" title="Save to see the code DuraGreen writes for it">save to see</span>';
  return (hit.code ? '<code class="dg-optcode">' + escapeHtml(hit.code) + "</code>" : "") +
    dgShortPill(hit.status).replace('title="', 'title="' + attr(hit.note ? hit.note + " - " : ""));
}

function dgShortPill(status) {
  const s = status || "none";
  const cls = s === "none" ? "dg-pill-gap" : s === "unconfirmed" ? "dg-pill-warn" : s === "general" ? "dg-pill-info" : "dg-pill-ok";
  return '<span class="dg-pill ' + cls + ' dg-pill-short" title="' + attr(DG_STATUS_BADGE[s] || "No code") + '">' +
    escapeHtml(DG_STATUS_SHORT[s] || s) + "</span>";
}

function dgNomenSource(src) {
  return DG_NOMEN_SOURCE[src] || src || "";
}

function dgNomenHtml(n) {
  if (!n) return '<p class="muted">Working out how this product\'s code is built…</p>';
  if (n.error) return '<p class="error-box">Could not work it out: ' + escapeHtml(n.error) + "</p>";
  const used = new Set();
  (n.options || []).forEach(function (op) { op.values.forEach(function (v) { used.add(v.status || "none"); }); });
  if (n.printed) used.add("printed");
  const structure = (n.structure || []).length
    ? '<div class="dg-nomen-structure" aria-label="The code, piece by piece">' + n.structure.map(function (p) {
        return p.dash ? '<span class="dg-nomen-dash">' + escapeHtml(p.token) + "</span>"
          : '<span class="dg-nomen-piece' + (p.fixed ? " fixed" : "") + '"><code>' + escapeHtml(p.token) + "</code>" +
            "<small>" + escapeHtml(p.label) + (p.fixed ? " · fixed" : "") + "</small></span>";
      }).join("") + "</div>" +
      '<p class="muted dg-nomen-cap">Example: <span class="dg-code">' + escapeHtml(n.example) + "</span>. " +
      "A fixed piece is this product's own and never changes; every other piece follows the option chosen.</p>"
    : '<p class="muted">DuraGreen prints no code for this product, so there is no structure to read.</p>';
  const order = '<ol class="dg-nomen-order">' + (n.order || []).map(function (s) {
    const pill = dgShortPill(s.status);
    return '<li class="' + (used.has(s.status) ? "used" : "unused") + '">' + pill + " " + escapeHtml(s.text) + "</li>";
  }).join("") + "</ol>";
  const rows = (n.options || []).map(function (op) {
    return op.values.map(function (v, i) {
      const pill = op.how ? '<span class="muted">' + escapeHtml(op.how) + "</span>"
        : dgShortPill(v.code ? v.status : "none");
      return "<tr>" + (i === 0 ? '<th scope="rowgroup" rowspan="' + op.values.length + '">' + escapeHtml(op.label) + "</th>" : "") +
        "<td>" + escapeHtml(v.value) + '</td><td class="dg-code">' + escapeHtml(v.code || "—") + "</td><td>" + pill + "</td>" +
        '<td class="muted">' + escapeHtml(dgNomenSource(v.source)) + (v.note ? '<div class="dg-piece-note">' + escapeHtml(v.note) + "</div>" : "") + "</td></tr>";
    }).join("");
  }).join("");
  return '<p class="dg-scheme">' + escapeHtml((n.scheme && n.scheme.text) || "") + "</p>" +
    "<h4>The code, piece by piece</h4>" + structure +
    "<h4>Where each piece comes from, surest first</h4>" + order +
    (rows ? '<h4>What every option adds to the code</h4><div class="dg-nomen-scroll"><table class="dg-table dg-readonly dg-nomen-table">' +
      "<thead><tr><th>Option</th><th>Value</th><th>Code</th><th>How sure</th><th>From</th></tr></thead><tbody>" + rows +
      "</tbody></table></div>" : "") +
    ((n.documents || []).length ? '<h4>DuraGreen\'s documents used</h4><ul class="dg-nomen-docs">' +
      n.documents.map(function (d) { return "<li>" + escapeHtml(dgNomenSource(d)) + "</li>"; }).join("") + "</ul>" : "");
}

async function dgSave() {
  const o = dgView.open, d = o.data, draft = o.draft;
  const options = {};
  dgConfigFields(o).forEach(function (k) {
    options[k] = (draft.options[k] || []).map(function (v) { return String(v).trim(); }).filter(Boolean);
  });
  // a list goes back the way the field has always been stored, so nothing that reads it changes
  const fields = Object.assign({}, draft.fields);
  Object.keys(draft.lists).forEach(function (key) {
    fields[key] = draft.lists[key].map(function (v) { return String(v).trim(); }).filter(Boolean).join(" / ");
  });
  const body = { fields: fields, options: options, typology: draft.typology };
  // How it is named goes with the specification - not for a product its catalogue page names.
  const st = dgDraftStructure(o);
  if (!(d.naming_locked && !d.naming)) {
    body.naming = dgNamingPayload(draft.naming.structure, st ? st.segments : [], draft.naming.modes);
  }
  if (can("prices.edit")) {
    body.base_price = draft.base_price === "" ? null : Number(draft.base_price);
    // only the adders of options the product still has
    const adders = {};
    Object.keys(draft.price_adders).forEach(function (k) {
      (options[k] || []).forEach(function (opt) {
        const v = (draft.price_adders[k] || {})[opt];
        if (v !== undefined && v !== "") (adders[k] = adders[k] || {})[opt] = v;
      });
    });
    body.price_adders = adders;
  }
  try {
    await api("/api/npd/duragreen/products/" + d.id, {
      method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
    });
    state.specsheets = [];        // the Library and Configurator read these values
    dgNaming.data = null;         // the Nomenclature tab files products by how they are named
    await dgOpenProduct(d.id);
    app.querySelector("#dg-save-msg").textContent = "Saved.";
  } catch (e) {
    app.querySelector("#dg-save-msg").textContent = e.message;
  }
}

// ---------------- Naming: DuraGreen's own (27 Oct 2026) ----------------
//
// The Nomenclature tab shows how a brand names its products. InHouse's is the studio's own product
// code (npdCodes above); DuraGreen's is DuraGreen's: its code tables (ACME, MOOD, EVOLINE ...), each a
// row of segments with their letters, and every product filed under the naming it follows. The owner,
// 27 Oct 2026: "always follow DuraGreen product naming" - and a new product with new codes must fit an
// existing structure (ACME's) or one a person makes, with every detail theirs to decide: fixed in NPD,
// chosen in the Configurator, priced by its adder. Nothing here changes what DuraGreen printed: a code a
// person adds is marked "entered", and only those can be removed. The codes themselves are always the
// server's (app/duragreen.py, structure_code) - this file only shows them.

const DG_MAKE = "Duragreen";
const dgNaming = { data: null, loading: false, error: "", pick: "", query: "", adding: null };

// The details a segment can name, as NPD (DuraGreen) labels them (duragreen.LABEL_OF). A segment of
// a structure made here may also name a detail of its own, keyed from its name.
const DG_NAMING_ATTRS = [
  ["type", "Type"], ["size", "Engine / size"], ["wattage", "System power"], ["style", "Baffle style"],
  ["trim", "Bezel style"], ["cct", "CCT"], ["control", "Control / driver"], ["beam_angle", "Optics / beam"],
  ["bezel_finish", "Bezel finish"], ["baffle_finish", "Baffle finish"], ["finish", "Finish"],
  ["accessories", "Accessories"], ["cri", "CRI"], ["voltage", "Voltage"], ["mounting", "Mounting"],
  ["length", "Length"], ["variant", "Version"],
];
// What a detail of its own is keyed as: "Lens colour" -> lens_colour.
function dgNamingKeyOf(label) {
  return String(label || "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").replace(/^(\d)/, "d$1").slice(0, 40);
}
function dgNamingLabel(key, fallback) {
  const hit = DG_NAMING_ATTRS.find(function (a) { return a[0] === key; });
  return hit ? hit[1] : (fallback || prettifyFieldKey(key));
}

// The classes a product nobody put in a structure is filed under (duragreen.naming_class).
const DG_NAMING_CLASSES = {
  PAGE: ["Its own catalogue page", "DuraGreen’s catalogue prints a page for these with its own worked example and legend, but no " +
    "code table for their range: each code follows its page and its spec sheet. Grouped by the letters DuraGreen starts the code with."],
  SHEET: ["Its own spec sheet", "No page of DuraGreen’s 2026 catalogue shows these: each code follows the codes its spec sheet " +
    "prints. Grouped by the letters DuraGreen starts the code with."],
  NONE: ["No code yet", "DuraGreen prints no code for these, on a spec sheet or in the catalogue. Open one to put it in a naming " +
    "structure, or to add the codes DuraGreen sends."],
};

function dgNamingHtml() {
  return '<div class="npd-ptables dg-naming" id="dg-naming">' + dgNamingInnerHtml() + "</div>";
}

async function dgNamingLoad(force) {
  if (dgNaming.data && !force) { dgNamingRender(); return; }
  // the old answer is dropped first: drawn while the new one loads, it would not know a structure
  // just made, and the class picked (that structure) would fall back to the first one
  dgNaming.data = null;
  dgNaming.loading = true;
  dgNaming.error = "";
  dgNamingRender();
  try {
    dgNaming.data = await api("/api/npd/duragreen/naming");
  } catch (e) {
    dgNaming.error = e.message;
  } finally {
    dgNaming.loading = false;
  }
  dgNamingRender();
}

function dgNamingRender() {
  const box = app.querySelector("#dg-naming");
  if (!box) return;
  box.innerHTML = dgNamingInnerHtml();
  dgNamingBind(box);
}

// Every class, in the order a person reads DuraGreen: its code tables, the structures made here, then
// the products named by their own page or sheet, and those with no code at all.
function dgNamingClasses(d) {
  const count = {};
  d.products.forEach(function (p) { count[p.class] = (count[p.class] || 0) + 1; });
  const out = d.structures.map(function (st) {
    return { key: st.name, label: st.name, count: count[st.name] || 0, structure: st };
  });
  Object.keys(DG_NAMING_CLASSES).forEach(function (k) {
    if (count[k]) out.push({ key: k, label: DG_NAMING_CLASSES[k][0], count: count[k], structure: null });
  });
  return out;
}

function dgNamingInnerHtml() {
  const mayEdit = can("npd.edit");
  const head = '<div class="npd-ptables-head"><h4>Naming</h4><span class="npd-codes-brand">DuraGreen</span>' +
    (mayEdit ? '<button class="btn small primary" id="dg-nm-new">+ New naming structure</button>' : "") + "</div>" +
    '<p class="npd-ptables-lede">DuraGreen names every product by its own order code. Most follow one of its <b>code tables</b> — ' +
    "a row of segments (type, size, power …), each with its letters; the rest their own catalogue page or spec sheet. A product " +
    "no catalogue page names can be put in a structure: one of DuraGreen’s tables, or one made here for codes DuraGreen has sent. " +
    "What DuraGreen printed never changes here — a code you add is marked <b>entered</b>.</p>";
  if (dgNaming.error) return head + '<div class="error-box">Could not load DuraGreen’s naming: ' + escapeHtml(dgNaming.error) + "</div>";
  const d = dgNaming.data;
  if (!d) {
    return head + '<div class="npd-codes-stats"><div class="npd-codes-stat npd-skel-tile"></div><div class="npd-codes-stat npd-skel-tile"></div>' +
      '<div class="npd-codes-stat npd-skel-tile"></div></div><div class="npd-codes-grid"><div class="npd-codes-card npd-skel-card"></div></div>';
  }
  const classes = dgNamingClasses(d);
  if (!classes.some(function (c) { return c.key === dgNaming.pick; })) {
    dgNaming.pick = (classes.find(function (c) { return c.count; }) || classes[0] || {}).key || "";
  }
  const cur = classes.find(function (c) { return c.key === dgNaming.pick; });
  const inTables = d.products.filter(function (p) { return p.structure; }).length;
  const byClass = function (k) { return d.products.filter(function (p) { return p.class === k; }).length; };
  const stats = '<div class="npd-codes-stats dg-nm-stats">' +
    dgNamingStat(d.products.length, "DuraGreen products", d.structures.length + " naming structures") +
    dgNamingStat(inTables, "Follow a code table", "ACME, MOOD … or one made in NPD", "ok") +
    dgNamingStat(byClass("PAGE") + byClass("SHEET"), "Named by their own page or sheet", "the codes DuraGreen prints for them") +
    dgNamingStat(byClass("NONE"), "No code yet", "open one to name it", byClass("NONE") ? "warn" : "") + "</div>";
  const chip = function (c) {
    return '<button type="button" class="config-tile small' + (c.key === dgNaming.pick ? " selected" : "") + '" data-dg-nm-pick="' + attr(c.key) + '">' +
      escapeHtml(c.label) + ' <span class="muted">(' + c.count + ")</span>" +
      (c.structure && c.structure.made ? ' <span class="dg-pill dg-pill-info dg-pill-short">made in NPD</span>' : "") + "</button>";
  };
  const tables = classes.filter(function (c) { return c.structure && !c.structure.made; });
  const made = classes.filter(function (c) { return c.structure && c.structure.made; });
  const own = classes.filter(function (c) { return !c.structure; });
  const facets = '<section class="npd-classify dg-nm-facets">' +
    '<div class="npd-facet"><span class="npd-facet-label">DuraGreen’s code tables</span><div class="npd-chips">' + tables.map(chip).join("") + "</div></div>" +
    (made.length ? '<div class="npd-facet"><span class="npd-facet-label">Made in NPD</span><div class="npd-chips">' + made.map(chip).join("") + "</div></div>" : "") +
    (own.length ? '<div class="npd-facet"><span class="npd-facet-label">Named by itself</span><div class="npd-chips">' + own.map(chip).join("") + "</div></div>" : "") +
    "</section>";
  const body = !cur ? '<p class="muted">DuraGreen has no products here yet.</p>'
    : cur.structure ? dgNamingStructureHtml(cur.structure, d) : dgNamingClassHtml(cur.key, d);
  return head + stats + facets + '<div class="dg-nm-body">' + body + "</div>";
}

function dgNamingStat(n, label, sub, tone) {
  return '<div class="npd-codes-stat' + (tone ? " " + tone : "") + '"><span class="npd-codes-stat-fig">' + escapeHtml(String(n)) + "</span>" +
    '<span class="npd-codes-stat-label">' + escapeHtml(label) + "</span>" +
    (sub ? '<span class="npd-codes-stat-sub">' + escapeHtml(sub) + "</span>" : "") + "</div>";
}

// The code, segment by segment, each with a letter it can take - DuraGreen's own way of printing it
// ("AFL 50 08W - C - TL - 30 N 24 - W B S").
function dgNamingRibbonHtml(segments) {
  return '<div class="dg-nomen-structure dg-nm-ribbon" aria-label="The code, segment by segment">' + segments.map(function (seg) {
    const first = (seg.entries[0] || {}).code || "…";
    return '<span class="dg-nomen-piece"><code>' + escapeHtml(first) + "</code><small>" + escapeHtml(seg.segment) + "</small></span>" +
      (seg.dash_after ? '<span class="dg-nomen-dash">-</span>' : "");
  }).join("") + "</div>";
}

function dgNamingStructureHtml(st, d) {
  const mayEdit = can("npd.edit");
  const mine = d.products.filter(function (p) { return p.class === st.name; });
  const actions = st.made && mayEdit
    ? '<button class="btn small secondary" data-dg-nm-edit="' + attr(String(st.id)) + '">Edit structure</button>' +
      (mine.length ? "" : '<button class="btn small danger" data-dg-nm-remove="' + attr(String(st.id)) + '">Remove</button>')
    : "";
  const rows = st.segments.map(function (seg) {
    const adding = dgNaming.adding && dgNaming.adding.structure === st.name && dgNaming.adding.position === seg.position;
    const letters = seg.entries.map(function (e) {
      return '<span class="dg-nm-letter' + (e.entered ? " entered" : "") + '" title="' + attr(e.source || "") + '"><code>' +
        escapeHtml(e.code) + "</code> " + escapeHtml(e.meaning) +
        (e.entered && !st.made ? ' <span class="dg-pill dg-pill-info dg-pill-short">entered</span>' +
          (mayEdit && e.id ? '<button type="button" class="dg-nm-x" data-dg-nm-del="' + attr(String(e.id)) + '" title="Remove this code" aria-label="' +
            attr("Remove " + e.code + " = " + e.meaning) + '">×</button>' : "") : "") + "</span>";
    }).join("") || '<span class="muted">No letters yet</span>';
    const addForm = adding
      ? '<div class="dg-nm-addform"><input id="dg-nm-a-code" placeholder="Code, e.g. 2765" aria-label="Code">' +
        '<input id="dg-nm-a-meaning" placeholder="What it means, e.g. 2700K-6500K" aria-label="What it means">' +
        '<input id="dg-nm-a-note" placeholder="Where it came from, e.g. DuraGreen email, 27 Oct" aria-label="Where it came from">' +
        '<button type="button" class="btn small primary" id="dg-nm-a-save">Add</button>' +
        '<button type="button" class="btn small ghost" id="dg-nm-a-cancel">Cancel</button></div>'
      : (mayEdit && !st.made ? '<button type="button" class="btn tiny ghost dg-nm-addbtn" data-dg-nm-add="' + attr(String(seg.position)) +
          '">+ Add a code DuraGreen sent</button>' : "");
    return '<tr><th scope="row">' + escapeHtml(seg.segment) +
      (seg.dash_after ? ' <span class="muted" title="A dash follows this segment">then –</span>' : "") + "</th>" +
      '<td class="muted">' + escapeHtml(dgNamingLabel(seg.attribute, seg.segment)) + "</td>" +
      '<td><div class="dg-nm-letters">' + letters + "</div>" + addForm + "</td></tr>";
  }).join("");
  const editions = (st.editions || []).length
    ? st.editions.map(function (ed) {
        return '<details class="dg-add"><summary>' + escapeHtml(ed.name) + " — an earlier edition, for reference</summary>" +
          '<p class="muted">' + escapeHtml(ed.source) + ". Read only for a meaning the newest table does not list, and only where the " +
          "editions agree.</p>" + dgNamingRibbonHtml(ed.segments) + "</details>";
      }).join("") : "";
  return '<div class="npd-codes-card dg-nm-card"><div class="npd-codes-card-head"><h5>' + escapeHtml(st.name) +
      " <small>" + (st.made ? "made in NPD" + (st.created_by ? " by " + escapeHtml(st.created_by) : "") : escapeHtml(st.source)) + "</small></h5>" +
      actions + "</div>" +
      (st.description ? '<p class="muted">' + escapeHtml(st.description) + "</p>" : "") +
      dgNamingRibbonHtml(st.segments) +
      '<div class="npd-ptable-scroll"><table class="dg-table dg-nm-table"><thead><tr><th>Segment</th><th>Names</th><th>Letters</th></tr></thead><tbody>' +
      rows + "</tbody></table></div>" + editions + "</div>" +
    '<div class="npd-codes-card dg-nm-card"><div class="npd-codes-card-head"><h5>Products named by ' + escapeHtml(st.name) +
      " <small>" + mine.length + "</small></h5></div>" + dgNamingSearchHtml() +
      (mine.length ? dgNamingProductsHtml(mine, function (p) { return p.series || "Other"; }, null)
        : '<p class="muted">No product follows it yet. Open a product with no catalogue page in NPD (DuraGreen) and choose ' +
          escapeHtml(st.name) + " under Naming, or add one by hand.</p>") + "</div>";
}

function dgNamingClassHtml(key, d) {
  const mine = d.products.filter(function (p) { return p.class === key; });
  const meaning = function (letters) {
    const said = (d.letters || {})[letters];
    return said && said.length ? " — " + said.join(" · ") : "";
  };
  const groupOf = key === "NONE" ? function (p) { return p.series || "Other"; }
    : function (p) { return p.letters || "?"; };
  return '<div class="npd-codes-card dg-nm-card"><div class="npd-codes-card-head"><h5>' + escapeHtml(DG_NAMING_CLASSES[key][0]) +
    " <small>" + mine.length + "</small></h5></div>" +
    '<p class="muted">' + escapeHtml(DG_NAMING_CLASSES[key][1]) + "</p>" + dgNamingSearchHtml() +
    dgNamingProductsHtml(mine, groupOf, key === "NONE" ? null : meaning) + "</div>";
}

function dgNamingSearchHtml() {
  return '<div class="npd-facet npd-facet-search dg-nm-search"><input type="search" id="dg-nm-q" placeholder="Search name, series, code…" value="' +
    attr(dgNaming.query) + '"></div>';
}

// The products of one class, under a heading per group (a DuraGreen range, or the letters its codes
// start with), each with the code that shows how it is named.
function dgNamingProductsHtml(list, groupOf, meaningOf) {
  const q = dgNaming.query.trim().toLowerCase();
  const rows = list.filter(function (p) {
    return !q || [p.product_name, p.series, p.family, p.typology, p.example].join(" ").toLowerCase().indexOf(q) >= 0;
  });
  if (!rows.length) return '<p class="muted">Nothing matches.</p>';
  const groups = new Map();
  rows.forEach(function (p) {
    const k = groupOf(p);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(p);
  });
  return [...groups.keys()].sort(function (a, b) { return a.localeCompare(b); }).map(function (k) {
    const items = groups.get(k);
    return '<h4 class="dg-range-head">' + (meaningOf ? '<span class="dg-code">' + escapeHtml(k) + "</span>" + escapeHtml(meaningOf(k)) : escapeHtml(k)) +
      ' <span class="muted">(' + items.length + ")</span></h4>" +
      '<div class="dg-nm-products">' + items.map(function (p) {
        return '<div class="dg-nm-prod">' +
          (p.thumb_url ? '<img src="' + attr(p.thumb_url) + '" alt="" loading="lazy">' : '<span class="dg-nm-noimg"></span>') +
          '<span class="dg-nm-prod-text"><span class="dg-nm-prod-name">' + escapeHtml(p.product_name || "Untitled") +
            npdStatusTag(p.approval_status) + "</span>" +
            '<span class="muted">' + escapeHtml([p.series, p.typology || "Unclassified"].filter(Boolean).join(" · ")) + "</span>" +
            (p.example ? '<span class="dg-code" title="' + attr(p.page ? "Its catalogue example, p." + p.page
              : p.printed ? "A code its spec sheet prints" : "Its code as its naming structure builds it") + '">' +
              escapeHtml(p.example) + "</span>" : "") +
            (p.by_person ? '<span class="dg-pill dg-pill-info dg-pill-short" title="Put in this structure in NPD">named in NPD</span>' : "") +
          "</span>" +
          '<button type="button" class="btn tiny secondary" data-dg-nm-open="' + attr(String(p.id)) + '">Open</button></div>';
      }).join("") + "</div>";
  }).join("");
}

// From the Nomenclature tab to the product in NPD (DuraGreen): renderDuragreenNpd opens dgView.open.
function dgOpenFromNomenclature(id) {
  npdView.npdBrand = DG_MAKE;
  try { localStorage.setItem("npd.brand", DG_MAKE); } catch (e) { /* remembered for this visit only */ }
  npdView.editing = null;
  dgView.open = { data: { id: Number(id) } };
  setView("npd");
}

function dgNamingBind(box) {
  box.querySelectorAll("[data-dg-nm-pick]").forEach(function (b) {
    b.addEventListener("click", function () {
      dgNaming.pick = b.dataset.dgNmPick;
      dgNaming.adding = null;
      dgNaming.query = "";       // a search typed in another class would hide this one's products
      dgNamingRender();
    });
  });
  const q = box.querySelector("#dg-nm-q");
  let timer = null;
  q?.addEventListener("input", function () {
    dgNaming.query = q.value;
    clearTimeout(timer);
    timer = setTimeout(function () {
      dgNamingRender();
      const again = app.querySelector("#dg-nm-q");
      if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
    }, 250);
  });
  box.querySelectorAll("[data-dg-nm-open]").forEach(function (b) {
    b.addEventListener("click", function () { dgOpenFromNomenclature(b.dataset.dgNmOpen); });
  });
  box.querySelector("#dg-nm-new")?.addEventListener("click", function () {
    dgStructureEditorModal(null, function (res) { dgNaming.pick = res.name; dgNamingLoad(true); });
  });
  const structureById = function (id) {
    return (dgNaming.data.structures || []).find(function (s) { return String(s.id) === String(id); });
  };
  box.querySelectorAll("[data-dg-nm-edit]").forEach(function (b) {
    b.addEventListener("click", function () {
      dgStructureEditorModal(structureById(b.dataset.dgNmEdit), function (res) { dgNaming.pick = res.name; dgNamingLoad(true); });
    });
  });
  box.querySelectorAll("[data-dg-nm-remove]").forEach(function (b) {
    b.addEventListener("click", function () {
      const st = structureById(b.dataset.dgNmRemove);
      if (!st || !confirm("Remove the naming structure " + st.name + "? No product follows it. It is recorded in the activity log.")) return;
      withBusy(b, async function () {
        try {
          await api("/api/npd/duragreen/structures/" + st.id, { method: "DELETE" });
          dgNaming.pick = "";
          await dgNamingLoad(true);
        } catch (e) { alert(e.message); }
      });
    });
  });
  box.querySelectorAll("[data-dg-nm-add]").forEach(function (b) {
    b.addEventListener("click", function () {
      dgNaming.adding = { structure: dgNaming.pick, position: Number(b.dataset.dgNmAdd) };
      dgNamingRender();
      app.querySelector("#dg-nm-a-code")?.focus();
    });
  });
  box.querySelector("#dg-nm-a-cancel")?.addEventListener("click", function () { dgNaming.adding = null; dgNamingRender(); });
  box.querySelector("#dg-nm-a-save")?.addEventListener("click", function (e) {
    withBusy(e.currentTarget, async function () {
      const v = function (id) { return box.querySelector(id).value.trim(); };
      try {
        await api("/api/npd/duragreen/structures/entries", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ structure: dgNaming.adding.structure, position: dgNaming.adding.position,
                                 code: v("#dg-nm-a-code"), meaning: v("#dg-nm-a-meaning"), note: v("#dg-nm-a-note") }),
        });
        dgNaming.adding = null;
        await dgNamingLoad(true);
      } catch (err) { alert(err.message); }
    });
  });
  box.querySelectorAll("[data-dg-nm-del]").forEach(function (b) {
    b.addEventListener("click", function () {
      if (!confirm("Remove this code? It was entered in NPD; every product that used it loses it. It is recorded in the activity log.")) return;
      withBusy(b, async function () {
        try {
          await api("/api/npd/duragreen/rules/" + b.dataset.dgNmDel, { method: "DELETE" });
          await dgNamingLoad(true);
        } catch (e) { alert(e.message); }
      });
    });
  });
}

// ---- making and changing a naming structure
//
// Drawn into any box, so the same editor works in its own window (Nomenclature) and inside "Add a
// DuraGreen product" without closing the product being typed in.
function dgStructureEditorModal(st, onSaved) {
  const modal = openModal('<span class="close-x" title="Close">✕</span><div id="dg-se-box"></div>', "modal-lg");
  modal.querySelector(".close-x").addEventListener("click", closeModal);
  dgStructureEditorInto(modal.querySelector("#dg-se-box"), st, {
    onSaved: function (res) { closeModal(); if (onSaved) onSaved(res); },
    onCancel: closeModal,
  });
}

function dgStructureEditorInto(box, st, opts) {
  const known = DG_NAMING_ATTRS.map(function (a) { return a[0]; });
  const ed = {
    id: st ? st.id : null,
    name: st ? st.name : "",
    description: st ? (st.description || "") : "",
    segments: st
      ? st.segments.map(function (seg) {
          return { segment: seg.segment, attribute: seg.attribute, own: known.indexOf(seg.attribute) < 0, dash_after: !!seg.dash_after,
                   entries: seg.entries.map(function (e) { return { meaning: e.meaning, code: e.code }; }) };
        })
      : [{ segment: "Type", attribute: "type", own: false, dash_after: false, entries: [{ meaning: "", code: "" }] }],
    error: "",
  };
  const attrOf = function (seg) { return seg.own ? dgNamingKeyOf(seg.segment) : seg.attribute; };
  const example = function () {
    return ed.segments.map(function (seg) {
      const first = seg.entries.find(function (e) { return e.code.trim(); });
      return (first ? first.code.trim().toUpperCase() : "…") + (seg.dash_after ? "-" : "");
    }).join("").replace(/-+$/, "");
  };
  const draw = function () {
    box.innerHTML = "<h3>" + (ed.id ? "Change the naming structure " + escapeHtml(st.name) : "A new naming structure") + "</h3>" +
      '<p class="muted">For a range DuraGreen has sent codes for that none of its printed tables holds. Set its segments in the order ' +
      "DuraGreen writes them, what each one names, whether a dash follows, and its letters. A product put in it gets its code from " +
      "these, piece by piece — and a code DuraGreen prints whole for a configuration still comes first.</p>" +
      '<div class="npd-fields"><label>Name<input id="dg-se-name" value="' + attr(ed.name) + '" placeholder="e.g. LUNA" maxlength="60"></label>' +
      '<label class="npd-f-wide">What it is for<input id="dg-se-desc" value="' + attr(ed.description) +
        '" placeholder="e.g. LUNA pendants, from DuraGreen\'s email of 27 Oct"></label></div>' +
      '<div class="dg-se-example">Reads as <span class="dg-code" id="dg-se-example">' + escapeHtml(example()) + "</span></div>" +
      '<div class="dg-se-segs">' + ed.segments.map(function (seg, i) {
        const sel = '<select data-se-attr="' + i + '" aria-label="What this segment names">' +
          DG_NAMING_ATTRS.map(function (a) {
            return '<option value="' + attr(a[0]) + '"' + (!seg.own && seg.attribute === a[0] ? " selected" : "") + ">" + escapeHtml(a[1]) + "</option>";
          }).join("") + '<option value="__own"' + (seg.own ? " selected" : "") + ">A detail of its own (named as the segment)</option></select>";
        return '<div class="dg-se-seg"><div class="dg-se-seg-head">' +
          '<span class="dg-se-num">' + (i + 1) + "</span>" +
          '<input data-se-name="' + i + '" value="' + attr(seg.segment) + '" placeholder="Segment, e.g. Engine size" aria-label="Segment name">' +
          '<label class="dg-se-names">Names ' + sel + "</label>" +
          '<label class="dg-se-dash"><input type="checkbox" data-se-dash="' + i + '"' + (seg.dash_after ? " checked" : "") + "> a dash follows</label>" +
          '<span class="dg-se-move"><button type="button" class="btn tiny ghost" data-se-up="' + i + '"' + (i ? "" : " disabled") + ' title="Move up">↑</button>' +
          '<button type="button" class="btn tiny ghost" data-se-down="' + i + '"' + (i < ed.segments.length - 1 ? "" : " disabled") + ' title="Move down">↓</button>' +
          '<button type="button" class="btn tiny ghost dg-del" data-se-del="' + i + '" title="Remove this segment">✕</button></span></div>' +
          (seg.own ? '<p class="muted dg-se-own">Keyed as <code>' + escapeHtml(dgNamingKeyOf(seg.segment) || "…") + "</code> — a detail of its own, " +
            "chosen when quoting or fixed per product.</p>" : "") +
          '<div class="npd-optlist dg-se-entries"><div class="npd-optlist-head"><span>Code</span><span>Means</span><span></span></div>' +
          seg.entries.map(function (e, j) {
            return '<div class="npd-optrow"><input data-se-code="' + i + "." + j + '" value="' + attr(e.code) + '" placeholder="e.g. AFL" aria-label="Code">' +
              '<input data-se-meaning="' + i + "." + j + '" value="' + attr(e.meaning) + '" placeholder="e.g. Adjustable" aria-label="What it means">' +
              '<button type="button" class="npd-optdel" data-se-edel="' + i + "." + j + '" title="Remove this code">×</button></div>';
          }).join("") +
          '<button type="button" class="npd-optadd" data-se-enew="' + i + '">+ Add a code</button></div></div>';
      }).join("") + "</div>" +
      '<button type="button" class="btn small secondary" id="dg-se-addseg">+ Add a segment</button>' +
      (ed.error ? '<div class="error-box">' + escapeHtml(ed.error) + "</div>" : "") +
      '<div class="modal-actions"><button type="button" class="btn secondary" id="dg-se-cancel">Cancel</button>' +
      '<button type="button" class="btn primary" id="dg-se-save">' + (ed.id ? "Save changes" : "Make it") + "</button></div>";
    bind();
  };
  const refreshExample = function () {
    const out = box.querySelector("#dg-se-example");
    if (out) out.textContent = example();
  };
  const pair = function (s) { const p = s.split("."); return [Number(p[0]), Number(p[1])]; };
  const bind = function () {
    box.querySelector("#dg-se-name").addEventListener("input", function (e) { ed.name = e.target.value; });
    box.querySelector("#dg-se-desc").addEventListener("input", function (e) { ed.description = e.target.value; });
    box.querySelectorAll("[data-se-name]").forEach(function (inp) {
      inp.addEventListener("input", function () { ed.segments[Number(inp.dataset.seName)].segment = inp.value; });
      inp.addEventListener("change", draw);          // a detail of its own is keyed from the name
    });
    box.querySelectorAll("[data-se-attr]").forEach(function (sel) {
      sel.addEventListener("change", function () {
        const seg = ed.segments[Number(sel.dataset.seAttr)];
        seg.own = sel.value === "__own";
        if (!seg.own) {
          seg.attribute = sel.value;
          if (!seg.segment.trim()) seg.segment = dgNamingLabel(sel.value);
        }
        draw();
      });
    });
    box.querySelectorAll("[data-se-dash]").forEach(function (cb) {
      cb.addEventListener("change", function () { ed.segments[Number(cb.dataset.seDash)].dash_after = cb.checked; refreshExample(); });
    });
    box.querySelectorAll("[data-se-code]").forEach(function (inp) {
      inp.addEventListener("input", function () { const p = pair(inp.dataset.seCode); ed.segments[p[0]].entries[p[1]].code = inp.value; refreshExample(); });
    });
    box.querySelectorAll("[data-se-meaning]").forEach(function (inp) {
      inp.addEventListener("input", function () { const p = pair(inp.dataset.seMeaning); ed.segments[p[0]].entries[p[1]].meaning = inp.value; });
    });
    box.querySelectorAll("[data-se-edel]").forEach(function (b) {
      b.addEventListener("click", function () { const p = pair(b.dataset.seEdel); ed.segments[p[0]].entries.splice(p[1], 1); draw(); });
    });
    box.querySelectorAll("[data-se-enew]").forEach(function (b) {
      b.addEventListener("click", function () {
        const i = Number(b.dataset.seEnew);
        ed.segments[i].entries.push({ meaning: "", code: "" });
        draw();
        box.querySelector('[data-se-code="' + i + "." + (ed.segments[i].entries.length - 1) + '"]')?.focus();
      });
    });
    box.querySelectorAll("[data-se-up],[data-se-down]").forEach(function (b) {
      b.addEventListener("click", function () {
        const i = Number(b.dataset.seUp != null ? b.dataset.seUp : b.dataset.seDown);
        const j = b.dataset.seUp != null ? i - 1 : i + 1;
        const moved = ed.segments.splice(i, 1)[0];
        ed.segments.splice(j, 0, moved);
        draw();
      });
    });
    box.querySelectorAll("[data-se-del]").forEach(function (b) {
      b.addEventListener("click", function () { ed.segments.splice(Number(b.dataset.seDel), 1); draw(); });
    });
    box.querySelector("#dg-se-addseg").addEventListener("click", function () {
      ed.segments.push({ segment: "", attribute: "", own: true, dash_after: false, entries: [{ meaning: "", code: "" }] });
      draw();
      box.querySelector('[data-se-name="' + (ed.segments.length - 1) + '"]')?.focus();
    });
    box.querySelector("#dg-se-cancel").addEventListener("click", function () { if (opts.onCancel) opts.onCancel(); });
    box.querySelector("#dg-se-save").addEventListener("click", function (e) {
      withBusy(e.currentTarget, async function () {
        const payload = {
          name: ed.name.trim(), description: ed.description.trim(),
          segments: ed.segments.map(function (seg) {
            return { segment: seg.segment.trim(), attribute: attrOf(seg), dash_after: seg.dash_after,
                     entries: seg.entries.filter(function (x) { return x.code.trim() || x.meaning.trim(); }) };
          }),
        };
        try {
          const res = await api("/api/npd/duragreen/structures" + (ed.id ? "/" + ed.id : ""), {
            method: ed.id ? "PUT" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload),
          });
          if (opts.onSaved) opts.onSaved(res);
        } catch (err) {
          ed.error = err.message;
          draw();
        }
      });
    });
  };
  draw();
}

// ---- how one product fills a structure: fixed / chosen when quoting / not in its code
//
// One table for the product page and for "Add a DuraGreen product: type it in". `ctx`:
//   segments     the structure's segments (with their letters)
//   modes        {attribute: {mode, value}} - changed in place
//   identity     details that name the product itself: fixed or out, never chosen when quoting
//   quotedHtml   function(seg) -> what the "chosen when quoting" cell shows
//   codeOf       function(seg, mode) -> the Code cell (the server's answer where there is one)
//   mayEdit
function dgNamingRowsHtml(ctx) {
  const ro = ctx.mayEdit ? "" : " disabled";
  return '<div class="npd-ptable-scroll"><table class="dg-table dg-nm-fill"><thead><tr><th>Segment</th><th>For this product</th>' +
    "<th>Value</th><th>Code</th></tr></thead><tbody>" + ctx.segments.map(function (seg) {
      const a = seg.attribute;
      const m = ctx.modes[a] || { mode: "out" };
      const identity = ctx.identity.indexOf(a) >= 0;
      const modeSel = '<select data-nm-mode="' + attr(a) + '"' + ro + ' aria-label="' + attr("How " + seg.segment + " is filled") + '">' +
        [["fixed", "Fixed for this product"], ["quoted", "Chosen when quoting"], ["out", "Not in its code"]]
          .filter(function (o) { return !(identity && o[0] === "quoted"); })
          .map(function (o) { return '<option value="' + o[0] + '"' + (m.mode === o[0] ? " selected" : "") + ">" + o[1] + "</option>"; }).join("") +
        "</select>";
      let value = '<span class="muted">—</span>';
      if (m.mode === "fixed") {
        const meanings = seg.entries.map(function (e) { return e.meaning; });
        // power is written as a number (08W), not picked from a list
        if (a === "wattage" || !meanings.length || (m.value && meanings.indexOf(m.value) < 0) || m.other) {
          value = '<input data-nm-value="' + attr(a) + '" value="' + attr(m.value || "") + '" placeholder="' + attr(a === "wattage" ? "e.g. 8W" : "Its value") + '"' + ro + ">" +
            (meanings.length && a !== "wattage" ? ' <button type="button" class="btn tiny ghost" data-nm-list="' + attr(a) + '">Choose from the list</button>' : "");
        } else {
          value = '<select data-nm-value="' + attr(a) + '"' + ro + '><option value="">Choose…</option>' + seg.entries.map(function (e) {
            return '<option value="' + attr(e.meaning) + '"' + (m.value === e.meaning ? " selected" : "") + ">" + escapeHtml(e.meaning + " — " + e.code) + "</option>";
          }).join("") + '<option value="__other">Another value…</option></select>';
        }
      } else if (m.mode === "quoted") {
        value = ctx.quotedHtml(seg);
      }
      return "<tr><th scope=\"row\">" + escapeHtml(seg.segment) + (seg.dash_after ? ' <span class="muted">–</span>' : "") + "</th><td>" + modeSel +
        "</td><td>" + value + "</td><td>" + ctx.codeOf(seg, m) + "</td></tr>";
    }).join("") + "</tbody></table></div>";
}

// Binds what dgNamingRowsHtml drew. `redraw` draws the table's owner again.
function dgNamingRowsBind(root, modes, redraw, onChange) {
  root.querySelectorAll("[data-nm-mode]").forEach(function (sel) {
    sel.addEventListener("change", function () {
      const a = sel.dataset.nmMode;
      const was = modes[a] || {};
      modes[a] = sel.value === "fixed" ? { mode: "fixed", value: was.value || "" } : { mode: sel.value };
      onChange(a, sel.value);
      redraw();
    });
  });
  root.querySelectorAll("[data-nm-value]").forEach(function (inp) {
    const a = inp.dataset.nmValue;
    const set = function () {
      if (inp.value === "__other") { modes[a] = { mode: "fixed", value: "", other: true }; redraw(); return; }
      modes[a] = Object.assign({}, modes[a], { mode: "fixed", value: inp.value.trim() });
      onChange(a, "fixed");
    };
    inp.addEventListener(inp.tagName === "SELECT" ? "change" : "input", set);
    if (inp.tagName !== "SELECT") inp.addEventListener("change", redraw);
  });
  root.querySelectorAll("[data-nm-list]").forEach(function (b) {
    b.addEventListener("click", function () {
      const a = b.dataset.nmList;
      modes[a] = { mode: "fixed", value: "" };
      redraw();
    });
  });
}

// The code a fixed value takes, read off the structure's letters - for show; the code on a line is
// always the server's (structure_code), which also reads the product's own codes first.
function dgNamingFixedCode(seg, value) {
  const hit = seg.entries.find(function (e) { return String(e.meaning).toLowerCase() === String(value || "").toLowerCase(); });
  return hit ? '<code class="dg-optcode">' + escapeHtml(hit.code) + "</code>" : "";
}

// A structure's modes for a product that has none yet: a detail it offers several values of is
// chosen when quoting, one it has a single value of is fixed at it, the rest left out of its code.
function dgNamingDefaults(segments, modes, optionsOf, fieldOf, identity) {
  segments.forEach(function (seg) {
    const a = seg.attribute;
    if (modes[a]) return;
    const opts = optionsOf(a);
    const field = String(fieldOf(a) || "").trim();
    if (opts.length > 1 && identity.indexOf(a) < 0) modes[a] = { mode: "quoted" };
    else if (opts.length === 1) modes[a] = { mode: "fixed", value: opts[0] };
    else if (field && dgOptionList(field).length === 1) modes[a] = { mode: "fixed", value: field };
    else modes[a] = { mode: "out" };
  });
}

// What a save sends: the structure and how each of its own segments is filled.
function dgNamingPayload(structure, segments, modes) {
  if (!structure) return { structure: "" };
  const out = {};
  segments.forEach(function (seg) {
    const m = modes[seg.attribute];
    if (!m) return;
    // a fixed segment with no value yet is sent as it is: the server says which one to fill in
    if (m.mode === "fixed") out[seg.attribute] = { mode: "fixed", value: m.value || "" };
    else out[seg.attribute] = { mode: m.mode };
  });
  return { structure: structure, modes: out };
}

async function renderNpd(generation) {
  // Each brand has an NPD of its own; DuraGreen's is a separate screen over separate data.
  if (npdChosenBrand() === "Duragreen") return renderDuragreenNpd(generation);
  app.innerHTML = '<div class="muted">Loading…</div>';
  let products = [];
  let typologies = npdView.typologies;
  try {
    products = await api("/api/npd/products");
    if (!typologies.length) typologies = await api("/api/npd/typologies");
    // The classification panel shows driver rates and lets them be edited, so they are part
    // of what this tab is, not a detail of one panel inside it.
    await loadDriverPrices();
  } catch (e) {
    if (renderSuperseded(generation)) return;
    app.innerHTML = '<div class="error-box">Could not load NPD: ' + escapeHtml(e.message) + "</div>";
    return;
  }
  if (renderSuperseded(generation)) return;
  npdView.products = products;
  npdView.typologies = typologies;
  if (npdView.editing) return npdRenderForm();
  npdRenderList();
}

// Which brand the panel opens on: the one with the most products, so the first thing shown
// is the catalogue actually being worked on rather than whichever name sorts first. InHouse
// wins this today by a wide margin; derived rather than hard-coded so it stays true as the
// catalogue grows.
function npdDefaultBrand() {
  const counts = new Map();
  npdView.products.forEach(function (p) {
    if (p.make) counts.set(p.make, (counts.get(p.make) || 0) + 1);
  });
  let best = "";
  counts.forEach(function (n, make) { if (!best || n > counts.get(best)) best = make; });
  return best;
}

// Priced means somebody has said what it costs, by any of the three routes this tab offers:
// a base price, an adder on some option, or a power supply of its own. A product with none
// of them quotes zero, which is the thing the panel exists to make visible.
// How many combinations carry a price, across every driver type. Counted off the rows rather
// than off a grid, because a grid folds IP away and would undercount the 24V DC rates that
// differ by it.
function npdDriverPriceCount() {
  let total = 0;
  driverPricing.types.forEach(function (type) {
    const byControl = driverPricing.rules[type] || {};
    Object.keys(byControl).forEach(function (control) {
      Object.keys(byControl[control]).forEach(function (ip) {
        byControl[control][ip].forEach(function (row) {
          if (row.price != null) total += 1;
        });
      });
    });
  });
  return total;
}

function npdIsPriced(p) {
  return Boolean(p.base_price) || Boolean(p.adder_count) ||
         Object.keys(p.power_supply || {}).length > 0;
}

// Products for the current brand - the frame everything else sits inside, exactly as in the
// Specsheet Library: a typology only means something within one manufacturer's catalogue, so
// counting "Downlight" across brands would count two different words as one thing.
function npdBrandProducts() {
  return npdView.brand
    ? npdView.products.filter(function (p) { return p.make === npdView.brand; })
    : npdView.products;
}

// ---- searching the NPD list by parameter
//
// One box, several terms, and every term must match: "12W 3000K" is the products that offer 12W
// AND 3000K. A term with a unit is read as that parameter - 12W a wattage, 3000K a colour
// temperature, 24° a beam, IP65, CRI90, 55mm a cut-out or length - and compared as a number, so
// 12W never matches 112W the way a plain text search would. Any other word is looked for in the
// names and codes and in every searchable parameter (finish, control, mounting ...). Built for
// price reviews: "every 12W product" is one search, and each card says what matched and what
// that option adds to the price.
const NPD_SEARCH_LABEL = {
  wattage: "Wattage", cct: "CCT", beam_angle: "Beam", cri: "CRI", ip_rating: "IP",
  finish: "Finish", control: "Control", cutout_dimensions: "Cut-out", luminaire_length: "Length",
  trim_details: "Trim", mounting: "Mounting", adjustability: "Adjustability",
  optics_type: "Optics", reflector_finish: "Reflector", lumen_package: "Lumens",
  input_voltage: "Input",
};

// How a term with a unit is recognised, which parameters it is looked for in, and how it is
// written back to the person in the line under the box.
const NPD_UNIT_TERMS = [
  { kind: "wattage", re: /^(\d+(?:\.\d+)?)w(\/m)?$/i, keys: ["wattage"], label: "Wattage",
    show: function (n, m) { return n + "W" + (m[2] ? "/M" : ""); } },
  { kind: "cct", re: /^(\d{4})k$/i, keys: ["cct"], label: "CCT",
    show: function (n) { return n + "K"; } },
  { kind: "beam", re: /^(\d+(?:\.\d+)?)(?:°|º|deg)$/i, keys: ["beam_angle"], label: "Beam",
    show: function (n) { return n + "°"; } },
  { kind: "ip", re: /^ip(\d{2})$/i, keys: ["ip_rating"], label: "IP",
    show: function (n) { return "IP" + n; } },
  { kind: "cri", re: /^(?:cri|ra)(\d{2,3})$/i, keys: ["cri"], label: "CRI",
    show: function (n) { return "CRI " + n; } },
  { kind: "mm", re: /^(\d+(?:\.\d+)?)mm$/i, keys: ["cutout_dimensions", "luminaire_length"], label: "Size",
    show: function (n) { return n + " mm"; } },
];

// Case, spacing and the en dash InHouse types for a hyphen are not differences: "ON –OFF" is
// "ON-OFF", and "on off" finds it too, as two words.
function npdSearchNorm(s) {
  return String(s == null ? "" : s).toUpperCase().replace(/[–—]/g, "-").replace(/\s+/g, "");
}

function npdParseQuery(q) {
  // "12 W", "ip 65" and "3000 K" are one term each, as they are written on a datasheet.
  const text = String(q || "")
    .replace(/(\d)\s+(w\s*\/\s*m|w|k|°|º|deg|mm)(?![a-z])/gi, "$1$2")
    .replace(/(\d)w\s*\/\s*m(?![a-z])/gi, "$1w/m")
    .replace(/\b(ip|cri|ra)\s+(?=\d)/gi, "$1");
  const terms = [];
  const re = /"([^"]+)"|(\S+)/g;      // "matte white" in quotes is one term
  let m;
  while ((m = re.exec(text))) {
    const raw = (m[1] || m[2] || "").trim();
    if (!raw) continue;
    const unit = m[1] ? null : NPD_UNIT_TERMS.find(function (u) { return u.re.test(raw); });
    if (unit) {
      const parts = raw.match(unit.re);
      const num = Number(parts[1]);
      terms.push({ kind: unit.kind, raw: raw, num: num, perMetre: unit.kind === "wattage" && !!parts[2],
                   keys: unit.keys, label: unit.label, display: unit.show(num, parts) });
    } else {
      terms.push({ kind: "text", raw: raw, text: npdSearchNorm(raw) });
    }
  }
  return terms;
}

// The numbers one value states for a kind of term, each as {lo, hi}: lo === hi for a single
// value, both ends for a range ("TW (2700K-6500K)", "1-3W"). A range is read as a range only -
// its two ends are not also counted as values the product offers on their own.
function npdValueNumbers(kind, value) {
  let v = String(value == null ? "" : value).replace(/[–—]/g, "-");
  const out = [];
  const take = function (re, perMetre) {
    let m;
    while ((m = re.exec(v))) out.push({ lo: Number(m[1]), hi: Number(m[1]), perMetre: !!(perMetre && m[2]) });
  };
  const range = function (re) {
    const m = v.match(re);
    if (!m) return;
    out.push({ lo: Number(m[1]), hi: Number(m[2]), perMetre: /W\s*\/\s*M/i.test(m[0]) });
    v = v.replace(m[0], " ");
  };
  if (kind === "wattage") {
    range(/(\d+(?:\.\d+)?)\s*W?\s*-\s*(\d+(?:\.\d+)?)\s*W(\s*\/\s*M)?/i);
    take(/(\d+(?:\.\d+)?)\s*W(\s*\/\s*M)?/gi, true);
  } else if (kind === "cct") {
    range(/(\d{4})\s*K?\s*-\s*(\d{4})\s*K/i);
    take(/(\d{4})\s*K/gi);
  } else if (kind === "ip") {
    take(/IP\s*(\d{2})/gi);
  } else if (kind === "cri") {
    const first = v.match(/(\d{2,3})/);           // "> 95 (R9 > 80)": the CRI is the first number
    if (first) out.push({ lo: Number(first[1]), hi: Number(first[1]) });
  } else if (kind === "beam" || (kind === "mm" && /mm/i.test(v))) {
    take(/(\d+(?:\.\d+)?)/g);                     // 24°, 13*55°, 105 mm x 55 mm
  }
  return out;
}

// Whether a range a product offers - a tunable white "2700K-6500K", a "1-3W" FLARE-Mini - covers
// the single value searched for: inclusively, so the ends count. Only ever asked as a fallback
// (npdMatchProduct): a range is how a product is found when it has no option of that value itself.
function npdRangeIncludes(term, lo, hi) {
  return term.num >= lo && term.num <= hi;
}

// "exact" when a value is the one searched for, "range" when it only lies inside a range the
// value states, else false.
function npdNumberMatches(term, n) {
  // A strip's 10W/M is ten watts per metre, a different quantity from a 10W fitting: each is
  // found only by a term written the same way.
  if (term.kind === "wattage" && !!n.perMetre !== term.perMetre) return false;
  if (n.lo === n.hi) return n.lo === term.num ? "exact" : false;
  return npdRangeIncludes(term, Math.min(n.lo, n.hi), Math.max(n.lo, n.hi)) ? "range" : false;
}

// null when the product misses any term; otherwise the parameter values that matched - what the
// card shows, so a search reads as an answer rather than a list to open one by one.
function npdMatchProduct(p, terms) {
  const params = p.params || {};
  const names = npdSearchNorm([p.product_name, p.series, p.family, p.variant, p.model_no,
    p.typology, p.identity_code && (p.identity_code.code || p.identity_code.partial)]
    .filter(Boolean).join(" "));
  const hits = [];
  const seen = {};
  const hit = function (key, value, covers) {
    const k = key + "\u0000" + value;
    if (!seen[k]) { seen[k] = true; hits.push({ key: key, value: value, covers: covers || "" }); }
  };
  for (const t of terms) {
    let found = false;
    if (t.kind === "text") {
      if (names.indexOf(t.text) >= 0) continue;   // named so - nothing to show beyond the name
      Object.keys(params).forEach(function (key) {
        params[key].forEach(function (value) {
          if (npdSearchNorm(value).indexOf(t.text) >= 0) { hit(key, value); found = true; }
        });
      });
    } else {
      // Options of exactly this value first. A range is the fallback, for a product with no such
      // option: every InHouse tunable white also offers a plain 3000K, so a "3000K" search shows
      // that option and its price - not the TW adder - while "5000K", which nothing offers on its
      // own, still finds the tunable whites, through the range that actually covers it.
      const exact = [], ranged = [];
      t.keys.forEach(function (key) {
        (params[key] || []).forEach(function (value) {
          const how = npdValueNumbers(t.kind, value).map(function (n) { return npdNumberMatches(t, n); });
          if (how.indexOf("exact") >= 0) exact.push([key, value]);
          else if (how.indexOf("range") >= 0) ranged.push([key, value]);
        });
      });
      (exact.length ? exact : ranged).forEach(function (kv) { hit(kv[0], kv[1], exact.length ? "" : t.display); });
      found = exact.length > 0 || ranged.length > 0;
    }
    if (!found) return null;
  }
  return hits;
}

// What the search understood, under the box - so "12W 3000K" is seen to mean what was meant.
function npdQueryHintHtml(terms) {
  if (!terms.length) return "";
  const parts = terms.map(function (t) {
    return t.kind === "text" ? "“" + escapeHtml(t.raw) + "”"
      : "<strong>" + escapeHtml(t.label + " " + t.display) + "</strong>";
  });
  // A bare number ("12") is searched as text, which finds 12W, 120° and LL103012 alike. Said only
  // then: a person whose every term was understood needs no lesson in how to type one.
  const bareNumber = terms.some(function (t) { return t.kind === "text" && /\d/.test(t.raw); });
  return '<p class="npd-search-hint">Showing products with ' + parts.join(" and ") + "." +
    (bareNumber ? " Add a unit to search one parameter: 12W, 3000K, 24°, IP65, CRI90, 55mm." : "") +
    "</p>";
}

// The matched values on a card, each with the adder that option carries. A click opens the
// product at that parameter, where its price is set.
function npdMatchChipsHtml(p, hits) {
  if (!hits || !hits.length) return "";
  const shown = hits.slice(0, 4);
  return '<div class="npd-match">' + shown.map(function (h) {
    const adder = Number(((p.price_adders || {})[h.key] || {})[h.value] || 0);
    const label = NPD_SEARCH_LABEL[h.key] || prettifyFieldKey(h.key);
    return '<button type="button" class="npd-match-chip" data-npd-jump="' + p.id + '" data-key="' +
      attr(h.key) + '" title="' + attr((h.covers ? "Covers " + h.covers + " within this range. " : "") +
      "Open this product at its " + label) + '">' +
      '<span class="npd-match-key">' + escapeHtml(label) + "</span> " + escapeHtml(h.value) +
      // Found through a range, not an option of its own: said on the chip, since its price is the
      // range option's.
      (h.covers ? ' <span class="npd-match-key">covers ' + escapeHtml(h.covers) + "</span>" : "") +
      (adder ? ' <span class="npd-match-adder">+₹' + npdMoney(adder) + "</span>" : "") +
      "</button>";
  }).join("") + (hits.length > shown.length
    ? '<span class="npd-match-more">+' + (hits.length - shown.length) + " more</span>" : "") +
    "</div>";
}

function npdVisibleProducts() {
  const terms = npdParseQuery(npdView.query);
  return npdBrandProducts().filter(function (p) {
    if (npdView.typology === NPD_UNCLASSIFIED) {
      if (p.typology) return false;
    } else if (npdView.typology && p.typology !== npdView.typology) {
      return false;
    }
    if (npdView.priced === "priced" && !npdIsPriced(p)) return false;
    if (npdView.priced === "unpriced" && npdIsPriced(p)) return false;
    // Names and codes as before - "DL-RC-CRV" still finds every recessed CURVE downlight - and
    // now the parameters too: "12W 3000K" finds the products offering both (npdMatchProduct).
    if (terms.length && !npdMatchProduct(p, terms)) return false;
    return true;
  });
}

// Counts as clickable chips, the same visual language the Specsheet Library classifies with,
// answering the question this tab now owns: how much of the catalogue actually has a price.
// Drivers need no special case - each is an ordinary product whose typology is "Driver", so
// they classify themselves and are priced like anything else. Power supplies do need one: a
// power supply is not a product but a component of one, priced by the control chosen, so it
// is counted here and shown on the card of the product that carries it.
// A driver and a power supply are quoted as their own BOQ lines, and their prices do not
// come from a specsheet - they come from the driver rates in NPD's Driver prices (the
// driver_prices table, loaded into driverPricing), read off the studio's real price sheets and
// used by openAddDriverModal and openAddPowerSupplyModal. That is why the 132 driver
// specsheets in the catalogue carry no price of their own and are not a gap: nothing quotes
// from them. Shown here so the pricing screen tells the truth about where every number in a
// quotation comes from, rather than reporting drivers as unpriced when they are not.
function npdPriceTableHtml(title, note, table) {
  const controls = Object.keys(table);
  const wattages = [...new Set(controls.reduce(function (acc, c) {
    return acc.concat(Object.keys(table[c]));
  }, []))].sort(function (a, b) { return parseFloat(a) - parseFloat(b); });
  return '<div class="npd-ptable"><h4>' + escapeHtml(title) + "</h4>" +
    '<p class="npd-ptable-note">' + escapeHtml(note) + "</p>" +
    '<div class="npd-ptable-scroll"><table><thead><tr><th>Control</th>' +
      wattages.map(function (w) { return "<th>" + escapeHtml(w) + "</th>"; }).join("") +
    "</tr></thead><tbody>" +
    controls.map(function (c) {
      return "<tr><th>" + escapeHtml(c) + "</th>" + wattages.map(function (w) {
        const v = table[c][w];
        return v == null ? '<td class="npd-ptable-gap">\u2014</td>'
                         : "<td>\u20b9" + npdMoney(v) + "</td>";
      }).join("") + "</tr>";
    }).join("") +
    "</tbody></table></div></div>";
}

// One driver type, as an editable grid. Each cell is the price of one real combination and
// carries its own row id, so typing in it changes exactly that rate and nothing else. Blank
// is a value in its own right - "we sell this, nobody has priced it" - and is why an empty
// cell is not read as zero.
function npdDriverTypeHtml(driverType) {
  const byControl = driverPricing.rules[driverType] || {};
  const controls = Object.keys(byControl);
  const wattages = [];
  controls.forEach(function (control) {
    Object.keys(byControl[control]).forEach(function (ip) {
      byControl[control][ip].forEach(function (row) {
        if (wattages.indexOf(row.wattage) < 0) wattages.push(row.wattage);
      });
    });
  });
  wattages.sort(function (a, b) { return parseFloat(a) - parseFloat(b); });

  // A type whose rates differ by IP needs the IP shown; one where they do not would only be
  // repeating itself, so it collapses to a single row per control.
  const splitByIp = controls.some(function (control) {
    const ips = Object.keys(byControl[control]);
    if (ips.length < 2) return false;
    const seen = ips.map(function (ip) {
      return byControl[control][ip].map(function (r) { return r.wattage + ":" + r.price; })
        .sort().join("|");
    });
    return new Set(seen).size > 1;
  });

  const cell = function (rows, wattage) {
    const row = rows.find(function (r) { return r.wattage === wattage; });
    if (!row) return '<td class="npd-ptable-gap">\u2014</td>';
    // A viewer reads the rate; only someone with "Change prices" gets a box to change it.
    if (!can("prices.edit")) {
      return row.price == null ? '<td class="npd-ptable-gap">not priced</td>'
                               : "<td>\u20b9" + npdMoney(row.price) + "</td>";
    }
    return '<td><input class="npd-rate" data-rate-id="' + row.id + '" inputmode="decimal" ' +
      'value="' + attr(row.price == null ? "" : String(row.price)) + '" ' +
      'title="' + attr(row.source_note || "") + '" placeholder="\u2014"></td>';
  };

  const bodyRows = [];
  controls.forEach(function (control) {
    const ips = Object.keys(byControl[control]);
    if (splitByIp) {
      ips.forEach(function (ip) {
        bodyRows.push("<tr><th>" + escapeHtml(control) + "</th><th>" + escapeHtml(ip) + "</th>" +
          wattages.map(function (w) { return cell(byControl[control][ip], w); }).join("") + "</tr>");
      });
    } else {
      const merged = ips.reduce(function (acc, ip) { return acc.concat(byControl[control][ip]); }, []);
      bodyRows.push("<tr><th>" + escapeHtml(control) + "</th>" +
        wattages.map(function (w) { return cell(merged, w); }).join("") + "</tr>");
    }
  });

  return '<div class="npd-ptable"><h4>' + escapeHtml(driverType) + "</h4>" +
    '<div class="npd-ptable-scroll"><table><thead><tr><th>Control</th>' +
      (splitByIp ? "<th>IP</th>" : "") +
      wattages.map(function (w) { return "<th>" + escapeHtml(w) + "</th>"; }).join("") +
    "</tr></thead><tbody>" + bodyRows.join("") + "</tbody></table></div></div>";
}

// Adding a driver combination, which is also how a whole new driver type gets created: a
// type is only the combinations that name it, so there is nothing else to create first. The
// type and control boxes offer what already exists and accept anything else, because the
// point of this screen is that a driver the studio has started selling needs no code change.
function npdAddDriverRateModal() {
  const datalist = function (id, values) {
    return '<datalist id="' + id + '">' + values.map(function (v) {
      return '<option value="' + attr(v) + '"></option>';
    }).join("") + "</datalist>";
  };
  const modal = openModal(
    '<span class="close-x" title="Close">&times;</span>' +
    "<h3>Add a driver rate</h3>" +
    '<p class="muted">One row is one buyable combination. Naming a driver type that does ' +
    "not exist yet creates it \u2014 it will appear in the Add Driver form straight away.</p>" +
    '<div class="field-row">' +
      '<div><label class="lbl">Driver type</label>' +
        '<input id="dr-type" list="dr-types" placeholder="e.g. Surface Mounted"></div>' +
      '<div><label class="lbl">Control</label>' +
        '<input id="dr-control" list="dr-controls" placeholder="e.g. DALI"></div>' +
      '<div><label class="lbl">IP</label><select id="dr-ip">' +
        DRIVER_IP_VALUES.map(function (v) {
          return '<option value="' + attr(v) + '">' + escapeHtml(v) + "</option>";
        }).join("") + "</select></div>" +
      '<div><label class="lbl">Wattage</label><input id="dr-wattage" placeholder="e.g. 10W"></div>' +
      '<div><label class="lbl">Price <span class="muted">(blank = not priced yet)</span>' +
        '</label><input id="dr-price" inputmode="decimal"></div>' +
    "</div>" +
    '<label class="lbl">Where this figure came from <span class="muted">(optional, shown ' +
      "beside it)</span></label>" +
    '<input id="dr-note" style="width:100%" placeholder="e.g. Studio price sheet, March 2026">' +
    datalist("dr-types", driverPricing.types) +
    datalist("dr-controls", driverControlTypes()) +
    '<div style="margin-top:12px"><button class="btn" id="dr-save">Add</button>' +
      '<span class="muted" id="dr-msg" style="margin-left:10px"></span></div>',
    "modal-lg");
  modal.querySelector(".close-x").addEventListener("click", closeModal);

  modal.querySelector("#dr-save").addEventListener("click", async function (e) {
    const msg = modal.querySelector("#dr-msg");
    const read = function (sel) { return modal.querySelector(sel).value.trim(); };
    const payload = {
      driver_type: read("#dr-type"), control_type: read("#dr-control"),
      ip_rating: read("#dr-ip"), wattage: read("#dr-wattage"),
      price: read("#dr-price") === "" ? null : read("#dr-price"),
      source_note: read("#dr-note"),
    };
    if (!payload.driver_type || !payload.control_type || !payload.wattage) {
      msg.textContent = "Driver type, control and wattage are all needed.";
      return;
    }
    await withBusy(e.currentTarget, async function () {
      try {
        await api("/api/npd/driver-prices", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload) });
        await loadDriverPrices(true);
        closeModal();
        npdRenderList();
      } catch (err) {
        msg.textContent = err.message;
      }
    });
  });
}

// The accessory catalogue, seen from the accessory's side. A datasheet says "this downlight
// takes a Honeycomb"; nothing until now said "325 products take a Honeycomb, and here they are".
// It is read from the specsheets themselves (GET /api/accessories), so it cannot drift from
// them: adding a specsheet adds its accessories here, and correcting one corrects them here.
function npdAccCatalogueHtml() {
  const cat = npdView.accessories;
  const head = '<div class="npd-ptables"><div class="npd-ptables-head">' +
    "<h4>Other brands\u2019 accessories</h4>" +
    '<button type="button" class="mx-link" data-lib-back>\u2190 ' + escapeHtml(LIB_BRANDS.join(", ")) +
      " accessory library</button>" +
    '<button type="button" class="btn small secondary" data-npd-component="">Close</button>' +
    "</div>";
  if (!cat) return head + '<p class="npd-ptables-lede">Reading the library\u2026</p></div>';
  if (cat.error) {
    return head + '<p class="npd-ptables-lede">Could not read the accessories: ' +
      escapeHtml(cat.error) + "</p></div>";
  }
  const q = npdView.accQuery.trim().toLowerCase();
  const shown = q
    ? cat.accessories.filter(function (a) {
        return a.name.toLowerCase().includes(q) ||
          a.makes.join(" ").toLowerCase().includes(q) ||
          a.spellings.join(" ").toLowerCase().includes(q);
      })
    : cat.accessories;
  return head +
    '<p class="npd-ptables-lede">Which accessories exist, and which products each one goes ' +
    "with, read from the specsheets themselves \u2014 so it is never out of step with them. " +
    "An accessory is priced <b>under a product</b>, because the same Honeycomb costs different " +
    "amounts under different fixtures; the price column shows the range across the products " +
    "that have one. To add an accessory to a product, or to price it, open that product.</p>" +
    npdAccIssuesHtml() +
    '<div class="npd-facet npd-facet-search">' +
      '<input type="search" id="npd-acc-search" placeholder="Search accessories or brands\u2026" ' +
        'value="' + attr(npdView.accQuery) + '">' +
      (q ? '<span class="muted">' + shown.length + " of " + cat.count + "</span>" : "") +
    "</div>" +
    (shown.length
      ? '<table class="npd-cat-table"><thead><tr><th>Accessory</th><th>Products</th>' +
        "<th>Brands</th><th>Priced</th><th></th></tr></thead><tbody>" +
        shown.map(npdAccCatRowHtml).join("") + "</tbody></table>"
      : '<p class="npd-ptables-lede">Nothing matches that.</p>') +
    "</div>";
}

function npdAccCatRowHtml(a) {
  const open = npdView.accOpen === a.key;
  const renaming = npdView.accRename === a.key;
  const alsoSpelled = a.spellings.length > 1
    ? ' <span class="muted" title="Spelled this way on some datasheets. The products keep their own spelling; this catalogue counts them as one accessory.">also ' +
      a.spellings.slice(1).map(escapeHtml).join(", ") + "</span>"
    : "";
  const price = a.priced
    ? (a.price_low === a.price_high ? formatListPrice(a.price_low)
       : formatListPrice(a.price_low) + "\u2013" + formatListPrice(a.price_high)) +
      ' <span class="muted">on ' + a.priced + "</span>"
    : '<span class="muted">not priced anywhere</span>';
  const setup = npdView.accSetup === a.key;
  // What has been defined for it, at a glance: its picture, and the parameters Add Product asks.
  const defined = (a.params || []).map(function (p) {
    return '<span class="acc-param-pill" title="' + attr((p.options || []).join(", ") || "Typed in when added") + '">' +
      escapeHtml(p.name) + ((p.options || []).length ? " \u00b7 " + p.options.length : "") + "</span>";
  }).join("");
  return '<tr class="npd-cat-row' + (open || setup ? " open" : "") + '">' +
    '<td><div class="acc-name-cell">' +
      (a.image_url ? '<img class="acc-thumb" src="' + attr(a.image_url) + '" alt="" loading="lazy">' : "") +
      "<div><b>" + escapeHtml(a.name) + "</b>" + alsoSpelled +
        (defined ? '<div class="acc-param-pills">' + defined + "</div>" : "") + "</div>" +
    "</div></td>" +
    "<td>" + a.count + "</td>" +
    '<td class="muted">' + escapeHtml(a.makes.join(", ")) + "</td>" +
    "<td>" + price + "</td>" +
    '<td class="npd-cat-acts">' +
      '<button type="button" class="mx-link" data-npd-cat="' + attr(a.key) + '">' +
        (open ? "Hide" : "Which products") + "</button>" +
      '<button type="button" class="mx-link" data-npd-cat-setup="' + attr(a.key) + '">' +
        (setup ? "Close" : "Parameters &amp; picture") + "</button>" +
      '<button type="button" class="mx-link" data-needs="specsheets.add" data-npd-cat-rename="' +
        attr(a.key) + '">' + (renaming ? "Cancel" : "Rename") + "</button>" +
      "</td></tr>" +
    (renaming ? '<tr class="npd-cat-detail"><td colspan="5">' + npdAccRenameHtml(a) + "</td></tr>" : "") +
    (setup ? '<tr class="npd-cat-detail"><td colspan="5">' + npdAccSetupHtml(a) + "</td></tr>" : "") +
    (open ? '<tr class="npd-cat-detail"><td colspan="5"><div id="npd-cat-products">' +
      npdAccCatProductsHtml(a) + "</div></td></tr>" : "");
}

// ---------------- An accessory's parameters and picture ----------------
//
// A datasheet says which accessories a product takes, but not what each is ordered on. A strip
// light prints "Profile Dimension: 16mm X 16mm / 17mm X 15mm" - the sizes of every profile it
// takes, together - and nothing ties a size to the U-shape profile rather than the triangular
// one. This panel is where that is decided, once per accessory: the parameters Add Product then
// asks of it, and the picture its BOQ line prints (models.AccessoryDetail on the server). What the
// datasheets print is offered as suggestions, and never applied on its own.

function npdAccDraftParams(params) {
  return (params || []).map(function (p) {
    return { name: p.name, options: (p.options || []).slice(), pending: "" };
  });
}

// Options typed into a box, split the way a datasheet writes them ("16mm X 16mm / 17mm X 15mm").
function npdAccSplitOptions(text) {
  return String(text || "").split(/[\/\n]+/).map(function (o) {
    return o.replace(/\s+/g, " ").trim();
  }).filter(Boolean);
}

// What Save sends: names and options tidied, an option still in its box included, and a row with
// neither a name nor an option left out - so an empty row is not an unsaved change.
function npdAccCleanParams(params) {
  return (params || []).map(function (p) {
    const options = [];
    (p.options || []).concat(npdAccSplitOptions(p.pending)).forEach(function (o) {
      o = String(o).replace(/\s+/g, " ").trim();
      if (o && !options.some(function (x) { return x.toLowerCase() === o.toLowerCase(); })) options.push(o);
    });
    return { name: String(p.name || "").replace(/\s+/g, " ").trim(), options: options };
  }).filter(function (p) { return p.name || p.options.length; });
}

function npdAccDraftDirty(d) {
  return !!(d && d.data) &&
    JSON.stringify(npdAccCleanParams(d.params)) !== JSON.stringify(npdAccCleanParams(d.data.params));
}

// Opens the panel, or closes it - asking first when there is something unsaved in it.
async function npdAccToggleSetup(key) {
  const d = npdView.accDraft;
  if (npdAccDraftDirty(d) && !confirm("Close without saving the changes to " +
      (d.data ? "\u201c" + d.data.name + "\u201d" : "its") + " parameters?")) return;
  if (npdView.accSetup === key) {
    npdView.accSetup = "";
    npdView.accDraft = null;
    npdRenderList();
    return;
  }
  npdView.accSetup = key;
  npdView.accDraft = { key: key, loading: true };
  npdRenderList();
  try {
    const data = await api("/api/accessories/" + encodeURIComponent(key) + "/details");
    if (npdView.accSetup !== key) return;
    npdView.accDraft = { key: key, data: data, params: npdAccDraftParams(data.params), busy: "", problem: "" };
  } catch (err) {
    if (npdView.accSetup !== key) return;
    npdView.accDraft = { key: key, error: err.message };
  }
  npdRenderList();
}

// The panel is drawn in one of two places: the catalogue's table here, or a window opened from a
// product's own Accessories section (npdOpenAccSetupModal). Its working copy carries `root` and
// `redraw` for the window; without them it is the catalogue's row, redrawn with the list.
function npdAccRoot() {
  const d = npdView.accDraft;
  return d && d.root && d.root.isConnected ? d.root : document;
}

function npdAccRender() {
  const d = npdView.accDraft;
  if (d && d.redraw) d.redraw();
  else npdRenderList();
}

// The server's reply, into the panel and into the table row behind it - the catalogue is not
// fetched again for a change that only this accessory's own definition carries.
function npdAccTakeReply(reply) {
  const d = npdView.accDraft;
  if (d && d.key === reply.key && d.data) {
    d.data.params = reply.params;
    d.data.image = reply.image;
    d.data.image_url = reply.image_url;
  }
  const entry = ((npdView.accessories && npdView.accessories.accessories) || [])
    .find(function (a) { return a.key === reply.key; });
  if (entry) {
    entry.params = reply.params;
    entry.image = reply.image;
    entry.image_url = reply.image_url;
  }
  if (npdView.accDefs) {
    npdView.accDefs.byKey[reply.key] = { params: reply.params, image: reply.image, image_url: reply.image_url };
  }
}

// Re-draws the panel and puts the caret back where the person was working.
function npdAccRedraw(focusSelector) {
  npdAccRender();
  if (!focusSelector) return;
  const el = npdAccRoot().querySelector(".acc-setup " + focusSelector);
  if (el) {
    el.focus();
    if (el.setSelectionRange && typeof el.value === "string") el.setSelectionRange(el.value.length, el.value.length);
  }
}

async function npdAccSaveParams() {
  const d = npdView.accDraft;
  if (!d || !d.data || d.busy) return;
  const params = npdAccCleanParams(d.params);
  const unnamed = params.find(function (p) { return !p.name; });
  if (unnamed) {
    d.problem = "Give every parameter a name - " + unnamed.options.slice(0, 2).join(", ") + " is the one without.";
    npdAccRender();
    return;
  }
  d.busy = "save";
  d.problem = "";
  npdAccRender();
  try {
    const reply = await api("/api/accessories/" + encodeURIComponent(d.key) + "/details", {
      method: "PUT", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ params: params }),
    });
    npdAccTakeReply(reply);
    d.params = npdAccDraftParams(reply.params);
    d.saved = Date.now();
  } catch (err) {
    d.problem = err.message;
  }
  d.busy = "";
  npdAccRender();
}

// `body` is a FormData holding an uploaded file, or {from_specsheet, label} for a picture already
// extracted from one of its datasheets.
async function npdAccSetPicture(body) {
  const d = npdView.accDraft;
  if (!d || !d.data || d.busy) return;
  d.busy = "picture";
  d.problem = "";
  npdAccRender();
  try {
    const opts = body instanceof FormData
      ? { method: "POST", body: body }
      : { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) };
    npdAccTakeReply(await api("/api/accessories/" + encodeURIComponent(d.key) + "/image", opts));
  } catch (err) {
    d.problem = "The picture was not saved: " + err.message;
  }
  d.busy = "";
  npdAccRender();
}

async function npdAccRemovePicture() {
  const d = npdView.accDraft;
  if (!d || !d.data || d.busy) return;
  if (!confirm("Take the picture off \u201c" + d.data.name + "\u201d?\n\n" +
      "Lines already in BOQs keep the picture they were added with.")) return;
  d.busy = "picture";
  d.problem = "";
  npdAccRender();
  try {
    npdAccTakeReply(await api("/api/accessories/" + encodeURIComponent(d.key) + "/image", { method: "DELETE" }));
  } catch (err) {
    d.problem = "The picture was not removed: " + err.message;
  }
  d.busy = "";
  npdAccRender();
}

// Where a value printed on the datasheets goes: the parameter that is about size, or a new one
// named after the datasheet field it came from. Never into some other parameter that happens to
// be first - a size added to "Finish" would be worse than none.
function npdAccSizeParam(d) {
  return d.params.findIndex(function (p) { return /dimension|size/i.test(p.name || ""); });
}

function npdAccAddSuggestion(value, field) {
  const d = npdView.accDraft;
  if (!d || !d.data) return;
  let i = npdAccSizeParam(d);
  if (i < 0) {
    d.params.push({ name: field || "Dimension", options: [], pending: "" });
    i = d.params.length - 1;
  }
  const options = d.params[i].options;
  if (!options.some(function (o) { return o.toLowerCase() === value.toLowerCase(); })) options.push(value);
  npdAccRedraw();
}

function npdAccSetupHtml(a) {
  const d = npdView.accDraft;
  if (!d || d.key !== a.key) return "";
  if (d.loading) return '<div class="acc-setup"><p class="muted">Reading what its specsheets print\u2026</p></div>';
  if (d.error) return '<div class="acc-setup"><p class="acc-problem">Could not open it: ' + escapeHtml(d.error) + "</p></div>";
  const editable = can("specsheets.add");
  return '<div class="acc-setup" data-acc-setup="' + attr(d.key) + '">' +
    '<div class="acc-setup-grid">' + npdAccPictureHtml(d, editable) + npdAccParamsHtml(d, editable) + "</div>" +
    npdAccFootHtml(d, editable) +
    "</div>";
}

function npdAccPictureHtml(d, editable) {
  const data = d.data;
  const busy = d.busy === "picture";
  const gallery = editable && (data.pictures || []).length
    ? '<details class="acc-gallery"' + (data.image_url ? "" : " open") + ">" +
        "<summary>Use a picture from its datasheets (" + data.pictures.length + ")</summary>" +
        '<div class="acc-gallery-grid">' + data.pictures.map(function (p) {
          return '<button type="button" class="acc-gallery-item" data-acc-pic-from="' + p.specsheet_id + '" ' +
            'data-acc-pic-label="' + attr(p.label) + '" title="' + attr(p.product + " \u00b7 " + p.label) + '"' +
            (busy ? " disabled" : "") + ">" +
            '<img src="' + attr(p.url) + '" alt="" loading="lazy">' +
            "<span>" + escapeHtml(p.product) + "</span></button>";
        }).join("") + "</div>" +
      "</details>"
    : "";
  return '<section class="acc-setup-picture">' +
    '<div class="acc-setup-label">Picture</div>' +
    '<div class="acc-pic-frame' + (data.image_url ? "" : " is-empty") + (busy ? " is-busy" : "") + '">' +
      (data.image_url ? '<img src="' + attr(data.image_url) + '" alt="' + attr(data.name) + '">'
                      : "<span>No picture</span>") +
    "</div>" +
    (editable
      ? '<div class="acc-pic-actions">' +
          '<label class="btn small secondary' + (busy ? " disabled" : "") + '">' +
            (busy ? "Saving\u2026" : data.image_url ? "Replace\u2026" : "Upload\u2026") +
            '<input type="file" accept=".png,.jpg,.jpeg,.gif,.webp" data-acc-upload hidden' + (busy ? " disabled" : "") + ">" +
          "</label>" +
          (data.image_url ? '<button type="button" class="btn small secondary" data-acc-pic-remove' + (busy ? " disabled" : "") + ">Remove</button>" : "") +
        "</div>"
      : "") +
    '<p class="acc-hint">Optional. Printed in the Dimension column of this accessory\u2019s BOQ line. PNG, JPG, GIF or WebP.</p>' +
    gallery +
    "</section>";
}

function npdAccParamsHtml(d, editable) {
  const data = d.data;
  const rows = d.params.map(function (p, i) {
    const chips = p.options.map(function (o, j) {
      return '<span class="acc-chip">' + escapeHtml(o) +
        (editable ? '<button type="button" data-acc-opt-remove="' + i + ":" + j + '" aria-label="Remove ' + attr(o) + '">\u00d7</button>' : "") +
        "</span>";
    }).join("");
    return '<div class="acc-param">' +
      '<div class="acc-param-head">' +
        (editable
          ? '<input type="text" class="acc-param-name" maxlength="40" placeholder="Parameter, e.g. Dimension" ' +
              'value="' + attr(p.name) + '" data-acc-param-name="' + i + '" aria-label="Parameter name">' +
            '<button type="button" class="acc-icon-btn" data-acc-param-remove="' + i + '" title="Remove this parameter">\u00d7</button>'
          : "<b>" + escapeHtml(p.name) + "</b>") +
      "</div>" +
      '<div class="acc-options">' + chips +
        (editable
          ? '<input type="text" class="acc-opt-input" value="' + attr(p.pending || "") + '" data-acc-opt-add="' + i + '" ' +
              'placeholder="' + (p.options.length ? "Add another option" : "Add an option") + ', then Enter" aria-label="Add an option">'
          : "") +
      "</div>" +
      (p.options.length ? "" : '<p class="acc-hint">No options: the value is typed in when the accessory is added.</p>') +
    "</div>";
  }).join("");
  const size = npdAccSizeParam(d);
  const inSize = size >= 0
    ? d.params[size].options.map(function (o) { return o.toLowerCase(); }) : [];
  const suggestions = editable && (data.suggestions || []).length
    ? '<div class="acc-suggest">' +
        '<div class="acc-setup-label">Printed on the datasheets of the ' + data.count +
          " product" + (data.count === 1 ? "" : "s") + " that list it</div>" +
        data.suggestions.map(function (g) {
          return '<div class="acc-suggest-group"><span class="acc-suggest-field">' + escapeHtml(g.field) + "</span>" +
            g.values.map(function (v) {
              const added = inSize.indexOf(v.value.toLowerCase()) >= 0;
              return '<button type="button" class="acc-suggest-chip' + (added ? " is-added" : "") + '" ' +
                'data-acc-suggest="' + attr(v.value) + '" data-acc-suggest-field="' + attr(g.field) + '"' +
                (added ? " disabled" : "") + ' title="Printed on ' + v.products + " of them" + (added ? " - already added" : "") + '">' +
                escapeHtml(v.value) + '<span class="acc-suggest-n">' + v.products + "</span></button>";
            }).join("") + "</div>";
        }).join("") +
        '<p class="acc-hint">' + (size >= 0
          ? "Click a value to add it to <b>" + escapeHtml(d.params[size].name) + "</b>. "
          : "Click a value to start a parameter with it. ") +
        "A datasheet prints the sizes of every profile its product takes together, so keep only this accessory\u2019s own.</p>" +
      "</div>"
    : "";
  return '<section class="acc-setup-params">' +
    '<div class="acc-setup-label">Parameters <span class="acc-setup-sub">asked when it is added with a product</span></div>' +
    (rows || '<p class="acc-empty">' + (editable
      ? "None yet. Add what this accessory is ordered on \u2014 for a profile, its dimension."
      : "None defined.") + "</p>") +
    (editable && d.params.length < 6
      ? '<button type="button" class="btn small secondary acc-add-param" data-acc-param-add>+ Add parameter</button>' : "") +
    suggestions +
    "</section>";
}

// The foot is drawn on its own as well, because typing a parameter's name changes it (unsaved
// marker, the preview) and re-drawing the whole panel on every keystroke would lose the caret.
function npdAccFootHtml(d, editable) {
  const params = npdAccCleanParams(d.params);
  const dirty = npdAccDraftDirty(d);
  const example = [d.data.name].concat(params.map(function (p) {
    return (p.name || "\u2026") + ": " + (p.options[0] || "(typed in)");
  }));
  const status = d.problem
    ? '<span class="acc-problem">' + escapeHtml(d.problem) + "</span>"
    : dirty ? '<span class="acc-dirty">Unsaved changes</span>'
    : d.saved && Date.now() - d.saved < 6000 ? '<span class="acc-saved">Saved</span>' : "";
  return '<div class="acc-setup-foot">' +
    '<div class="acc-preview"><span class="acc-setup-label">Its BOQ line will read</span>' +
      '<div class="acc-preview-line">' + example.map(escapeHtml).join("<br>") + "</div></div>" +
    '<div class="acc-setup-actions">' + (editable ? status : "") +
      '<button type="button" class="btn small secondary" data-acc-setup-close>' + (dirty ? "Discard" : "Close") + "</button>" +
      (editable
        ? '<button type="button" class="btn small" data-acc-setup-save' + (dirty && !d.busy ? "" : " disabled") + ">" +
            (d.busy === "save" ? "Saving\u2026" : "Save parameters") + "</button>"
        : "") +
    "</div>" +
  "</div>";
}

function npdAccRefreshFoot() {
  const d = npdView.accDraft;
  const foot = npdAccRoot().querySelector(".acc-setup .acc-setup-foot");
  if (!d || !d.data || !foot) return;
  foot.outerHTML = npdAccFootHtml(d, can("specsheets.add"));
}

// One set of listeners on the panel, delegated, so they keep working when parts of it are re-drawn.
function npdWireAccSetup(root) {
  const box = root.querySelector(".acc-setup[data-acc-setup]");
  const d = npdView.accDraft;
  if (!box || !d || !d.data) return;
  box.addEventListener("click", function (e) {
    const t = e.target.closest("button");
    if (!t || t.disabled) return;
    if (t.matches("[data-acc-param-add]")) {
      d.params.push({ name: "", options: [], pending: "" });
      npdAccRedraw('[data-acc-param-name="' + (d.params.length - 1) + '"]');
    } else if (t.matches("[data-acc-param-remove]")) {
      const i = Number(t.dataset.accParamRemove);
      const p = d.params[i];
      if (p.options.length && !confirm("Remove \u201c" + (p.name || "this parameter") + "\u201d and its " +
          p.options.length + " option(s)?")) return;
      d.params.splice(i, 1);
      npdAccRedraw();
    } else if (t.matches("[data-acc-opt-remove]")) {
      const ij = t.dataset.accOptRemove.split(":").map(Number);
      d.params[ij[0]].options.splice(ij[1], 1);
      npdAccRedraw('[data-acc-opt-add="' + ij[0] + '"]');
    } else if (t.matches("[data-acc-suggest]")) {
      npdAccAddSuggestion(t.dataset.accSuggest, t.dataset.accSuggestField);
    } else if (t.matches("[data-acc-pic-from]")) {
      npdAccSetPicture({ from_specsheet: Number(t.dataset.accPicFrom), label: t.dataset.accPicLabel });
    } else if (t.matches("[data-acc-pic-remove]")) {
      npdAccRemovePicture();
    } else if (t.matches("[data-acc-setup-save]")) {
      npdAccSaveParams();
    } else if (t.matches("[data-acc-setup-close]")) {
      if (d.close) d.close();
      else npdAccToggleSetup(d.key);
    }
  });
  box.addEventListener("input", function (e) {
    const t = e.target;
    if (t.matches("[data-acc-param-name]")) {
      d.params[Number(t.dataset.accParamName)].name = t.value;
      d.problem = "";
      npdAccRefreshFoot();
    } else if (t.matches("[data-acc-opt-add]")) {
      d.params[Number(t.dataset.accOptAdd)].pending = t.value;
      npdAccRefreshFoot();
    }
  });
  box.addEventListener("keydown", function (e) {
    const t = e.target;
    if (e.key !== "Enter" || !t.matches("[data-acc-opt-add]")) return;
    e.preventDefault();
    const i = Number(t.dataset.accOptAdd);
    const p = d.params[i];
    npdAccSplitOptions(t.value).forEach(function (o) {
      if (!p.options.some(function (x) { return x.toLowerCase() === o.toLowerCase(); })) p.options.push(o);
    });
    p.pending = "";
    npdAccRedraw('[data-acc-opt-add="' + i + '"]');
  });
  box.addEventListener("change", function (e) {
    const t = e.target;
    if (!t.matches("[data-acc-upload]") || !t.files || !t.files[0]) return;
    const form = new FormData();
    form.append("file", t.files[0]);
    npdAccSetPicture(form);
  });
}

// One box. Typing a name that already belongs to another accessory is a merge, and the form says
// so - with the number of products it would move - before anything is written. The alternative,
// a separate "merge" control, hides the fact that they are the same operation.
function npdAccRenameHtml(a) {
  const typed = npdView.accRenameTo === null || npdView.accRenameTo === undefined
    ? a.name : npdView.accRenameTo;
  const folded = String(typed).toLowerCase().replace(/[^a-z0-9]+/g, "");
  const into = folded && folded !== a.key
    ? (npdView.accessories.accessories || []).find(function (x) { return x.key === folded; })
    : null;
  const same = folded === a.key && typed.trim() === a.name;
  let note;
  if (!String(typed).trim()) note = "Give it a name.";
  else if (into) {
    note = "<b>This merges into " + escapeHtml(into.name) + "</b> - the " + a.count +
      " product(s) listing " + escapeHtml(a.name) + " would list " + escapeHtml(into.name) +
      " instead, joining its " + into.count + ". Their prices and order codes move with them.";
  } else if (same) note = "That is already its name.";
  else {
    note = "The " + a.count + " product(s) listing " + escapeHtml(a.name) +
      " would list <b>" + escapeHtml(typed) + "</b> instead, in the specsheets themselves. " +
      "Its prices and order codes move with it.";
  }
  return '<div class="npd-cat-rename">' +
    '<label class="lbl">Name this accessory</label>' +
    '<div class="npd-cat-rename-row">' +
      '<input type="text" id="npd-cat-rename-input" value="' + attr(typed) + '" autocomplete="off">' +
      '<button type="button" class="btn small" id="npd-cat-rename-go"' +
        (!String(typed).trim() || same ? " disabled" : "") + ">" +
        (into ? "Merge" : "Rename") + " in the specsheets</button>" +
    "</div>" +
    '<p class="npd-cat-rename-note">' + note + "</p>" +
    "</div>";
}

function npdAccCatProductsHtml(a) {
  const products = a.products;
  if (!products) return '<span class="muted">Reading\u2026</span>';
  if (!products.length) return '<span class="muted">No product lists this any more.</span>';
  return '<div class="npd-cat-products">' + products.map(function (p) {
    return '<button type="button" class="npd-cat-product" data-npd-cat-product="' + p.id + '" ' +
      'title="Open this product">' +
      "<b>" + escapeHtml(p.name) + "</b>" +
      '<span class="muted">' + escapeHtml(p.make) + (p.typology ? " \u00b7 " + escapeHtml(p.typology) : "") + "</span>" +
      (p.price != null ? '<span class="npd-cat-price">' + formatListPrice(p.price) + "</span>" : "") +
      (p.code ? '<span class="pill">' + escapeHtml(p.code) + "</span>" : "") +
      "</button>";
  }).join("") + "</div>";
}

// ---------------- The InHouse accessory library (app/accessory_parts.py) ----------------
//
// An accessory's name is a label, not an identity: two products can list "U Shape Profile" and
// take a 35 x 35 mm profile and a 16 x 16 mm one, and two strip lights can take the very same
// profile. Typed per product, the first pair would share one price and the second could be
// spelled two ways and counted as two things. So every InHouse accessory is one record in a
// library, and a product PICKS the ones it takes - in its own NPD form, step 4. Nothing about an
// accessory is ever typed against a product: a new one is created in the library once (from the
// product, or from NPD -> Accessory library), then picked by every product that takes it.
//
// Accessories that share a name are variants, told apart by their specifications. Creating one
// whose name is another spelling of an existing one takes the existing spelling, and one with the
// same name AND specifications as an existing one is refused with that one offered instead.

const LIB_BRANDS = ["InHouse"];

function libIsBrand(make) {
  const m = String(make || "").trim().toLowerCase();
  return LIB_BRANDS.some(function (b) { return b.toLowerCase() === m; });
}

// The library, read once and read again after anything changes it.
async function libLoad(force) {
  if (!force && npdView.lib && npdView.lib.list) return npdView.lib.list;
  try {
    const reply = await api("/api/accessory-library");
    npdView.lib = { list: reply.accessories || [] };
  } catch (err) {
    npdView.lib = { list: null, error: err.message };
  }
  return npdView.lib.list || [];
}

function libSpecsText(e) {
  return ((e && e.specs) || []).map(function (s) { return s.name + " " + s.value; }).join(" · ");
}

function libSpecValues(e) {
  return ((e && e.specs) || []).map(function (s) { return s.value; }).join(", ");
}

// Variants of one accessory together, in the library's order.
function libFamilies(list) {
  const out = [];
  const by = {};
  list.forEach(function (e) {
    if (!by[e.group]) {
      by[e.group] = { key: e.group, name: e.name, items: [] };
      out.push(by[e.group]);
    }
    by[e.group].items.push(e);
  });
  return out;
}

// A search matches the name, a specification or the code, whatever the case and spacing.
function libMatches(e, q) {
  const f = accessoryFold(q);
  if (!f) return true;
  return accessoryFold(e.name).includes(f) || accessoryFold(libSpecsText(e)).includes(f) ||
    accessoryFold(e.code).includes(f);
}

// How alike two folded names are, 0 to 1 - for "did you mean" when a name is close to one in
// the library but not the same (a typo is how one accessory becomes two).
function libSimilar(a, b) {
  if (!a || !b) return 0;
  if (a === b) return 1;
  let prev = [];
  for (let j = 0; j <= b.length; j++) prev.push(j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)));
    }
    prev = cur;
  }
  return 1 - prev[b.length] / Math.max(a.length, b.length);
}

function libThumb(e, cls) {
  return e && e.image_url
    ? '<img class="' + cls + '" src="' + attr(e.image_url) + '" alt="" loading="lazy">'
    : '<span class="' + cls + ' is-empty" aria-hidden="true"></span>';
}

function libPriceHtml(e) {
  if (e && e.price != null) return escapeHtml(formatListPrice(e.price));
  if (e && e.price_conflict) {
    return '<span class="lib-warn" title="Its price rows disagree - settle it in List Pricing">two prices</span>';
  }
  return '<span class="muted">Not priced</span>';
}

// ---- step 4 of a InHouse product's form

function npdLibMode(d) {
  return libIsBrand(d.make || "InHouse");
}

// What the form sends: a library accessory by its id (and the datasheet name it replaces, whose
// price may move onto it), anything else as the name and price it always was.
function npdAccessoriesPayload(d) {
  return d.accessories.map(function (a) {
    return a.part_id ? { part_id: a.part_id, replaces: a.replaces || "" } : { name: a.name, price: a.price };
  });
}

// What each library accessory is called on this product: its name, or name and size when the
// product takes two variants of it - the same rule as accessory_parts.labels_for_parts, so the
// code preview and the saved list agree.
function npdLibRelabel(d) {
  const lib = d.accessories.filter(function (a) { return a.part_id && a.part; });
  const count = {};
  lib.forEach(function (a) { const k = accessoryFold(a.part.name); count[k] = (count[k] || 0) + 1; });
  lib.forEach(function (a) {
    a.name = count[accessoryFold(a.part.name)] > 1
      ? a.part.name + " (" + (libSpecValues(a.part) || "#" + a.part.id) + ")" : a.part.name;
  });
}

function npdLibAccessoriesHtml(d) {
  npdLibRelabel(d);
  const rows = d.accessories;
  const legacy = rows.filter(function (a) { return !a.part_id; }).length;
  return '<section class="npd-step"><h3><span class="npd-num">4</span> Accessories</h3>' +
    '<p class="npd-steplede">What this product is sold with, picked from the InHouse <b>accessory ' +
    "library</b>. An accessory is one record wherever it is used — its specifications, picture, code " +
    "and price are the same on every product that takes it — so pick the one that exists rather " +
    "than adding it again. Each is quoted as its own line when the product goes into a BOQ.</p>" +
    (legacy
      ? '<p class="lib-note"><b>' + legacy + "</b> accessor" + (legacy === 1 ? "y" : "ies") + " from this " +
        "product’s datasheet " + (legacy === 1 ? "is" : "are") + " not in the library yet. Choose " +
        "the library accessory for " + (legacy === 1 ? "it" : "each") + ", or create it, so it gets its " +
        "own specifications, picture and price.</p>"
      : "") +
    (rows.length === 0
      ? '<p class="npd-await">No accessories yet.</p>'
      : '<div class="lib-acc-list">' +
        '<div class="lib-acc-head"><span>Accessory</span>' +
          '<span title="What it adds to this product\u2019s code: a library accessory\u2019s own code, or the abbreviation of a datasheet name">Code</span>' +
          "<span>Price</span><span>Used by</span><span></span></div>" +
        rows.map(function (a, i) { return a.part_id ? npdLibRowHtml(d, a, i) : npdLibLegacyRowHtml(a, i); }).join("") +
        "</div>") +
    '<div class="lib-acc-add">' +
      '<button type="button" class="btn small" id="lib-acc-add">+ Add accessory</button>' +
      '<span class="muted">Search the library, or create a new accessory there.</span>' +
    "</div></section>";
}

function npdLibRowHtml(d, a, i) {
  const e = a.part || {};
  const others = (e.products || []).filter(function (p) { return p.id !== d.id; }).length;
  const specs = libSpecsText(e);
  return '<div class="lib-acc-row">' +
    '<div class="lib-acc-main">' + libThumb(e, "lib-thumb") +
      '<div class="lib-acc-text"><b>' + escapeHtml(e.name || a.name) + "</b>" +
        '<div class="lib-acc-specs">' + (specs ? escapeHtml(specs) : '<span class="muted">No specifications</span>') + "</div>" +
      "</div></div>" +
    '<span class="npd-acc-code lib-code-seg">' + (e.code
      ? '<span class="lib-code" title="Its own code - what it adds to this product\u2019s code">' + escapeHtml(e.code) + "</span>"
      : '<span class="lib-warn" title="Give it a code in the library (Edit) - it has none yet">no code</span>') + "</span>" +
    '<span class="lib-acc-price">' + libPriceHtml(e) + "</span>" +
    '<span class="lib-acc-used">' + (others
      ? "also on " + others + " other product" + (others === 1 ? "" : "s")
      : '<span class="muted">only this product</span>') + "</span>" +
    '<span class="lib-acc-acts">' +
      '<button type="button" class="mx-link" data-lib-edit="' + i + '" data-needs="npd.edit">Edit</button>' +
      '<button type="button" class="mx-link lib-remove" data-acc-del="' + i + '" ' +
        'title="Take it off this product - it stays in the library">Remove</button>' +
    "</span></div>";
}

function npdLibLegacyRowHtml(a, i) {
  return '<div class="lib-acc-row is-legacy">' +
    '<div class="lib-acc-main"><span class="lib-thumb is-legacy" aria-hidden="true">!</span>' +
      '<div class="lib-acc-text"><b>' + escapeHtml(a.name) + "</b>" +
        '<div class="lib-acc-specs">On the datasheet — not in the library yet</div></div></div>' +
    '<span class="npd-acc-code" data-code-acccell="' + i + '"></span>' +
    '<span class="npd-money-input lib-legacy-price" title="This product’s own price for it, used until it is in the library">' +
      '<span class="npd-rupee">₹</span><input type="number" step="0.01" min="0" data-acc-price="' + i + '" value="' +
      attr(a.price === "" || a.price === null || a.price === undefined ? "" : String(a.price)) + '" placeholder="0.00"></span>' +
    "<span></span>" +
    '<span class="lib-acc-acts">' +
      '<button type="button" class="btn small" data-lib-choose="' + i + '">Choose from library</button>' +
      '<button type="button" class="mx-link lib-remove" data-acc-del="' + i + '">Remove</button>' +
    "</span></div>";
}

function npdWireLibAccessories(d) {
  const add = app.querySelector("#lib-acc-add");
  if (add) add.addEventListener("click", function () { libPickerOpen(d, null, ""); });
  const list = app.querySelector(".lib-acc-list");
  if (list) list.addEventListener("click", function (e) {
    const b = e.target.closest("button");
    if (!b) return;
    if (b.dataset.libChoose !== undefined) {
      const i = Number(b.dataset.libChoose);
      libPickerOpen(d, i, d.accessories[i].name);
    } else if (b.dataset.libEdit !== undefined) {
      const row = d.accessories[Number(b.dataset.libEdit)];
      libEditorOpen({ entry: row.part, onSaved: function (entry) {
        closeModal();
        npdLibRefreshRows(d, entry);
        npdRenderForm();
      } });
    }
  });
  app.querySelectorAll("[data-acc-price]").forEach(function (inp) {
    inp.addEventListener("input", function () { d.accessories[Number(inp.dataset.accPrice)].price = inp.value; });
  });
  app.querySelectorAll("[data-acc-del]").forEach(function (b) {
    b.addEventListener("click", function () {
      d.accessories.splice(Number(b.dataset.accDel), 1);
      npdRenderForm();
    });
  });
  libLoad();
}

// An accessory picked for this product: added at the end, or in place of the datasheet name it
// was chosen for - whose own price may then move onto it when the product is saved.
function npdLibPick(d, entry, replacing) {
  if (!entry) return;
  const row = { part_id: entry.id, name: entry.name, part: entry };
  const already = d.accessories.findIndex(function (a) { return a.part_id === entry.id; });
  if (replacing !== null && replacing !== undefined && d.accessories[replacing]) {
    row.replaces = d.accessories[replacing].name;
    if (already >= 0) d.accessories.splice(replacing, 1);           // it is on the product already
    else d.accessories.splice(replacing, 1, row);
  } else if (already < 0) {
    d.accessories.push(row);
  }
  npdRenderForm();
}

// After an accessory is edited, every row showing it shows the new version.
function npdLibRefreshRows(d, entry) {
  d.accessories.forEach(function (a) {
    if (a.part_id === entry.id) { a.part = entry; a.name = entry.name; }
  });
}

// ---- the picker: "Add an accessory" / "Choose the library accessory for ..."

function libPickerOpen(d, replacing, query) {
  const from = replacing !== null && replacing !== undefined ? d.accessories[replacing] : null;
  const product = d.product_name || "this product";
  const modal = openModal('<div class="lib-m-head"><span class="close-x" title="Close">&times;</span>' +
    '<h3 class="lib-modal-title">' + (from
      ? "Choose the library accessory for <span>\u201c" + escapeHtml(from.name) + "\u201d</span>"
      : "Add an accessory <span>to " + escapeHtml(product) + "</span>") + "</h3>" +
    '<p class="lib-modal-lede">' + (from
      ? "This product\u2019s datasheet calls it \u201c" + escapeHtml(from.name) + "\u201d. Pick the accessory it " +
        "is \u2014 every variant is listed with its specifications and code \u2014 or create it if it is not " +
        "in the library yet." + (from.price !== "" && from.price !== null && from.price !== undefined
          ? " Its price here, " + escapeHtml(formatListPrice(from.price)) + ", moves onto the accessory " +
            "when the product is saved, if that has no other price."
          : "")
      : "Pick it from the InHouse accessory library.") + "</p>" +
    '<input type="search" id="lib-pick-q" class="lib-input lib-pick-q" placeholder="Search by name, size or code\u2026" ' +
      'value="' + attr(query || "") + '" autocomplete="off">' +
    "</div>" +
    '<div class="lib-m-body"><div id="lib-pick-results" class="lib-pick-results">' +
      '<p class="muted">Reading the library\u2026</p></div></div>' +
    '<div class="lib-m-foot"><div class="lib-m-actions">' +
      '<span class="muted">Not in the library?</span>' +
      '<button type="button" class="btn small" id="lib-pick-new" data-needs="npd.edit">+ Create a new accessory</button>' +
      '<span class="lib-ed-spacer"></span>' +
      '<button type="button" class="btn small secondary" id="lib-pick-close">Close</button>' +
    "</div></div>", "modal-lg lib-modal");
  modal.querySelector("#lib-pick-close").addEventListener("click", closeModal);
  modal.querySelector(".close-x").addEventListener("click", closeModal);
  const q = modal.querySelector("#lib-pick-q");
  const results = modal.querySelector("#lib-pick-results");
  const taken = new Set(d.accessories.filter(function (a) { return a.part_id; }).map(function (a) { return a.part_id; }));

  function draw() {
    if (npdView.lib && npdView.lib.error) {
      results.innerHTML = '<p class="acc-problem">Could not read the library: ' + escapeHtml(npdView.lib.error) + "</p>";
      return;
    }
    const list = (npdView.lib && npdView.lib.list) || [];
    const shown = list.filter(function (e) { return libMatches(e, q.value); });
    if (!list.length) {
      results.innerHTML = '<p class="lib-empty">The library is empty so far — create the first accessory.</p>';
      return;
    }
    if (!shown.length) {
      results.innerHTML = '<p class="lib-empty">Nothing in the library matches “' + escapeHtml(q.value) +
        "”. Check the spelling, or create it.</p>";
      return;
    }
    results.innerHTML = libFamilies(shown).map(function (f) {
      return '<div class="lib-pick-family"><div class="lib-pick-fname">' + escapeHtml(f.name) +
        (f.items.length > 1 ? ' <span class="muted">' + f.items.length + " variants</span>" : "") + "</div>" +
        f.items.map(function (e) {
          const has = taken.has(e.id);
          const specs = libSpecsText(e);
          return '<div class="lib-pick-item' + (has ? " is-taken" : "") + '">' + libThumb(e, "lib-thumb") +
            '<div class="lib-pick-text">' +
              '<div class="lib-pick-specs">' + (specs ? escapeHtml(specs) : '<span class="muted">No specifications</span>') + "</div>" +
              '<div class="lib-pick-meta">' + (e.code ? '<span class="pill">' + escapeHtml(e.code) + "</span>" : "") +
                "<span>" + libPriceHtml(e) + "</span>" +
                '<span class="muted">used by ' + e.products.length + " product" + (e.products.length === 1 ? "" : "s") + "</span>" +
              "</div></div>" +
            (has ? '<span class="lib-pick-added">On this product</span>'
                 : '<button type="button" class="btn small" data-lib-pick="' + e.id + '">' + (from ? "Choose" : "Add") + "</button>") +
          "</div>";
        }).join("") + "</div>";
    }).join("");
  }

  q.addEventListener("input", draw);
  results.addEventListener("click", function (e) {
    const b = e.target.closest("[data-lib-pick]");
    if (!b) return;
    const entry = (npdView.lib.list || []).find(function (x) { return x.id === Number(b.dataset.libPick); });
    closeModal();
    npdLibPick(d, entry, replacing);
  });
  const create = modal.querySelector("#lib-pick-new");
  if (create) create.addEventListener("click", function () {
    libEditorOpen({
      prefill: { name: q.value.trim() || (from ? from.name : ""), price: from ? from.price : "" },
      productId: d.id || 0,
      back: function (name) { libPickerOpen(d, replacing, name !== undefined ? name : q.value); },
      onSaved: function (entry) { closeModal(); npdLibPick(d, entry, replacing); },
      useTwin: function (twin) { closeModal(); npdLibPick(d, twin, replacing); },
    });
  });
  q.focus();
  q.setSelectionRange(q.value.length, q.value.length);
  if (npdView.lib && npdView.lib.list) draw();
  else libLoad().then(draw);
}

// ---- the editor: one accessory's name, code, price, specifications and picture

// A code made from the accessory itself: the letters its variants already use (or the initials of
// its name) and the numbers in its specifications - "U Shape Profile", 16 x 16 mm -> USP16X16.
// Only ever a suggestion, typed into the box for the person to keep or change.
function libSuggestCode(name, specs, family) {
  const coded = family.find(function (e) { return e.code; });
  let base = coded ? ((coded.code.match(/^[A-Z]+/) || [""])[0]) : "";
  if (!base) {
    base = String(name || "").split(/[^A-Za-z0-9]+/).filter(Boolean)
      .map(function (w) { return w[0]; }).join("").toUpperCase();
  }
  const numbers = [];
  specs.forEach(function (s) {
    (String(s.value || "").match(/\d+(?:[.,]\d+)?/g) || []).forEach(function (n) {
      numbers.push(n.replace(",", ".").replace(/\.0+$/, "").replace(".", "P"));
    });
  });
  return (base + numbers.join("X")).slice(0, 60);
}

// opts: {entry} to edit one, or {prefill: {name, price}, productId} for a new one; onSaved(entry);
// back(name) returns to the picker; useTwin(entry) is offered when the accessory already exists.
function libEditorOpen(opts) {
  const entry = opts.entry || null;
  const prefill = opts.prefill || {};
  const canPrice = can("prices.edit");
  const used = entry ? (entry.products || []).length : 0;
  const st = {
    specs: entry ? entry.specs.map(function (s) { return { name: s.name, value: s.value }; })
                 : [{ name: "Dimension", value: "" }],
    file: null, fileUrl: null, pick: null, pickUrl: null, pickNote: "", removePicture: false,
    busy: false, codeTouched: !!(entry && entry.code), gallery: null, galleryOpen: false,
  };
  const startPrice = entry ? (entry.price != null ? String(entry.price) : "")
    : (prefill.price !== "" && prefill.price !== null && prefill.price !== undefined ? String(prefill.price) : "");
  const saveLabel = entry ? "Save changes" : opts.useTwin ? "Create and add" : "Create accessory";

  const modal = openModal(
    '<div class="lib-m-head"><span class="close-x" title="Close">&times;</span>' +
      '<h3 class="lib-modal-title">' + (entry ? "Edit accessory" : "New accessory") + "</h3>" +
      (entry && used
        ? '<p class="lib-shared">Used by <b>' + used + " product" + (used === 1 ? "" : "s") + "</b> — a change " +
          "here applies to all of them. Lines already in BOQs keep what they were added with.</p>"
        : '<p class="lib-modal-lede">Added once, then picked by every product that takes it. Two accessories ' +
          "may share a name — a U Shape Profile in 35 × 35 mm and one in 16 × 16 mm — when a " +
          "specification tells them apart, and each has its own code.</p>") +
    "</div>" +
    '<div class="lib-m-body">' +
      '<section class="lib-sec">' +
        '<h4 class="lib-sec-title">Name and code</h4>' +
        '<div class="lib-field">' +
          '<label class="lib-label" for="lib-ed-name">Name <b class="req">*</b></label>' +
          '<input type="text" id="lib-ed-name" class="lib-input lib-input-lg" maxlength="80" value="' +
            attr(entry ? entry.name : (prefill.name || "")) + '" placeholder="e.g. U Shape Profile" autocomplete="off">' +
          '<div id="lib-ed-match"></div>' +
        "</div>" +
        '<div class="lib-grid2">' +
          '<div class="lib-field">' +
            '<label class="lib-label" for="lib-ed-code">Product code <b class="req">*</b></label>' +
            '<div class="lib-inline">' +
              '<input type="text" id="lib-ed-code" class="lib-input lib-mono" maxlength="60" value="' +
                attr(entry ? entry.code : "") + '" placeholder="e.g. USP16X16" autocomplete="off">' +
              '<button type="button" class="btn small secondary" id="lib-ed-suggest" title="Make one from its name and size">Suggest</button>' +
            "</div>" +
            '<p class="lib-help">Its own code — what it adds to the code of every product that takes it, ' +
              "so no two accessories share one.</p>" +
          "</div>" +
          '<div class="lib-field">' +
            '<label class="lib-label" for="lib-ed-price">Price</label>' +
            '<span class="npd-money-input lib-price-input"><span class="npd-rupee">₹</span>' +
              '<input type="number" min="0" step="0.01" id="lib-ed-price" value="' + attr(startPrice) + '" placeholder="0.00"' +
              (canPrice ? "" : " disabled") + "></span>" +
            '<p class="lib-help">' + (canPrice ? "One price for every product that takes it."
              : "Pricing needs “Change prices” — someone who has it can add it later.") + "</p>" +
          "</div>" +
        "</div>" +
      "</section>" +
      '<section class="lib-sec">' +
        '<h4 class="lib-sec-title">Specifications <span>what tells it apart — printed on its BOQ line</span></h4>' +
        '<div class="lib-spec-head"><span>Specification</span><span>Value</span><span></span></div>' +
        '<div id="lib-ed-specs"></div>' +
        '<datalist id="lib-spec-names"><option value="Dimension"><option value="Length"><option value="Size">' +
          '<option value="Finish"><option value="Colour"><option value="Material"><option value="Beam"></datalist>' +
        '<button type="button" class="btn small ghost lib-add-spec" id="lib-ed-addspec">+ Add specification</button>' +
      "</section>" +
      '<section class="lib-sec">' +
        '<h4 class="lib-sec-title">Picture <span>printed in the Dimension column of its BOQ line</span></h4>' +
        '<div class="lib-pic-row">' +
          '<div class="lib-ed-frame" id="lib-ed-frame"></div>' +
          '<div class="lib-pic-side">' +
            '<div class="lib-pic-btns">' +
              '<button type="button" class="btn small secondary" id="lib-ed-choose">Choose an existing picture</button>' +
              '<label class="btn small secondary">Upload a file<input type="file" accept=".png,.jpg,.jpeg,.gif,.webp" id="lib-ed-file" hidden></label>' +
              '<button type="button" class="btn small ghost lib-remove" id="lib-ed-picremove">Remove</button>' +
            "</div>" +
            '<p class="lib-help" id="lib-ed-picnote"></p>' +
          "</div>" +
        "</div>" +
        '<div id="lib-ed-gallery" class="lib-gallery" hidden></div>' +
      "</section>" +
    "</div>" +
    '<div class="lib-m-foot">' +
      '<div class="lib-ed-problem" id="lib-ed-problem" hidden></div>' +
      '<div class="lib-m-actions">' +
        (opts.back ? '<button type="button" class="btn small secondary" id="lib-ed-back">← Back to the library</button>' : "") +
        '<span class="lib-ed-spacer"></span>' +
        '<button type="button" class="btn small secondary" id="lib-ed-cancel">Cancel</button>' +
        '<button type="button" class="btn small" id="lib-ed-save">' + saveLabel + "</button>" +
      "</div>" +
    "</div>", "modal-lg lib-modal");

  const $ = function (sel) { return modal.querySelector(sel); };
  const nameInput = $("#lib-ed-name");
  const codeInput = $("#lib-ed-code");
  const problem = $("#lib-ed-problem");

  function family() {
    const f = accessoryFold(nameInput.value);
    return ((npdView.lib && npdView.lib.list) || []).filter(function (e) {
      return e.group === f && (!entry || e.id !== entry.id);
    });
  }

  // While the code has not been typed by hand, it follows the name and the specifications.
  function autoCode() {
    if (st.codeTouched) return;
    codeInput.value = libSuggestCode(nameInput.value, st.specs, family());
  }

  function drawPicture() {
    const url = st.fileUrl || st.pickUrl || (!st.removePicture && entry && entry.image_url) || null;
    $("#lib-ed-frame").innerHTML = url ? '<img src="' + attr(url) + '" alt="">' : "<span>No picture yet</span>";
    $("#lib-ed-frame").classList.toggle("is-empty", !url);
    $("#lib-ed-picremove").hidden = !url;
    $("#lib-ed-picnote").textContent = st.file ? "New file: " + st.file.name
      : st.pick ? "Chosen: " + st.pickNote
      : url ? "Its current picture." : "Choose one already in the library or on a datasheet, or upload a file (PNG, JPG, GIF or WebP, up to 8 MB).";
  }

  function drawGallery() {
    const box = $("#lib-ed-gallery");
    box.hidden = !st.galleryOpen;
    $("#lib-ed-choose").textContent = st.galleryOpen ? "Hide pictures" : "Choose an existing picture";
    if (!st.galleryOpen) return;
    if (!st.gallery) { box.innerHTML = '<p class="lib-help">Looking for pictures…</p>'; return; }
    if (st.gallery.error) { box.innerHTML = '<p class="acc-problem">' + escapeHtml(st.gallery.error) + "</p>"; return; }
    const tile = function (pick, url, title, sub) {
      const on = st.pick && JSON.stringify(st.pick) === JSON.stringify(pick);
      return '<button type="button" class="lib-tile' + (on ? " is-on" : "") + '" data-pick="' + attr(JSON.stringify(pick)) +
        '" data-url="' + attr(url) + '" data-note="' + attr(title + (sub ? " · " + sub : "")) + '" title="' + attr(title + (sub ? " · " + sub : "")) + '">' +
        '<img src="' + attr(url) + '" alt="" loading="lazy"><span class="lib-tile-t">' + escapeHtml(title) + "</span>" +
        (sub ? '<span class="lib-tile-s">' + escapeHtml(sub) + "</span>" : "") + "</button>";
    };
    const g = st.gallery;
    box.innerHTML =
      (g.library.length
        ? '<div class="lib-gallery-group"><div class="lib-gallery-title">In the accessory library <span>' + g.library.length + "</span></div>" +
          '<div class="lib-gallery-grid">' + g.library.map(function (p) {
            return tile({ from_part: p.part_id }, p.url, p.name, p.specs);
          }).join("") + "</div></div>"
        : "") +
      (g.datasheet.length
        ? '<div class="lib-gallery-group"><div class="lib-gallery-title">On the datasheets <span>' + g.datasheet.length + "</span></div>" +
          '<div class="lib-gallery-grid">' + g.datasheet.map(function (p) {
            return tile({ from_specsheet: p.specsheet_id, label: p.label }, p.url, p.product, p.label);
          }).join("") + "</div></div>"
        : "") +
      (!g.library.length && !g.datasheet.length
        ? '<p class="lib-help">No pictures yet for an accessory of this name — upload one instead.</p>' : "");
  }

  async function loadGallery() {
    st.gallery = null;
    drawGallery();
    const q = "name=" + encodeURIComponent(nameInput.value.trim()) +
      "&product_id=" + encodeURIComponent(opts.productId || 0) + "&part_id=" + encodeURIComponent(entry ? entry.id : 0);
    try {
      st.gallery = await api("/api/accessory-library/pictures?" + q);
    } catch (err) {
      st.gallery = { error: "Could not look for pictures: " + err.message };
    }
    drawGallery();
  }

  function drawSpecs() {
    $("#lib-ed-specs").innerHTML = st.specs.map(function (s, i) {
      return '<div class="lib-spec-row">' +
        '<input type="text" class="lib-input" data-spec-name="' + i + '" list="lib-spec-names" maxlength="40" ' +
          'value="' + attr(s.name) + '" placeholder="e.g. Dimension" aria-label="Specification">' +
        '<input type="text" class="lib-input" data-spec-value="' + i + '" maxlength="60" ' +
          'value="' + attr(s.value) + '" placeholder="e.g. 35 × 35 mm" aria-label="Value">' +
        '<button type="button" class="acc-icon-btn" data-spec-remove="' + i + '" title="Remove this specification">×</button>' +
        "</div>";
    }).join("") || '<p class="lib-help">None — fine for an accessory that comes in one form only.</p>';
    $("#lib-ed-addspec").hidden = st.specs.length >= 6;
  }

  // As the name is typed: the variants already in the library under it, or close names that may
  // be the same accessory spelled another way.
  function drawMatch() {
    const box = $("#lib-ed-match");
    const list = ((npdView.lib && npdView.lib.list) || []).filter(function (e) { return !entry || e.id !== entry.id; });
    const f = accessoryFold(nameInput.value);
    if (!f) { box.innerHTML = ""; return; }
    const fam = family();
    if (fam.length) {
      box.innerHTML = '<div class="lib-match is-family"><div><b>' + escapeHtml(fam[0].name) + "</b> is already in the library" +
        (fam.length > 1 ? " in " + fam.length + " variants" : "") + ":</div>" +
        '<div class="lib-match-chips">' + fam.map(function (e) {
          return '<span class="lib-chip">' + escapeHtml(libSpecValues(e) || "no specifications") +
            (e.code ? ' <span class="lib-chip-code">' + escapeHtml(e.code) + "</span>" : "") + "</span>";
        }).join("") + "</div>" +
        "<div>This one is saved as another variant under that spelling — give it a specification and a code that tell it apart." +
        (opts.back ? ' <button type="button" class="mx-link" id="lib-ed-usefamily">Pick one of those instead</button>' : "") +
        "</div></div>";
      return;
    }
    const near = libFamilies(list).map(function (fm) { return { fm: fm, score: libSimilar(f, fm.key) }; })
      .filter(function (x) { return x.score >= 0.75 || (f.length >= 4 && (x.fm.key.includes(f) || f.includes(x.fm.key))); })
      .sort(function (a, b) { return b.score - a.score; }).slice(0, 3);
    box.innerHTML = near.length
      ? '<div class="lib-match">Already in the library: ' + near.map(function (x) {
          return '<button type="button" class="lib-chip is-btn" data-lib-name="' + attr(x.fm.name) + '">' +
            escapeHtml(x.fm.name) + "</button>";
        }).join(" ") + " — is it one of these?</div>"
      : "";
  }

  function fail(message, twin) {
    problem.hidden = false;
    problem.innerHTML = '<span class="acc-problem">' + escapeHtml(message) + "</span>" +
      (twin && opts.useTwin ? '<button type="button" class="btn small" id="lib-ed-twin">Use “' +
        escapeHtml(twin.name) + "”" + (libSpecValues(twin) ? " (" + escapeHtml(libSpecValues(twin)) + ")" : "") + "</button>" : "");
    const use = $("#lib-ed-twin");
    if (use) use.addEventListener("click", function () { opts.useTwin(twin); });
  }

  function busy(on) {
    st.busy = on;
    $("#lib-ed-save").disabled = on;
    $("#lib-ed-save").textContent = on ? "Saving…" : saveLabel;
  }

  async function save() {
    if (st.busy) return;
    problem.hidden = true;
    const name = nameInput.value.trim();
    const specs = st.specs.filter(function (s) { return s.name.trim() || s.value.trim(); });
    const code = codeInput.value.trim();
    const priceRaw = $("#lib-ed-price").value.trim();
    if (!name) { fail("Give the accessory a name."); nameInput.focus(); return; }
    if (!code) { fail("Give it a product code of its own — Suggest makes one from its name and size."); codeInput.focus(); return; }
    if (priceRaw && (isNaN(Number(priceRaw)) || Number(priceRaw) < 0)) { fail("A price is a number of rupees."); return; }
    const json = { "Content-Type": "application/json" };
    busy(true);
    let saved;
    try {
      if (entry) {
        saved = await api("/api/accessory-library/" + entry.id, { method: "PUT", headers: json,
          body: JSON.stringify({ name: name, specs: specs, code: code }) });
        if (canPrice && priceRaw !== "" && Number(priceRaw) !== entry.price) {
          saved = await api("/api/accessory-library/" + entry.id + "/price", { method: "PUT", headers: json,
            body: JSON.stringify({ price: Number(priceRaw) }) });
        }
      } else {
        saved = await api("/api/accessory-library", { method: "POST", headers: json,
          body: JSON.stringify({ name: name, specs: specs, code: code,
                                 price: canPrice && priceRaw !== "" ? Number(priceRaw) : null }) });
      }
    } catch (err) {
      busy(false);
      await libLoad(true);
      const twin = err.detail && err.detail.twin_id
        ? (npdView.lib.list || []).find(function (x) { return x.id === err.detail.twin_id; }) : null;
      fail(err.message, twin);
      return;
    }
    // The picture goes after the record exists. If it fails the accessory is still saved - said so.
    try {
      const url = "/api/accessory-library/" + saved.id + "/image";
      if (st.file) {
        const fd = new FormData();
        fd.append("file", st.file);
        saved = await api(url, { method: "POST", body: fd });
      } else if (st.pick) {
        saved = await api(url, { method: "POST", headers: json, body: JSON.stringify(st.pick) });
      } else if (st.removePicture && entry && entry.image) {
        saved = await api(url, { method: "DELETE" });
      }
    } catch (err) {
      alert("“" + saved.name + "” was saved, but its picture was not: " + err.message);
    }
    await libLoad(true);
    busy(false);
    opts.onSaved((npdView.lib.list || []).find(function (x) { return x.id === saved.id; }) || saved);
  }

  modal.querySelector(".close-x").addEventListener("click", closeModal);
  $("#lib-ed-cancel").addEventListener("click", closeModal);
  if (opts.back) $("#lib-ed-back").addEventListener("click", function () { opts.back(); });
  $("#lib-ed-save").addEventListener("click", save);
  nameInput.addEventListener("input", function () { drawMatch(); autoCode(); });
  nameInput.addEventListener("change", function () { if (st.galleryOpen) loadGallery(); });
  codeInput.addEventListener("input", function () { st.codeTouched = codeInput.value.trim() !== ""; });
  $("#lib-ed-suggest").addEventListener("click", function () {
    codeInput.value = libSuggestCode(nameInput.value, st.specs, family());
    st.codeTouched = true;
    codeInput.focus();
  });
  [nameInput, codeInput].forEach(function (inp) {
    inp.addEventListener("keydown", function (e) { if (e.key === "Enter") { e.preventDefault(); save(); } });
  });
  $("#lib-ed-match").addEventListener("click", function (e) {
    const chip = e.target.closest("[data-lib-name]");
    if (chip) { nameInput.value = chip.dataset.libName; drawMatch(); autoCode(); nameInput.focus(); return; }
    if (e.target.closest("#lib-ed-usefamily")) opts.back(nameInput.value);
  });
  $("#lib-ed-specs").addEventListener("input", function (e) {
    const t = e.target;
    if (t.dataset.specName !== undefined) st.specs[Number(t.dataset.specName)].name = t.value;
    if (t.dataset.specValue !== undefined) st.specs[Number(t.dataset.specValue)].value = t.value;
    autoCode();
  });
  $("#lib-ed-specs").addEventListener("click", function (e) {
    const b = e.target.closest("[data-spec-remove]");
    if (!b) return;
    st.specs.splice(Number(b.dataset.specRemove), 1);
    drawSpecs();
    autoCode();
  });
  $("#lib-ed-addspec").addEventListener("click", function () {
    st.specs.push({ name: "", value: "" });
    drawSpecs();
    const inputs = modal.querySelectorAll("[data-spec-name]");
    if (inputs.length) inputs[inputs.length - 1].focus();
  });
  $("#lib-ed-choose").addEventListener("click", function () {
    st.galleryOpen = !st.galleryOpen;
    if (st.galleryOpen && !st.gallery) loadGallery();
    else drawGallery();
  });
  $("#lib-ed-gallery").addEventListener("click", function (e) {
    const t = e.target.closest("[data-pick]");
    if (!t) return;
    st.pick = JSON.parse(t.dataset.pick);
    st.pickUrl = t.dataset.url;
    st.pickNote = t.dataset.note;
    st.file = null;
    st.fileUrl = null;
    st.removePicture = false;
    drawPicture();
    drawGallery();
  });
  $("#lib-ed-file").addEventListener("change", function (e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) { fail("Pictures up to 8 MB."); return; }
    st.file = file;
    st.fileUrl = URL.createObjectURL(file);
    st.pick = null;
    st.pickUrl = null;
    st.removePicture = false;
    drawPicture();
    drawGallery();
  });
  $("#lib-ed-picremove").addEventListener("click", function () {
    st.file = null;
    st.fileUrl = null;
    st.pick = null;
    st.pickUrl = null;
    st.removePicture = true;
    drawPicture();
    drawGallery();
  });
  drawPicture();
  drawSpecs();
  libLoad().then(function () { drawMatch(); autoCode(); });
  nameInput.focus();
}

// ---- NPD -> Accessory library: every InHouse accessory, what it is, costs, and goes with

function npdLibViewHtml() {
  const lib = npdView.lib;
  const head = '<div class="npd-ptables lib-view"><div class="npd-ptables-head">' +
    '<h4>Accessory library <span class="lib-brand">' + escapeHtml(LIB_BRANDS.join(", ")) + "</span></h4>" +
    '<div class="lib-head-acts">' +
      '<button type="button" class="btn small" data-lib-new data-needs="npd.edit">+ New accessory</button>' +
      '<button type="button" class="btn small secondary" data-npd-component="">Close</button>' +
    "</div></div>";
  if (!lib || (!lib.list && !lib.error)) return head + '<p class="npd-ptables-lede">Reading the library…</p></div>';
  if (lib.error) return head + '<p class="npd-ptables-lede">Could not read the library: ' + escapeHtml(lib.error) + "</p></div>";
  const list = lib.list;
  const is = {
    unpriced: function (e) { return e.price == null; },
    nopicture: function (e) { return !e.image_url; },
    unused: function (e) { return !e.products.length; },
  };
  const filter = npdView.libFilter || "";
  const shown = list.filter(function (e) {
    return libMatches(e, npdView.libQuery) && (!filter || is[filter](e));
  });
  // The same chips the product list filters with.
  function chip(label, key, n) {
    return '<button type="button" class="config-tile small' + (filter === key ? " selected" : "") +
      '" data-lib-filter="' + key + '">' + escapeHtml(label) + ' <span class="muted">(' + n + ")</span></button>";
  }
  const rows = libFamilies(shown).map(function (f) {
    const many = f.items.length > 1;
    return (many
      ? '<tr class="lib-family-row"><td colspan="6"><b>' + escapeHtml(f.name) + '</b> <span class="muted">' +
        f.items.length + " variants</span></td></tr>"
      : "") + f.items.map(function (e) {
        const open = npdView.libOpen === e.id;
        return '<tr class="lib-row' + (many ? " is-variant" : "") + (open ? " open" : "") + '">' +
          '<td><div class="lib-name-cell">' + libThumb(e, "lib-thumb") + "<b>" + escapeHtml(e.name) + "</b></div></td>" +
          "<td>" + (e.specs.length
            ? e.specs.map(function (s) {
                return '<span class="lib-spec"><span class="muted">' + escapeHtml(s.name) + "</span> " + escapeHtml(s.value) + "</span>";
              }).join("")
            : '<span class="muted">—</span>') + "</td>" +
          "<td>" + (e.code ? '<span class="pill">' + escapeHtml(e.code) + "</span>" : '<span class="muted">—</span>') + "</td>" +
          '<td class="lib-price-cell">' + libPriceHtml(e) + "</td>" +
          "<td>" + (e.products.length
            ? '<button type="button" class="mx-link" data-lib-used="' + e.id + '">' + e.products.length + " product" +
              (e.products.length === 1 ? "" : "s") + (open ? " ▴" : " ▾") + "</button>"
            : '<span class="muted">Not used yet</span>') + "</td>" +
          '<td class="npd-cat-acts">' +
            '<button type="button" class="mx-link" data-lib-edit-id="' + e.id + '" data-needs="npd.edit">Edit</button>' +
            '<button type="button" class="mx-link lib-remove" data-lib-delete="' + e.id + '" data-needs="npd.edit">Delete</button>' +
          "</td></tr>" +
          (open
            ? '<tr class="npd-cat-detail"><td colspan="6"><div class="npd-cat-products">' + e.products.map(function (p) {
                return '<button type="button" class="npd-cat-product" data-lib-product="' + p.id + '" title="Open this product">' +
                  "<b>" + escapeHtml(p.name) + "</b>" +
                  '<span class="muted">' + escapeHtml([p.series, p.family, p.typology].filter(Boolean).join(" · ")) + "</span></button>";
              }).join("") + "</div></td></tr>"
            : "");
      }).join("");
  }).join("");
  return head +
    '<p class="npd-ptables-lede">Every accessory once, with what it is, what it costs and the products that take it. ' +
    "Products pick from here in their own form (NPD → a product → Accessories); an accessory’s " +
    "specifications, picture, code and price are the same on every product that takes it.</p>" +
    '<div class="npd-chips lib-chips">' +
      chip("All", "", list.length) +
      chip("Not priced", "unpriced", list.filter(is.unpriced).length) +
      chip("No picture", "nopicture", list.filter(is.nopicture).length) +
      chip("Not used yet", "unused", list.filter(is.unused).length) +
    "</div>" +
    '<div class="npd-facet npd-facet-search">' +
      '<input type="search" id="lib-q" placeholder="Search by name, size or code…" value="' + attr(npdView.libQuery || "") + '">' +
      (npdView.libQuery || filter ? '<span class="muted">' + shown.length + " of " + list.length + "</span>" : "") +
    "</div>" +
    (shown.length
      ? '<table class="npd-cat-table lib-table"><thead><tr><th>Accessory</th><th>Specifications</th><th>Code</th>' +
        "<th>Price</th><th>Used in</th><th></th></tr></thead><tbody>" + rows + "</tbody></table>"
      : '<p class="npd-ptables-lede">' + (list.length ? "Nothing matches that."
          : "The library is empty so far. Add accessories here, or from a product’s own form.") + "</p>") +
    '<p class="lib-other"><button type="button" class="mx-link" data-lib-other>Other brands’ accessories, as their datasheets list them →</button></p>' +
    "</div>";
}

function npdWireLibView(root) {
  const view = root.querySelector(".lib-view");
  if (!view) return;
  const search = view.querySelector("#lib-q");
  if (search) search.addEventListener("input", function () {
    npdView.libQuery = search.value;
    npdRenderList();
    const again = app.querySelector("#lib-q");
    if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
  });
  view.addEventListener("click", async function (e) {
    const b = e.target.closest("button");
    if (!b) return;
    if (b.dataset.libFilter !== undefined) {
      npdView.libFilter = b.dataset.libFilter;
      npdRenderList();
    } else if (b.dataset.libNew !== undefined) {
      libEditorOpen({ onSaved: function () { closeModal(); npdRenderList(); } });
    } else if (b.dataset.libEditId !== undefined) {
      const entry = (npdView.lib.list || []).find(function (x) { return x.id === Number(b.dataset.libEditId); });
      if (entry) libEditorOpen({ entry: entry, onSaved: function () { closeModal(); npdRenderList(); } });
    } else if (b.dataset.libUsed !== undefined) {
      const id = Number(b.dataset.libUsed);
      npdView.libOpen = npdView.libOpen === id ? null : id;
      npdRenderList();
    } else if (b.dataset.libProduct !== undefined) {
      npdOpenProduct(Number(b.dataset.libProduct));
    } else if (b.dataset.libDelete !== undefined) {
      const entry = (npdView.lib.list || []).find(function (x) { return x.id === Number(b.dataset.libDelete); });
      if (!entry) return;
      // Removing it everywhere (18 Nov 2026): the products that take it lose it too, named here first.
      const label = entry.name + (libSpecValues(entry) ? " (" + libSpecValues(entry) + ")" : "") + (entry.code ? " - " + entry.code : "");
      const takers = entry.products || [];
      const names = takers.slice(0, 8).map(function (p) { return "  • " + (p.product_name || p.name || "#" + p.id); }).join("\n") +
        (takers.length > 8 ? "\n  • and " + (takers.length - 8) + " more" : "");
      if (!confirm("Remove “" + label + "” from the accessory library" +
          (takers.length ? " and from the " + takers.length + " product" + (takers.length === 1 ? "" : "s") + " that take" +
            (takers.length === 1 ? "s" : "") + " it?\n\n" + names + "\n\nTheir accessory lists and printed sheets lose it. " +
            "BOQ lines already made keep it as they are." : "? No product takes it.") +
          (entry.price != null ? "\n\nIts price goes back to List Pricing’s waiting list rather than being lost." : ""))) return;
      try {
        const done = await api("/api/accessory-library/" + entry.id + "?everywhere=true", { method: "DELETE" });
        const n = (done.products || []).length;
        showToast("Removed " + entry.name + (n ? " from the library and " + n + " product" + (n === 1 ? "" : "s") : " from the library"));
      } catch (err) {
        alert("Could not delete it: " + err.message);
      }
      await libLoad(true);
      npdRenderList();
    } else if (b.dataset.libOther !== undefined) {
      npdView.accOther = true;
      npdRenderList();
      npdLoadAccCatalogue();
    }
  });
}

function npdComponentPricesHtml() {
  if (npdView.component === "accessories") return npdView.accOther ? npdAccCatalogueHtml() : npdLibViewHtml();
  if (npdView.component === "drivers") {
    return '<div class="npd-ptables"><div class="npd-ptables-head">' +
      "<h4>Driver prices</h4>" +
      '<button type="button" class="btn small secondary" data-npd-component="">Close</button>' +
      "</div>" +
      '<p class="npd-ptables-lede">What the Add Driver form fills in \u2014 a driver is quoted ' +
      "as its own line, so these are its prices, not a luminaire's. Every rate is editable " +
      "here: type over one to change it, or add a combination the studio has started selling. " +
      "A blank price means the combination is real but has never been priced, and opens at 0 " +
      "for whoever adds it to type.</p>" +
      driverPricing.types.map(npdDriverTypeHtml).join("") +
      (can("prices.edit") ? '<button type="button" class="btn small" id="npd-add-driver-rate">' +
        "+ Add a driver or a rate</button>" : "") +
      "</div>";
  }
  if (npdView.component === "supplies") {
    const withSupply = npdView.products.filter(function (p) {
      return Object.keys(p.power_supply || {}).length > 0;
    });
    return '<div class="npd-ptables"><div class="npd-ptables-head">' +
      "<h4>Power supply prices</h4>" +
      '<button type="button" class="btn small secondary" data-npd-component="">Close</button>' +
      "</div>" +
      '<p class="npd-ptables-lede">A power supply is priced two ways, and both are real. ' +
      "When it belongs to a fixture it is priced on that fixture, by the control chosen, and " +
      "is added to the fixture\u2019s own price automatically. When it is quoted as its own " +
      "line it is priced from the 24V DC tables, the same ones the Add Driver form uses.</p>" +
      (withSupply.length
        ? '<div class="npd-ptable"><h4>Priced on a fixture</h4>' +
          '<p class="npd-ptable-note">Added to the fixture price as soon as the control is ' +
          "chosen in the Configurator.</p>" +
          '<div class="npd-ptable-scroll"><table><thead><tr><th>Product</th>' +
          [...new Set(withSupply.reduce(function (acc, p) {
            return acc.concat(Object.keys(p.power_supply));
          }, []))].sort().map(function (c) { return "<th>" + escapeHtml(c) + "</th>"; }).join("") +
          "</tr></thead><tbody>" +
          withSupply.map(function (p) {
            const controls = [...new Set(withSupply.reduce(function (acc, q) {
              return acc.concat(Object.keys(q.power_supply)); }, []))].sort();
            return "<tr><th>" + escapeHtml(p.product_name || "Untitled") + "</th>" +
              controls.map(function (c) {
                const v = p.power_supply[c];
                return v == null ? '<td class="npd-ptable-gap">\u2014</td>'
                                 : "<td>\u20b9" + npdMoney(v) + "</td>";
              }).join("") + "</tr>";
          }).join("") + "</tbody></table></div></div>"
        : '<p class="muted">No fixture carries its own power supply price yet.</p>') +
      npdPriceTableHtml("Quoted on its own line \u2014 24V DC, IP rated",
        "Outdoor and wet locations.", driverPriceGrid("24V DC", "IP Rated")) +
      npdPriceTableHtml("Quoted on its own line \u2014 24V DC, non IP rated",
        "Indoor and dry locations.", driverPriceGrid("24V DC", "Non IP Rated")) +
      "</div>";
  }
  return "";
}

function npdClassificationHtml() {
  const scoped = npdBrandProducts();
  const brands = new Map();
  npdView.products.forEach(function (p) {
    if (p.make) brands.set(p.make, (brands.get(p.make) || 0) + 1);
  });
  const typologies = new Map();
  scoped.forEach(function (p) {
    const key = p.typology || NPD_UNCLASSIFIED;
    typologies.set(key, (typologies.get(key) || 0) + 1);
  });
  const priced = scoped.filter(npdIsPriced).length;
  // Counted across every brand, unlike the facets above - a power supply belongs to whatever
  // fixture carries it, not to the brand currently in view.
  const withSupply = npdView.products.filter(function (p) {
    return Object.keys(p.power_supply || {}).length > 0;
  });
  const supplyControls = [...new Set(withSupply.reduce(function (acc, p) {
    return acc.concat(Object.keys(p.power_supply));
  }, []))].sort();

  const chip = function (label, count, active, data) {
    return '<button type="button" class="config-tile small' + (active ? " selected" : "") +
      '" ' + data + ">" + escapeHtml(label) +
      ' <span class="muted">(' + count + ")</span></button>";
  };
  const typologyChips = [...typologies.entries()]
    .filter(function (e) { return e[0] !== NPD_UNCLASSIFIED; })
    .sort(function (a, b) { return b[1] - a[1] || a[0].localeCompare(b[0]); });

  return '<section class="npd-classify">' +
    '<div class="npd-classify-head"><h3>Classification</h3>' +
      '<p class="npd-classify-summary">' + scoped.length + " product" +
        (scoped.length === 1 ? "" : "s") +
        (npdView.brand ? " from " + escapeHtml(npdView.brand) : "") +
        " across " + typologyChips.length + " typolog" +
        (typologyChips.length === 1 ? "y" : "ies") + " \u00b7 <strong>" + priced +
        " priced</strong>, " + (scoped.length - priced) + " still at zero</p></div>" +

    // Only worth a row once there is a choice to make. NPD is InHouse-only for now, and a
    // Brand row reading "All brands (141) | InHouse (141)" is the same answer twice.
    (brands.size > 1
      ? '<div class="npd-facet"><span class="npd-facet-label">Brand</span>' +
        '<div class="npd-chips">' +
          chip("All brands", npdView.products.length, npdView.brand === "", 'data-npd-brand=""') +
          [...brands.entries()]
            .sort(function (a, b) { return b[1] - a[1] || a[0].localeCompare(b[0]); })
            .map(function (e) {
              return chip(e[0], e[1], e[0] === npdView.brand,
                          'data-npd-brand="' + attr(e[0]) + '"');
            }).join("") + "</div></div>"
      : "") +

    '<div class="npd-facet"><span class="npd-facet-label">Typology</span>' +
      '<div class="npd-chips">' +
        chip("All", scoped.length, npdView.typology === "", 'data-npd-typology=""') +
        typologyChips.map(function (e) {
          return chip(e[0], e[1], e[0] === npdView.typology,
                      'data-npd-typology="' + attr(e[0]) + '"');
        }).join("") +
        (typologies.has(NPD_UNCLASSIFIED)
          ? chip("Unclassified", typologies.get(NPD_UNCLASSIFIED),
                 npdView.typology === NPD_UNCLASSIFIED,
                 'data-npd-typology="' + NPD_UNCLASSIFIED + '"')
          : "") +
      "</div></div>" +

    '<div class="npd-facet"><span class="npd-facet-label">Pricing</span>' +
      '<div class="npd-chips">' +
        chip("Any", scoped.length, npdView.priced === "", 'data-npd-priced=""') +
        chip("Priced", priced, npdView.priced === "priced", 'data-npd-priced="priced"') +
        chip("Not priced yet", scoped.length - priced, npdView.priced === "unpriced",
             'data-npd-priced="unpriced"') +
      "</div></div>" +

    // A driver and a power supply are what a fixture needs to actually run, and both are
    // quoted alongside it, so their pricing belongs in this same view rather than in a
    // screen of its own. Each line is a shortcut into the grid below.
    '<div class="npd-components">' +
      '<button type="button" class="npd-component' +
        (npdView.component === "drivers" ? " open" : "") + '" data-npd-component="drivers">' +
        '<span class="npd-component-name">Driver prices</span>' +
        '<span class="npd-component-fig">' + npdDriverPriceCount() + "</span>" +
        '<span class="npd-component-sub">across ' + driverPricing.types.length +
          ' driver types · editable</span></button>' +
      '<button type="button" class="npd-component' +
        (npdView.component === "supplies" ? " open" : "") + '" data-npd-component="supplies">' +
        '<span class="npd-component-name">Power supply prices</span>' +
        '<span class="npd-component-fig">' + withSupply.length + "</span>" +
        '<span class="npd-component-sub">' + (supplyControls.length
          ? "on a fixture, per control: " + escapeHtml(supplyControls.join(", "))
          : "none priced on a fixture yet") + "</span></button>" +
      '<button type="button" class="npd-component' +
        (npdView.component === "accessories" ? " open" : "") + '" data-npd-component="accessories">' +
        '<span class="npd-component-name">Accessory library</span>' +
        '<span class="npd-component-fig">' +
          (npdView.lib && npdView.lib.list ? npdView.lib.list.length : "\u2026") + "</span>" +
        '<span class="npd-component-sub">every accessory the library knows, and the products ' +
          "it goes with</span></button>" +
      // What the Configurator asks when one of these products is added to a BOQ - decided here,
      // per typology, because it is part of how the products are defined.
      '<button type="button" class="npd-component" data-npd-configurator ' +
        'title="Choose what is asked when a product of this brand is added to a BOQ">' +
        '<span class="npd-component-name">Configurator questions</span>' +
        '<span class="npd-component-fig">' + cfgEdTypologiesOf(scoped, npdView.brand || npdDefaultBrand()).length + "</span>" +
        '<span class="npd-component-sub">typologies: what is asked, in which order, when one of these ' +
          "products is added to a BOQ</span></button>" +
      // How each product's code is built lives on the Nomenclature tab now; the tile stays here as
      // the way to it from the products, for whoever may open that tab.
      (can("config.edit")
        ? '<button type="button" class="npd-component" data-npd-goto-nomenclature ' +
            'title="Open the Nomenclature tab">' +
            '<span class="npd-component-name">Product codes →</span>' +
            '<span class="npd-component-fig">' + npdCodesTileFigure() + "</span>" +
            '<span class="npd-component-sub">on the Nomenclature tab: how each product’s code is ' +
              "built, and the abbreviation for every value</span></button>"
        : "") +
    "</div>" +
    npdComponentPricesHtml() +

    '<div class="npd-facet npd-facet-search">' +
      '<input type="search" id="npd-search" placeholder="Search by name, code or parameter \u2014 e.g. 12W 3000K IP65" ' +
        'value="' + attr(npdView.query) + '" aria-describedby="npd-search-hint">' +
      '<div id="npd-search-hint">' + npdQueryHintHtml(npdParseQuery(npdView.query)) + "</div>" +
    "</div>" +
  "</section>";
}

function npdBindClassification() {
  app.querySelectorAll("[data-npd-brand]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.brand = b.dataset.npdBrand;
      // Typologies are named per catalogue, so one brand's selection filters the next to
      // nothing. Clearing it is what makes switching brand show that brand's products.
      npdView.typology = "";
      npdRenderList();
    });
  });
  app.querySelectorAll("[data-npd-typology]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.typology = b.dataset.npdTypology;
      npdRenderList();
    });
  });
  app.querySelectorAll("[data-npd-priced]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.priced = b.dataset.npdPriced;
      npdRenderList();
    });
  });
  // A rate is saved when the box is left, not on every keystroke - typing "1234" would
  // otherwise write 1, then 14, then 147.
  app.querySelectorAll(".npd-rate").forEach(function (input) {
    let asLoaded = input.value;
    input.addEventListener("change", async function () {
      if (input.value.trim() === asLoaded.trim()) return;
      const raw = input.value.trim();
      if (raw && isNaN(Number(raw))) {
        alert("A price has to be a number, or blank for \u201cnot priced yet\u201d.");
        input.value = asLoaded;
        return;
      }
      input.disabled = true;
      try {
        await api("/api/npd/driver-prices/" + input.dataset.rateId,
                  { method: "PUT", headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ price: raw === "" ? null : Number(raw) }) });
        asLoaded = input.value;
        await loadDriverPrices(true);
        npdRenderList();
      } catch (e) {
        alert("Could not save that price: " + e.message);
        input.value = asLoaded;
      } finally {
        input.disabled = false;
      }
    });
  });
  const addRate = app.querySelector("#npd-add-driver-rate");
  if (addRate) addRate.addEventListener("click", npdAddDriverRateModal);

  app.querySelectorAll("[data-npd-component]").forEach(function (b) {
    b.addEventListener("click", function () {
      const want = b.dataset.npdComponent;
      npdView.component = npdView.component === want ? "" : want;   // click again to close
      npdRenderList();
      if (npdView.component === "accessories") {
        npdView.accOther = false;
        libLoad(true).then(npdRenderList);
      }
    });
  });
  const cfgTile = app.querySelector("[data-npd-configurator]");
  if (cfgTile) cfgTile.addEventListener("click", function () {
    const make = npdView.brand || npdDefaultBrand();
    cfgEditorOpen(make, cfgEdTypologiesOf(npdView.products, make),
                  npdView.typology && npdView.typology !== NPD_UNCLASSIFIED ? npdView.typology : "");
  });
  // The brand and typology in view here are the ones the Nomenclature tab opens on.
  const toNomenclature = app.querySelector("[data-npd-goto-nomenclature]");
  if (toNomenclature) toNomenclature.addEventListener("click", function () {
    npdOpenNomenclature(npdView.brand || "",
                        npdView.typology && npdView.typology !== NPD_UNCLASSIFIED ? npdView.typology : null);
  });
  const accSearch = app.querySelector("#npd-acc-search");
  if (accSearch) {
    accSearch.addEventListener("input", function () {
      npdView.accQuery = accSearch.value;
      npdRenderList();
      // The panel is rebuilt on every keystroke, so the box being typed into is a new element.
      const again = app.querySelector("#npd-acc-search");
      if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
    });
  }
  app.querySelectorAll("[data-npd-cat]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.accOpen = npdView.accOpen === b.dataset.npdCat ? "" : b.dataset.npdCat;
      npdRenderList();
    });
  });
  app.querySelectorAll("[data-npd-cat-product]").forEach(function (b) {
    b.addEventListener("click", function () { showSpecsheetDetail(Number(b.dataset.npdCatProduct)); });
  });
  app.querySelectorAll("[data-npd-cat-setup]").forEach(function (b) {
    b.addEventListener("click", function () { npdAccToggleSetup(b.dataset.npdCatSetup); });
  });
  npdWireAccSetup(app);
  npdWireLibView(app);
  app.querySelectorAll("[data-lib-back]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.accOther = false;
      npdRenderList();
    });
  });
  app.querySelectorAll("[data-npd-cat-rename]").forEach(function (b) {
    b.addEventListener("click", function () {
      const key = b.dataset.npdCatRename;
      npdView.accRename = npdView.accRename === key ? "" : key;
      npdView.accRenameTo = null;
      npdRenderList();
      const box = app.querySelector("#npd-cat-rename-input");
      if (box) { box.focus(); box.select(); }
    });
  });
  const renameBox = app.querySelector("#npd-cat-rename-input");
  if (renameBox) {
    renameBox.addEventListener("input", function () {
      npdView.accRenameTo = renameBox.value;
      npdRenderList();
      const again = app.querySelector("#npd-cat-rename-input");
      if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
    });
    renameBox.addEventListener("keydown", function (e) {
      if (e.key === "Enter") { e.preventDefault(); npdAccDoRename(npdView.accRename, renameBox.value); }
    });
  }
  const renameGo = app.querySelector("#npd-cat-rename-go");
  if (renameGo) {
    renameGo.addEventListener("click", function () {
      npdAccDoRename(npdView.accRename, app.querySelector("#npd-cat-rename-input").value);
    });
  }
  app.querySelectorAll("[data-npd-cat-merge]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdView.accIssuesOpen = true;
      npdAccDoRename(b.dataset.npdCatMerge, b.dataset.npdCatMergeTo);
    });
  });
  const search = app.querySelector("#npd-search");
  if (search) {
    search.addEventListener("input", function () {
      npdView.query = search.value;
      npdRenderList();
      // npdRenderList() replaces the whole panel, so the box being typed into is a new
      // element each keystroke; without this the caret leaves after the first character.
      const again = app.querySelector("#npd-search");
      if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
    });
  }
}

// What a card says about its product: the typology, then what names it - mounting, aperture,
// heads, trim, voltage - in the order its code reads. Two sheets called "CURVE -Micro" are two
// different fittings, and this line is where a reader sees how, without opening either.
function npdCardMetaHtml(p) {
  const named = (p.identity_code && p.identity_code.values) || [];
  const parts = named.length
    ? [p.typology].concat(named.map(function (v) { return npdDisplayValue(v.value); }))
    : [p.typology, p.series, p.family, p.variant];
  const text = parts.filter(Boolean).join(" · ");
  return '<div class="npd-card-meta" title="' + attr(text) + '">' + escapeHtml(text) + "</div>";
}

// A catalogue value as a person would write it: WITH TRIM as With Trim, LENS + REFLECTOR as
// Lens + Reflector - but an acronym or a number stays as it is (RGBW, 220-240V AC).
const NPD_ACRONYMS = new Set(["RGB", "RGBW", "LED", "AC", "DC", "TW", "IP", "DALI", "DMX", "PWM", "UV", "COB"]);
function npdDisplayValue(value) {
  return String(value || "").split(/(\s+|\/|\+)/).map(function (w) {
    if (!/^[A-Z]{2,}$/.test(w) || NPD_ACRONYMS.has(w)) return w;
    return w.charAt(0) + w.slice(1).toLowerCase();
  }).join("");
}

function npdRenderList() {
  if (npdView.brand === null) npdView.brand = npdDefaultBrand();
  const rows = npdVisibleProducts();
  const terms = npdParseQuery(npdView.query);
  app.innerHTML =
    '<div class="npd-head">' +
      "<div>" + npdBrandPickerHtml() + "<h2>New Product Development — InHouse</h2>" +
      '<p class="muted npd-lede">Author a product and its pricing together. What you enter here is ' +
      "the source of truth: the specsheet is generated from it, and every configuration is priced " +
      "from the same definition. A new product stays here until it is approved — until then it is " +
      "not in the Specsheet Library and cannot be quoted.</p></div>" +
      (can("npd.edit") ? '<button class="btn primary" id="npd-new">+ New product</button>' : "") +
    "</div>" +
    npdClassificationHtml() +
    (rows.length === 0
      ? '<div class="npd-empty"><h3>' +
        (npdView.products.length ? "Nothing matches those filters" : "No products yet") +
        "</h3>" +
        '<p class="muted">' + (npdView.products.length
          ? "Widen the classification above to see the rest of the catalogue."
          : "Start one and it joins the Specsheet Library like any other product — " +
            "browsable, matchable, and addable to a BOQ, with its price already attached.") +
        "</p></div>"
      : '<div class="npd-count muted">Showing ' + rows.length + " of " +
        npdBrandProducts().length + "</div>" +
        '<div class="card-grid npd-grid">' + rows.map(function (p) {
          return '<div class="spec-card npd-card">' +
            '<div class="npd-card-img">' + (p.thumb_url
              ? '<img src="' + p.thumb_url + '" alt="">'
              : '<div class="npd-noimg">no image</div>') + "</div>" +
            '<div class="npd-card-body">' +
              '<div class="npd-card-name">' + escapeHtml(p.product_name || "Untitled") +
                npdStatusTag(p.approval_status) + "</div>" +
              npdCardMetaHtml(p) +
              (terms.length ? npdMatchChipsHtml(p, npdMatchProduct(p, terms)) : "") +
              (p.model_no ? '<div class="npd-card-meta">Model ' + escapeHtml(p.model_no) + "</div>" : "") +
              // The identity part of its code - greyed with a "?" where a segment is unsettled,
              // so an unfinished classification is visible from the list.
              (p.identity_code
                ? '<div class="npd-card-code' + (p.identity_code.complete ? "" : " incomplete") +
                  '" title="' + (p.identity_code.complete ? "Product code (identity part)"
                    : "Not complete - a segment has no value or no abbreviation yet") + '">' +
                  escapeHtml(p.identity_code.code || p.identity_code.partial) + "</div>"
                : "") +
              '<div class="npd-card-price">' +
                (p.base_price == null || p.base_price === 0
                  ? '<span class="price-tag-none">Not priced yet</span>'
                  : '<span class="price-tag-locked">Base ₹' + npdMoney(p.base_price) + "</span>") +
                (p.adder_count ? '<span class="npd-adders">' + p.adder_count + " adder" +
                  (p.adder_count === 1 ? "" : "s") + "</span>" : "") +
              "</div>" +
              // The power supply is bought with the fixture and quoted with it, so what it
              // costs belongs on the fixture's own card rather than a screen away.
              (Object.keys(p.power_supply || {}).length
                ? '<div class="npd-card-supply"><span class="npd-supply-head">Power supply</span>' +
                  Object.keys(p.power_supply).sort().map(function (control) {
                    return '<span class="npd-supply-row">' + escapeHtml(control) +
                      ' <b>₹' + npdMoney(p.power_supply[control]) + "</b></span>";
                  }).join("") + "</div>"
                : "") +
              '<div class="row-actions">' +
                '<a class="btn small npd-sheet npd-sheet-' +
                  (NPD_STATUS_LABEL[p.approval_status] ? p.approval_status : "pending") +
                  '" href="/api/specsheets/' + p.id +
                  '/generated-specsheet.pdf?preview=true" target="_blank" rel="noopener">Specsheet</a>' +
                '<button class="btn small secondary" data-edit="' + p.id + '">' +
                  (npdCanEdit() ? "Edit" : "View") + "</button>" +
                (can("npd.approve") ? npdStatusActions(p) : "") +
                (IS_ADMIN
                  ? '<button class="btn small danger" data-npd-delete="' + p.id + '" data-name="' +
                    attr(p.product_name || "this product") + '" title="Delete this product - for one discontinued or entered wrongly">Delete</button>'
                  : "") +
              "</div>" +
            "</div></div>";
        }).join("") + "</div>");

  npdBindClassification();
  npdBindBrandPicker();
  app.querySelector("#npd-new")?.addEventListener("click", async function (e) {
    const draft = npdBlankDraft();
    await withBusy(e.currentTarget, function () { return npdEnsureCodesData(draft.make); });
    npdView.addingClass = false;
    npdView.editing = draft;
    npdRenderForm();
  });
  app.querySelectorAll("[data-npd-jump]").forEach(function (b) {
    b.addEventListener("click", async function () {
      await npdOpenProduct(b.dataset.npdJump, b.dataset.key);
      // Straight to the parameter as soon as the form is drawn - waiting for its code took two to
      // three seconds of looking at the top of the form. The jump npdOpenProduct keeps pending
      // still lands once the codes arrive and redraw the form, so the caret ends up there too.
      if (npdView.editing) npdJumpTo(b.dataset.key);
    });
  });
  app.querySelectorAll("[data-edit]").forEach(function (b) {
    b.addEventListener("click", function () { npdOpenProduct(b.dataset.edit); });
  });
  app.querySelectorAll("[data-status]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdSetStatus(b.dataset.id, b.dataset.status, b);
    });
  });
  app.querySelectorAll("[data-npd-delete]").forEach(function (b) {
    b.addEventListener("click", function () {
      npdDeleteProduct(b.dataset.npdDelete, b.dataset.name, b);
    });
  });
}

// ---------------------------------------------------------------- what the Configurator asks
//
// NPD decides what the Configurator asks when a product is added to a BOQ, per brand and typology
// (app/configurator.py, models.ConfiguratorField). One editor for every brand, opened from
// InHouse's "Configurator questions" tile and DuraGreen's header button. Left: the details shown,
// in order, each renamable, and under them the ones not shown. Right: the Configure tab as it will
// look, drawn from the products' real values. A detail some product is sold in more than one of is
// always asked - it is locked, and says why - so what is decided is the order, the names, and
// which fixed details are shown beside the choices.
const cfgEd = { make: "", typologies: [], typology: "", data: null, shown: [], saved: "",
                decided: new Set(), canEdit: false, dragKey: "", modal: null };

const CFGED_LOCK_SVG = '<svg class="cfged-lock" viewBox="0 0 16 16" width="12" height="12" aria-hidden="true" focusable="false">' +
  '<rect x="3" y="7" width="10" height="7" rx="1.5" fill="currentColor"/>' +
  '<path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';

function cfgEdSignature() { return JSON.stringify(cfgEd.shown.map((f) => [f.key, f.label])); }
function cfgEdDirty() { return !!cfgEd.data && cfgEdSignature() !== cfgEd.saved; }

// Typologies of one brand with how many products each has: [{typology, count}], most first.
function cfgEdTypologiesOf(products, make) {
  const counts = new Map();
  products.forEach((p) => {
    if (p.make && p.make !== make) return;
    if (p.typology) counts.set(p.typology, (counts.get(p.typology) || 0) + 1);
  });
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([typology, count]) => ({ typology, count }));
}

async function cfgEditorOpen(make, typologies, initialTypology) {
  cfgEd.make = make;
  cfgEd.typologies = typologies;
  cfgEd.canEdit = can("npd.edit");
  cfgEd.data = null;
  cfgEd.typology = typologies.some((t) => t.typology === initialTypology)
    ? initialTypology : ((typologies[0] || {}).typology || "");
  const brand = NPD_BRAND_LABEL[make] || make;
  cfgEd.modal = openModal(
    '<span class="close-x" title="Close">✕</span>' +
    "<h3>What the Configurator asks — " + escapeHtml(brand) + "</h3>" +
    '<p class="muted cfged-lede">Decide what someone sees when they add a ' + escapeHtml(brand) +
    " product to a BOQ, one typology at a time. Details a product is sold in more than one of are " +
    "always asked; you choose their order, what each is called, and which fixed details are shown beside them." +
    (cfgEd.canEdit ? "" : " You can look; changing it needs “Create and edit products”.") + "</p>" +
    '<div class="cfged-typologies" aria-label="Typology"></div>' +
    '<div id="cfged-body"><p class="muted">Loading…</p></div>', "modal-lg cfged-modal");
  cfgEd.modal.querySelector(".close-x").addEventListener("click", cfgEdClose);
  if (!cfgEd.typology) {
    cfgEd.modal.querySelector("#cfged-body").innerHTML =
      '<div class="empty-state">No ' + escapeHtml(brand) + " product has a typology yet. Classify one in NPD first.</div>";
    return;
  }
  try {
    cfgEd.decided = new Set((await api("/api/npd/configurator/decided?make=" + encodeURIComponent(make))).typologies);
  } catch (e) {
    cfgEd.decided = new Set();
  }
  cfgEdRenderTypologies();
  await cfgEdLoad();
}

function cfgEdClose() {
  if (cfgEdDirty() && !confirm("Close without saving your changes to " + cfgEd.typology + "?")) return;
  cfgEd.data = null;
  closeModal();
}

function cfgEdRenderTypologies() {
  const holder = cfgEd.modal.querySelector(".cfged-typologies");
  holder.innerHTML = '<div class="npd-chips">' + cfgEd.typologies.map((t) =>
    '<button type="button" class="config-tile small' + (t.typology === cfgEd.typology ? " selected" : "") +
    '" data-cfged-typology="' + attr(t.typology) + '" aria-pressed="' + (t.typology === cfgEd.typology) + '">' +
    escapeHtml(t.typology) + ' <span class="muted">(' + t.count + ")</span>" +
    (cfgEd.decided.has(t.typology) ? '<span class="cfged-set" title="Set in NPD">set</span>' : "") +
    "</button>").join("") + "</div>";
  holder.querySelectorAll("[data-cfged-typology]").forEach((b) => b.addEventListener("click", async () => {
    const want = b.dataset.cfgedTypology;
    if (want === cfgEd.typology) return;
    if (cfgEdDirty() && !confirm("Leave " + cfgEd.typology + " without saving your changes?")) return;
    cfgEd.typology = want;
    cfgEdRenderTypologies();
    await cfgEdLoad();
  }));
}

async function cfgEdLoad() {
  const body = cfgEd.modal.querySelector("#cfged-body");
  body.innerHTML = '<p class="muted">Loading…</p>';
  try {
    cfgEd.data = await api("/api/npd/configurator?make=" + encodeURIComponent(cfgEd.make) +
                           "&typology=" + encodeURIComponent(cfgEd.typology));
  } catch (e) {
    body.innerHTML = '<div class="error-box">Could not load it: ' + escapeHtml(e.message) + "</div>";
    return;
  }
  cfgEd.shown = cfgEd.data.fields.filter((f) => f.shown).map((f) => ({ key: f.key, label: f.label }));
  cfgEd.saved = cfgEdSignature();
  cfgEdRender();
}

function cfgEdValues(f) {
  const vals = f.values.slice(0, 5).join(", ");
  const more = f.values.length - 5 + (f.more_values || 0);
  return vals + (more > 0 ? " and " + more + " more" : "");
}

function cfgEdRowHtml(f, shown, index, count) {
  const d = cfgEd.data;
  const label = shown ? cfgEd.shown[index].label : f.label;
  const renamed = shown && label && label !== f.npd_label;
  const meta = "On " + f.products + " of " + d.products + " product" + (d.products === 1 ? "" : "s") +
    (renamed ? "; NPD calls it “" + f.npd_label + "”" : "") +
    (f.added_back ? "; put back on its own - it is a choice" : "");
  const nameHtml = shown && cfgEd.canEdit
    ? '<input class="cfged-label" type="text" maxlength="60" value="' + attr(label) + '" placeholder="' + attr(f.npd_label) +
      '" aria-label="Name for ' + attr(f.npd_label) + ' in the Configurator">'
    : '<span class="cfged-label-text">' + escapeHtml(label) + "</span>";
  const moves = !cfgEd.canEdit ? "" : shown
    ? '<div class="cfged-moves">' +
        '<button type="button" class="btn small ghost cfged-move" data-dir="-1" title="Move up" aria-label="Move ' + attr(label) + ' up"' + (index === 0 ? " disabled" : "") + ">↑</button>" +
        '<button type="button" class="btn small ghost cfged-move" data-dir="1" title="Move down" aria-label="Move ' + attr(label) + ' down"' + (index === count - 1 ? " disabled" : "") + ">↓</button>" +
        (f.locked ? "" : '<button type="button" class="btn small secondary cfged-hide">Hide</button>') +
      "</div>"
    : '<div class="cfged-moves"><button type="button" class="btn small secondary cfged-show">Show</button></div>';
  return '<li class="cfged-row' + (f.locked ? " is-locked" : "") + (shown ? "" : " is-off") + '" data-key="' + attr(f.key) + '"' +
    (shown && cfgEd.canEdit ? ' draggable="true"' : "") + ">" +
    (shown && cfgEd.canEdit ? '<span class="cfged-grip" title="Drag to reorder" aria-hidden="true"></span>' : "") +
    '<div class="cfged-main">' + nameHtml +
      '<div class="cfged-values">' + escapeHtml(cfgEdValues(f)) + "</div>" +
      '<div class="cfged-meta">' + escapeHtml(meta) + "</div>" +
      (f.locked ? '<div class="cfged-why">' + CFGED_LOCK_SVG + "Always asked: " + escapeHtml(f.why) + "</div>" : "") +
    "</div>" + moves + "</li>";
}

function cfgEdPreviewHtml() {
  const byKey = new Map(cfgEd.data.fields.map((f) => [f.key, f]));
  return cfgEd.shown.map((s) => {
    const f = byKey.get(s.key);
    return '<div class="cfged-mfield"><label class="lbl">' + escapeHtml(s.label || f.npd_label) + "</label>" +
      '<select tabindex="-1" aria-hidden="true"><option>Any</option>' +
      f.values.map((v) => "<option>" + escapeHtml(v) + "</option>").join("") + "</select></div>";
  }).join("");
}

function cfgEdRefreshChrome() {
  const m = cfgEd.modal;
  const preview = m.querySelector(".cfged-mock");
  if (preview) preview.innerHTML = cfgEdPreviewHtml();
  const flag = m.querySelector(".cfged-unsaved");
  if (flag) flag.hidden = !cfgEdDirty();
  const save = m.querySelector("#cfged-save");
  if (save) save.disabled = !cfgEdDirty();
}

function cfgEdRender(focus) {
  const d = cfgEd.data;
  const body = cfgEd.modal.querySelector("#cfged-body");
  const byKey = new Map(d.fields.map((f) => [f.key, f]));
  const shownKeys = new Set(cfgEd.shown.map((f) => f.key));
  const off = d.fields.filter((f) => !shownKeys.has(f.key));
  const when = d.saved_at ? new Date(d.saved_at).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "";
  body.innerHTML =
    '<div class="cfged-status' + (d.decided ? " is-set" : "") + '">' + (d.decided
      ? "Set in NPD" + (d.saved_by ? " by " + escapeHtml(d.saved_by) : "") + (when ? " on " + escapeHtml(when) : "") +
        ". The Configure tab and the product form ask exactly this list for " + escapeHtml(cfgEd.typology) + "."
      : "Automatic: nobody has set " + escapeHtml(cfgEd.typology) + " yet, so this is what the Configurator works out " +
        "for itself today. Saving makes the list yours to keep.") + "</div>" +
    '<div class="cfged-grid">' +
      '<section class="cfged-col">' +
        '<h4 class="cfged-h">Shown, in this order <span class="muted">(' + cfgEd.shown.length + ")</span></h4>" +
        '<ol class="cfged-list" id="cfged-shown">' +
          cfgEd.shown.map((s, i) => cfgEdRowHtml(byKey.get(s.key), true, i, cfgEd.shown.length)).join("") + "</ol>" +
        (off.length
          ? '<h4 class="cfged-h">Not shown <span class="muted">(' + off.length + ")</span></h4>" +
            '<p class="muted cfged-note">Other details the ' + d.products + " " + escapeHtml(cfgEd.typology) +
            " products record in NPD. Show one to let people filter by it and to carry it onto the BOQ line.</p>" +
            '<ul class="cfged-list">' + off.map((f) => cfgEdRowHtml(f, false, 0, 0)).join("") + "</ul>"
          : "") +
      "</section>" +
      '<aside class="cfged-preview">' +
        '<h4 class="cfged-h">Preview</h4>' +
        '<p class="muted cfged-note">The Configure tab for ' + escapeHtml(cfgEd.typology) +
          ", filled with the values these products hold.</p>" +
        '<div class="cfged-mock"></div>' +
      "</aside>" +
    "</div>" +
    '<div class="cfged-actions">' +
      (d.decided && cfgEd.canEdit ? '<button type="button" class="btn secondary" id="cfged-reset">Back to automatic</button>' : "") +
      '<span class="cfged-unsaved" hidden>Unsaved changes</span>' +
      '<button type="button" class="btn secondary" id="cfged-close">Close</button>' +
      (cfgEd.canEdit ? '<button type="button" class="btn primary" id="cfged-save">Save</button>' : "") +
    "</div>";
  cfgEdRefreshChrome();
  cfgEdBind();
  if (focus) {
    const target = body.querySelector('.cfged-row[data-key="' + CSS.escape(focus.key) + '"] ' + focus.selector);
    if (target && !target.disabled) target.focus();
  }
}

function cfgEdMove(key, to) {
  const from = cfgEd.shown.findIndex((f) => f.key === key);
  if (from < 0 || to < 0 || to >= cfgEd.shown.length || to === from) return;
  const [item] = cfgEd.shown.splice(from, 1);
  cfgEd.shown.splice(to, 0, item);
}

function cfgEdBind() {
  const body = cfgEd.modal.querySelector("#cfged-body");
  body.querySelector("#cfged-close").addEventListener("click", cfgEdClose);
  body.querySelectorAll("#cfged-shown .cfged-row").forEach((row) => {
    const key = row.dataset.key;
    const entry = () => cfgEd.shown.find((f) => f.key === key);
    const input = row.querySelector(".cfged-label");
    if (input) input.addEventListener("input", () => { entry().label = input.value.trim() || input.placeholder; cfgEdRefreshChrome(); });
    row.querySelectorAll(".cfged-move").forEach((b) => b.addEventListener("click", () => {
      const at = cfgEd.shown.findIndex((f) => f.key === key);
      cfgEdMove(key, at + Number(b.dataset.dir));
      cfgEdRender({ key, selector: '.cfged-move[data-dir="' + b.dataset.dir + '"]' });
    }));
    const hide = row.querySelector(".cfged-hide");
    if (hide) hide.addEventListener("click", () => {
      cfgEd.shown = cfgEd.shown.filter((f) => f.key !== key);
      cfgEdRender();
    });
    // Drag to reorder: dropped on a row, the dragged detail takes that row's place.
    row.addEventListener("dragstart", (e) => {
      cfgEd.dragKey = key;
      row.classList.add("is-dragging");
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", key);
    });
    row.addEventListener("dragend", () => { cfgEd.dragKey = ""; row.classList.remove("is-dragging"); });
    row.addEventListener("dragover", (e) => {
      if (!cfgEd.dragKey || cfgEd.dragKey === key) return;
      e.preventDefault();
      row.classList.add("is-drop-target");
    });
    row.addEventListener("dragleave", () => row.classList.remove("is-drop-target"));
    row.addEventListener("drop", (e) => {
      e.preventDefault();
      const dragged = cfgEd.dragKey;
      cfgEd.dragKey = "";
      if (!dragged || dragged === key) return;
      cfgEdMove(dragged, cfgEd.shown.findIndex((f) => f.key === key));
      cfgEdRender();
    });
  });
  body.querySelectorAll(".cfged-show").forEach((b) => b.addEventListener("click", () => {
    const key = b.closest(".cfged-row").dataset.key;
    const f = cfgEd.data.fields.find((x) => x.key === key);
    cfgEd.shown.push({ key, label: f.npd_label });
    cfgEdRender({ key, selector: ".cfged-label" });
  }));
  const save = body.querySelector("#cfged-save");
  if (save) save.addEventListener("click", () => withBusy(save, async () => {
    try {
      cfgEd.data = await api("/api/npd/configurator", {
        method: "PUT", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ make: cfgEd.make, typology: cfgEd.typology, fields: cfgEd.shown }),
      });
    } catch (e) { alert(e.message); return; }
    cfgEd.shown = cfgEd.data.fields.filter((f) => f.shown).map((f) => ({ key: f.key, label: f.label }));
    cfgEd.saved = cfgEdSignature();
    cfgEd.decided.add(cfgEd.typology);
    cfgEdRenderTypologies();
    cfgEdRender();
    showToast("Saved. The Configurator now asks " + cfgEd.shown.length + " details for " + cfgEd.typology + ".");
  }));
  const reset = body.querySelector("#cfged-reset");
  if (reset) reset.addEventListener("click", () => {
    if (!confirm("Put " + cfgEd.typology + " back on the automatic list? Your order, names and shown details for it are forgotten.")) return;
    withBusy(reset, async () => {
      try {
        cfgEd.data = await api("/api/npd/configurator?make=" + encodeURIComponent(cfgEd.make) +
                               "&typology=" + encodeURIComponent(cfgEd.typology), { method: "DELETE" });
      } catch (e) { alert(e.message); return; }
      cfgEd.shown = cfgEd.data.fields.filter((f) => f.shown).map((f) => ({ key: f.key, label: f.label }));
      cfgEd.saved = cfgEdSignature();
      cfgEd.decided.delete(cfgEd.typology);
      cfgEdRenderTypologies();
      cfgEdRender();
      showToast(cfgEd.typology + " is back on the automatic list.");
    });
  });
}

// Admins only - the server refuses anyone else. A product on BOQs is retired, not erased: it leaves
// NPD and every picker, and those BOQs keep it and export exactly as before (18 Nov 2026).
async function npdDeleteProduct(id, name, button) {
  if (!confirm('Delete "' + name + '"?\n\nIt disappears from NPD and can no longer be added to a BOQ. ' +
      "If BOQs already use it, they keep it exactly as it is and export as before - only those lines can " +
      "no longer be reconfigured. Otherwise its price-sheet rows go back to List Pricing's waiting list " +
      "and rules written for it alone are deleted. This cannot be undone from the screen.")) return;
  const original = button.textContent;
  button.disabled = true;
  button.textContent = "…";
  try {
    const r = await api("/api/npd/products/" + id, { method: "DELETE" });
    state.specsheets = [];        // the library's contents just changed
    await renderNpd(currentRender());
    showToast('Deleted "' + name + '"' +
      (r.retired ? " - kept as it is on " + r.boq_lines + " BOQ line" + (r.boq_lines === 1 ? "" : "s") : "") +
      (r.prices_released ? " - " + r.prices_released + " price row(s) back in List Pricing" : "") +
      (r.rules_deleted ? " - " + r.rules_deleted + " rule(s) for it removed" : "") + ".");
  } catch (e) {
    button.disabled = false;
    button.textContent = original;
    alert(e.message);
  }
}

function npdRenderForm() {
  const d = npdView.editing;

  // Whether a parameter affects the price is a property of the parameter, so it is asked on
  // the parameter - not gathered into a separate pricing step that makes you hold the sheet
  // in your head while filling in a second form about it. The template's own is_configurable
  // is the starting answer; this product can disagree with it.
  d.groups.forEach(function (g) {
    g.parameters.forEach(function (p) {
      if (d.affects[p.field_key] === undefined) d.affects[p.field_key] = !!p.is_configurable;
    });
  });

  const priced = npdPricedParameters(d);

  const paramsHtml = !d.typology
    ? '<p class="npd-await">Choose a typology above and the parameters that describe it ' +
      "appear here.</p>"
    : d.groups.length === 0
      ? '<p class="npd-await">No parameters yet for ' + escapeHtml(d.typology) +
        " — add the ones this product needs.</p>"
      : d.groups.filter(npdIsSpecGroup).map(function (g) {
          return '<div class="npd-group">' +
            '<div class="npd-group-head"><span>' + escapeHtml(g.group_name) + "</span>" +
            '<button class="btn tiny ghost" data-addparam="' + escapeHtml(g.group_name) +
            '">Add parameter</button></div>' +
            '<div class="npd-rows">' + g.parameters.map(function (p) {
              return npdParameterRow(d, p, npdMoveRoom(d, p));
            }).join("") + "</div></div>";
        }).join("");

  app.innerHTML =
    '<div class="npd-head"><div><h2>' +
      (!npdCanEdit() ? escapeHtml(d.product_name || "Product")
        : d.id ? "Edit " + escapeHtml(d.product_name || "product") : "New product") + "</h2>" +
      '<p class="muted npd-lede">' +
      (!npdCanEdit()
        ? "Everything this product is defined by - its identity, pictures, specification, " +
          "prices and accessories. This is a read-only view; only an admin can change a product."
        : d.id
        ? "Change the specification or the pricing. An approved product returns to awaiting " +
          "approval when it is edited, since the approval was given for the earlier version."
        : "What the product is, and what it costs, in one place. Nothing is saved until you " +
          "finish.") + "</p></div>" +
      '<button class="btn secondary" id="npd-cancel">' + (npdCanEdit() ? "Cancel" : "Back") +
      "</button></div>" +

    // Identity reads top to bottom as it is decided: what the product is called, then what it
    // is - each classification value with its code beside it, in the order the code reads -
    // and last, tucked away, how the sheet prints its name, which is held and rarely touched.
    '<section class="npd-step npd-step-identity"><h3><span class="npd-num">1</span> Identity</h3>' +
      '<div class="npd-fields npd-name-fields">' +
        '<label class="npd-f-wide"><span class="npd-cap">Product name<b class="req">*</b></span>' +
          '<input id="npd-name" value="' + escapeHtml(d.product_name) +
          '" placeholder="e.g. NOVA -Mini"></label>' +
        '<label>Make <input id="npd-make" value="' + escapeHtml(d.make) + '"></label>' +
        '<label>Model number <input id="npd-model" value="' + escapeHtml(d.model_no) +
          '" placeholder="LL-NOVA-M"></label>' +
        '<label title="A short label the Library shows beside the name. Trim, adjustability and ' +
          'supply voltage have fields of their own.">Variant label' +
          '<input class="npd-ident-value" data-ident-value="variant" value="' + attr(d.variant || "") +
          '" placeholder="e.g. Trimless"></label>' +
      "</div>" +
      '<div class="npd-classbox">' +
        '<div class="npd-classbox-head"><span class="npd-classbox-title">Classification</span>' +
          '<span class="npd-classbox-sub">What the product is. Each value has its code beside it, ' +
          "in the order the product code reads.</span></div>" +
        '<div class="npd-fields npd-class-fields">' +
          '<label class="npd-ident npd-class"><span class="npd-cap">Typology<b class="req">*</b></span>' +
            '<span class="npd-ident-row"><select id="npd-typology"><option value="">Choose…</option>' +
            npdView.typologies.map(function (t) {
              return '<option value="' + escapeHtml(t.typology) + '"' +
                (t.typology === d.typology ? " selected" : "") + ">" +
                escapeHtml(t.typology) + "</option>";
            }).join("") + "</select>" +
            (d.typology && npdInCode(d, "typology") ? npdCodeBoxHtml("typology", d.typology, "Typology") : "") +
            "</span>" +
            '<button type="button" class="npd-linkbtn" id="npd-new-typology">' +
            "Not listed? Add a typology</button></label>" +
          npdClassFieldsHtml(d) +
          npdIdentityExtrasHtml(d) +
        "</div>" +
        npdAddClassHtml(d) +
      "</div>" +
      npdSheetNameHtml(d) +
    "</section>" +

    '<section class="npd-step"><h3><span class="npd-num">2</span> Pictures</h3>' +
      '<div class="npd-uploads">' +
        npdUploadHtml("npd-img", "Product image", d.files.product_image,
                      d.existing["Product Image"]) +
        npdUploadHtml("npd-diag", "Line diagram", d.files.line_diagram,
                      d.existing["Line Diagram"]) +
      "</div>" + npdMoreDiagramsHtml(d) + "</section>" +

    '<section class="npd-step"><h3><span class="npd-num">3</span> Specification &amp; price</h3>' +
      '<div class="npd-basebar">' +
        '<label class="npd-base">Base price' +
          '<span class="npd-money-input"><span class="npd-rupee">₹</span>' +
          '<input id="npd-base" type="number" min="0" step="0.01" value="' + d.base_price +
          '" placeholder="0.00"></span></label>' +
        '<p class="npd-basenote">Every configuration starts here. Mark a parameter as ' +
        "<strong>affects price</strong> and each of its options can add to it.</p>" +
      "</div>" +
      paramsHtml +
      (priced.length ? '<div class="npd-preview" id="npd-preview"></div>' : "") +
    "</section>" +

    npdAccessoriesHtml(d) +
    // Rules (17 Nov 2026): choices that depend on other choices. Drawn by npdLoadRules once the
    // product is saved, since a rule belongs to a product or its typology.
    (d.id ? '<section class="npd-step npd-rules" id="npd-rules"></section>' : "") +

    // The code reads along the foot of the page wherever you are on it, with anything still
    // missing as a link to the field that needs it.
    '<div class="npd-save-bar">' +
      '<div class="npd-codebar-wrap"><div class="npd-codebar" id="npd-codebar" aria-live="polite"></div>' +
        // The structure is kept on the Nomenclature tab, offered only to whoever may open it.
        (can("config.edit")
          ? '<button type="button" class="npd-linkbtn npd-codebar-how" id="npd-code-structure">' +
            "How codes are built</button>"
          : "") + "</div>" +
      '<div class="npd-save-msg" id="npd-msg"></div>' +
      '<button class="btn primary" id="npd-save"' + (d.saving ? " disabled" : "") + ">" +
      (d.saving ? "Saving…" : (d.id ? "Save changes" : "Save product & generate specsheet")) +
      "</button></div>";

  npdWireForm(d);
  npdWireAccessories(d);
  npdCodeWire(d);
  npdApplyEditRights();
  npdLoadRules(d);
  // The last answer is shown straight away - a redraw never waits on the server - and a fresh
  // one is asked for whenever there is none yet.
  if (d.code === undefined) npdCodeRefreshSoon(d, 0);
  else npdCodeCellsRender(d);
  const sheet = app.querySelector(".npd-sheetname");
  if (sheet) sheet.addEventListener("toggle", function () { npdView.sheetNameOpen = sheet.open; });
}

// How the sheet prints the product's name and title - held values, rarely changed, so shown as
// one line that opens to the two editors rather than as two editors always in the way.
function npdSheetNameHtml(d) {
  return '<details class="npd-sheetname"' + (npdView.sheetNameOpen ? " open" : "") + ">" +
    '<summary><span class="npd-sheetname-title">On the specsheet</span>' +
      '<span class="npd-sheetname-bar">' + escapeHtml(npdNameBarText(d) || "unnamed") + "</span>" +
      '<span class="npd-sheetname-edit">Edit name and title</span></summary>' +
    '<div class="npd-sheetname-body">' + npdIdentityPreviewHtml(d) + npdTitleBlockHtml(d) + "</div>" +
  "</details>";
}

// The product page for someone who may look but not change. Every field still shows what it
// holds - including each parameter's "Affects price" switch, which is part of what a viewer
// came to see - but none can be changed, and the controls that exist only to change
// something are taken away rather than left greyed out. The server refuses the change
// regardless; this is so the page does not offer what it would refuse.
// Whether this person can change anything about a product at all - its specification, its
// prices, or both. Which of the two is decided field by field in npdApplyEditRights.
function npdCanEdit() { return can("npd.edit") || can("prices.edit"); }

// A product's price fields: the base price, each option's adder, each accessory's price.
// Everything else on the page is specification - including which options a parameter has and
// whether it affects price at all, since those decide what the product is offered as.
const NPD_PRICE_FIELDS = "#npd-base, [data-optadd-key], [data-acc-price]";

// Opens the product page with exactly the fields this person may change. With both
// permissions nothing is locked; with neither it is the read-only view below; with one, the
// other half is locked and its add/remove controls are taken away. The server makes the same
// split on save (see npd_update_product), so this only keeps the page honest about it.
function npdApplyEditRights() {
  const spec = can("npd.edit");
  const price = can("prices.edit");
  if (spec && price) return;
  if (!spec && !price) { npdMakeReadOnly(); return; }
  const priceFields = new Set(Array.from(app.querySelectorAll(NPD_PRICE_FIELDS)));
  app.querySelectorAll(".npd-step input, .npd-step select, .npd-step textarea, [data-affects]")
    .forEach(function (el) {
      const isPrice = priceFields.has(el);
      if ((isPrice && !price) || (!isPrice && !spec)) el.disabled = true;
    });
  if (!spec) {
    app.querySelectorAll(".npd-optadd, .npd-optdel, .npd-linkbtn, .npd-del, .npd-move, .npd-acc-del, " +
      "#npd-acc-add, #lib-acc-add, [data-lib-choose], .lib-remove, [data-addparam], .npd-drop-cta, input[type=file]")
      .forEach(function (el) { el.style.display = "none"; });
  }
  const msg = app.querySelector("#npd-msg");
  if (msg) msg.textContent = spec
    ? "You can change this product\u2019s specification, not its prices."
    : "You can change this product\u2019s prices, not its specification.";
}

function npdMakeReadOnly() {
  app.querySelectorAll("input, select, textarea").forEach(function (el) { el.disabled = true; });
  app.querySelectorAll("button").forEach(function (b) {
    if (b.id !== "npd-cancel") b.disabled = true;
  });
  app.querySelectorAll(
    "#npd-save, .npd-optadd, .npd-optdel, .npd-linkbtn:not(.npd-codebar-how), .npd-del, .npd-move, .npd-acc-del, " +
    "#npd-acc-add, #lib-acc-add, [data-lib-choose], .lib-remove, [data-addparam], .npd-drop-cta, input[type=file]"
  ).forEach(function (el) { el.style.display = "none"; });
  app.querySelectorAll(".npd-drop-name").forEach(function (el) {
    if (el.textContent.trim() === "No file chosen") el.textContent = "None";
  });
}


// Whether a parameter can move up or down: only past another row of its own group, the same
// rule the server applies. Looked for across the whole template rather than within the block
// on screen, because a group can appear twice - a parameter added to an earlier group used to
// land at the end, after the others - and its arrow is how that row gets walked back home.
function npdMoveRoom(d, p) {
  const all = [];
  d.groups.forEach(function (g) {
    g.parameters.forEach(function (q) { all.push({ id: q.id, group: g.group_name }); });
  });
  const at = all.findIndex(function (q) { return q.id === p.id; });
  const mine = function (q) { return q.group === all[at].group; };
  return { up: all.slice(0, at).some(mine), down: all.slice(at + 1).some(mine) };
}

// The two arrows that move a parameter within its group. They change the typology's template,
// like Add parameter and Remove do, so the order holds for every product of this kind.
function npdMoveButtons(p, move) {
  const btn = function (dir, glyph, can) {
    return '<button type="button" class="npd-move-btn" data-moveparam="' + attr(String(p.id)) +
      '" data-movedir="' + dir + '"' + (can ? "" : " disabled") +
      ' title="Move ' + attr(p.label) + " " + dir + " - for every product of this typology\">" +
      glyph + "</button>";
  };
  return '<span class="npd-move">' + btn("up", "&#9650;", move.up) +
    btn("down", "&#9660;", move.down) + "</span>";
}

// One printed row: what it is called, what it says, and whether it changes the price. The
// adders sit inside the row rather than in a pricing section of their own, so the option and
// the money it costs are read together.
function npdParameterRow(d, p, move) {
  const arrows = move ? npdMoveButtons(p, move) : "";
  // Accessories are a list of orderable things with their own prices, not one fact about the
  // luminaire, so they are entered in their own section. The row still appears, because it is
  // printed on the sheet - it just shows what that section says rather than offering a second
  // place to type it and disagree.
  if (p.field_key === "accessories") {
    const named = d.accessories.map(function (a) { return a.name; }).filter(Boolean);
    return '<div class="npd-row is-managed">' +
      '<div class="npd-row-label">' + arrows + escapeHtml(p.label) + "</div>" +
      '<div class="npd-row-value"><div class="npd-managed">' +
        (named.length ? escapeHtml(named.join(" / ")) : "None") +
      "</div></div>" +
      '<div class="npd-row-code"></div>' +
      '<div class="npd-row-price"><span class="npd-managed-note">set in Accessories below' +
      "</span></div></div>";
  }

  const key = p.field_key;
  const on = !!d.affects[key];

  const head =
    '<div class="npd-row-label">' + arrows + escapeHtml(p.label) +
      // Any parameter can go (18 Nov 2026) - from this typology and every product of it.
      (can("npd.edit") && p.id
        ? ' <button class="npd-del" data-delparam="' + p.id + '" data-delkey="' + escapeHtml(p.field_key) +
          '" data-dellabel="' + escapeHtml(p.label) + '" data-delgroup="' + escapeHtml(p.group_name || "") +
          '" title="Remove this parameter from the ' + escapeHtml(d.typology) + ' template">Remove</button>'
        : "") +
    "</div>";
  const toggle =
    '<div class="npd-row-price">' +
      '<button type="button" class="npd-toggle' + (on ? " on" : "") +
      '" data-affects="' + escapeHtml(key) + '" role="switch" aria-checked="' +
      (on ? "true" : "false") + '">' +
      '<span class="npd-toggle-track"><span class="npd-toggle-knob"></span></span>' +
      '<span class="npd-toggle-text">Affects price</span></button>' +
    "</div>";

  // Not priced: one value, typed as it is printed.
  if (!on) {
    return '<div class="npd-row">' + head +
      '<div class="npd-row-value"><input data-key="' + escapeHtml(key) + '" value="' +
        escapeHtml(d.values[key] || "") + '" placeholder="value">' +
        // one code per option, when the value offers several
        '<div class="npd-code-strip" data-code-strip="' + escapeHtml(key) + '"></div></div>' +
      '<div class="npd-row-code" data-code-cell="' + escapeHtml(key) + '"></div>' +
      toggle + "</div>";
  }

  // Priced: the parameter's options, each with the amount it adds to the base price. This is
  // the whole point of the switch, so turning it on has to hand you the place to type those
  // amounts - an earlier version only revealed them once you had typed "A / B / C" into a
  // single value box, which meant the switch appeared to do nothing at all.
  const rows = npdOptionRows(d, key);
  return '<div class="npd-row is-priced">' + head +
    '<div class="npd-row-value"><div class="npd-optlist">' +
      '<div class="npd-optlist-head"><span>Option</span><span>Code</span>' +
      "<span>Adds to base price</span><span></span></div>" +
      rows.map(function (r, i) {
        return '<div class="npd-optrow">' +
          // No example in the box. One example cannot suit every parameter - a CCT's options
          // and a wattage's look nothing alike - and repeating one down the whole form put a
          // colour temperature inside ACTUAL POWER. The column heading says what goes here.
          '<input data-opt-key="' + escapeHtml(key) + '" data-opt-i="' + i + '" value="' +
            escapeHtml(r.value) + '">' +
          '<span class="npd-optcode" data-code-optcell="' + escapeHtml(key) + '" data-i="' + i + '"></span>' +
          '<span class="npd-money-input small"><span class="npd-rupee">+₹</span>' +
            '<input type="number" step="0.01" data-optadd-key="' + escapeHtml(key) +
            '" data-optadd-i="' + i + '" value="' + escapeHtml(String(r.adder)) +
            '" placeholder="0"></span>' +
          '<button type="button" class="npd-optdel" data-optdel-key="' + escapeHtml(key) +
            '" data-optdel-i="' + i + '" title="Remove this option">×</button>' +
        "</div>";
      }).join("") +
      '<button type="button" class="npd-optadd" data-optadd-new="' + escapeHtml(key) +
      '">+ Add option</button>' +
    "</div></div>" +
    '<div class="npd-row-code" data-code-cell="' + escapeHtml(key) + '"></div>' +
    toggle + "</div>";
}

// The option/adder rows for one parameter. Seeded the first time the switch is turned on from
// whatever was already typed in the plain value box, so nothing is lost by switching, and from
// any adders already recorded against those values.
function npdOptionRows(d, key) {
  if (!d.optionRows[key]) {
    const existing = npdOptionsOf(d.values[key]);
    const adders = d.adders[key] || {};
    d.optionRows[key] = existing.length
      ? existing.map(function (v) {
          return { value: v, adder: adders[v] === undefined ? "" : String(adders[v]) };
        })
      : [{ value: "", adder: "" }];
  }
  return d.optionRows[key];
}

// The option rows are the truth while a parameter is priced; the printed value and the adder
// map are derived from them, so the sheet and the pricing cannot disagree about what the
// options are.
function npdSyncOptionRows(d, key) {
  const rows = d.optionRows[key] || [];
  const values = rows.map(function (r) { return String(r.value).trim(); }).filter(Boolean);
  d.values[key] = values.join(" / ");
  const adders = {};
  rows.forEach(function (r) {
    const v = String(r.value).trim();
    const amount = Number(r.adder);
    if (v && r.adder !== "" && !isNaN(amount) && amount !== 0) adders[v] = amount;
  });
  if (Object.keys(adders).length) d.adders[key] = adders;
  else delete d.adders[key];
}


// The parameters that can carry adders: marked as affecting the price, with more than one
// option, and counted once per field even where a sheet prints the same fact twice.
function npdPricedParameters(d) {
  const out = [], seen = {};
  d.groups.forEach(function (g) {
    g.parameters.forEach(function (p) {
      if (!d.affects[p.field_key] || seen[p.field_key]) return;
      if (!npdOptionsOf(d.values[p.field_key]).length) return;
      seen[p.field_key] = true;
      out.push(p);
    });
  });
  return out;
}

function npdWireForm(d) {
  const bind = function (id, key) {
    const node = app.querySelector(id);
    if (node) node.addEventListener("input", function () { d[key] = node.value; });
  };
  bind("#npd-name", "product_name");
  bind("#npd-model", "model_no"); bind("#npd-make", "make");
  // The model number is the right-hand end of the name bar in the preview, so it follows the
  // typing there too - the preview is only worth having if it is never out of date.
  const model = app.querySelector("#npd-model");
  if (model) model.addEventListener("input", function () {
    const right = app.querySelector(".npd-ident-bar-model");
    if (right) right.textContent = model.value;
  });
  npdWireIdentity(d);
  npdBindTitleBlock(d);

  app.querySelector("#npd-typology").addEventListener("change", async function (e) {
    d.typology = e.target.value;
    d.groups = [];
    if (d.typology) {
      try {
        const res = await api("/api/npd/parameters?typology=" + encodeURIComponent(d.typology));
        d.groups = res.groups || [];
      } catch (err) { d.groups = []; }
    }
    // Which identity fields this typology names its products by, and every short code already
    // known for their values - both change with the typology.
    await npdLoadIdentity(d);
    npdRenderForm();
  });
  app.querySelector("#npd-new-typology").addEventListener("click", npdNewTypologyModal);

  const img = app.querySelector("#npd-img");
  if (img) img.addEventListener("change", function () {
    d.files.product_image = img.files[0] || null; npdRenderForm();
  });
  const diag = app.querySelector("#npd-diag");
  if (diag) diag.addEventListener("change", function () {
    d.files.line_diagram = diag.files[0] || null; npdRenderForm();
  });
  // More dimension drawings: several files at once, each removable before or after saving
  const more = app.querySelector("#npd-more-diag");
  if (more) more.addEventListener("change", function () {
    d.files.more_diagrams = (d.files.more_diagrams || []).concat(Array.from(more.files || []));
    npdRenderForm();
  });
  app.querySelectorAll("[data-more-drop]").forEach(function (b) {
    b.addEventListener("click", function () {
      const label = b.dataset.moreDrop;
      if (b.dataset.saved) d.removeDiagrams = (d.removeDiagrams || []).concat([label]);
      else d.files.more_diagrams.splice(Number(label), 1);
      npdRenderForm();
    });
  });

  app.querySelectorAll("[data-key]").forEach(function (inp, idx) {
    const key = inp.dataset.key;
    inp.dataset.row = String(idx);
    inp.addEventListener("input", function () {
      const before = npdOptionsOf(d.values[key]).join("|");
      d.values[key] = inp.value;
      if (key === "adjustability" || key === "trim_details") npdRefreshTitle(d);
      // Rows share a key only when they are the same fact entered twice (a few seeded
      // templates repeat a line in one group), so those are kept equal. A name repeated under
      // another banner - IP RATING for the luminaire and for its driver - has a key of its
      // own (npd.distinct_field_key) and is never touched by this.
      app.querySelectorAll('[data-key="' + key + '"]').forEach(function (other) {
        if (other !== inp) other.value = inp.value;
      });
      if (npdOptionsOf(inp.value).join("|") !== before) npdUpdatePreview();
    });
  });

  app.querySelectorAll("[data-affects]").forEach(function (b) {
    b.addEventListener("click", function () {
      const key = b.dataset.affects;
      d.affects[key] = !d.affects[key];
      // Turning it off drops any adders recorded against it, rather than keeping money on a
      // parameter the product no longer says is priced.
      if (!d.affects[key]) { delete d.adders[key]; delete d.optionRows[key]; }
      else npdOptionRows(d, key);        // seed from whatever was already typed
      npdRenderForm();
    });
  });

  app.querySelectorAll("[data-addparam]").forEach(function (b) {
    b.addEventListener("click", function () { npdAddParameterModal(b.dataset.addparam); });
  });
  app.querySelectorAll("[data-delparam]").forEach(function (b) {
    b.addEventListener("click", async function () {
      const label = b.dataset.dellabel || "this parameter";
      if (!confirm('Remove "' + label + '" from ' + (b.dataset.delgroup || "its group") + " for every " + d.typology +
          " product?\n\nIt disappears from the template, from every " + d.typology + " product authored in NPD and " +
          "from their sheets. What each product held is kept in the activity log. A parameter that sets a price " +
          "cannot be removed until those prices are.")) return;
      try {
        const r = await api("/api/npd/parameters/" + b.dataset.delparam, { method: "DELETE" });
        // this form forgets it too - a value it still held would be saved straight back
        const key = b.dataset.delkey;
        const res = await api("/api/npd/parameters?typology=" + encodeURIComponent(d.typology));
        d.groups = res.groups || [];
        const still = d.groups.some(function (g) { return g.parameters.some(function (p) { return p.field_key === key; }); });
        if (key && !still) {
          delete d.values[key];
          delete d.adders[key];
          delete d.affects[key];
          if (d.optionRows) delete d.optionRows[key];
        }
        showToast("Removed " + label + (r && r.products ? " from " + r.products + " product" + (r.products === 1 ? "" : "s") : ""));
        npdRenderForm();
      } catch (e) { alert(e.message); }
    });
  });
  // Moving a parameter. What has been typed lives in `d`, not in the inputs, so redrawing the
  // form after the move loses nothing. Every arrow is disabled while one move is in flight, so
  // a quick double click cannot send a second move computed from the old order.
  app.querySelectorAll("[data-moveparam]").forEach(function (b) {
    b.addEventListener("click", async function () {
      const id = b.dataset.moveparam, dir = b.dataset.movedir;
      app.querySelectorAll("[data-moveparam]").forEach(function (x) { x.disabled = true; });
      try {
        await api("/api/npd/parameters/" + encodeURIComponent(id) + "/move", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ direction: dir }),
        });
      } catch (e) { alert(e.message); }
      try {
        const res = await api("/api/npd/parameters?typology=" + encodeURIComponent(d.typology));
        d.groups = res.groups || [];
      } catch (e) { /* keep the order we had; the redraw below re-enables the arrows */ }
      npdRenderForm();
      // Keep the arrow under the cursor focused, so moving a row several places is repeated
      // clicks (or Enter presses) rather than hunting for where it went each time.
      const again = app.querySelector('[data-moveparam="' + id + '"][data-movedir="' + dir + '"]');
      if (again && !again.disabled) again.focus();
    });
  });

  const base = app.querySelector("#npd-base");
  if (base) base.addEventListener("input", function () {
    d.base_price = base.value; npdUpdatePreview();
  });
  // An option's name. Typed freely - the printed value and the adder map are rebuilt from
  // these rows, so there is no second place for them to disagree.
  app.querySelectorAll("[data-opt-key]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      const k = inp.dataset.optKey;
      d.optionRows[k][Number(inp.dataset.optI)].value = inp.value;
      npdSyncOptionRows(d, k);
      npdUpdatePreview();
    });
  });
  // What that option adds to the base price.
  app.querySelectorAll("[data-optadd-key]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      const k = inp.dataset.optaddKey;
      d.optionRows[k][Number(inp.dataset.optaddI)].adder = inp.value;
      npdSyncOptionRows(d, k);
      npdUpdatePreview();
    });
  });
  app.querySelectorAll("[data-optadd-new]").forEach(function (b) {
    b.addEventListener("click", function () {
      const k = b.dataset.optaddNew;
      d.optionRows[k].push({ value: "", adder: "" });
      npdRenderForm();
      const rows = app.querySelectorAll('[data-opt-key="' + k + '"]');
      if (rows.length) rows[rows.length - 1].focus();
    });
  });
  app.querySelectorAll("[data-optdel-key]").forEach(function (b) {
    b.addEventListener("click", function () {
      const k = b.dataset.optdelKey;
      d.optionRows[k].splice(Number(b.dataset.optdelI), 1);
      if (!d.optionRows[k].length) d.optionRows[k].push({ value: "", adder: "" });
      npdSyncOptionRows(d, k);
      npdRenderForm();
    });
  });
  npdUpdatePreview();

  app.querySelector("#npd-cancel").addEventListener("click", function () {
    npdView.editing = null; npdRenderList();
  });
  app.querySelector("#npd-save").addEventListener("click", npdSave);
}



// The dearest and cheapest configuration this product can be ordered in. Two numbers say more
// about whether the adders are right than a single worked example would.
function npdUpdatePreview() {
  const d = npdView.editing;
  const box = app.querySelector("#npd-preview");
  if (!box) return;
  const base = Number(d.base_price || 0);
  let low = base, high = base;
  Object.keys(d.adders).forEach(function (key) {
    const opts = npdOptionsOf(d.values[key]);
    if (!opts.length) return;
    const amounts = opts.map(function (o) { return Number(d.adders[key][o] || 0); });
    // A parameter whose only option carries an adder always costs that much, so it lifts
    // both ends of the range rather than being a choice between two prices.
    low += Math.min.apply(null, amounts);
    high += Math.max.apply(null, amounts);
  });
  box.innerHTML = '<div class="npd-preview-inner">' +
    '<span class="npd-preview-label">This product will price between</span> ' +
    "<strong>₹" + npdMoney(low) + "</strong> <span class=\"muted\">and</span> " +
    "<strong>₹" + npdMoney(high) + '</strong> <span class="muted">depending on the ' +
    "configuration chosen</span></div>";
}

function npdAddParameterModal(groupName) {
  const d = npdView.editing;
  const modal = openModal(
    '<span class="close-x" title="Close">×</span>' +
    "<h3>Add a parameter</h3>" +
    '<p class="muted">It is added to the <strong>' + escapeHtml(d.typology) +
    "</strong> template, so the next product of this kind starts with it too.</p>" +
    '<label>Group<input id="npd-np-group" value="' + escapeHtml(groupName) + '"></label>' +
    '<label>Label (as printed on the sheet)<input id="npd-np-label" placeholder="MOUNTING TYPE"></label>' +
    '<label class="npd-check"><input type="checkbox" id="npd-np-cfg"> ' +
    "A choice the buyer makes, with options that can carry price adders</label>" +
    '<div class="modal-actions"><button class="btn secondary" id="npd-np-cancel">Cancel</button>' +
    '<button class="btn primary" id="npd-np-add">Add parameter</button></div>');
  modal.querySelector(".close-x").addEventListener("click", closeModal);
  modal.querySelector("#npd-np-cancel").addEventListener("click", closeModal);
  modal.querySelector("#npd-np-add").addEventListener("click", async function () {
    const label = modal.querySelector("#npd-np-label").value.trim();
    if (!label) return;
    try {
      await api("/api/npd/parameters", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          typology: d.typology,
          group_name: modal.querySelector("#npd-np-group").value.trim(),
          label: label,
          is_configurable: modal.querySelector("#npd-np-cfg").checked,
        }),
      });
      const res = await api("/api/npd/parameters?typology=" + encodeURIComponent(d.typology));
      d.groups = res.groups || [];
      closeModal();
      npdRenderForm();
    } catch (e) { alert(e.message); }
  });
}

async function npdSave() {
  const d = npdView.editing;
  const msg = app.querySelector("#npd-msg");
  if (!d.product_name.trim()) { msg.textContent = "Give the product a name first."; return; }
  if (!d.typology) { msg.textContent = "Choose a typology first."; return; }
  d.saving = true;
  npdRenderForm();

  const form = new FormData();
  form.append("payload", JSON.stringify({
    product_name: d.product_name, typology: d.typology, series: d.series,
    family: d.family, variant: d.variant, model_no: d.model_no, make: d.make,
    sub_typology: d.sub_typology,
    description_line: d.description_line,
    values: d.values,
    // Which parameters this product treats as a choice - the "affects price" switches. Sent
    // so the Configurator offers a dropdown for exactly the parameters that carry adders.
    affects: d.affects,
    base_price: d.base_price === "" ? null : Number(d.base_price),
    price_adders: d.adders,
    accessories: npdAccessoriesPayload(d),
    remove_diagrams: d.removeDiagrams || [],
  }));
  if (d.files.product_image) form.append("product_image", d.files.product_image);
  if (d.files.line_diagram) form.append("line_diagram", d.files.line_diagram);
  (d.files.more_diagrams || []).forEach(function (f) { form.append("more_diagrams", f); });

  try {
    const res = d.id
      ? await api("/api/npd/products/" + d.id, { method: "PUT", body: form })
      : await api("/api/npd/products", { method: "POST", body: form });
    const wasEdit = !!d.id;
    npdView.editing = null;
    state.specsheets = [];          // what the Library holds has changed
    await renderNpd(currentRender());
    if (!wasEdit) window.open(res.specsheet_url + "?preview=true", "_blank", "noopener");
  } catch (e) {
    d.saving = false;
    npdRenderForm();
    const m = app.querySelector("#npd-msg");
    if (m) m.textContent = e.message;
  }
}

// A kind of product the studio has not documented before. It starts from the InHouse sheet
// shape rather than from nothing - a blank sheet is not a useful place to begin describing a
// luminaire, and everything issued should read the same way whether or not there were products
// of that kind before. Every parameter can then be renamed, removed or added to.
function npdNewTypologyModal() {
  const d = npdView.editing;
  const modal = openModal(
    '<span class="close-x" title="Close">×</span>' +
    "<h3>Add a typology</h3>" +
    '<p class="muted">It starts with the standard InHouse parameters — the four banners a ' +
    "specsheet is divided into — which you can then change for this kind of product.</p>" +
    '<label>Typology name<input id="npd-nt-name" placeholder="e.g. Linear Profile"></label>' +
    '<div class="npd-nt-msg" id="npd-nt-msg"></div>' +
    '<div class="modal-actions"><button class="btn secondary" id="npd-nt-cancel">Cancel</button>' +
    '<button class="btn primary" id="npd-nt-add">Add typology</button></div>');
  modal.querySelector(".close-x").addEventListener("click", closeModal);
  modal.querySelector("#npd-nt-cancel").addEventListener("click", closeModal);
  const input = modal.querySelector("#npd-nt-name");
  input.focus();
  const submit = async function () {
    const name = input.value.trim();
    if (!name) return;
    try {
      await api("/api/npd/typologies", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ typology: name }),
      });
      npdView.typologies = await api("/api/npd/typologies");
      d.typology = name;
      const res = await api("/api/npd/parameters?typology=" + encodeURIComponent(name));
      d.groups = res.groups || [];
      closeModal();
      npdRenderForm();
    } catch (e) {
      modal.querySelector("#npd-nt-msg").textContent = e.message;
    }
  };
  modal.querySelector("#npd-nt-add").addEventListener("click", submit);
  input.addEventListener("keydown", function (e) { if (e.key === "Enter") submit(); });
}

// The price of one configuration of a product authored in NPD: its base price plus the adder
// recorded against each option chosen. Mirrors price_for() in app/npd.py - the same sum is
// available from /api/npd/price for anything server-side, and is computed here as well so the
// number moves the instant a dropdown changes rather than after a round trip.
//
// An option with no adder costs nothing extra, which is the default and the common case. The
// status is reported as "locked" because, unlike a matched price entry, there is nothing
// uncertain about it: it is the rule the product was defined with, not a reading of somebody
// else's price sheet.
// Priced by base + adders: authored in NPD, or a DuraGreen product, whose prices are entered in
// NPD (DuraGreen) the same way. Mirrors priced_by_rule() in app/npd.py.
function pricedByRule(specsheet) {
  return !!specsheet && (specsheet.origin === "npd" || specsheet.make === "Duragreen");
}

function resolveNpdPrice(specsheet, current) {
  if (!pricedByRule(specsheet)) return null;
  if (specsheet.base_price === null || specsheet.base_price === undefined) return null;
  const adders = specsheet.price_adders || {};
  let total = Number(specsheet.base_price);
  Object.keys(adders).forEach(function (key) {
    const chosen = current ? current[key] : null;
    if (!chosen) return;
    const amount = Number(adders[key][chosen] || 0);
    if (amount) total += amount;
  });
  // The power supply is a separate physical component with its own price, which depends on
  // the control chosen - SOLARA Midi's is Rs N On/Off but Rs N Dali. That is true of
  // the fixture no matter how the fixture itself is priced, so it is added here exactly as
  // the price-entry branch below adds it; without this, moving a product onto NPD pricing
  // silently dropped its power supply from the quote.
  total += resolvePowerSupplyAdder(specsheet, current ? current.control : null);
  return { price: Math.round(total * 100) / 100, status: "locked", npd: true };
}

// What the base price and each adder contributed, so a configurator price can be understood
// rather than only accepted - the same itemisation price_breakdown() produces server-side.
function npdPriceParts(specsheet, current) {
  if (!pricedByRule(specsheet)) return null;
  if (specsheet.base_price === null || specsheet.base_price === undefined) return null;
  const adders = specsheet.price_adders || {};
  const parts = [{ label: "Base", amount: Number(specsheet.base_price) }];
  Object.keys(adders).forEach(function (key) {
    const chosen = current ? current[key] : null;
    if (!chosen) return;
    const amount = Number(adders[key][chosen] || 0);
    if (amount) {
      parts.push({ label: configFieldLabel(specsheet, key) + " " + chosen, amount: amount });
    }
  });
  const ps = resolvePowerSupplyAdder(specsheet, current ? current.control : null);
  if (ps) parts.push({ label: "Power supply " + current.control, amount: ps });
  return parts;
}

// Accessories a product is sold with, each with its own price. They are entered here rather
// than as a parameter value because they are not one fact about the luminaire - they are a
// list of orderable things, and each one costs money. On save they become the product's
// accessories field, which is what the Configurator's picker offers, and one price entry per
// accessory, which is where that picker already looks for what each costs. So an authored
// product's accessories are picked and priced by exactly the code a parsed product's are.
// ---------------- NPD > Rules ----------------
//
// "When IP rating is IP66, hide IP68 Connector from Accessories." A rule is one sentence: up to
// five conditions on this product's choices, then what happens to another choice - some of its
// values hidden, or only some offered. It applies to this product, or to every product of its
// typology. Stored in config_rules and evaluated by app/config_rules.py, the engine the Configurator
// already runs; Accessories are one more thing a rule can act on (GET .../accessories?state=).
// Rules save on their own, not with the product's Save.
const NPD_RULE_ACTIONS = [
  ["Hide Only", "hide", "from"],
  ["Show Only", "offer only", "in"],
];

function npdRuleFields(r) {
  // the product's choices (a parameter with more than one option), named as its template names them
  const out = [];
  r.d.groups.forEach(function (g) {
    g.parameters.forEach(function (p) {
      // Accessories are offered as a target from the product's own accessory list (npdRuleTargets), never
      // from the printed row, which reads "NIL / ..." - and a configuration never chooses one.
      const vals = p.field_key === "accessories" ? [] : npdOptionsOf(r.d.values[p.field_key]);
      if (vals.length > 1 && !out.some(function (f) { return f.key === p.field_key; })) {
        let label = sentenceLabel(p.label);
        if (out.some(function (f) { return f.label === label; })) {
          const banner = String(g.group_name || "").replace(/\s*PARAMETERS?\s*$/i, "").trim().toLowerCase();
          if (banner) label += " (" + banner + ")";
        }
        out.push({ key: p.field_key, label: label, values: vals });
      }
    });
  });
  return out;
}

function sentenceLabel(label) {
  const s = String(label || "").trim();
  if (!s || s !== s.toUpperCase()) return s;
  return s.toLowerCase().replace(/^./, function (c) { return c.toUpperCase(); })
    .replace(/\b(ip|ik|cct|cri|ugr|led|dali|dmx|rgb|rgbw|tw|lm|w)\b/gi, function (w) { return w.toUpperCase(); });
}

function npdRuleTargets(r) {
  const out = npdRuleFields(r).slice();
  if (r.accessories.length) out.push({ key: "accessories", label: "Accessories", values: r.accessories });
  return out;
}

function npdRuleLabel(r, key) {
  const f = npdRuleTargets(r).find(function (x) { return x.key === key; });
  return f ? f.label : (key === "accessories" ? "Accessories" : sentenceLabel(key.replace(/_/g, " ")));
}

function npdRuleWords(values) {
  if (!values.length) return '<span class="muted">…</span>';
  return values.map(function (v) { return "<b>" + escapeHtml(v) + "</b>"; }).join(" or ");
}

// The brand a typology-wide rule is limited to rides along as a condition on "make" (RULE_BRAND_FIELD on
// the server); it is shown as the rule's reach, not as one of its conditions.
const NPD_RULE_BRAND = "make";
function npdRuleConditions(rule) {
  return (rule.triggers || []).filter(function (t) { return t.field !== NPD_RULE_BRAND; });
}
function npdRuleScope(d, rule) {
  if (rule.specsheet_id) return "This product";
  const brand = (rule.triggers || []).find(function (t) { return t.field === NPD_RULE_BRAND; });
  return brand ? "Every " + brand.values.join(" or ") + " " + d.typology : "Every " + d.typology + ", every brand";
}

function npdRuleSentence(r, rule) {
  const act = NPD_RULE_ACTIONS.find(function (a) { return a[0] === rule.action; });
  const when = npdRuleConditions(rule).map(function (t) {
    return (t.field ? "<b>" + escapeHtml(npdRuleLabel(r, t.field)) + "</b>" : '<span class="muted">…</span>') +
      " is " + npdRuleWords(t.values || []);
  }).join(" and ");
  const target = (rule.target_fields || []).map(function (k) { return escapeHtml(npdRuleLabel(r, k)); }).join(", ");
  const what = act
    ? act[1] + " " + npdRuleWords(rule.affected_options || []) + " " + act[2] + " <b>" + target + "</b>"
    : escapeHtml(rule.action) + " " + npdRuleWords(rule.affected_options || []) + " (" + target + ")";
  return "When " + when + ", " + what + ".";
}

async function npdLoadRules(d) {
  const box = app.querySelector("#npd-rules");
  if (!box || !d.id) return;
  const r = (d.rules = d.rules || { d: d, list: [], accessories: [], editing: null, open: false, loaded: false });
  r.d = d;
  if (!r.loaded) {
    box.innerHTML = '<h3>Rules</h3><p class="muted">Loading…</p>';
    try {
      const [list, acc] = await Promise.all([
        api("/api/config-rules?specsheet_id=" + d.id),
        api("/api/specsheets/" + d.id + "/accessories"),
      ]);
      if (npdView.editing !== d) return;          // another product was opened meanwhile
      r.list = list;
      r.accessories = (acc.accessory_types || []).filter(function (a) { return !/^nil$/i.test(String(a).trim()); });
      r.loaded = true;
    } catch (e) {
      if (npdView.editing !== d) return;
      box.innerHTML = '<h3>Rules</h3><div class="error-box">Could not load the rules: ' + escapeHtml(e.message) + "</div>";
      return;
    }
  }
  npdDrawRules(d);
}

function npdDrawRules(d) {
  const box = app.querySelector("#npd-rules");
  const r = d.rules;
  if (!box || !r || npdView.editing !== d) return;
  const mayEdit = can("npd.edit") || can("config.edit");
  const fields = npdRuleFields(r);
  // Rules of the typology that name another brand are that brand's: not shown, counted or edited here.
  const mine = r.list.filter(function (rule) {
    const b = (rule.triggers || []).find(function (t) { return t.field === NPD_RULE_BRAND; });
    return !b || !d.make || b.values.indexOf(d.make) >= 0;
  });
  const n = mine.length;
  const head = '<div class="npd-rules-head"><h3>Rules' + (n ? ' <span class="npd-rules-count">' + n + "</span>" : "") + "</h3>" +
    (mayEdit && !r.editing && d.typology && fields.length
      ? '<button type="button" class="btn small secondary" id="npd-rule-add">+ Add rule</button>' : "") + "</div>";
  const intro = '<p class="muted npd-rules-intro">When one choice rules out another. Used whenever this product is added ' +
    "to a BOQ; each rule saves as soon as you add it" + (d.typology ? "" : ". Give the product a typology first") + ".</p>";
  const list = n ? '<ul class="npd-rule-list">' + mine.map(function (rule) {
    const scope = npdRuleScope(d, rule);
    return '<li class="npd-rule"><span class="npd-rule-text">' + npdRuleSentence(r, rule) + "</span>" +
      '<span class="npd-rule-scope">' + escapeHtml(scope) + "</span>" +
      (mayEdit ? '<span class="npd-rule-acts"><button type="button" class="npd-linkbtn" data-rule-edit="' + rule.id + '">Edit</button>' +
        '<button type="button" class="npd-linkbtn npd-rule-del" data-rule-del="' + rule.id + '">Remove</button></span>' : "") + "</li>";
  }).join("") + "</ul>" : (r.editing ? "" : '<p class="muted npd-rules-empty">No rules yet: every choice is offered with every other.</p>');
  box.innerHTML = head + intro + list + (r.editing ? npdRuleEditorHtml(d) : "");
  npdWireRules(d);
}

function npdRuleChipsHtml(kind, i, values, picked) {
  values = values.concat(picked.filter(function (v) { return values.indexOf(v) < 0; }));
  return '<span class="rule-chips">' + values.map(function (v) {
    const on = picked.indexOf(v) >= 0;
    return '<button type="button" class="rule-chip' + (on ? " on" : "") + '" aria-pressed="' + on + '" data-rchip="' + kind +
      '" data-i="' + i + '" data-v="' + attr(v) + '">' + escapeHtml(v) + "</button>";
  }).join("") + "</span>";
}

function npdRuleEditorHtml(d) {
  const r = d.rules, e = r.editing;
  const fields = npdRuleFields(r), targets = npdRuleTargets(r);
  const fieldSelect = function (attrName, i, current, list) {
    return '<select ' + attrName + '="' + i + '">' + (current ? "" : '<option value="" selected>Choose…</option>') + list.map(function (f) {
      return '<option value="' + attr(f.key) + '"' + (f.key === current ? " selected" : "") + ">" + escapeHtml(f.label) + "</option>";
    }).join("") + "</select>";
  };
  const conds = e.triggers.map(function (t, i) {
    const f = fields.find(function (x) { return x.key === t.field; }) || { values: [] };
    return '<div class="rule-line"><span class="rule-word">' + (i ? "and" : "When") + "</span>" +
      fieldSelect("data-rfield", i, t.field, fields) + '<span class="rule-word">is</span>' +
      npdRuleChipsHtml("cond", i, f.values, t.values) +
      (i ? '<button type="button" class="npd-linkbtn" data-rcond-del="' + i + '" aria-label="Remove this condition">×</button>' : "") + "</div>";
  }).join("");
  const tf = targets.find(function (x) { return x.key === e.target; }) || { values: [] };
  const act = NPD_RULE_ACTIONS.find(function (a) { return a[0] === e.action; }) || NPD_RULE_ACTIONS[0];
  return '<div class="rule-editor">' + conds +
    (e.triggers.length < 5 ? '<button type="button" class="npd-linkbtn rule-more" id="rule-add-cond">+ and another condition</button>' : "") +
    '<div class="rule-line"><span class="rule-word">then</span><select id="rule-action">' + NPD_RULE_ACTIONS.map(function (a) {
      return '<option value="' + attr(a[0]) + '"' + (a[0] === e.action ? " selected" : "") + ">" + escapeHtml(a[1]) + "</option>";
    }).join("") + '</select><span class="rule-word">' + escapeHtml(act[2]) + "</span>" +
    fieldSelect("data-rtarget", 0, e.target, targets) + "</div>" +
    '<div class="rule-line rule-line-indent">' + npdRuleChipsHtml("target", 0, tf.values, e.options) + "</div>" +
    '<div class="rule-line"><span class="rule-word">for</span>' +
      '<label class="rule-radio"><input type="radio" name="rule-scope" value="typology"' + (e.scope === "typology" ? " checked" : "") +
      "> every " + escapeHtml((d.make ? d.make + " " : "") + d.typology) + "</label>" +
      '<label class="rule-radio"><input type="radio" name="rule-scope" value="product"' + (e.scope === "product" ? " checked" : "") +
      "> this product only</label></div>" +
    '<p class="rule-preview" id="rule-preview">' + npdRuleSentence(r, npdRuleFromDraft(e)) + "</p>" +
    '<div class="error-box" id="rule-msg" hidden></div>' +
    '<div class="rule-actions"><button type="button" class="btn small secondary" id="rule-cancel">Cancel</button>' +
    '<button type="button" class="btn small" id="rule-save">' + (e.id ? "Save rule" : "Add rule") + "</button></div></div>";
}

function npdRuleFromDraft(e) {
  return { triggers: e.triggers, action: e.action, target_fields: [e.target], affected_options: e.options,
           specsheet_id: e.scope === "product" ? 1 : null };
}

function npdWireRules(d) {
  const box = app.querySelector("#npd-rules");
  const r = d.rules;
  const redraw = function () { npdDrawRules(d); };
  box.querySelector("#npd-rule-add")?.addEventListener("click", function () {
    const fields = npdRuleFields(r), targets = npdRuleTargets(r);
    const target = targets.find(function (t) { return t.key === "accessories"; }) || targets[targets.length - 1];
    r.editing = { id: null, triggers: [{ field: "", values: [] }], action: "Hide Only",
                  target: target.key, options: [], scope: "typology" };
    redraw();
  });
  box.querySelectorAll("[data-rule-edit]").forEach(function (b) {
    b.addEventListener("click", function () {
      const rule = r.list.find(function (x) { return String(x.id) === b.dataset.ruleEdit; });
      if (!rule) return;
      const brandT = (rule.triggers || []).find(function (t) { return t.field === NPD_RULE_BRAND; });
      r.editing = { id: rule.id, brand: brandT ? brandT.values.slice() : null, wasTypology: !rule.specsheet_id,
                    triggers: JSON.parse(JSON.stringify(npdRuleConditions(rule))), action: rule.action,
                    target: (rule.target_fields || [])[0] || "", options: (rule.affected_options || []).slice(),
                    scope: rule.specsheet_id ? "product" : "typology" };
      redraw();
    });
  });
  box.querySelectorAll("[data-rule-del]").forEach(function (b) {
    b.addEventListener("click", async function () {
      const rule = r.list.find(function (x) { return String(x.id) === b.dataset.ruleDel; });
      if (!rule || !confirm("Remove this rule? It applies to: " + npdRuleScope(d, rule) + ".")) return;
      await withBusy(b, async function () {
        await api("/api/config-rules/" + rule.id, { method: "DELETE" });
        r.list = r.list.filter(function (x) { return x.id !== rule.id; });
        showToast("Rule removed");
        redraw();
      });
    });
  });
  const e = r.editing;
  if (!e) return;
  const preview = function () {
    const p = box.querySelector("#rule-preview");
    if (p) p.innerHTML = npdRuleSentence(r, npdRuleFromDraft(e));
  };
  box.querySelectorAll("[data-rfield]").forEach(function (sel) {
    sel.addEventListener("change", function () { e.triggers[+sel.dataset.rfield] = { field: sel.value, values: [] }; redraw(); });
  });
  box.querySelector("[data-rtarget]")?.addEventListener("change", function (ev) { e.target = ev.target.value; e.options = []; redraw(); });
  box.querySelector("#rule-action")?.addEventListener("change", function (ev) { e.action = ev.target.value; redraw(); });
  box.querySelectorAll("[data-rchip]").forEach(function (chip) {
    chip.addEventListener("click", function () {
      const list = chip.dataset.rchip === "cond" ? e.triggers[+chip.dataset.i].values : e.options;
      const at = list.indexOf(chip.dataset.v);
      if (at >= 0) list.splice(at, 1); else list.push(chip.dataset.v);
      chip.classList.toggle("on", at < 0);
      chip.setAttribute("aria-pressed", String(at < 0));
      preview();
    });
  });
  box.querySelectorAll("[data-rcond-del]").forEach(function (b) {
    b.addEventListener("click", function () { e.triggers.splice(+b.dataset.rcondDel, 1); redraw(); });
  });
  box.querySelector("#rule-add-cond")?.addEventListener("click", function () {
    const used = e.triggers.map(function (t) { return t.field; });
    const next = npdRuleFields(r).find(function (f) { return used.indexOf(f.key) < 0; }) || npdRuleFields(r)[0];
    e.triggers.push({ field: next.key, values: [] });
    redraw();
  });
  box.querySelectorAll('input[name="rule-scope"]').forEach(function (radio) {
    radio.addEventListener("change", function () { e.scope = radio.value; preview(); });
  });
  box.querySelector("#rule-cancel").addEventListener("click", function () { r.editing = null; redraw(); });
  box.querySelector("#rule-save").addEventListener("click", function (ev) {
    const msg = box.querySelector("#rule-msg");
    const problem = e.triggers.some(function (t) { return !t.field; }) ? "Choose what each condition depends on."
      : e.triggers.some(function (t) { return !t.values.length; }) ? "Pick at least one value for each condition."
      : !e.options.length ? "Pick what the rule " + (e.action === "Hide Only" ? "hides" : "offers") + "."
      : e.triggers.some(function (t) { return t.field === e.target; }) ? "A rule cannot act on the choice it depends on." : "";
    if (problem) { msg.hidden = false; msg.textContent = problem; return; }
    withBusy(ev.currentTarget, async function () {
      // a rule for the typology is this brand's only (see NPD_RULE_BRAND)
      // an existing typology rule keeps the brand it had (none = every brand); a new one is this brand's
      const brand = e.id && e.wasTypology ? e.brand : (d.make ? [d.make] : null);
      const triggers = e.scope === "product" || !brand ? e.triggers
        : e.triggers.concat([{ field: NPD_RULE_BRAND, values: brand }]);
      const body = { typology: d.typology, specsheet_id: e.scope === "product" ? d.id : null, triggers: triggers,
                     action: e.action, target_fields: [e.target], affected_options: e.options };
      try {
        const saved = await api("/api/config-rules" + (e.id ? "/" + e.id : ""), {
          method: e.id ? "PUT" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
        });
        r.list = e.id ? r.list.map(function (x) { return x.id === saved.id ? saved : x; }) : r.list.concat([saved]);
        r.editing = null;
        showToast(e.id ? "Rule saved" : "Rule added");
        redraw();
      } catch (err) { msg.hidden = false; msg.textContent = err.message; }
    });
  });
}

function npdAccessoriesHtml(d) {
  if (npdLibMode(d)) return npdLibAccessoriesHtml(d);
  const rows = d.accessories;
  return '<section class="npd-step"><h3><span class="npd-num">4</span> Accessories</h3>' +
    '<p class="npd-steplede">Anything orderable alongside this product — a louver, a bracket, ' +
    "a driver. Each is quoted as its own line when the product is added to a BOQ, so it needs " +
    "its own price rather than a share of the base.</p>" +
    (rows.length === 0
      ? '<p class="npd-await">No accessories yet.</p>'
      : '<div class="npd-acc-list">' +
        '<div class="npd-acc-head"><span>Accessory</span><span>Code</span><span>Price</span>' +
          '<span title="What the accessory is ordered on (e.g. its dimension) and its picture - asked when it is added to a BOQ">Parameters &amp; picture</span><span></span></div>' +
        rows.map(function (a, i) {
          return '<div class="npd-acc-row">' +
            // Likewise no example here: it would repeat down every accessory row, and the
            // column heading already says what the field is.
            '<input class="npd-acc-name" data-acc-name="' + i + '" value="' +
              escapeHtml(a.name) + '">' +
            '<span class="npd-acc-code" data-code-acccell="' + i + '"></span>' +
            '<span class="npd-money-input"><span class="npd-rupee">₹</span>' +
              '<input type="number" step="0.01" min="0" data-acc-price="' + i + '" value="' +
              (a.price === "" || a.price === null || a.price === undefined ? "" : a.price) +
              '" placeholder="0.00"></span>' +
            '<span class="npd-acc-setup" data-acc-setup-cell="' + i + '">' + npdAccSetupCellHtml(a.name, i) + "</span>" +
            '<button type="button" class="npd-acc-del" data-acc-del="' + i +
              '" title="Remove this accessory">Remove</button>' +
            "</div>";
        }).join("") + "</div>") +
    '<button type="button" class="btn small ghost" id="npd-acc-add">Add accessory</button>' +
    "</section>";
}

function npdWireAccessories(d) {
  if (npdLibMode(d)) return npdWireLibAccessories(d);
  const add = app.querySelector("#npd-acc-add");
  if (add) add.addEventListener("click", function () {
    d.accessories.push({ name: "", price: "" });
    npdRenderForm();
    const inputs = app.querySelectorAll("[data-acc-name]");
    if (inputs.length) inputs[inputs.length - 1].focus();
  });
  app.querySelectorAll("[data-acc-name]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      d.accessories[Number(inp.dataset.accName)].name = inp.value;
      // The ACCESSORIES row up in the specification prints this list, so it is kept in step
      // as the names are typed. Updated in place rather than by re-rendering the form, which
      // would take the focus out of the field being typed into.
      npdSyncAccessoryRow(d);
      npdRefreshAccButtons();
    });
  });
  // Each accessory's parameters & picture, opened from its own row - one listener on the list,
  // since the buttons are redrawn as names are typed and as definitions arrive.
  const accList = app.querySelector(".npd-acc-list");
  if (accList) accList.addEventListener("click", function (e) {
    const b = e.target.closest("[data-acc-setup-open]");
    if (b) npdOpenAccSetupModal((d.accessories[Number(b.dataset.accSetupOpen)] || {}).name);
  });
  npdLoadAccDefs();
  app.querySelectorAll("[data-acc-price]").forEach(function (inp) {
    inp.addEventListener("input", function () {
      d.accessories[Number(inp.dataset.accPrice)].price = inp.value;
    });
  });
  app.querySelectorAll("[data-acc-del]").forEach(function (b) {
    b.addEventListener("click", function () {
      d.accessories.splice(Number(b.dataset.accDel), 1);
      npdRenderForm();
    });
  });
}

// ---- Parameters & picture, from a product's own Accessories section ----
//
// The same definition as NPD -> Accessories (models.AccessoryDetail), reached from where someone
// working on a product looks for it. It belongs to the accessory, not to this product, so it
// applies to every product that takes one - the button's window says how many.

async function npdLoadAccDefs() {
  if (npdView.accDefs && Date.now() - npdView.accDefs.at < 30000) {
    npdRefreshAccButtons();
    return;
  }
  const byKey = {};
  try {
    ((await api("/api/accessories")).accessories || []).forEach(function (a) {
      if ((a.params || []).length || a.image) {
        byKey[a.key] = { params: a.params || [], image: a.image, image_url: a.image_url };
      }
    });
  } catch (err) { /* the buttons simply offer to set one up */ }
  npdView.accDefs = { at: Date.now(), byKey: byKey };
  npdRefreshAccButtons();
}

function npdAccSetupCellHtml(name, i) {
  name = String(name || "").trim();
  if (!name) return "";
  const mine = npdView.accDefs ? npdView.accDefs.byKey[accessoryFold(name)] : null;
  const params = (mine && mine.params) || [];
  const set = params.length > 0 || !!(mine && mine.image_url);
  const label = params.length
    ? params.map(function (p) {
        return p.name + ((p.options || []).length ? " · " + p.options.length : "");
      }).join(", ")
    : set ? "Picture only" : "Set up";
  return '<button type="button" class="npd-acc-setup-btn' + (set ? " is-set" : "") + '" ' +
    'data-acc-setup-open="' + i + '" title="' + attr(set
      ? "What " + name + " is ordered on, and its picture — open to change"
      : "Define what " + name + " is ordered on (e.g. its dimension) and its picture") + '">' +
    (mine && mine.image_url ? '<img src="' + attr(mine.image_url) + '" alt="">' : "") +
    "<span>" + escapeHtml(label) + "</span></button>";
}

function npdRefreshAccButtons() {
  app.querySelectorAll("[data-acc-setup-cell]").forEach(function (cell) {
    const input = app.querySelector('[data-acc-name="' + cell.dataset.accSetupCell + '"]');
    cell.innerHTML = npdAccSetupCellHtml(input ? input.value : "", cell.dataset.accSetupCell);
  });
}

async function npdOpenAccSetupModal(name) {
  name = String(name || "").trim();
  const key = accessoryFold(name);
  if (!key) return;
  const modal = openModal('<span class="close-x" title="Close">&times;</span>' +
    '<h3 class="acc-modal-title">Parameters &amp; picture <span>' + escapeHtml(name) + "</span></h3>" +
    '<p class="acc-modal-lede" id="acc-modal-lede">Reading what its specsheets print…</p>' +
    '<div id="acc-modal-body"></div>', "modal-lg acc-modal");
  const body = modal.querySelector("#acc-modal-body");
  const lede = modal.querySelector("#acc-modal-lede");
  function close() {
    if (npdAccDraftDirty(npdView.accDraft) &&
        !confirm("Close without saving the changes to its parameters?")) return;
    npdView.accDraft = null;
    closeModal();
    npdRefreshAccButtons();
  }
  function redraw() {
    if (!body.isConnected) return;
    body.innerHTML = npdAccSetupHtml({ key: key, name: name });
    npdWireAccSetup(body);
  }
  modal.querySelector(".close-x").addEventListener("click", close);
  npdView.accSetup = "";            // one panel at a time: the catalogue's is not open behind this
  npdView.accDraft = { key: key, loading: true, root: body, redraw: redraw, close: close };
  redraw();
  try {
    const data = await api("/api/accessories/" + encodeURIComponent(key) + "/details");
    const d = npdView.accDraft;
    if (!d || d.root !== body) return;
    Object.assign(d, { loading: false, data: data, params: npdAccDraftParams(data.params), busy: "", problem: "" });
    lede.innerHTML = "This belongs to the accessory, so it applies to every product that takes one — " +
      "<b>" + data.count + " product" + (data.count === 1 ? "" : "s") + "</b>. Add Product asks it when the " +
      "accessory is ticked.";
  } catch (err) {
    const d = npdView.accDraft;
    if (!d || d.root !== body) return;
    Object.assign(d, { loading: false, error: err.message });
    lede.textContent = "";
  }
  redraw();
}

// Keep the printed ACCESSORIES row showing what the Accessories section currently says.
function npdSyncAccessoryRow(d) {
  const cell = app.querySelector(".npd-row.is-managed .npd-managed");
  if (!cell) return;
  const named = d.accessories.map(function (a) { return a.name; }).filter(Boolean);
  cell.textContent = named.length ? named.join(" / ") : "None";
}

// A product authored here is a draft until somebody approves it. Until then it is visible in
// this tab and nowhere else - not the Library, not the Configurator, not a BOQ picker - so an
// unfinished definition cannot be quoted from by someone who never knew it was being written.
const NPD_STATUS_LABEL = {
  pending: "Awaiting approval",
  approved: "In the library",
  held: "On hold",
};

function npdStatusTag(status) {
  const s = NPD_STATUS_LABEL[status] ? status : "pending";
  return '<span class="npd-status npd-status-' + s + '">' + NPD_STATUS_LABEL[s] + "</span>";
}

function npdStatusActions(p) {
  const status = NPD_STATUS_LABEL[p.approval_status] ? p.approval_status : "pending";
  if (status === "approved") {
    return '<button class="btn small secondary" data-status="held" data-id="' + p.id +
      '" title="Take this product back out of the library">Put on hold</button>';
  }
  return '<button class="btn small primary" data-status="approved" data-id="' + p.id +
      '" title="Publish this product to the Specsheet Library">Approve</button>' +
    (status === "pending"
      ? '<button class="btn small secondary" data-status="held" data-id="' + p.id +
        '" title="Park this product without approving it">Hold</button>'
      : '<button class="btn small secondary" data-status="pending" data-id="' + p.id +
        '" title="Move this back to awaiting approval">Reopen</button>');
}

async function npdSetStatus(id, status, button) {
  const original = button.textContent;
  button.disabled = true;
  button.textContent = "…";
  try {
    await api("/api/npd/products/" + id + "/status", {
      method: "PUT", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ approval_status: status }),
    });
    state.specsheets = [];        // the library's contents just changed
    await renderNpd(currentRender());
  } catch (e) {
    button.disabled = false;
    button.textContent = original;
    alert(e.message);
  }
}

// Reopen a saved product in the same form it was written in. The draft is rebuilt from what
// the server holds - values, which parameters are priced, the adders, the accessories - so
// editing a product and creating one are the same screen and cannot disagree about anything.
async function npdOpenProduct(id, jumpTo) {
  let d, tmpl;
  try {
    d = await api("/api/npd/products/" + id);
    [tmpl] = await Promise.all([
      api("/api/npd/parameters?typology=" + encodeURIComponent(d.typology)),
      // The classification fields a typology has come from its code structure - read once per
      // brand, so the form draws whole the first time rather than filling in later.
      npdEnsureCodesData(d.make || ""),
    ]);
  } catch (e) {
    showToast("Could not open that product: " + e.message, "error");
    return;
  }
  if (!jumpTo) window.scrollTo(0, 0);       // the list's scroll position is not the form's
  npdView.pendingJump = jumpTo || null;
  npdView.addingClass = false;
  const draft = npdBlankDraft();
  draft.id = d.id;
  draft.approval_status = d.approval_status;
  draft.product_name = d.product_name || "";
  draft.typology = d.typology || "";
  draft.series = d.series || "";
  draft.family = d.family || "";
  draft.variant = d.variant || "";
  draft.model_no = d.model_no || "";
  draft.make = d.make || "InHouse";
  draft.sub_typology = d.sub_typology || "";
  draft.description_line = d.description_line || d.category || "";
  // Keyed by what the form calls its two upload boxes, not by what the picture happens to be
  // labelled - the server decides which picture is which, by the same rule that puts them on
  // the generated sheet (see _npd_picture_urls). A product read from a manufacturer's PDF
  // calls its line diagram "Additional Diagram 2", so matching the label here showed nothing.
  if (d.product_image_url) draft.existing["Product Image"] = d.product_image_url;
  if (d.line_diagram_url) draft.existing["Line Diagram"] = d.line_diagram_url;
  draft.moreDiagrams = d.more_diagrams || [];
  draft.removeDiagrams = [];
  draft.groups = tmpl.groups || [];
  draft.values = Object.assign({}, d.values || {});
  draft.affects = Object.assign({}, d.affects || {});
  draft.adders = JSON.parse(JSON.stringify(d.price_adders || {}));
  draft.base_price = d.base_price === null || d.base_price === undefined ? "" : String(d.base_price);
  draft.accessories = (d.accessories || []).map(function (a) {
    // A library accessory is kept as the record it is (app/accessory_parts.py); anything else as
    // the name and price it always was - for a InHouse product, a datasheet name not in the
    // library yet, which the form offers to choose there.
    if (a.part_id) return { part_id: a.part_id, name: a.name, part: a.part };
    return { name: a.name, price: a.price === null || a.price === undefined ? "" : String(a.price) };
  });
  // seed the option rows from the saved value and adder for each priced parameter, so the
  // editor opens showing the same options and amounts that were entered
  Object.keys(draft.affects).forEach(function (k) {
    if (!draft.affects[k]) return;
    const opts = npdOptionsOf(draft.values[k]);
    if (!opts.length) return;
    const byValue = draft.adders[k] || {};
    draft.optionRows[k] = opts.map(function (v) {
      return { value: v, adder: byValue[v] === undefined ? "" : String(byValue[v]) };
    });
  });
  npdView.editing = draft;
  npdRenderForm();
  // After the first paint: the form is usable while the codes arrive, and they only change
  // what the identity boxes show, not what they hold.
  npdLoadIdentity(draft).then(function () {
    if (npdView.editing === draft) npdRenderForm();
  });
}

// The line the specsheet prints in its first bar, shown as the sum of its parts rather than
// as a finished string - so it is obvious where each word comes from, and obvious that
// changing a parameter changes the sheet's title. The same parts are what a product code
// will be assembled from once each has a short code, which is why they are held separately
// instead of being typed as one sentence.
function npdTitleParts(d) {
  const multi = function (v) { return String(v || "").indexOf("/") >= 0; };
  const adj = d.values.adjustability || "";
  const trim = d.values.trim_details || "";
  return [
    { label: "Sub-typology", value: d.sub_typology || "", from: "identity" },
    { label: "Typology", value: d.typology || "", from: "identity" },
    { label: "Adjustability", value: multi(adj) ? "" : adj, from: "parameter" },
    { label: "Trim details", value: multi(trim) ? "" : trim, from: "parameter" },
  ];
}

function npdComposedTitle(d) {
  const parts = npdTitleParts(d);
  const head = [parts[0].value, "LED", parts[1].value].filter(Boolean).join(" ");
  const tail = parts.slice(2).map(function (p) {
    return p.value ? p.value.replace(/\w\S*/g, function (w) {
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    }) : "";
  }).filter(Boolean);
  return head ? [head].concat(tail).join(" – ") : "";
}

// What names a product rather than specifies it. Series and family have always been its own
// columns; anything further is a template row under IDENTITY, added per typology by whoever
// needs it, so the second product of a kind starts from the first one's vocabulary.
//
// Each carries a short code as well as a value, because naming is what a product code is made
// of: "Nyx" is NYX and "Midi" is M, and the person inventing the series is the only one who
// knows its abbreviation. Asking for it here rather than in Config Rules is the difference
// between a code that gets defined and one that never does.
const NPD_IDENTITY_GROUP = "IDENTITY";

function npdIsSpecGroup(g) {
  return g.group_name !== NPD_IDENTITY_GROUP;
}

function npdIdentityTemplates(d) {
  const group = (d.groups || []).find(function (g) { return g.group_name === NPD_IDENTITY_GROUP; });
  return group ? group.parameters : [];
}

function npdIdentityCode(d, key, value) {
  const want = String(value || "").trim().toLowerCase();
  if (!want) return "";
  const hit = ((d.identity && d.identity.codes) || []).find(function (c) {
    return c.field === key && String(c.option_value).toLowerCase() === want;
  });
  return hit ? hit.code : "";
}

// Value and code side by side, because they are one decision. The code box is only usable once
// the value exists - there is nothing to abbreviate before that - and says so rather than
// sitting there inert.
function npdIdentityField(d, key, label, value, placeholder, removable, tag) {
  const code = npdIdentityCode(d, key, value);
  const has = !!String(value || "").trim();
  return '<label class="npd-ident" data-ident="' + attr(key) + '">' +
    "<span>" + escapeHtml(label) +
      (tag ? '<span class="npd-ident-tag" title="Printed in the specsheet\u2019s name bar, after the ' +
        'series and size - unlike a classification field, which never prints">' + escapeHtml(tag) + "</span>" : "") +
      (removable ? '<button type="button" class="npd-ident-x" data-ident-del="' + removable +
        '" title="Remove this identity field from ' + attr(d.typology) + '">&times;</button>' : "") +
    "</span>" +
    '<span class="npd-ident-row">' +
      '<input class="npd-ident-value" data-ident-value="' + attr(key) + '" value="' + attr(value || "") +
        '" placeholder="' + attr(placeholder || "") + '">' +
      '<input class="npd-ident-code" data-ident-code="' + attr(key) + '" value="' + attr(code) +
        '" maxlength="8" placeholder="' + (has ? "code" : "\u2013") + '"' +
        (has ? "" : " disabled") + ' title="' +
        (has ? "The short code this value adds to the product code, e.g. Midi \u2192 M"
             : "Give it a value first - there is nothing to abbreviate yet") + '">' +
    "</span></label>";
}

function npdIdentityExtrasHtml(d) {
  const extras = npdIdentityTemplates(d).map(function (t) {
    return npdIdentityField(d, t.field_key, t.label, d.values[t.field_key] || "", "",
                            t.user_added ? t.id : 0, "prints");
  }).join("");
  // Fields added this way before classification fields existed print in the specsheet's name
  // bar, so they are kept as they were; new ones are added as classification fields, which do
  // not print, so adding one never changes a sheet.
  return extras;
}

// The name bar as the sheet prints it: the held line where there is one, otherwise the series,
// the size and any printed identity field, as npd.identity_bits() composes it.
function npdNameBarText(d) {
  const held = String(d.values[NPD_NAME_LINE] || "").trim();
  if (held) return held;
  const bits = [];
  const seen = {};
  const add = function (key, value) {
    const text = String(value || "").trim();
    if (!text || text.indexOf("/") >= 0) return;
    const up = text.toUpperCase();
    if (seen[up]) return;
    seen[up] = 1;
    bits.push(key === "series" ? up : text);
  };
  add("series", d.series);
  add("family", d.family);
  npdIdentityTemplates(d).forEach(function (t) { add(t.field_key, d.values[t.field_key]); });
  return bits.join(" - ") || (d.product_name || "").trim();
}

// What the sheet's name bar will actually read. It is assembled from the fields above and is not
// visible until the sheet is generated, so it is shown here, being assembled, rather than
// described. The product code reads along the bar at the foot of the page.
function npdIdentityPreviewHtml(d) {
  const bits = [];
  const seen = {};
  // `named` says whether the value is also printed in the name bar. Sub-typology and variant
  // are not: the title line above already says "Recessed LED Downlight - Trimless", and printing
  // them twice would change the sheet of every product authored so far.
  // Must match npd.identity_bits() on the server, which draws the real bar.
  function add(key, label, value, named) {
    const text = String(value || "").trim();
    if (!text) return;
    if (!named || text.indexOf("/") >= 0) return;   // a choice, not this product's identity
    const up = text.toUpperCase();
    if (seen[up]) return;
    seen[up] = 1;
    bits.push(key === "series" ? up : text);
  }
  add("series", "Series", d.series, true);
  add("family", "Family", d.family, true);
  add("sub_typology", "Sub-typology", d.sub_typology, false);
  add("variant", "Variant", d.variant, false);
  npdIdentityTemplates(d).forEach(function (t) {
    add(t.field_key, t.label, d.values[t.field_key], true);
  });
  // A name line held as written wins, exactly as npd.identity_bits() prints it - the series
  // was split into its parts (NYX, Square, Dual) and composing it again would print less.
  const held = String(d.values[NPD_NAME_LINE] || "").trim();
  const composed = bits.join(" - ") || (d.product_name || "").trim();
  const name = held || composed;
  return '<div class="npd-ident-preview">' +
    '<div class="npd-ident-preview-head">On the specsheet</div>' +
    '<div class="npd-ident-bar"><span class="npd-ident-bar-name">' +
      // As npd.identity_bits() prints it: the series in capitals, everything else as typed.
      (name ? escapeHtml(name) : '<i>unnamed</i>') + "</span>" +
      '<span class="npd-ident-bar-model">' + escapeHtml(d.model_no || "") + "</span></div>" +
    (held
      ? '<div class="npd-ident-held"><label>Name line, held as written ' +
          '<input id="npd-name-line" value="' + attr(held) + '"></label>' +
          (composed && composed !== held
            ? '<button type="button" class="npd-linkbtn" id="npd-name-compose">Compose it from the fields instead (' +
              escapeHtml(composed) + ")</button>"
            : "") + "</div>"
      : '<p class="npd-ident-note">The name bar, with the model number flush right. Identity ' +
        "fields you add follow the series and family, in the order they are listed. Sub-typology " +
        "and variant are already in the title line, so they code without being printed twice.</p>") +
    "</div>";
}

// Where a held name line lives on a product - npd.NAME_LINE_KEY on the server.
const NPD_NAME_LINE = "name_line";

async function npdLoadIdentity(d) {
  try {
    d.identity = await api("/api/npd/identity?typology=" + encodeURIComponent(d.typology || ""));
  } catch (err) {
    d.identity = { fields: [], codes: [] };
  }
}

// The held name line: edited as itself, or given up for the composed one. Bound again whenever
// the preview it sits in is redrawn.
function npdWireNameLine(d) {
  const held = app.querySelector("#npd-name-line");
  if (held) held.addEventListener("input", function () {
    d.values[NPD_NAME_LINE] = held.value;
    const bar = app.querySelector(".npd-ident-bar-name");
    if (bar) bar.textContent = held.value;
  });
  const compose = app.querySelector("#npd-name-compose");
  if (compose) compose.addEventListener("click", function () {
    delete d.values[NPD_NAME_LINE];
    const preview = app.querySelector(".npd-ident-preview");
    if (preview) { preview.outerHTML = npdIdentityPreviewHtml(d); npdWireNameLine(d); }
  });
}

// One identity row: its value, and the short code that value contributes to the product code.
//
// The value redraws the step as it is typed, because the name bar and the code shown below are
// assembled from it. The code is saved when the box is left rather than on every keystroke - it
// writes a row of the Product Codes table, and "M" should not be stored on the way to "MD".
function npdWireIdentity(d) {
  npdWireNameLine(d);
  app.querySelectorAll("[data-ident-value]").forEach(function (input) {
    const key = input.dataset.identValue;
    input.addEventListener("input", function () {
      if (key === "series") d.series = input.value;
      else if (key === "family") d.family = input.value;
      else if (key === "variant") d.variant = input.value;
      else if (key === "sub_typology") d.sub_typology = input.value;
      else d.values[key] = input.value;
      npdRefreshIdentity(d, input);
    });
  });
  app.querySelectorAll("[data-ident-code]").forEach(function (input) {
    const key = input.dataset.identCode;
    input.addEventListener("change", function () { npdSaveIdentityCode(d, key, input); });
  });
  const add = app.querySelector("#npd-ident-add");
  if (add) add.addEventListener("click", function () { npdAddIdentityField(d); });
  app.querySelectorAll("[data-ident-del]").forEach(function (b) {
    b.addEventListener("click", function (e) {
      e.preventDefault();
      npdRemoveIdentityField(d, Number(b.dataset.identDel));
    });
  });
}

// Redraw what the value feeds - the title line, the name bar and the code - without rebuilding
// the box being typed into.
function npdRefreshIdentity(d, typing) {
  npdRefreshTitle(d);
  const preview = app.querySelector(".npd-ident-preview");
  if (preview) { preview.outerHTML = npdIdentityPreviewHtml(d); npdWireNameLine(d); }
  const summary = app.querySelector(".npd-sheetname-bar");
  if (summary) summary.textContent = npdNameBarText(d) || "unnamed";
  // The code box beside this value only becomes usable once there is a value to abbreviate.
  const row = typing.closest(".npd-ident");
  const code = row && row.querySelector(".npd-ident-code");
  if (code) {
    const has = !!typing.value.trim();
    code.disabled = !has;
    code.placeholder = has ? "code" : "\u2013";
    if (has && !code.value) code.value = npdIdentityCode(d, typing.dataset.identValue, typing.value);
  }
}

async function npdSaveIdentityCode(d, key, input) {
  const value = (npdIdentityValue(d, key) || "").trim();
  const code = input.value.trim().toUpperCase();
  if (!value) { input.value = ""; return; }
  if (code === npdIdentityCode(d, key, value)) return;
  try {
    const saved = await api("/api/npd/identity-code", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field_key: key, value: value, code: code, typology: d.typology }),
    });
    const codes = (d.identity && d.identity.codes) || [];
    const at = codes.findIndex(function (c) {
      return c.field === key && String(c.option_value).toLowerCase() === value.toLowerCase();
    });
    if (!saved.code) { if (at >= 0) codes.splice(at, 1); }
    else if (at >= 0) codes[at] = saved;
    else codes.push(saved);
    d.identity = { fields: (d.identity && d.identity.fields) || [], codes: codes };
    input.value = saved.code;
    // Anything cached for the Configurator's own code panel has just gone stale.
    if (Array.isArray(state.fieldCodes)) {
      const i = state.fieldCodes.findIndex(function (c) {
        return c.field === key && String(c.option_value).toLowerCase() === value.toLowerCase();
      });
      if (!saved.code) { if (i >= 0) state.fieldCodes.splice(i, 1); }
      else if (i >= 0) state.fieldCodes[i] = saved;
      else state.fieldCodes.push(saved);
    }
    const preview = app.querySelector(".npd-ident-preview");
    if (preview) { preview.outerHTML = npdIdentityPreviewHtml(d); npdWireNameLine(d); }
  } catch (err) {
    input.value = npdIdentityCode(d, key, value);
    alert("Could not save that code: " + err.message);
  }
}

function npdIdentityValue(d, key) {
  if (key === "series") return d.series;
  if (key === "family") return d.family;
  if (key === "variant") return d.variant;
  if (key === "sub_typology") return d.sub_typology;
  return d.values[key] || "";
}

// An identity field belongs to the typology, not to this one product: the next product of the
// same kind should start with it already there. Same rule the parameter template follows.
async function npdAddIdentityField(d) {
  const label = (prompt("What does this identity field name?\n\nA part of the product's own " +
    "name that will carry its own short code \u2014 Optic, Mounting, Lens. It is added to " +
    d.typology + ", so every product of that typology gets it.") || "").trim();
  if (!label) return;
  try {
    const row = await api("/api/npd/parameters", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ typology: d.typology, group_name: NPD_IDENTITY_GROUP, label: label }),
    });
    const group = (d.groups || []).find(function (g) { return g.group_name === NPD_IDENTITY_GROUP; });
    if (group) group.parameters.push(row);
    else d.groups.unshift({ group_name: NPD_IDENTITY_GROUP, parameters: [row] });
    await npdLoadIdentity(d);
    npdRenderForm();
  } catch (err) {
    alert("Could not add it: " + err.message);
  }
}

async function npdRemoveIdentityField(d, id) {
  const group = (d.groups || []).find(function (g) { return g.group_name === NPD_IDENTITY_GROUP; });
  const row = group && group.parameters.find(function (p) { return p.id === id; });
  if (!row) return;
  if (!confirm("Remove \u201c" + row.label + "\u201d from " + d.typology + "?\n\n" +
      "It stops being asked for on every product of this typology. Values already saved on " +
      "other products stay as they are.")) return;
  try {
    await api("/api/npd/parameters/" + id, { method: "DELETE" });
    group.parameters = group.parameters.filter(function (p) { return p.id !== id; });
    delete d.values[row.field_key];
    npdRenderForm();
  } catch (err) {
    alert("Could not remove it: " + err.message);
  }
}

function npdTitleBlockHtml(d) {
  const parts = npdTitleParts(d);
  const suggestion = npdComposedTitle(d);
  const current = d.description_line || "";
  // The composed line is offered, not imposed. A real InHouse description carries wording no
  // composition produces - "Flexible LED Strip (Standard)", a track light's rail voltage - so
  // deriving it and writing the result back rewrote 127 of 135 products' printed titles the
  // first time anyone edited them. What is typed here is what the sheet prints.
  const differs = suggestion && npdSquash(suggestion) !== npdSquash(current);
  return '<div class="npd-title-block">' +
    '<div class="npd-title-head">Specsheet title line</div>' +
    '<input class="npd-title-input" id="npd-description-line" value="' + attr(current) +
      '" placeholder="Recessed LED Downlight \u2013 Adjustable \u2013 With Trim">' +
    '<div class="npd-title-parts">' + parts.map(function (p) {
      return '<span class="npd-title-part' + (p.value ? "" : " missing") + '">' +
        '<span class="npd-tp-label">' + escapeHtml(p.label) + "</span>" +
        '<span class="npd-tp-value">' + escapeHtml(p.value || "not set") + "</span>" +
        '<span class="npd-tp-from">' + p.from + "</span></span>";
    }).join("") + "</div>" +
    (differs
      ? '<p class="npd-title-note">From the parts above this would read ' +
        '<b>' + escapeHtml(suggestion) + "</b>. " +
        '<button type="button" class="npd-linkbtn" id="npd-use-composed">Use that</button></p>'
      : '<p class="npd-title-note">This is what the sheet prints, and it matches the parts ' +
        "above \u2014 each held as its own field, so it can carry a short code later and be " +
        "read by systems beyond quoting.</p>") +
  "</div>";
}

function npdSquash(v) {
  return String(v || "").replace(/\s+/g, "").toLowerCase();
}

// ---------------- Product codes: the panel on the Nomenclature tab ----------------
// (npd-* names are from when it lived in NPD; the product form below still shares its data.)
//
// A product code is the product's address: one configured product, one code. It is built from
// segments - the product type, its series, its trim, then the wattage and CCT it is quoted in -
// each written as a short abbreviation, in an order the studio decides per typology. All three
// of those (the segments, their order, the abbreviations) live in the database and are edited
// here, so a new axis or a renamed abbreviation never waits on a developer.
//
// The code itself is only ever assembled on the server (app/product_codes.py). This page,
// the product form and the Configurator all ask it, because two copies of the rule would
// sooner or later disagree about a code on a purchase order.

// Why a value that reads "IP20 / IP67" gets no code: the product lists two options without
// offering them as a choice, so it does not say which one it is - and the code will not guess.
const NPD_SEVERAL_HELP = "It lists several options, but the product does not offer them as a " +
  "choice, so no code can say which one it is. Turn on its “Affects price” switch if the " +
  "buyer picks one, or give it the one value the product has.";

const npdCodes = {
  data: null,          // GET /api/npd/codes for `make`
  make: "",
  loading: false,
  error: "",
  typology: null,      // null = not chosen yet; "" = the brand's default structure
  wantTypology: null,  // asked for from NPD before the brand's codes were read
  draft: null,         // the structure on screen: { prefix, separator, segments }
  dirty: false,
  selected: "",        // the attribute whose abbreviations are listed
  allValues: false,    // list values from every typology, not only this one
  onlyMissing: false,
  exampleId: null,
  example: null,       // preview of the example product under the draft structure
  picker: false,       // "add a segment" open
  dragKey: "",
};

function npdCodeCanEdit() { return can("npd.edit"); }

// The tile's figure: how many of the brand's products have a complete identity code, read off
// the product list so it shows before the panel is ever opened.
function npdCodesTileFigure() {
  const coded = npdBrandProducts().filter(function (p) { return p.identity_code; });
  if (!coded.length) return "—";
  return coded.filter(function (p) { return p.identity_code.complete; }).length +
    '<small class="npd-component-of">/' + coded.length + "</small>";
}

async function npdCodesLoad(force) {
  const make = npdCodesBrand();
  if (!make) { npdCodes.data = null; npdCodes.make = ""; npdCodesRender(); return; }
  if (!force && npdCodes.data && npdCodes.make === make) {
    npdCodesRender();
    // Data read earlier by a product form comes without an example drawn for it.
    if (!npdCodes.example) npdCodesExampleSoon(0);
    return;
  }
  npdCodes.loading = true;
  npdCodes.error = "";
  npdCodesRender();
  try {
    const data = await api("/api/npd/codes?make=" + encodeURIComponent(make));
    const changedBrand = npdCodes.make !== make;
    npdCodes.data = data;
    npdCodes.make = make;
    // A typology already chosen for this brand is kept; one asked for from NPD (see
    // npdOpenNomenclature) is taken if the brand has it.
    const want = npdCodes.wantTypology;
    npdCodes.wantTypology = null;
    if (changedBrand || npdCodes.typology === null || want) {
      npdCodes.typology = want && npdCodesTypologies().indexOf(want) >= 0 ? want : (npdCodesTypologies()[0] || "");
      npdCodes.draft = null;
    }
    if (!npdCodes.dirty) npdCodesStartDraft();
  } catch (e) {
    npdCodes.error = e.message;
  } finally {
    npdCodes.loading = false;
  }
  npdCodesRender();
  npdCodesExampleSoon(0);
}

// Every typology worth a tab: those with products of this brand, and those with a structure of
// their own - in use or retired, so a retired one always has a tab to be restored from. A
// typology with none of these uses the brand default, which has a tab of its own.
function npdCodesTypologies() {
  const data = npdCodes.data || {};
  const counts = {};
  (data.typologies || []).forEach(function (t) { if (t.typology) counts[t.typology] = t.count; });
  (data.schemes || []).concat(data.retired || []).forEach(function (s) {
    if (s.typology && !(s.typology in counts)) counts[s.typology] = 0;
  });
  return Object.keys(counts).sort(function (a, b) { return (counts[b] - counts[a]) || a.localeCompare(b); });
}

function npdCodesCount(typology) {
  const hit = ((npdCodes.data || {}).typologies || []).find(function (t) { return t.typology === typology; });
  return hit ? hit.count : 0;
}

function npdCodesOwnScheme(typology) {
  return ((npdCodes.data || {}).schemes || []).find(function (s) { return s.typology === typology; }) || null;
}

// The structure a typology had before it was put on the brand default - kept so it can be
// brought back, and replaced only if someone saves a new one for that typology.
function npdCodesRetiredScheme(typology) {
  return ((npdCodes.data || {}).retired || []).find(function (s) { return s.typology === typology; }) || null;
}

function npdCodesEffective(typology) {
  return npdCodesOwnScheme(typology) || npdCodesOwnScheme("");
}

function npdCodesStartDraft() {
  const base = npdCodesEffective(npdCodes.typology);
  npdCodes.draft = base
    ? { prefix: base.prefix || "", separator: base.separator == null ? "-" : base.separator,
        segments: base.segments.map(function (s) { return Object.assign({}, s); }) }
    : { prefix: "", separator: "-", segments: [] };
  npdCodes.dirty = false;
  npdCodes.picker = false;
  if (!npdCodes.selected || !npdCodes.draft.segments.some(function (s) { return s.key === npdCodes.selected; })) {
    npdCodes.selected = npdCodes.draft.segments.length ? npdCodes.draft.segments[0].key : "";
  }
  const ids = npdCodesProducts().map(function (p) { return p.id; });
  if (ids.indexOf(npdCodes.exampleId) < 0) npdCodes.exampleId = ids.length ? ids[0] : null;
}

function npdCodesAttr(key) {
  return ((npdCodes.data || {}).attributes || []).find(function (a) { return a.key === key; }) ||
    { key: key, label: key, part: "identity", rule: "list", multi: false, note: "" };
}

function npdCodesRule(key) {
  return ((npdCodes.data || {}).rules || []).find(function (r) { return r.key === key; }) || { label: key, help: "", example: "" };
}

// The products the tab is about - the typology's own, or the whole brand on the default tab.
function npdCodesProducts() {
  const report = (npdCodes.data || {}).report || [];
  return npdCodes.typology ? report.filter(function (r) { return r.typology === npdCodes.typology; }) : report;
}

// Values of one attribute with the code each gets, limited to this typology unless asked.
function npdCodesValues(key) {
  const all = ((npdCodes.data || {}).values || {})[key] || [];
  const scoped = !npdCodes.allValues && npdCodes.typology;
  return all.filter(function (v) {
    if (npdCodes.onlyMissing && v.code) return false;
    return !scoped || (v.typologies || {})[npdCodes.typology] || !v.count;
  });
}

// ---- the panel

function npdCodesHtml() {
  return '<div class="npd-ptables npd-codes" id="npd-codes">' + npdCodesInnerHtml() + "</div>";
}

function npdCodesInnerHtml() {
  const brand = npdCodesBrand();
  const head = '<div class="npd-ptables-head"><h4>Product codes</h4>' +
    (brand ? '<span class="npd-codes-brand">' + escapeHtml(brand) + "</span>" : "") + "</div>" +
    '<p class="npd-ptables-lede">A product code is the product’s address: one configured ' +
    "product, one code. The <b>identity</b> segments name which product it is and must be unique " +
    "across the brand; the <b>configuration</b> segments are chosen when it is quoted. Change the " +
    "structure or an abbreviation here and every code from then on follows — lines already " +
    "in a BOQ keep the code they were quoted with.</p>";
  if (!brand) return head + '<p class="muted">Choose one brand above: each brand has codes of its own.</p>';
  if (npdCodes.error) return head + '<div class="error-box">Could not load the product codes: ' + escapeHtml(npdCodes.error) + "</div>";
  if (!npdCodes.data || npdCodes.make !== brand) {
    return head + '<div class="npd-codes-stats">' +
      '<div class="npd-codes-stat npd-skel-tile"></div><div class="npd-codes-stat npd-skel-tile"></div>' +
      '<div class="npd-codes-stat npd-skel-tile"></div></div>' +
      '<div class="npd-codes-grid"><div class="npd-codes-card npd-skel-card"></div>' +
      '<div class="npd-codes-card npd-skel-card"></div></div>';
  }
  if (npdCodes.typology === null) npdCodes.typology = npdCodesTypologies()[0] || "";
  if (!npdCodes.draft) npdCodesStartDraft();
  return head + '<div id="npd-codes-health">' + npdCodesHealthHtml() + "</div>" +
    npdCodesTabsHtml() +
    '<div class="npd-codes-grid">' +
      '<section class="npd-codes-card" id="npd-codes-structure">' + npdCodesStructureHtml() + "</section>" +
      '<section class="npd-codes-card" id="npd-codes-abbrev">' + npdCodesAbbrevHtml() + "</section>" +
    "</div>" +
    '<section class="npd-codes-card" id="npd-codes-coverage">' + npdCodesCoverageHtml() + "</section>";
}

function npdCodesRender() {
  const box = app.querySelector("#npd-codes");
  if (!box) return;
  box.innerHTML = npdCodesInnerHtml();
  npdCodesBind();
}

function npdCodesHealthHtml() {
  const products = npdCodesProducts();
  const complete = products.filter(function (p) { return p.complete; }).length;
  const skus = products.reduce(function (n, p) { return n + (p.skus || 0); }, 0);
  const ids = new Set(products.map(function (p) { return p.id; }));
  const shared = ((npdCodes.data || {}).duplicates || []).filter(function (d) {
    return d.ids.some(function (id) { return ids.has(id); });
  });
  const sharedCodes = shared.reduce(function (n, d) { return n + (d.count || 1); }, 0);
  const sharedProducts = new Set([].concat.apply([], shared.map(function (d) { return d.ids; }))).size;
  let missing = 0;
  (npdCodes.draft ? npdCodes.draft.segments : []).forEach(function (s) {
    if (!s.include) return;
    const all = ((npdCodes.data || {}).values || {})[s.key] || [];
    all.forEach(function (v) {
      const inScope = !npdCodes.typology || (v.typologies || {})[npdCodes.typology];
      if (inScope && v.count && !v.code) missing += 1;
    });
  });
  const scope = npdCodes.typology ? escapeHtml(npdCodes.typology) : "all " + escapeHtml(npdCodesBrand());
  const tile = function (cls, fig, label, sub, target) {
    return '<button type="button" class="npd-codes-stat ' + cls + '" data-codes-go="' + target + '">' +
      '<span class="npd-codes-stat-fig">' + fig +
      '</span><span class="npd-codes-stat-label">' + label + '</span><span class="npd-codes-stat-sub">' +
      sub + "</span></button>";
  };
  // Counted in SKUs - every combination of the options a product offers - because that is
  // what a code has to tell apart: one configured product, one code.
  return '<div class="npd-codes-stats">' +
    tile(complete === products.length ? "ok" : "warn", complete + "<small>/" + products.length + "</small>",
         "products fully coded", scope + " \u2014 " + skus.toLocaleString("en-IN") + " configurations" +
           (complete === products.length ? ", each with a code"
             : "; " + (products.length - complete) + " need a value or a code, listed below"), "coverage") +
    tile(shared.length ? "warn" : "ok", sharedCodes.toLocaleString("en-IN"),
         "codes shared by two configurations", shared.length
           ? "across " + sharedProducts + " products \u2014 one code must mean one SKU"
           : "no two configurations share a code", "shared") +
    tile(missing ? "warn" : "ok", String(missing), "values with no abbreviation",
         missing ? "used by products here \u2014 fill them in one list" : "every value in use is coded", "missing") +
    "</div>";
}

function npdCodesTabsHtml() {
  const tab = function (value, label, count, own) {
    return '<button type="button" class="npd-codes-tab' + (npdCodes.typology === value ? " active" : "") +
      '" data-codes-typology="' + attr(value) + '">' + escapeHtml(label) +
      (count !== null ? ' <span class="muted">' + count + "</span>" : "") +
      (own ? "" : '<span class="npd-codes-tab-note">default</span>') + "</button>";
  };
  return '<div class="npd-codes-tabs" role="tablist">' +
    tab("", "Brand default", null, true) +
    npdCodesTypologies().map(function (t) {
      return tab(t, t, npdCodesCount(t), !!npdCodesOwnScheme(t));
    }).join("") + "</div>";
}

function npdCodeSpans(result, only, jump) {
  if (!result) return "";
  const sep = escapeHtml(result.separator == null ? "-" : result.separator);
  const bits = [];
  // Accessories go after the product, each with a "+" - as product_codes.compose() writes them.
  const added = [];
  if (result.prefix) bits.push('<span class="npd-cs npd-cs-prefix" title="Prefix">' + escapeHtml(result.prefix) + "</span>");
  (result.segments || []).forEach(function (s) {
    if (s.status === "off" || s.status === "skipped") return;
    if (only && s.part !== only) return;
    const open = s.status === "choose";
    const accessories = s.status === "ok" && s.codes && s.codes.length;
    const text = s.status === "ok" ? (accessories ? s.codes.join("+") : s.code) : open ? "…" : "?";
    const why = s.status === "choose" ? "chosen when quoted" : s.status === "no_value"
      ? "no value recorded" : s.status === "no_code" ? "“" + s.value + "” has no abbreviation" : s.value;
    (accessories ? added : bits).push('<span class="npd-cs npd-cs-' + (s.part === "config" ? "cfg" : "id") +
      (s.status === "ok" ? "" : open ? " npd-cs-open" : " npd-cs-gap") + '" title="' + attr(s.label + ": " + why) + '"' +
      (jump ? ' data-jump="' + attr(s.key) + '" role="link" tabindex="0"' : "") + ">" +
      escapeHtml(text) + "</span>");
  });
  return bits.join('<span class="npd-cs-sep">' + sep + "</span>") +
    added.map(function (a) { return '<span class="npd-cs-sep">+</span>' + a; }).join("");
}

function npdCodesStructureHtml() {
  const d = npdCodes.draft;
  const typ = npdCodes.typology;
  const own = npdCodesOwnScheme(typ);
  const editable = npdCodeCanEdit();
  const ex = npdCodes.example;
  const exampleSegs = {};
  ((ex && ex.result && ex.result.segments) || []).forEach(function (s) { exampleSegs[s.key] = s; });
  const products = npdCodesProducts();
  const retired = own ? null : npdCodesRetiredScheme(typ);
  const source = (typ
    ? (own ? "Its own structure." : "Follows the brand default — change anything and " +
             escapeHtml(typ) + " gets a structure of its own.")
    : "Used by every typology that has no structure of its own.") +
    (retired
      ? " Its own structure was put aside " + escapeHtml(formatIST(retired.retired_at)) +
        (retired.updated_by ? " by " + escapeHtml(retired.updated_by) : "") + ": " +
        escapeHtml(retired.segments.filter(function (s) { return s.include; })
          .map(function (s) { return npdCodesAttr(s.key).label; }).join(" · ") || "no segments") +
        (editable ? ". Restore it below; saving a new structure here replaces it." : ".")
      : "");

  const rows = d.segments.map(function (s, i) {
    const a = npdCodesAttr(s.key);
    const sample = exampleSegs[s.key];
    const code = sample && sample.status === "ok" ? sample.code
      : sample && sample.status_if_included === "ok" ? sample.code : "";
    return '<li class="npd-seg' + (s.key === npdCodes.selected ? " selected" : "") +
      (s.include ? "" : " off") + '" data-seg="' + attr(s.key) + '"' +
      (editable ? ' draggable="true"' : "") + ">" +
      (editable ? '<span class="npd-seg-grip" title="Drag to reorder" aria-hidden="true">⋮⋮</span>' : "") +
      '<span class="npd-seg-pos">' + (i + 1) + "</span>" +
      '<button type="button" class="npd-seg-name" data-seg-select="' + attr(s.key) + '">' +
        "<b>" + escapeHtml(a.label) + "</b>" +
        '<small>' + escapeHtml(a.rule === "list" ? "By abbreviation" : npdCodesRule(a.rule).label) +
          (a.multi ? " · several at once" : "") + "</small>" +
      "</button>" +
      '<span class="npd-seg-part npd-seg-part-' + (a.part === "config" ? "cfg" : "id") + '">' +
        (a.part === "config" ? "Configuration" : "Identity") + "</span>" +
      '<span class="npd-seg-sample" title="In the example below">' + escapeHtml(code || "–") + "</span>" +
      '<label class="npd-seg-toggle" title="Whether this segment is written into the code at all">' +
        '<input type="checkbox" data-seg-include="' + attr(s.key) + '"' + (s.include ? " checked" : "") +
        (editable ? "" : " disabled") + "> In code</label>" +
      '<label class="npd-seg-toggle" title="Leave it out for a product that records no value, instead of calling that product’s code incomplete">' +
        '<input type="checkbox" data-seg-optional="' + attr(s.key) + '"' + (s.optional ? " checked" : "") +
        (editable && s.include ? "" : " disabled") + "> Skip if blank</label>" +
      (editable
        ? '<span class="npd-seg-actions">' +
          '<button type="button" class="npd-seg-btn" data-seg-move="' + attr(s.key) + '" data-dir="-1" title="Move earlier"' + (i === 0 ? " disabled" : "") + ">↑</button>" +
          '<button type="button" class="npd-seg-btn" data-seg-move="' + attr(s.key) + '" data-dir="1" title="Move later"' + (i === d.segments.length - 1 ? " disabled" : "") + ">↓</button>" +
          '<button type="button" class="npd-seg-btn npd-seg-remove" data-seg-remove="' + attr(s.key) + '" title="Take out of this structure">×</button>' +
          "</span>"
        : "") +
      "</li>";
  }).join("");

  return '<div class="npd-codes-card-head"><h5>Structure — ' +
      escapeHtml(typ || "brand default") + "</h5>" +
      '<span class="npd-codes-source">' + source + "</span></div>" +

    '<div class="npd-code-example">' +
      '<div class="npd-code-example-head"><span>Example</span>' +
      (products.length
        ? '<select id="npd-codes-example">' + products.map(function (p) {
            return '<option value="' + p.id + '"' + (p.id === npdCodes.exampleId ? " selected" : "") + ">" +
              escapeHtml(p.product_name || "Untitled") + (typ ? "" : " (" + escapeHtml(p.typology || "no typology") + ")") +
              "</option>";
          }).join("") + "</select>"
        : '<span class="muted">no product of this typology yet</span>') +
      "</div>" +
      '<div class="npd-code-big" id="npd-codes-example-code">' +
        (ex && ex.result ? npdCodeSpans(Object.assign({ separator: d.separator, prefix: d.prefix }, ex.result))
                         : '<span class="muted">—</span>') + "</div>" +
      '<div class="npd-code-legend"><span class="npd-cs npd-cs-id">Identity</span>' +
        '<span class="npd-cs npd-cs-cfg">Configuration</span>' +
        '<span class="npd-cs npd-cs-gap">?</span><span class="muted">missing for this product — hover for why. ' +
        "Open choices take their first option here.</span></div>" +
    "</div>" +

    (d.segments.length
      ? '<ol class="npd-seglist" id="npd-seglist">' + rows + "</ol>"
      : '<p class="npd-await">No segments yet. Add the first one below.</p>') +

    (editable ? npdCodesPickerHtml() : "") +

    '<div class="npd-codes-foot">' +
      '<label>Prefix <input id="npd-codes-prefix" value="' + attr(d.prefix) + '" maxlength="8" placeholder="none"' +
        (editable ? "" : " disabled") + "></label>" +
      '<label>Separator <select id="npd-codes-sep"' + (editable ? "" : " disabled") + ">" +
        ((npdCodes.data || {}).separators || ["-"]).map(function (s) {
          const name = { "-": "Hyphen  -", ".": "Full stop  .", "/": "Slash  /", "_": "Underscore  _", " ": "Space", "": "None" }[s] || s;
          return '<option value="' + attr(s) + '"' + (s === d.separator ? " selected" : "") + ">" + escapeHtml(name) + "</option>";
        }).join("") + "</select></label>" +
      (editable
        ? '<span class="npd-codes-foot-actions">' +
          (npdCodes.dirty ? '<span class="npd-codes-dirty">Unsaved changes</span>' +
            '<button type="button" class="btn small secondary" id="npd-codes-discard">Discard</button>' : "") +
          (typ && own && !npdCodes.dirty ? '<button type="button" class="btn small secondary" id="npd-codes-reset" title="Put this structure aside so ' + attr(typ) + ' follows the brand default. It can be restored.">Use brand default</button>' : "") +
          (retired && !npdCodes.dirty ? '<button type="button" class="btn small secondary" id="npd-codes-restore" title="Bring back the structure ' + attr(typ || "the brand default") + ' had, exactly as it was">Restore its own structure</button>' : "") +
          '<button type="button" class="btn small primary" id="npd-codes-save"' + (npdCodes.dirty ? "" : " disabled") + ">" +
            (typ && !own ? "Save as " + escapeHtml(typ) + "’s own" : "Save structure") + "</button></span>"
        : '<span class="muted">Only someone who may edit NPD products can change this.</span>') +
    "</div>";
}

function npdCodesPickerHtml() {
  if (!npdCodes.picker) {
    return '<button type="button" class="btn small ghost npd-seg-add" id="npd-codes-add">+ Add a segment</button>';
  }
  const inUse = new Set(npdCodes.draft.segments.map(function (s) { return s.key; }));
  const attrs = ((npdCodes.data || {}).attributes || []).filter(function (a) { return !inUse.has(a.key); });
  const known = new Set(((npdCodes.data || {}).attributes || []).map(function (a) { return a.key; }));
  const params = (((npdCodes.data || {}).parameters || {})[npdCodes.typology] || []).filter(function (p) {
    return !known.has(p.key) && !inUse.has(p.key);
  });
  const rules = (npdCodes.data || {}).rules || [];
  return '<div class="npd-seg-picker">' +
    '<div class="npd-seg-picker-head"><b>Add a segment</b>' +
      '<button type="button" class="btn tiny ghost" id="npd-codes-picker-close">Close</button></div>' +
    (attrs.length
      ? '<div class="npd-seg-picker-sub">Attributes the code already knows</div><div class="npd-seg-picker-list">' +
        attrs.map(function (a) {
          return '<button type="button" class="npd-pick" data-pick-attr="' + attr(a.key) + '">' +
            escapeHtml(a.label) + ' <span class="muted">' + (a.part === "config" ? "configuration" : "identity") + "</span></button>";
        }).join("") + "</div>"
      : "") +
    (params.length
      ? '<div class="npd-seg-picker-sub">From ' + escapeHtml(npdCodes.typology) + "’s specification</div>" +
        '<div class="npd-seg-picker-list">' + params.map(function (p) {
          return '<button type="button" class="npd-pick" data-pick-param="' + attr(p.key) + '" data-label="' +
            attr(p.label) + '" data-configurable="' + (p.configurable ? "1" : "") + '">' +
            escapeHtml(p.label.charAt(0) + p.label.slice(1).toLowerCase()) + ' <span class="muted">' +
            escapeHtml(p.group.toLowerCase()) + "</span></button>";
        }).join("") + "</div>"
      : "") +
    '<div class="npd-seg-picker-sub">Or a new attribute — something the catalogue has never recorded</div>' +
    '<div class="npd-seg-new">' +
      '<input id="npd-new-attr-label" placeholder="e.g. Beam shape" maxlength="60">' +
      '<select id="npd-new-attr-part"><option value="identity">Identity — names the product</option>' +
        '<option value="config">Configuration — chosen when quoted</option></select>' +
      '<select id="npd-new-attr-rule">' + rules.map(function (r) {
        return '<option value="' + attr(r.key) + '">' + escapeHtml(r.label) + "</option>";
      }).join("") + "</select>" +
      '<button type="button" class="btn small" id="npd-new-attr-go">Create and add</button>' +
    "</div>" +
    '<p class="npd-seg-picker-note">A new identity attribute is filled in per product, in the ' +
      "Classification box of its Identity step; its abbreviations are set on the right. A number " +
      "rule needs a unit under <b>Written as</b>, so its codes say what they measure.</p>" +
  "</div>";
}

function npdCodesAbbrevHtml() {
  if (npdCodes.showMissing) return npdCodesMissingHtml();
  const key = npdCodes.selected;
  if (!key) return '<p class="npd-await">Choose a segment to see its values and abbreviations.</p>';
  const a = npdCodesAttr(key);
  const rule = npdCodesRule(a.rule);
  const editable = npdCodeCanEdit();
  const values = npdCodesValues(key);
  const rules = (npdCodes.data || {}).rules || [];
  const scopeLabel = npdCodes.typology && !npdCodes.allValues ? escapeHtml(npdCodes.typology) : "every typology";
  return '<div class="npd-codes-card-head"><h5>' + escapeHtml(a.label) + ' <small class="muted">' +
      escapeHtml(key) + "</small></h5>" +
      (editable ? '<button type="button" class="btn tiny ghost" id="npd-attr-rename">Rename</button>' +
        '<button type="button" class="btn tiny ghost" id="npd-attr-delete" title="Remove this attribute from the code system">Delete</button>' : "") +
    "</div>" +
    (a.note ? '<p class="npd-abbr-note">' + escapeHtml(a.note) + "</p>" : "") +
    '<div class="npd-abbr-meta">' +
      '<label>Part <select id="npd-attr-part"' + (editable ? "" : " disabled") + ">" +
        '<option value="identity"' + (a.part !== "config" ? " selected" : "") + ">Identity</option>" +
        '<option value="config"' + (a.part === "config" ? " selected" : "") + ">Configuration</option>" +
      "</select></label>" +
      '<label>Without an abbreviation <select id="npd-attr-rule"' + (editable ? "" : " disabled") + ">" +
        rules.map(function (r) {
          return '<option value="' + attr(r.key) + '"' + (r.key === a.rule ? " selected" : "") + ">" + escapeHtml(r.label) + "</option>";
        }).join("") + "</select></label>" +
      '<label class="npd-abbr-multi"><input type="checkbox" id="npd-attr-multi"' + (a.multi ? " checked" : "") +
        (editable ? "" : " disabled") + "> Several at once, each adding its own code</label>" +
      '<p class="npd-abbr-rulehelp">' + escapeHtml(rule.help) + (rule.example ? ' <span class="npd-abbr-eg">' + escapeHtml(rule.example) + "</span>" : "") + "</p>" +
      // A rule's number says what it measures only with its unit - 7W, CRI95, IP20 - so the
      // unit is set here, beside a real value showing what it produces.
      (a.rule !== "list"
        ? '<div class="npd-abbr-affix"><span class="npd-abbr-affix-label">Written as</span>' +
            '<input id="npd-attr-prefix" value="' + attr(a.prefix || "") + '" maxlength="6" placeholder="before"' +
              (editable ? "" : " disabled") + ' aria-label="Letters before the number">' +
            '<span class="npd-abbr-affix-n">n</span>' +
            '<input id="npd-attr-suffix" value="' + attr(a.suffix || "") + '" maxlength="6" placeholder="after"' +
              (editable ? "" : " disabled") + ' aria-label="Letters after the number">' +
            npdCodesAffixExample(key) + "</div>"
        : "") +
    "</div>" +
    '<div class="npd-abbr-filters">' +
      '<span class="muted">Values used in ' + scopeLabel + "</span>" +
      (npdCodes.typology ? '<label><input type="checkbox" id="npd-abbr-all"' + (npdCodes.allValues ? " checked" : "") + "> every typology</label>" : "") +
      '<label><input type="checkbox" id="npd-abbr-missing"' + (npdCodes.onlyMissing ? " checked" : "") + "> only missing</label>" +
    "</div>" +
    (values.length
      ? '<div class="npd-abbr-scroll"><table class="npd-abbr-table"><thead><tr><th>Value</th>' +
        '<th class="num">Products</th><th>Code</th><th></th></tr></thead><tbody>' +
        values.map(function (v) {
          const n = npdCodes.typology && !npdCodes.allValues ? ((v.typologies || {})[npdCodes.typology] || 0) : v.count;
          return '<tr class="' + (v.code ? "" : "is-missing") + '"><td>' + escapeHtml(v.value) +
            '</td><td class="num">' + (n || '<span class="muted">none yet</span>') + "</td><td>" +
            npdAbbrInputHtml(key, v, editable) + "</td><td>" + npdAbbrBadge(v, key, editable) + "</td></tr>";
        }).join("") + "</tbody></table></div>"
      : '<p class="npd-await">' + (npdCodes.onlyMissing ? "Every value here has a code." : "No product here records a value for this yet.") + "</p>") +
    (editable
      ? '<div class="npd-abbr-add"><input id="npd-abbr-new-value" placeholder="A value the team has agreed on">' +
        '<input id="npd-abbr-new-code" placeholder="Code" maxlength="8">' +
        '<button type="button" class="btn small" id="npd-abbr-add">Add value</button></div>'
      : "");
}

function npdAbbrBadge(v, key, editable) {
  if (v.source === "set") return '<span class="npd-abbr-badge set">typed</span>';
  // A library accessory's own code (NPD > Accessory library) - shown, never typed over here.
  if (v.source === "library") {
    return '<span class="npd-abbr-badge set lib" title="Set on the accessory in NPD > Accessory library' +
      (v.library_missing ? " - another accessory of this name has no code yet" : "") + '">from library</span>' +
      (v.library_missing ? '<span class="npd-abbr-badge none" title="Another accessory of this name has no code yet - give it one in NPD > Accessory library">one missing</span>' : "");
  }
  if (v.reason === "library") {
    return '<span class="npd-abbr-badge none" title="Give it a code on the accessory in NPD > Accessory library">missing in library</span>';
  }
  if (v.source === "rule") return '<span class="npd-abbr-badge rule" title="Worked out by the rule - type a code to override it">by rule</span>';
  // A missing code offers its suggestion as one click, so filling a gap is never an invention.
  return (v.suggestion && editable
      ? '<button type="button" class="npd-abbr-use" data-abbr-accept="' + attr(v.value) + '"' +
        (key ? ' data-abbr-key="' + attr(key) + '"' : "") + ' data-suggest="' + attr(v.suggestion) +
        '" title="Use the suggested code">Use ' + escapeHtml(v.suggestion) + "</button>"
      : "") +
    '<span class="npd-abbr-badge none" title="' + attr(v.reason === "digits"
      ? "Its rule gives digits alone, which do not say what the value is"
      : "Nothing gives it a code yet") + '">' + (v.reason === "digits" ? "digits only" : "missing") + "</span>";
}

// One code box in the panel: a typed code in bold, a rule's code or a suggestion in grey.
function npdAbbrInputHtml(key, v, editable) {
  if (v.source === "library" || v.reason === "library") {
    if (!v.code) return '<span class="muted">in NPD</span>';
    // one name, many library accessories (HONEYCOMB in ten sizes): the first two, the rest on hover
    const codes = v.code.split(" / ");
    const first = '<code class="npd-abbr-lib" title="Set in NPD > Accessory library">' + escapeHtml(codes[0]) + "</code>";
    // the rest open in place - a hover title reaches no phone and no keyboard
    return codes.length === 1 ? first : first + '<details class="npd-abbr-more"><summary>+' + (codes.length - 1) +
      ' more</summary><code class="npd-abbr-lib">' + escapeHtml(codes.slice(1).join(" / ")) + "</code></details>";
  }
  return '<input class="npd-abbr-code" data-abbr-key="' + attr(key) + '" data-abbr-value="' + attr(v.value) +
    '" value="' + attr(v.source === "set" ? v.code : "") + '" placeholder="' +
    attr(v.source === "rule" ? v.code : (v.suggestion || "")) + '" data-suggest="' +
    attr(v.code ? "" : (v.suggestion || "")) + '" maxlength="10" autocomplete="off"' +
    (editable ? "" : " disabled") + ">";
}

// What the unit makes of a real value: the first one in use that the rule codes.
function npdCodesAffixExample(key) {
  const hit = (((npdCodes.data || {}).values || {})[key] || []).find(function (v) { return v.source === "rule"; });
  return hit
    ? '<span class="npd-abbr-affix-eg">' + escapeHtml(hit.value) + " \u2192 <b>" + escapeHtml(hit.code) + "</b></span>"
    : "";
}

// Every value used here that has no code, from every segment in this structure, in one list -
// so closing the gaps is one pass down a column, not a hunt through twenty segments.
function npdCodesMissingHtml() {
  const editable = npdCodeCanEdit();
  const rows = [];
  (npdCodes.draft ? npdCodes.draft.segments : []).forEach(function (seg) {
    if (!seg.include) return;
    const a = npdCodesAttr(seg.key);
    ((((npdCodes.data || {}).values || {})[seg.key]) || []).forEach(function (v) {
      const n = npdCodes.typology ? ((v.typologies || {})[npdCodes.typology] || 0) : v.count;
      if (n && !v.code) rows.push({ key: seg.key, label: a.label, v: v, n: n });
    });
  });
  return '<div class="npd-codes-card-head"><h5>Values with no code <small class="muted">' + rows.length +
      "</small></h5>" +
      (npdCodes.selected ? '<button type="button" class="btn tiny ghost" id="npd-missing-back">Back to ' +
        escapeHtml(npdCodesAttr(npdCodes.selected).label) + "</button>" : "") + "</div>" +
    '<p class="npd-abbr-note">Type a code, or press <b>Enter</b> on an empty box to take the one ' +
      "shown in grey \u2014 it moves you to the next.</p>" +
    (rows.length
      ? '<div class="npd-abbr-scroll"><table class="npd-abbr-table"><thead><tr><th>Segment</th><th>Value</th>' +
        '<th class="num">Products</th><th>Code</th><th></th></tr></thead><tbody>' +
        rows.map(function (r) {
          return '<tr class="is-missing"><td class="muted">' + escapeHtml(r.label) + "</td><td>" + escapeHtml(r.v.value) +
            '</td><td class="num">' + r.n + "</td><td>" + npdAbbrInputHtml(r.key, r.v, editable) + "</td><td>" +
            npdAbbrBadge(r.v, r.key, editable) + "</td></tr>";
        }).join("") + "</tbody></table></div>"
      : '<p class="npd-await">Every value used here has a code.</p>');
}

function npdCodesCoverageHtml() {
  const products = npdCodesProducts();
  const incomplete = products.filter(function (p) { return !p.complete; });
  const ids = new Set(products.map(function (p) { return p.id; }));
  const byId = {};
  ((npdCodes.data || {}).report || []).forEach(function (r) { byId[r.id] = r; });
  const shared = ((npdCodes.data || {}).duplicates || []).filter(function (d) {
    return d.ids.some(function (id) { return ids.has(id); });
  });
  const open = function (id, field) {
    return '<button type="button" class="btn tiny ghost" data-codes-open="' + id + '"' +
      (field ? ' data-open-field="' + attr(field) + '"' : "") +
      ' title="Open the product' + (field ? " at the field it needs" : "") + '">Open</button>';
  };
  return '<div class="npd-codes-card-head"><h5>What still needs a decision</h5>' +
      '<span class="npd-codes-source">As saved — an unsaved structure above is not counted yet.</span></div>' +
    '<div class="npd-cover-grid">' +
      "<div><h6>Missing a value or a code (" + incomplete.length + ")</h6>" +
        (incomplete.length
          ? '<table class="npd-cover-table"><tbody>' + incomplete.map(function (p) {
              return "<tr><td><b>" + escapeHtml(p.product_name || "Untitled") + "</b>" +
                (npdCodes.typology ? "" : '<br><span class="muted">' + escapeHtml(p.typology || "no typology") + "</span>") +
                '</td><td><span class="npd-cover-missing">' + escapeHtml(p.missing.join(", ") || "—") +
                "</span>" + (p.uncoded ? ' <span class="muted">— ' + p.uncoded + " of " + p.skus +
                  " configurations have no code</span>" : "") +
                '<br><code class="npd-cover-code">' + escapeHtml(p.partial || p.identity_partial) + "</code></td><td>" +
                open(p.id, (p.missing_keys || [])[0]) + "</td></tr>";
            }).join("") + "</tbody></table>"
          : '<p class="muted">Every configuration of every product here has a code.</p>') +
      "</div>" +
      '<div id="npd-cover-shared"><h6>Sharing codes (' + shared.length + ")</h6>" +
        (shared.length
          ? '<p class="npd-cover-note">Two configurations with one code is what the code exists to ' +
            "prevent. Usually it is one fitting written up twice — merge the sheets; otherwise add " +
            "the segment that tells them apart.</p>" +
            shared.map(function (d) {
              return '<div class="npd-cover-dup"><code class="npd-cover-code">' + escapeHtml(d.code) + "</code>" +
                (d.count > 1 ? ' <span class="muted">and ' + (d.count - 1) + " more</span>" : "") +
                d.ids.map(function (id) {
                  const r = byId[id] || {};
                  return '<div class="npd-cover-dup-row"><span>' + escapeHtml(r.product_name || "#" + id) + "</span>" + open(id) + "</div>";
                }).join("") + "</div>";
            }).join("")
          : '<p class="muted">No two configurations share a code.</p>') +
      "</div>" +
    "</div>";
}

// ---- behaviour

function npdCodesChanged() {
  npdCodes.dirty = true;
  npdCodesRenderPart("structure");
  npdCodesExampleSoon();
}

function npdCodesRenderPart(which) {
  const box = app.querySelector("#npd-codes-" + which);
  if (!box) return;
  box.innerHTML = which === "structure" ? npdCodesStructureHtml()
    : which === "abbrev" ? npdCodesAbbrevHtml()
    : which === "coverage" ? npdCodesCoverageHtml() : npdCodesHealthHtml();
  npdCodesBind(box);
}

let npdCodesExampleTimer = null;
function npdCodesExampleSoon(wait) {
  clearTimeout(npdCodesExampleTimer);
  npdCodesExampleTimer = setTimeout(npdCodesExample, wait === undefined ? 200 : wait);
}

async function npdCodesExample() {
  if (!npdCodes.exampleId || !npdCodes.draft) { npdCodes.example = null; return; }
  const asked = npdCodes.exampleId;
  try {
    const res = await api("/api/npd/codes/preview", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sheet_id: asked, scheme: npdCodes.draft, sample: true }),
    });
    if (asked !== npdCodes.exampleId) return;
    npdCodes.example = res;
  } catch (e) {
    npdCodes.example = null;
  }
  npdCodesRenderPart("structure");
}

function npdCodesMove(key, to) {
  const segs = npdCodes.draft.segments;
  const from = segs.findIndex(function (s) { return s.key === key; });
  if (from < 0 || to < 0 || to >= segs.length || from === to) return;
  const item = segs.splice(from, 1)[0];
  segs.splice(to, 0, item);
  npdCodesChanged();
}

function npdCodesBind(root) {
  const scope = root || app.querySelector("#npd-codes");
  if (!scope) return;
  const on = function (sel, ev, fn) {
    scope.querySelectorAll(sel).forEach(function (n) { n.addEventListener(ev, function (e) { fn(n, e); }); });
  };
  on("[data-codes-typology]", "click", function (b) {
    const want = b.dataset.codesTypology;
    if (want === npdCodes.typology) return;
    if (npdCodes.dirty && !confirm("Leave the unsaved changes to " + (npdCodes.typology || "the brand default") + "?")) return;
    npdCodes.typology = want;
    npdCodes.example = null;
    npdCodesStartDraft();
    npdCodesRender();
    npdCodesExampleSoon(0);
  });
  on("#npd-codes-example", "change", function (s) {
    npdCodes.exampleId = Number(s.value);
    npdCodesExampleSoon(0);
  });
  on("[data-seg-select]", "click", function (b) {
    npdCodes.selected = b.dataset.segSelect;
    npdCodes.showMissing = false;
    app.querySelectorAll(".npd-seg").forEach(function (li) { li.classList.toggle("selected", li.dataset.seg === npdCodes.selected); });
    npdCodesRenderPart("abbrev");
  });
  on("[data-seg-include]", "change", function (c) {
    const s = npdCodes.draft.segments.find(function (x) { return x.key === c.dataset.segInclude; });
    if (s) { s.include = c.checked; npdCodesChanged(); }
  });
  on("[data-seg-optional]", "change", function (c) {
    const s = npdCodes.draft.segments.find(function (x) { return x.key === c.dataset.segOptional; });
    if (s) { s.optional = c.checked; npdCodesChanged(); }
  });
  on("[data-seg-move]", "click", function (b) {
    const segs = npdCodes.draft.segments;
    const i = segs.findIndex(function (s) { return s.key === b.dataset.segMove; });
    npdCodesMove(b.dataset.segMove, i + Number(b.dataset.dir));
  });
  on("[data-seg-remove]", "click", function (b) {
    npdCodes.draft.segments = npdCodes.draft.segments.filter(function (s) { return s.key !== b.dataset.segRemove; });
    if (npdCodes.selected === b.dataset.segRemove) {
      npdCodes.selected = npdCodes.draft.segments.length ? npdCodes.draft.segments[0].key : "";
      npdCodesRenderPart("abbrev");
    }
    npdCodesChanged();
  });
  // Drag to reorder; the arrow buttons do the same for anyone not using a mouse.
  on(".npd-seg[draggable]", "dragstart", function (li, e) {
    npdCodes.dragKey = li.dataset.seg;
    li.classList.add("dragging");
    e.dataTransfer.effectAllowed = "move";
    try { e.dataTransfer.setData("text/plain", li.dataset.seg); } catch (err) { /* IE-era browsers */ }
  });
  on(".npd-seg[draggable]", "dragend", function (li) { li.classList.remove("dragging"); npdCodes.dragKey = ""; });
  on(".npd-seg[draggable]", "dragover", function (li, e) {
    if (!npdCodes.dragKey) return;
    e.preventDefault();
    const box = li.getBoundingClientRect();
    li.classList.toggle("drop-before", e.clientY < box.top + box.height / 2);
    li.classList.toggle("drop-after", e.clientY >= box.top + box.height / 2);
  });
  on(".npd-seg[draggable]", "dragleave", function (li) { li.classList.remove("drop-before", "drop-after"); });
  on(".npd-seg[draggable]", "drop", function (li, e) {
    e.preventDefault();
    const after = li.classList.contains("drop-after");
    li.classList.remove("drop-before", "drop-after");
    const segs = npdCodes.draft.segments;
    const from = segs.findIndex(function (s) { return s.key === npdCodes.dragKey; });
    let to = segs.findIndex(function (s) { return s.key === li.dataset.seg; });
    if (from < 0 || to < 0) return;
    if (after) to += 1;
    if (from < to) to -= 1;
    npdCodesMove(npdCodes.dragKey, to);
  });
  on("#npd-codes-prefix", "change", function (i) { npdCodes.draft.prefix = i.value.trim().toUpperCase(); npdCodesChanged(); });
  on("#npd-codes-sep", "change", function (s) { npdCodes.draft.separator = s.value; npdCodesChanged(); });
  on("#npd-codes-discard", "click", function () {
    npdCodesStartDraft();
    npdCodesRenderPart("structure");
    npdCodesExampleSoon(0);
  });
  on("#npd-codes-save", "click", function (b) { withBusy(b, npdCodesSave); });
  on("#npd-codes-reset", "click", function (b) { withBusy(b, npdCodesReset); });
  on("#npd-codes-restore", "click", function (b) { withBusy(b, npdCodesRestore); });
  on("#npd-codes-add", "click", function () { npdCodes.picker = true; npdCodesRenderPart("structure"); });
  on("#npd-codes-picker-close", "click", function () { npdCodes.picker = false; npdCodesRenderPart("structure"); });
  on("[data-pick-attr]", "click", function (b) {
    npdCodes.draft.segments.push({ key: b.dataset.pickAttr, include: true, optional: false });
    npdCodes.selected = b.dataset.pickAttr;
    npdCodes.picker = false;
    npdCodesRenderPart("abbrev");
    npdCodesChanged();
  });
  on("[data-pick-param]", "click", function (b) {
    withBusy(b, function () {
      return npdCodesCreateAttr({ key: b.dataset.pickParam, label: b.dataset.label.charAt(0) + b.dataset.label.slice(1).toLowerCase(),
                                  part: b.dataset.configurable ? "config" : "identity", rule: "list" });
    });
  });
  on("#npd-new-attr-go", "click", function (b) {
    const label = (scope.querySelector("#npd-new-attr-label").value || "").trim();
    if (!label) { alert("Give the new attribute a name first."); return; }
    withBusy(b, function () {
      return npdCodesCreateAttr({ label: label, part: scope.querySelector("#npd-new-attr-part").value,
                                  rule: scope.querySelector("#npd-new-attr-rule").value });
    });
  });
  on("#npd-attr-part", "change", function (s) { npdCodesEditAttr({ part: s.value }); });
  on("#npd-attr-rule", "change", function (s) { npdCodesEditAttr({ rule: s.value }); });
  on("#npd-attr-multi", "change", function (c) { npdCodesEditAttr({ multi: c.checked }); });
  on("#npd-attr-rename", "click", function () {
    const a = npdCodesAttr(npdCodes.selected);
    const label = (prompt("What should “" + a.label + "” be called?\n\nOnly the name changes - " +
      "the values already recorded on products stay where they are.", a.label) || "").trim();
    if (label && label !== a.label) npdCodesEditAttr({ label: label });
  });
  on("#npd-attr-delete", "click", function (b) {
    const a = npdCodesAttr(npdCodes.selected);
    if (!confirm("Delete the attribute “" + a.label + "”?\n\nIt has to be out of every structure first. " +
      "Values already recorded on products, and the abbreviations typed for them, are kept.")) return;
    withBusy(b, async function () {
      try {
        await api("/api/npd/codes/attributes/" + encodeURIComponent(a.key), { method: "DELETE" });
        npdCodes.selected = "";
        await npdCodesLoad(true);
        showToast("Deleted \u201c" + a.label + "\u201d.");
      } catch (e) { showToast(e.message, "error"); }
    });
  });
  on("#npd-abbr-all", "change", function (c) { npdCodes.allValues = c.checked; npdCodesRenderPart("abbrev"); });
  on("#npd-abbr-missing", "change", function (c) { npdCodes.onlyMissing = c.checked; npdCodesRenderPart("abbrev"); });
  // A code is saved when the box is left, not on every keystroke - "M" should not be stored on
  // the way to "MD". Updated in place, so tabbing down the list keeps its place.
  on(".npd-abbr-code", "change", function (input) {
    npdCodesSetAbbrev(input.dataset.abbrKey || npdCodes.selected, input.dataset.abbrValue, input.value, input);
  });
  // Enter saves and moves down the column; on an empty box it first takes the suggestion.
  on(".npd-abbr-code", "keydown", function (input, e) {
    if (e.key !== "Enter") return;
    e.preventDefault();
    if (!input.value.trim() && input.dataset.suggest) input.value = input.dataset.suggest;
    const all = Array.from(scope.querySelectorAll(".npd-abbr-code:not([disabled])"));
    const next = all[all.indexOf(input) + 1];
    npdCodesSetAbbrev(input.dataset.abbrKey || npdCodes.selected, input.dataset.abbrValue, input.value, input);
    if (next) next.focus(); else input.blur();
  });
  on("#npd-abbr-add", "click", function (b) {
    const value = scope.querySelector("#npd-abbr-new-value").value.trim();
    const code = scope.querySelector("#npd-abbr-new-code").value.trim();
    if (!value || !code) { alert("Give both the value and its code."); return; }
    withBusy(b, async function () {
      await npdCodesSetAbbrev(npdCodes.selected, value, code, null);
      npdCodesRenderPart("abbrev");
    });
  });
  // A product is opened where it is edited - NPD - with the caret in the field it needs.
  on("[data-codes-open]", "click", async function (b) {
    if (npdCodes.dirty && !confirm("Leave the unsaved structure changes?")) return;
    npdCodes.dirty = false;
    const id = b.dataset.codesOpen, field = b.dataset.openField || null;
    npdView.editing = null;
    await setView("npd");
    if (state.view === "npd") npdOpenProduct(id, field);
  });
  on("[data-codes-go]", "click", function (b) {
    const go = b.dataset.codesGo;
    if (go === "missing") {
      npdCodes.showMissing = true;
      npdCodesRenderPart("abbrev");
      const card = app.querySelector("#npd-codes-abbrev");
      if (card) {
        card.scrollIntoView({ behavior: "smooth", block: "nearest" });
        flashHighlight(card);
        const first = card.querySelector(".npd-abbr-code:not([disabled])");
        if (first) setTimeout(function () { first.focus({ preventScroll: true }); }, 300);
      }
      return;
    }
    const target = app.querySelector(go === "shared" ? "#npd-cover-shared" : "#npd-codes-coverage");
    if (target) { target.scrollIntoView({ behavior: "smooth", block: "start" }); flashHighlight(target); }
  });
  on("#npd-missing-back", "click", function () { npdCodes.showMissing = false; npdCodesRenderPart("abbrev"); });
  on("[data-abbr-accept]", "click", function (b) {
    const row = b.closest("tr");
    const input = row && row.querySelector(".npd-abbr-code");
    npdCodesSetAbbrev(b.dataset.abbrKey || npdCodes.selected, b.dataset.abbrAccept, b.dataset.suggest, input);
  });
  on("#npd-attr-prefix", "change", function (i) { npdCodesEditAttr({ prefix: i.value.trim().toUpperCase() }); });
  on("#npd-attr-suffix", "change", function (i) { npdCodesEditAttr({ suffix: i.value.trim().toUpperCase() }); });
}

async function npdCodesSave() {
  try {
    await api("/api/npd/codes/schemes", {
      method: "PUT", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ make: npdCodesBrand(), typology: npdCodes.typology,
                             prefix: npdCodes.draft.prefix, separator: npdCodes.draft.separator,
                             segments: npdCodes.draft.segments }),
    });
    npdCodes.dirty = false;
    const n = npdCodes.typology ? npdCodesCount(npdCodes.typology) : ((npdCodes.data || {}).report || []).length;
    await npdCodesLoad(true);
    // NPD's product cards show each product's code; they read it afresh the next time NPD opens.
    showToast("Saved \u2014 the " + (npdCodes.typology || "brand default") + " code now reads this way" +
      (n ? " for " + n + " product" + (n === 1 ? "" : "s") : "") + ".");
  } catch (e) {
    showToast("Could not save the structure: " + e.message, "error");
  }
}

async function npdCodesReset() {
  const own = npdCodesOwnScheme(npdCodes.typology);
  if (!own) return;
  if (!confirm(npdCodes.typology + " will use the brand default structure from now on. Its own structure is put aside, and “Restore its own structure” brings it back.")) return;
  try {
    await api("/api/npd/codes/schemes/" + own.id, { method: "DELETE" });
    npdCodes.dirty = false;
    await npdCodesLoad(true);
    showToast(npdCodes.typology + " now follows the brand default. Its own structure is kept — “Restore its own structure” brings it back.");
  } catch (e) {
    showToast("Could not reset it: " + e.message, "error");
  }
}

async function npdCodesRestore() {
  const typ = npdCodes.typology;
  const retired = npdCodesRetiredScheme(typ);
  if (!retired) return;
  try {
    const res = await api("/api/npd/codes/schemes/" + retired.id + "/restore", { method: "POST" });
    npdCodes.dirty = false;
    await npdCodesLoad(true);
    const dropped = (res.dropped || []);
    showToast((typ || "The brand default") + " has its own structure again" +
      (dropped.length ? ", without " + dropped.join(", ") + " (no longer an attribute)" : "") + ".");
  } catch (e) {
    showToast("Could not restore it: " + e.message, "error");
  }
}

async function npdCodesCreateAttr(body) {
  try {
    const made = await api("/api/npd/codes/attributes", {
      method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
    });
    npdCodes.data.attributes.push(made);
    npdCodes.data.values[made.key] = npdCodes.data.values[made.key] || [];
    npdCodes.draft.segments.push({ key: made.key, include: true, optional: false });
    npdCodes.selected = made.key;
    npdCodes.picker = false;
    npdCodesRenderPart("abbrev");
    npdCodesChanged();
    // The value list for a parameter comes from the products, which only a reload counts.
    const keep = npdCodes.draft, dirty = npdCodes.dirty;
    const data = await api("/api/npd/codes?make=" + encodeURIComponent(npdCodesBrand()));
    npdCodes.data = data;
    npdCodes.draft = keep;
    npdCodes.dirty = dirty;
    npdCodesRenderPart("abbrev");
  } catch (e) {
    showToast("Could not create it: " + e.message, "error");
  }
}

async function npdCodesEditAttr(patch) {
  const key = npdCodes.selected;
  try {
    const saved = await api("/api/npd/codes/attributes/" + encodeURIComponent(key), {
      method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(patch),
    });
    const list = npdCodes.data.attributes;
    const i = list.findIndex(function (a) { return a.key === key; });
    if (i >= 0) list[i] = saved;
    // How values are coded may just have changed, so the codes are asked for again.
    await npdCodesRefreshData();
  } catch (e) {
    showToast("Could not change it: " + e.message, "error");
    npdCodesRenderPart("abbrev");
  }
}

// Fetch the panel's data again without touching the structure being edited.
async function npdCodesRefreshData() {
  const keep = npdCodes.draft, dirty = npdCodes.dirty;
  try {
    npdCodes.data = await api("/api/npd/codes?make=" + encodeURIComponent(npdCodesBrand()));
  } catch (e) { return; }
  npdCodes.draft = keep;
  npdCodes.dirty = dirty;
  ["health", "structure", "abbrev", "coverage"].forEach(npdCodesRenderPart);
  npdCodesExampleSoon(0);
}

async function npdCodesSetAbbrev(key, value, code, input) {
  const clean = String(code || "").replace(/\s+/g, "").toUpperCase();
  // Enter commits and the box then loses focus, which would commit it a second time.
  if (input) {
    if (input.dataset.committing === clean) return;
    input.dataset.committing = clean;
  }
  if (clean && !/[A-Z]/.test(clean)) {
    if (input) { input.dataset.committing = ""; input.classList.add("is-error"); }
    showToast("A code needs a letter so it says what it is \u2014 " + clean + "W or " + clean +
      "K, not " + clean + " alone.", "error");
    return;
  }
  if (input) input.classList.add("is-saving");
  try {
    const saved = await api("/api/npd/codes/abbreviations", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field: key, value: value, code: clean }),
    });
    const list = (npdCodes.data.values[key] = npdCodes.data.values[key] || []);
    let row = list.find(function (v) { return npdSquash(v.value) === npdSquash(value); });
    if (!row) { row = { value: value, count: 0, typologies: {} }; list.push(row); }
    row.code = saved.effective || "";
    row.source = saved.code ? "set" : (saved.source || "");
    row.suggestion = saved.suggestion || "";
    row.reason = saved.effective ? "" : row.reason;
    if (input) {
      input.value = saved.code;
      input.placeholder = saved.code ? "" : (saved.rule_code || saved.suggestion || "");
      input.dataset.suggest = row.code ? "" : row.suggestion;
      input.dataset.committing = "";
      input.classList.remove("is-saving", "is-error");
      input.classList.add("is-saved");
      setTimeout(function () { input.classList.remove("is-saved"); }, 1400);
      const tr = input.closest("tr");
      if (tr) {
        tr.classList.toggle("is-missing", !row.code);
        tr.lastElementChild.innerHTML = npdAbbrBadge(row, key, npdCodeCanEdit());
        tr.lastElementChild.querySelectorAll("[data-abbr-accept]").forEach(function (b) {
          b.addEventListener("click", function () {
            npdCodesSetAbbrev(b.dataset.abbrKey || key, b.dataset.abbrAccept, b.dataset.suggest, input);
          });
        });
      }
    }
    if (saved.clashes && saved.clashes.length) {
      showToast("Saved. " + saved.code + " is also the code for " + saved.clashes.join(", ") +
        " \u2014 right if they are the same thing spelled differently.", "warn");
    }
    npdCodesRenderPart("health");
    npdCodesExampleSoon();
    npdCodesRefreshReportSoon();
  } catch (e) {
    showToast("Could not save that code: " + e.message, "error");
    if (input) {
      input.dataset.committing = "";
      input.classList.remove("is-saving");
      input.classList.add("is-error");
    }
  }
}

// The completeness and uniqueness check depends on every abbreviation, so it is recounted a
// moment after the last one is typed rather than after each.
let npdCodesReportTimer = null;
function npdCodesRefreshReportSoon() {
  clearTimeout(npdCodesReportTimer);
  npdCodesReportTimer = setTimeout(async function () {
    try {
      const fresh = await api("/api/npd/codes?make=" + encodeURIComponent(npdCodesBrand()));
      npdCodes.data.report = fresh.report;
      npdCodes.data.duplicates = fresh.duplicates;
      npdCodesRenderPart("health");
      npdCodesRenderPart("coverage");
    } catch (e) { /* the numbers stay as they were until the next load */ }
  }, 900);
}

// ---------------- the product form: every code beside the value it abbreviates ----------------
//
// A product's code is not a separate thing to fill in. Each segment abbreviates one value on this
// page - the series, the trim, each wattage on offer - so its code is typed and shown beside that
// value, the way each option's price sits beside the option. The whole code reads along the bar
// at the foot of the page, and anything it still needs is a link to the field that needs it.
//
// The server assembles the code (app/product_codes.py); this page asks it and shows the answer in
// place. A code box is found by what it abbreviates (data-code-key, data-code-value) and handled
// by listeners on the page, so a box redrawn after an answer behaves like the one it replaced.

// The brand's structures, attributes and vocabulary - read once per brand and shared with the
// Product codes panel.
async function npdEnsureCodesData(make, force) {
  const want = make || "";
  if (!force && npdCodes.data && npdCodes.make === want) return npdCodes.data;
  try {
    const data = await api("/api/npd/codes?make=" + encodeURIComponent(want));
    const keepDraft = npdCodes.make === want && npdCodes.dirty;
    npdCodes.data = data;
    npdCodes.make = want;
    if (!keepDraft) { npdCodes.typology = null; npdCodes.draft = null; npdCodes.dirty = false; }
  } catch (e) { /* the form still works; its boxes just offer no suggestions */ }
  return npdCodes.data;
}

function npdSchemeFor(make, typology) {
  const data = npdCodes.data;
  if (!data || npdCodes.make !== (make || "")) return null;
  const schemes = data.schemes || [];
  return schemes.find(function (s) { return s.typology === typology; }) ||
    schemes.find(function (s) { return !s.typology; }) || null;
}

function npdInCode(d, key) {
  const scheme = npdSchemeFor(d.make, d.typology);
  return !!(scheme && scheme.segments.some(function (s) { return s.key === key && s.include; }));
}

function npdSpecKeys(d) {
  const keys = new Set();
  (d.groups || []).forEach(function (g) {
    if (g.group_name === NPD_IDENTITY_GROUP) return;
    g.parameters.forEach(function (p) { keys.add(p.field_key); });
  });
  return keys;
}

// The fields that say what this product is and have no other home on the page: mounting, series
// and size always, then whatever this typology's code names that the specification does not
// print - the series variant, aperture shape, heads, supply voltage. In the order the code reads
// them, so the page and the code agree about what comes first.
function npdClassKeys(d) {
  const scheme = npdSchemeFor(d.make, d.typology);
  const spec = npdSpecKeys(d);
  const skip = ["typology", "model_no", "variant", "make"];
  const keys = (scheme ? scheme.segments : [])
    .filter(function (s) { return s.include && npdCodesAttr(s.key).part !== "config"; })
    .map(function (s) { return s.key; })
    .filter(function (k) { return skip.indexOf(k) < 0 && !spec.has(k); });
  ["sub_typology", "series", "family"].forEach(function (k, i) {
    if (keys.indexOf(k) < 0) keys.splice(Math.min(i, keys.length), 0, k);
  });
  return keys;
}

const NPD_CLASS_LABELS = { sub_typology: "Mounting", family: "Size" };

function npdClassFieldHtml(d, key) {
  const a = npdCodesAttr(key);
  const label = NPD_CLASS_LABELS[key] || a.label;
  const value = npdIdentityValue(d, key);
  const vocab = (((npdCodes.data || {}).values || {})[key] || []).filter(function (v) { return v.value; });
  const listId = "npd-vocab-" + key;
  return '<label class="npd-ident npd-class" data-class-field="' + attr(key) + '">' +
    '<span class="npd-class-label">' + escapeHtml(label) +
      (a.note ? '<span class="npd-hint" tabindex="0" title="' + attr(a.note) + '">?</span>' : "") +
    "</span>" +
    '<span class="npd-ident-row">' +
      '<input class="npd-ident-value" data-ident-value="' + attr(key) + '" value="' + attr(value || "") +
        '" list="' + listId + '" autocomplete="off" placeholder="' +
        (vocab.length ? "Choose\u2026" : "Type\u2026") + '">' +
      (npdInCode(d, key)
        ? npdCodeBoxHtml(key, value, label)
        : '<span class="npd-code-off" title="Not part of the ' + attr(d.typology || "") + ' code">–</span>') +
    "</span>" +
    '<datalist id="' + listId + '">' + vocab.map(function (v) {
      return '<option value="' + attr(v.value) + '">' + escapeHtml(v.code || "") + "</option>";
    }).join("") + "</datalist></label>";
}

function npdClassFieldsHtml(d) {
  if (!d.typology) return "";
  return npdClassKeys(d).map(function (k) { return npdClassFieldHtml(d, k); }).join("");
}

// A classification field the typology does not have yet, added from here: it becomes part of the
// typology's code (after the identity it already has, skipped on any product that leaves it
// blank), so filling it in and giving it codes happen in the same place.
function npdAddClassHtml(d) {
  if (!can("npd.edit") || !d.typology || !npdSchemeFor(d.make, d.typology)) return "";
  return '<div class="npd-addclass" id="npd-addclass">' +
    (npdView.addingClass
      ? '<input id="npd-addclass-label" maxlength="40" placeholder="What it describes — e.g. Beam shape">' +
        '<button type="button" class="btn small" id="npd-addclass-go">Add to ' + escapeHtml(d.typology) + "</button>" +
        '<button type="button" class="btn small ghost" id="npd-addclass-cancel">Cancel</button>' +
        '<span class="npd-addclass-note">Every ' + escapeHtml(d.typology) + " gets it, after the " +
        "identity it already has; a product that leaves it blank simply skips it in its code.</span>"
      : '<button type="button" class="npd-linkbtn" id="npd-addclass-open">+ Add a classification field</button>') +
    "</div>";
}

async function npdAddClassField(d, label) {
  const scheme = npdSchemeFor(d.make, d.typology);
  if (!scheme) return;
  const key = String(label).toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  let made = ((npdCodes.data || {}).attributes || []).find(function (a) {
    return a.key === key || a.label.toLowerCase() === String(label).toLowerCase();
  });
  try {
    if (!made) {
      made = await api("/api/npd/codes/attributes", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ label: label, part: "identity", rule: "list" }),
      });
    }
    const segs = scheme.segments.map(function (s) { return Object.assign({}, s); });
    if (segs.some(function (s) { return s.key === made.key; })) {
      showToast("“" + made.label + "” is already part of the " + d.typology + " code.");
    } else {
      let at = 0;
      segs.forEach(function (s, i) { if (npdCodesAttr(s.key).part !== "config") at = i + 1; });
      segs.splice(at, 0, { key: made.key, include: true, optional: true });
      await api("/api/npd/codes/schemes", {
        method: "PUT", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ make: d.make, typology: d.typology, prefix: scheme.prefix,
                               separator: scheme.separator, segments: segs }),
      });
      showToast("Added “" + made.label + "” to " + d.typology +
        ". Fill it in here — its code goes beside it.");
    }
  } catch (e) {
    showToast("Could not add it: " + e.message, "error");
    return;
  }
  await npdEnsureCodesData(d.make, true);
  npdView.addingClass = false;
  d.code = undefined;
  npdRenderForm();
  const input = app.querySelector('[data-ident-value="' + made.key + '"]');
  if (input) { input.focus(); flashHighlight(input.closest(".npd-ident")); }
}

function npdCodeBoxHtml(key, value, label) {
  return '<input class="npd-code-in is-pending" data-code-key="' + attr(key) + '" data-code-value="' +
    attr(String(value || "").trim()) + '" maxlength="10" autocomplete="off" spellcheck="false" ' +
    'placeholder="…" aria-label="' + attr("Code for " + (label || key)) + '"' +
    (can("npd.edit") ? "" : " disabled") + ">";
}

// What the last answer says about one value of one attribute.
function npdCodeInfo(seg, value) {
  if (!seg || !String(value || "").trim()) return null;
  const want = npdSquash(value);
  const hit = (seg.choices || []).find(function (c) { return npdSquash(c.value) === want; });
  if (hit) return hit;
  if (seg.value && npdSquash(seg.value) === want) {
    return { value: seg.value, code: seg.code, source: seg.source, reason: seg.reason,
             suggestion: seg.suggestion };
  }
  return null;
}

function npdCodeIndex(d) {
  const out = {};
  const r = d.code && d.code.result;
  (r ? r.segments : []).forEach(function (s) { out[s.key] = s; });
  return out;
}

// One box, set from the answer: a typed code in bold, a rule's code as grey placeholder text you
// can type over, a missing one outlined red with a suggestion that Enter accepts. The box under
// the caret is never touched - an answer arriving mid-keystroke must not rewrite what is typed.
function npdCodeBoxApply(input, info) {
  if (document.activeElement === input) return;
  input.classList.remove("is-pending", "is-set", "is-rule", "is-missing", "is-error");
  const value = input.dataset.codeValue || "";
  if (!value) {
    input.value = "";
    input.placeholder = "–";
    input.disabled = true;
    input.dataset.saved = "";
    input.dataset.suggest = "";
    input.title = "Give it a value first — there is nothing to abbreviate yet.";
    return;
  }
  input.disabled = !can("npd.edit");
  if (!info) {
    input.placeholder = "…";
    input.classList.add("is-pending");
    input.title = "";
    return;
  }
  input.dataset.saved = info.source === "set" ? info.code : "";
  input.dataset.suggest = info.code ? "" : (info.suggestion || "");
  if (info.source === "set") {
    input.value = info.code;
    input.placeholder = "";
    input.classList.add("is-set");
    input.title = "“" + value + "” is " + info.code + " on every product. Change it here and every one follows.";
  } else if (info.code) {
    input.value = "";
    input.placeholder = info.code;
    input.classList.add("is-rule");
    input.title = "Worked out by its rule: " + info.code + ". Type a code to use another.";
  } else {
    input.value = "";
    input.placeholder = info.suggestion || "code";
    input.classList.add("is-missing");
    input.title = (info.reason === "digits"
      ? "A number alone does not say what it is — give it a code with a letter."
      : info.reason === "several" ? NPD_SEVERAL_HELP
      : "No code yet.") + (info.suggestion ? " Press Enter to use " + info.suggestion + ", or type your own." : "");
  }
}

// Bring every code on the page up to date with the last answer: the boxes beside the identity,
// a box (or a strip of them, one per option) beside each specification row the code uses, one per
// priced option and per accessory - then the bar at the foot, and the fields still needed.
function npdCodeCellsRender(d) {
  if (npdView.editing !== d) return;
  const segs = npdCodeIndex(d);
  const scheme = d.code && d.code.scheme;
  const inCode = new Set((scheme ? scheme.segments : []).filter(function (s) { return s.include; })
    .map(function (s) { return s.key; }));
  const focused = document.activeElement;
  const busyHere = function (el) { return el && focused && el.contains(focused); };

  app.querySelectorAll("[data-code-cell]").forEach(function (cell) {
    const key = cell.dataset.codeCell;
    const strip = app.querySelector('[data-code-strip="' + key + '"]');
    if (busyHere(cell) || busyHere(strip)) return;
    const seg = segs[key];
    const priced = !!cell.closest(".npd-row.is-priced");
    if (!inCode.has(key) || !seg || priced) {
      cell.innerHTML = "";
      if (strip) strip.innerHTML = "";
      return;
    }
    const options = seg.choices && seg.choices.length ? seg.choices : null;
    if (options && strip) {
      cell.innerHTML = '<span class="npd-code-many" title="One code per option, below">' +
        options.length + " codes</span>";
      strip.innerHTML = options.map(function (c) {
        return '<label class="npd-cchip"><span>' + escapeHtml(c.value) + "</span>" +
          npdCodeBoxHtml(key, c.value, c.value) + "</label>";
      }).join("");
    } else {
      const value = seg.value || (d.values[key] || "");
      const box = cell.querySelector(".npd-code-in");
      if (!box || box.dataset.codeValue !== value) cell.innerHTML = npdCodeBoxHtml(key, value, key);
      if (strip) strip.innerHTML = "";
    }
  });

  app.querySelectorAll("[data-code-optcell]").forEach(function (cell) {
    if (busyHere(cell)) return;
    const key = cell.dataset.codeOptcell;
    const row = ((d.optionRows || {})[key] || [])[Number(cell.dataset.i)];
    const value = row ? String(row.value || "").trim() : "";
    if (!inCode.has(key)) { cell.innerHTML = '<span class="npd-code-off">–</span>'; return; }
    const box = cell.querySelector(".npd-code-in");
    if (!box || box.dataset.codeValue !== value) cell.innerHTML = npdCodeBoxHtml(key, value, value);
  });

  app.querySelectorAll("[data-code-acccell]").forEach(function (cell) {
    if (busyHere(cell)) return;
    const acc = d.accessories[Number(cell.dataset.codeAcccell)];
    const value = acc ? String(acc.name || "").trim() : "";
    if (!inCode.has("accessories")) { cell.innerHTML = '<span class="npd-code-off">–</span>'; return; }
    const box = cell.querySelector(".npd-code-in");
    if (!box || box.dataset.codeValue !== value) cell.innerHTML = npdCodeBoxHtml("accessories", value, value);
  });

  app.querySelectorAll(".npd-step .npd-code-in").forEach(function (input) {
    npdCodeBoxApply(input, npdCodeInfo(segs[input.dataset.codeKey], input.dataset.codeValue));
  });

  // A value the code needs and the product does not have is marked where it is typed.
  app.querySelectorAll(".npd-needs").forEach(function (el) { el.classList.remove("npd-needs"); });
  Object.keys(segs).forEach(function (key) {
    if (segs[key].status !== "no_value") return;
    const el = app.querySelector('[data-ident-value="' + key + '"]') ||
      app.querySelector('input[data-key="' + key + '"]');
    if (el) el.classList.add("npd-needs");
  });

  npdCodeBarRender(d);
  if (npdView.pendingJump && d.code) {
    const key = npdView.pendingJump;
    npdView.pendingJump = null;
    setTimeout(function () { npdJumpTo(key); }, 60);
  }
}

// ---- the bar at the foot of the page

function npdCodeBarRender(d, busy) {
  const bar = app.querySelector("#npd-codebar");
  if (!bar) return;
  const label = '<span class="npd-codebar-label">Code</span>';
  const res = d.code;
  bar.classList.toggle("is-busy", !!busy);
  if (!d.typology) {
    bar.innerHTML = label + '<span class="npd-codebar-note">Choose a typology and the code starts here.</span>';
    return;
  }
  if (res === undefined) {
    bar.innerHTML = label + '<span class="npd-skel npd-skel-code"></span>';
    return;
  }
  if (!res || !res.scheme) {
    bar.innerHTML = label + '<span class="npd-codebar-note">' + escapeHtml(d.make || "This brand") +
      " has no code structure yet — one is set up on the Nomenclature tab.</span>";
    return;
  }
  const r = res.result;
  const withSep = Object.assign({ separator: res.scheme.separator, prefix: res.scheme.prefix }, r);
  // Anything that leaves some configuration without a code: a value missing, a value with no
  // code, or one option of a choice with no code - that option's SKUs would have none.
  const missing = r.segments.filter(function (s) {
    return s.status === "no_value" || s.status === "no_code" ||
      (s.status === "choose" && (s.choices || []).some(function (c) { return !c.code; }));
  });
  const shared = res.shared_with || [];
  let status;
  if (missing.length) {
    status = '<span class="npd-codebar-status bad">' + missing.length + " to fill</span>" +
      missing.map(function (s) {
        const why = s.reason === "several" ? NPD_SEVERAL_HELP
          : s.status === "no_value" ? "Needs a value" : "Needs a code";
        return '<button type="button" class="npd-codebar-fix" data-jump="' + attr(s.key) + '" title="' +
          attr(why) + ' — go to it">' + escapeHtml(s.label) + "</button>";
      }).join("");
  } else if (shared.length) {
    status = '<span class="npd-codebar-status warn" title="' + attr(
      "A configuration of this product has the same code as one of " +
      (shared[0].product_name || "#" + shared[0].id) + " (" + (shared[0].code || "") + "). If they " +
      "are one fitting, merge them; if not, a segment that tells them apart is missing.") +
      '">Same code as ' +
      escapeHtml(shared.slice(0, 2).map(function (p) { return p.product_name || "#" + p.id; }).join(", ")) +
      (shared.length > 2 ? " +" + (shared.length - 2) : "") + "</span>";
  } else {
    status = '<span class="npd-codebar-status ok" title="Every configuration of this product has ' +
      'a code of its own, and no other product has any of them">✓ Unique</span>';
  }
  bar.innerHTML = label + '<span class="npd-codebar-code">' + npdCodeSpans(withSep, null, true) + "</span>" + status;
}

// Scroll to the field one segment of the code comes from, and put the caret in it: the value
// when there is none, the code box when the value has no code.
function npdJumpTo(key) {
  const d = npdView.editing;
  if (!d) return;
  const seg = npdCodeIndex(d)[key];
  const valueEl = app.querySelector('[data-ident-value="' + key + '"]') ||
    app.querySelector('input[data-key="' + key + '"]') ||
    app.querySelector('[data-opt-key="' + key + '"]');
  const boxes = Array.from(app.querySelectorAll('.npd-step .npd-code-in[data-code-key="' + key + '"]'));
  const gap = boxes.find(function (b) { return b.classList.contains("is-missing"); });
  const focusEl = (seg && seg.status === "no_code" && (gap || boxes[0])) || valueEl || boxes[0];
  if (!focusEl) return;
  const holder = focusEl.closest(".npd-row, .npd-ident, .npd-acc-row") || focusEl;
  holder.scrollIntoView({ behavior: "smooth", block: "center" });
  flashHighlight(holder);
  setTimeout(function () { try { focusEl.focus({ preventScroll: true }); } catch (e) { focusEl.focus(); } }, 250);
}

// ---- asking for the code, and saving one

let npdCodeTimer = null;
function npdCodeRefreshSoon(d, wait) {
  clearTimeout(npdCodeTimer);
  // The bar dims at once, so a change reads as being worked on rather than ignored. Only its
  // class changes: redrawing it here would pull a link out from under a click that is landing
  // on it - typing a value and then clicking "to fill" blurs the box, which comes through here.
  const bar = app.querySelector("#npd-codebar");
  if (bar && d && d.code !== undefined) bar.classList.add("is-busy");
  npdCodeTimer = setTimeout(function () { npdCodeRefresh(d); }, wait === undefined ? 180 : wait);
}

async function npdCodeRefresh(d) {
  if (npdView.editing !== d) return;
  if (!d.typology) { d.code = undefined; npdCodeCellsRender(d); return; }
  await npdEnsureCodesData(d.make);
  try {
    d.code = await api("/api/npd/codes/preview", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        // `affects` too: a value becomes a choice only where the product offers it as one,
        // exactly as saving it would decide - so the code shown is the code it will have.
        draft: { typology: d.typology, make: d.make, series: d.series, family: d.family,
                 variant: d.variant, sub_typology: d.sub_typology, model_no: d.model_no,
                 values: npdCodeDraftValues(d), affects: d.affects,
                 // library accessories code themselves (app/accessory_parts.py)
                 accessory_parts: (d.accessories || []).filter(function (a) { return a.part_id; })
                   .map(function (a) { return a.part_id; }) },
        exclude_id: d.id || null,
      }),
    });
  } catch (e) {
    d.code = null;
  }
  if (npdView.editing === d) npdCodeCellsRender(d);
}

// What the code is worked out from: the values as typed, plus the accessories as listed below -
// the accessory row up in the specification prints what that list says, so the list is the truth.
function npdCodeDraftValues(d) {
  const values = Object.assign({}, d.values);
  const named = d.accessories.map(function (a) { return String(a.name || "").trim(); }).filter(Boolean);
  if (named.length) values.accessories = named.join(" / ");
  return values;
}

async function npdCodeCommit(d, input) {
  const key = input.dataset.codeKey;
  const value = input.dataset.codeValue || "";
  const code = input.value.replace(/\s+/g, "").toUpperCase();
  input.value = code;
  if (!value || code === (input.dataset.saved || "")) return;
  if (code && !/[A-Z]/.test(code)) {
    input.classList.add("is-error");
    showToast("A code needs a letter so it says what it is — " + code + "W, " + code + "H or " +
      code + "K, not " + code + " alone.", "error");
    return;
  }
  input.classList.remove("is-error", "is-missing", "is-rule");
  input.classList.add("is-saving");
  npdCodeBarRender(d, true);
  try {
    const saved = await api("/api/npd/codes/abbreviations", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field: key, value: value, code: code }),
    });
    input.dataset.saved = saved.code;
    input.classList.remove("is-saving");
    input.classList.add("is-saved");
    setTimeout(function () { input.classList.remove("is-saved"); }, 1400);
    npdVocabUpdate(key, value, saved);
    if (saved.clashes && saved.clashes.length) {
      showToast("Saved. " + saved.code + " is also the code for " + saved.clashes.join(", ") +
        " — right only if they are the same thing spelled differently.", "warn");
    }
  } catch (err) {
    input.classList.remove("is-saving");
    input.classList.add("is-error");
    showToast("Could not save that code: " + err.message, "error");
  }
  npdCodeRefreshSoon(d, 0);
}

// Keep the shared vocabulary in step with a code just saved, so the next suggestion list and
// the Product codes panel read the same thing without asking the server again.
function npdVocabUpdate(key, value, saved) {
  const values = npdCodes.data && npdCodes.data.values;
  if (!values) return;
  const list = (values[key] = values[key] || []);
  let row = list.find(function (v) { return npdSquash(v.value) === npdSquash(value); });
  if (!row) { row = { value: value, count: 0, typologies: {} }; list.push(row); }
  row.code = saved.effective || saved.code || "";
  row.source = saved.code ? "set" : (saved.source || "");
  row.suggestion = saved.suggestion || "";
}

function npdCodeWire(d) {
  const open = app.querySelector("#npd-addclass-open");
  if (open) open.addEventListener("click", function () {
    npdView.addingClass = true;
    const box = app.querySelector("#npd-addclass");
    if (box) { box.outerHTML = npdAddClassHtml(d); npdCodeWire(d); }
    const input = app.querySelector("#npd-addclass-label");
    if (input) input.focus();
  });
  const cancel = app.querySelector("#npd-addclass-cancel");
  if (cancel) cancel.addEventListener("click", function () {
    npdView.addingClass = false;
    const box = app.querySelector("#npd-addclass");
    if (box) { box.outerHTML = npdAddClassHtml(d); npdCodeWire(d); }
  });
  const go = app.querySelector("#npd-addclass-go");
  const labelBox = app.querySelector("#npd-addclass-label");
  const submit = function () {
    const label = (labelBox.value || "").trim();
    if (!label) { labelBox.focus(); return; }
    withBusy(go, function () { return npdAddClassField(d, label); });
  };
  if (go) go.addEventListener("click", submit);
  if (labelBox) labelBox.addEventListener("keydown", function (e) {
    if (e.key === "Enter") { e.preventDefault(); submit(); }
    if (e.key === "Escape") { e.preventDefault(); cancel.click(); }
  });
  const structure = app.querySelector("#npd-code-structure");
  if (structure) structure.addEventListener("click", function () {
    if (!confirm("Leave this product for the Nomenclature tab? Anything not saved here is lost.")) return;
    npdView.editing = null;
    npdOpenNomenclature(d.make || "", d.typology || null);
  });
}

// ---- listeners on the page, registered once
//
// Anything typed on the product form can change its code, so any edit asks for it again - one
// listener rather than one per box, which a partial redraw would leave behind. A value typed next
// to a code box also retargets that box, so it waits for the new value's code instead of showing
// the old one's. Enter in a code box saves it and moves to the next; on an empty box it first
// takes the suggestion shown in grey. Escape puts back what was saved.
["input", "change"].forEach(function (type) {
  app.addEventListener(type, function (e) {
    const d = npdView.editing;
    const t = e.target;
    if (!d || !app.querySelector("#npd-codebar") || !t || t.type === "file") return;
    if (t.classList && t.classList.contains("npd-code-in")) {
      if (type === "change") npdCodeCommit(d, t);
      return;
    }
    if (type === "input") {
      const holder = t.closest && t.closest(".npd-ident-row, .npd-optrow, .npd-acc-row");
      const box = (holder && holder.querySelector(".npd-code-in")) ||
        (t.dataset && t.dataset.key && app.querySelector('[data-code-cell="' + t.dataset.key + '"] .npd-code-in'));
      if (box && box !== t) {
        box.dataset.codeValue = String(t.value || "").trim();
        box.value = "";
        box.placeholder = "…";
        box.className = "npd-code-in is-pending";
      }
    }
    npdCodeRefreshSoon(d);
  });
});

app.addEventListener("keydown", function (e) {
  const input = e.target && e.target.closest && e.target.closest(".npd-step .npd-code-in");
  if (!input || !npdView.editing) return;
  if (e.key === "Enter") {
    e.preventDefault();
    if (!input.value.trim() && input.dataset.suggest) input.value = input.dataset.suggest;
    const boxes = Array.from(app.querySelectorAll(".npd-step .npd-code-in:not([disabled])"));
    const next = boxes[boxes.indexOf(input) + 1];
    npdCodeCommit(npdView.editing, input);
    if (next) next.focus(); else input.blur();
  } else if (e.key === "Escape") {
    input.value = input.dataset.saved || "";
    input.blur();
  }
});

// A jump acts on the press, not the click: the bar is redrawn whenever an answer arrives, and
// one landing between press and release would otherwise swallow the click. Enter or Space on a
// focused link arrives as a click with no pointer behind it (detail 0), and is taken there.
app.addEventListener("pointerdown", function (e) {
  const jump = e.target && e.target.closest && e.target.closest("#npd-codebar [data-jump]");
  if (!jump || !npdView.editing || e.button !== 0) return;
  e.preventDefault();
  npdJumpTo(jump.dataset.jump);
});
app.addEventListener("click", function (e) {
  const jump = e.target && e.target.closest && e.target.closest("#npd-codebar [data-jump]");
  if (jump && npdView.editing && e.detail === 0) {
    e.preventDefault();
    npdJumpTo(jump.dataset.jump);
  }
});
app.addEventListener("keydown", function (e) {
  const jump = e.target && e.target.closest && e.target.closest("#npd-codebar .npd-cs[data-jump]");
  if (jump && npdView.editing && (e.key === "Enter" || e.key === " ")) {
    e.preventDefault();
    npdJumpTo(jump.dataset.jump);
  }
});

// ---------------- feedback ----------------
//
// A short message that comes and goes by itself at the foot of the screen - for a save that
// worked, or one that did not - so confirming something never costs a click on an OK button.
function showToast(message, kind) {
  let host = document.getElementById("toast-host");
  if (!host) {
    host = document.createElement("div");
    host.id = "toast-host";
    host.setAttribute("role", "status");
    host.setAttribute("aria-live", "polite");
    document.body.appendChild(host);
  }
  const t = document.createElement("div");
  t.className = "toast toast-" + (kind || "ok");
  t.textContent = message;
  host.appendChild(t);
  requestAnimationFrame(function () { t.classList.add("in"); });
  setTimeout(function () {
    t.classList.remove("in");
    setTimeout(function () { t.remove(); }, 250);
  }, kind === "error" ? 6500 : 3500);
}

// A picture the product already has, shown as itself. The file inputs stay, so choosing a new
// one replaces what is there; without this the form said "No file chosen" about a product
// whose sheet plainly has an image on it.
// Further dimension drawings (18 Nov 2026): some sheets print several in their DIMENSION box. The
// saved ones and the ones about to be added, each with a remove button; added several at a time.
function npdMoreDiagramsHtml(d) {
  const saved = (d.moreDiagrams || []).filter(function (x) { return (d.removeDiagrams || []).indexOf(x.label) < 0; });
  const fresh = (d.files && d.files.more_diagrams) || [];
  const tile = function (inner, name, key, isSaved) {
    return '<span class="npd-more-tile">' + inner + '<span class="npd-more-name">' + escapeHtml(name) + "</span>" +
      '<button type="button" class="npd-more-drop" data-more-drop="' + attr(key) + '"' + (isSaved ? ' data-saved="1"' : "") +
      ' aria-label="' + attr("Remove " + name) + '" title="Remove">×</button></span>';
  };
  return '<div class="npd-more-diagrams"><div class="npd-more-head"><span>More dimension drawings</span>' +
    '<span class="muted">printed together with the line diagram in the sheet’s DIMENSION box</span></div>' +
    '<div class="npd-more-list">' +
      saved.map(function (x) { return tile('<img src="' + attr(x.url) + '" alt="">', x.label, x.label, true); }).join("") +
      fresh.map(function (f, i) {
        f._preview = f._preview || URL.createObjectURL(f);
        return tile('<img src="' + attr(f._preview) + '" alt="">', f.name, String(i), false);
      }).join("") +
      '<label class="npd-more-add">+ Add drawings<input type="file" id="npd-more-diag" multiple accept=".png,.jpg,.jpeg,.gif,.webp"></label>' +
    "</div></div>";
}

function npdUploadHtml(id, title, file, existingUrl) {
  const state = file
    ? escapeHtml(file.name) + " (replaces the current one)"
    : (existingUrl ? "Attached" : "No file chosen");
  return '<label class="npd-drop' + (file || existingUrl ? " has-file" : "") + '">' +
    '<span class="npd-drop-title">' + title + "</span>" +
    (existingUrl && !file
      ? '<span class="npd-drop-preview"><img src="' + attr(existingUrl) + '" alt=""></span>'
      : "") +
    '<span class="npd-drop-name">' + state + "</span>" +
    '<span class="npd-drop-cta">' + (file || existingUrl ? "Replace" : "Choose file") + "</span>" +
    // The types the server accepts (PICTURE_SUFFIXES in app/main.py) - "image/*" offered SVG too.
    '<input type="file" id="' + id + '" accept=".png,.jpg,.jpeg,.gif,.webp"></label>';
}

// Redraw just the title line and its parts. In place rather than by re-rendering the whole
// form, so it keeps up as a parameter is typed without moving the caret.
function npdRefreshTitle(d) {
  const block = app.querySelector(".npd-title-block");
  if (!block) return;
  const fresh = el(npdTitleBlockHtml(d));
  block.replaceWith(fresh);
  // The block is replaced wholesale, so whatever was listening on the old one went with it.
  npdBindTitleBlock(d);
}

// The printed line itself, typed straight in because it is what the sheet prints - the parts
// beneath it stay in view so it is clear where each word comes from.
function npdBindTitleBlock(d) {
  const line = app.querySelector("#npd-description-line");
  if (line) {
    line.addEventListener("input", function () { d.description_line = line.value; });
  }
  const useComposed = app.querySelector("#npd-use-composed");
  if (useComposed) {
    useComposed.addEventListener("click", function () {
      d.description_line = npdComposedTitle(d);
      npdRefreshTitle(d);
    });
  }
}
